window.STUDY_BANK = [{"id":1,"prompt":"An upstream system has been configured to pass the date for a given batch of data to the Databricks Jobs API as a parameter. The notebook to\nbe scheduled will use this parameter to load data with the following code: df = spark.read.format(\"parquet\").load(f\"/mnt/source/{date}\")\nWhich code block should be used to create the date Python variable used in the above code block?","options":[{"id":"A","text":"date = spark.conf.get(\"date\")","rationale":"Spark configuration is not the notebook task-parameter interface.","isCorrect":false},{"id":"B","text":"input_dict = input()\ndate= input_dict[\"date\"]","rationale":"input() reads stdin, not notebook parameters.","isCorrect":false},{"id":"C","text":"import sys\ndate = sys.argv[1]","rationale":"sys.argv is for script arguments, not notebook widgets.","isCorrect":false},{"id":"D","text":"date = dbutils.notebooks.getParam(\"date\")","rationale":"This notebook utility method does not exist.","isCorrect":false},{"id":"E","text":"dbutils.widgets.text(\"date\", \"null\")\ndate = dbutils.widgets.get(\"date\")","rationale":"Widgets expose notebook task parameters as strings.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"Widgets expose notebook task parameters as strings.","topic":"widgets","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/widgets","sourceTitle":"Databricks widgets | Databricks on AWS","sourcePage":1,"images":["questions/001-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"An upstream system has been configured to pass the date for a given batch of data to the Databricks Jobs API as a parameter. The notebook to\nbe scheduled will use this parameter to load data with the following code: df = spark.read.format(\"parquet\").load(f\"/mnt/source/(date)\")\nWhich code block should be used to create the date Python variable used in the above code block?","options":[{"id":"A","text":"date = spark.conf.get(\"date\")"},{"id":"B","text":"input_dict = input()\ndate= input_dict[\"date\"]"},{"id":"C","text":"import sys\ndate = sys.argv[1]"},{"id":"D","text":"date = dbutils.notebooks.getParam(\"date\")"},{"id":"E","text":"dbutils.widgets.text(\"date\", \"null\")\ndate = dbutils.widgets.get(\"date\")"}],"correctAnswers":["E"],"explanation":"Notebook task parameters are read through dbutils.widgets.get. Spark configuration, stdin and sys.argv are different mechanisms; dbutils.notebooks.getParam is not the supported API.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Corrected the f-string date placeholder.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":2,"prompt":"The Databricks workspace administrator has configured interactive clusters for each of the data engineering groups. To control costs, clusters are\nset to terminate after 30 minutes of inactivity. Each user should be able to execute workloads against their assigned clusters at any time of the\nday.\nAssuming users have been added to a workspace but not granted any permissions, which of the following describes the minimal permissions a\nuser would need to start and attach to an already configured cluster.","options":[{"id":"A","text":"\"Can Manage\" privileges on the required cluster","rationale":"CAN MANAGE is broader than necessary.","isCorrect":false},{"id":"B","text":"Workspace Admin privileges, cluster creation allowed, \"Can Attach To\" privileges on the required cluster","rationale":"Workspace administration and cluster creation are unnecessary.","isCorrect":false},{"id":"C","text":"Cluster creation allowed, \"Can Attach To\" privileges on the required cluster","rationale":"CAN ATTACH TO cannot restart terminated compute.","isCorrect":false},{"id":"D","text":"\"Can Restart\" privileges on the required cluster","rationale":"CAN RESTART includes restart and attachment.","isCorrect":true},{"id":"E","text":"Cluster creation allowed, \"Can Restart\" privileges on the required cluster","rationale":"Cluster creation adds an unnecessary privilege.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"CAN RESTART includes restart and attachment.","topic":"compute","sourceUrl":"https://docs.databricks.com/aws/en/compute/clusters-manage","sourceTitle":"Manage classic compute | Databricks on AWS","sourcePage":1,"images":["questions/002-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":3,"prompt":"When scheduling Structured Streaming jobs for production, which configuration automatically recovers from query failures and keeps costs low?","options":[{"id":"A","text":"Cluster: New Job Cluster;\nRetries: Unlimited;\nMaximum Concurrent Runs: Unlimited","rationale":"Concurrent copies must not share this stream checkpoint.","isCorrect":false},{"id":"B","text":"Cluster: New Job Cluster;\nRetries: None;\nMaximum Concurrent Runs: 1","rationale":"Without retries, failures do not recover automatically.","isCorrect":false},{"id":"C","text":"Cluster: Existing All-Purpose Cluster;\nRetries: Unlimited;\nMaximum Concurrent Runs: 1","rationale":"All-purpose compute is not the lowest-cost listed production setup.","isCorrect":false},{"id":"D","text":"Cluster: New Job Cluster;\nRetries: Unlimited;\nMaximum Concurrent Runs: 1","rationale":"Job compute, retries and one run support recovery.","isCorrect":true},{"id":"E","text":"Cluster: Existing All-Purpose Cluster;\nRetries: None;\nMaximum Concurrent Runs: 1","rationale":"This lacks retries and uses all-purpose compute.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Job compute, retries and one run support recovery.","topic":"streamprod","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/production","sourceTitle":"Production considerations for Structured Streaming | Databricks on AWS","sourcePage":2,"images":["questions/003-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":4,"prompt":"Each minute, a query computes AVG(temperature) AS mean_temperature grouped by sensor_id over the most recent five minutes. A SQL alert evaluates MAX(mean_temperature) > 120. It evaluates TRUE for three consecutive refreshes and FALSE on the next. Which statement is necessarily true for each of the three triggering refreshes?","options":[{"id":"A","text":"The total average temperature across all sensors exceeded 120 on three consecutive executions of the query","rationale":"One sensor mean does not determine the overall mean.","isCorrect":false},{"id":"B","text":"The recent_sensor_recordings table was unresponsive for three consecutive runs of the query","rationale":"A true threshold evaluation does not imply unresponsiveness.","isCorrect":false},{"id":"C","text":"The source query failed to update properly for three consecutive minutes and then restarted","rationale":"A true evaluation does not establish a failed refresh.","isCorrect":false},{"id":"D","text":"Every sensor had a maximum temperature above 120 on each of the three triggering refreshes.","rationale":"The condition does not require every sensor to exceed it.","isCorrect":false},{"id":"E","text":"At least one sensor had an average temperature above 120 at each of the three triggering refreshes; it need not be the same sensor.","rationale":"At least one per-sensor mean exceeds the threshold.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"At least one per-sensor mean exceeds the threshold.","topic":"alerts","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/alerts/query-patterns","sourceTitle":"SQL alert aggregation and multi-column patterns","sourcePage":2,"images":["questions/004-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":4,"prompt":"The data engineering team has configured a Databricks SQL query and alert to monitor the values in a Delta Lake table. The\nrecent_sensor_recordings table contains an identifying sensor_id alongside the timestamp and temperature for the most recent 5 minutes of\nrecordings.\nThe below query is used to create the alert:\nThe query is set to refresh each minute and always completes in less than 10 seconds. The alert is set to trigger when mean (temperature) > 120.\nNotifications are triggered to be sent at most every 1 minute.\nIf this alert raises notifications for 3 consecutive minutes and then stops, which statement must be true?","options":[{"id":"A","text":"The total average temperature across all sensors exceeded 120 on three consecutive executions of the query"},{"id":"B","text":"The recent_sensor_recordings table was unresponsive for three consecutive runs of the query"},{"id":"C","text":"The source query failed to update properly for three consecutive minutes and then restarted"},{"id":"D","text":"The maximum temperature recording for at least one sensor exceeded 120 on three consecutive executions of the query"},{"id":"E","text":"The average temperature recordings for at least one sensor exceeded 120 on three consecutive executions of the query"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["E"],"status":"review","explanation":"E is the intended answer for a per-sensor mean alert, but D is also logically implied: if a sensor mean exceeds 120, its maximum must exceed 120. Alert aggregation settings are not fully specified. Keep this single-select question out of scoring until rewritten.","topic":"alerts","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/alerts/","sourceTitle":"Databricks SQL alerts | Databricks on AWS","sourcePage":2,"images":["questions/004-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Disambiguated the alert aggregation and removed a second logically implied answer.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":5,"prompt":"A junior developer complains that the code in their notebook isn't producing the correct results in the development environment. A shared\nscreenshot reveals that while they're using a notebook versioned with Databricks Repos, they're using a personal branch that contains old logic.\nThe desired branch named dev-2.3.9 is not available from the branch selection dropdown.\nWhich approach will allow this developer to review the current logic for this notebook?","options":[{"id":"A","text":"Use Repos to make a pull request use the Databricks REST API to update the current branch to dev-2.3.9","rationale":"A pull request does not fetch the missing branch.","isCorrect":false},{"id":"B","text":"Use Repos to pull changes from the remote Git repository and select the dev-2.3.9 branch.","rationale":"Pull remote changes, then select the existing remote branch.","isCorrect":true},{"id":"C","text":"Use Repos to checkout the dev-2.3.9 branch and auto-resolve conflicts with the current branch","rationale":"The unavailable branch cannot simply be selected; conflicts are not auto-resolved.","isCorrect":false},{"id":"D","text":"Merge all changes back to the main branch in the remote Git repository and clone the repo again","rationale":"Merging into main and recloning is unnecessary and disruptive.","isCorrect":false},{"id":"E","text":"Use Repos to merge the current branch and the dev-2.3.9 branch, then make a pull request to sync with the remote repository","rationale":"Merging unrelated work is unnecessary to inspect a branch.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Pull remote changes, then select the existing remote branch.","topic":"git","sourceUrl":"https://docs.databricks.com/aws/en/repos/git-operations-with-repos","sourceTitle":"Create and manage Git folders | Databricks on AWS","sourcePage":3,"images":["questions/005-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":6,"prompt":"The security team is exploring whether or not the Databricks secrets module can be leveraged for connecting to an external database.\nAfter testing the code with all Python variables being defined with strings, they upload the password to the secrets module and configure the\ncorrect permissions for the currently active user. They then modify their code to the following (leaving all other variables unchanged).\nWhich statement describes what will happen when the above code is executed?","options":[{"id":"A","text":"The connection to the external table will fail; the string \"REDACTED\" will be printed.","rationale":"Redaction affects displayed output, not the supplied credential.","isCorrect":false},{"id":"B","text":"An interactive input box will appear in the notebook; if the right password is provided, the connection will succeed and the encoded\npassword will be saved to DBFS.","rationale":"Secret retrieval is not an interactive password prompt.","isCorrect":false},{"id":"C","text":"An interactive input box will appear in the notebook; if the right password is provided, the connection will succeed and the password will be\nprinted in plain text.","rationale":"Secret retrieval does not prompt or normally print plaintext.","isCorrect":false},{"id":"D","text":"The connection to the external table will succeed; the string value of password will be printed in plain text.","rationale":"Direct notebook display of the retrieved secret is redacted.","isCorrect":false},{"id":"E","text":"The connection to the external table will succeed; the string \"REDACTED\" will be printed.","rationale":"JDBC receives the secret while notebook output is redacted.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"JDBC receives the secret while notebook output is redacted.","topic":"secrets","sourceUrl":"https://docs.databricks.com/aws/en/security/secrets/","sourceTitle":"Secret management | Databricks on AWS","sourcePage":3,"images":["questions/006-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":7,"prompt":"The data science team has created and logged a production model using MLflow. The following code correctly imports and applies the production\nmodel to output the predictions as a new DataFrame named preds with the schema \"customer_id LONG, predictions DOUBLE, date DATE\".\nThe data science team would like predictions saved to a Delta Lake table with the ability to compare all predictions across time. Churn predictions\nwill be made at most once per day.\nWhich code block accomplishes this task while minimizing potential compute costs?","options":[{"id":"A","text":"preds.write.mode(\"append\").saveAsTable(\"churn_preds\")","rationale":"Append retains predictions from earlier dates.","isCorrect":true},{"id":"B","text":"preds.write.format(\"delta\").save(\"/preds/churn_preds\")","rationale":"Default save mode fails when the destination already exists.","isCorrect":false},{"id":"C","text":"[Code choice shown in the original PDF image]","rationale":"A batch DataFrame cannot use writeStream; overwrite is also invalid there.","isCorrect":false},{"id":"D","text":"[Code choice shown in the original PDF image]","rationale":"Overwrite discards previously stored predictions.","isCorrect":false},{"id":"E","text":"[Code choice shown in the original PDF image]","rationale":"A batch DataFrame cannot use writeStream.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Append retains predictions from earlier dates.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":4,"images":["questions/007-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":8,"prompt":"An upstream source writes Parquet data as hourly batches to directories named with the current date. A nightly batch job runs the following code\nto ingest all data from the previous day as indicated by the date variable:\nAssume that the fields customer_id and order_id serve as a composite key to uniquely identify each order.\nIf the upstream system is known to occasionally produce duplicate entries for a single order hours apart, which statement is correct?","options":[{"id":"A","text":"Each write to the orders table will only contain unique records, and only those records without duplicates in the target table will be written.","rationale":"Batch deduplication does not check the existing target.","isCorrect":false},{"id":"B","text":"Each write to the orders table will only contain unique records, but newly written records may have duplicates already present in the target\ntable.","rationale":"The batch is deduplicated; append does not deduplicate history.","isCorrect":true},{"id":"C","text":"Each write to the orders table will only contain unique records; if existing records with the same key are present in the target table, these\nrecords will be overwritten.","rationale":"Append does not overwrite matching business keys.","isCorrect":false},{"id":"D","text":"Each write to the orders table will only contain unique records; if existing records with the same key are present in the target table, the\noperation will fail.","rationale":"No uniqueness constraint is established by this append.","isCorrect":false},{"id":"E","text":"Each write to the orders table will run deduplication over the union of new and existing records, ensuring no duplicate records are present.","rationale":"Existing target rows are not part of this deduplication.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"The batch is deduplicated; append does not deduplicate history.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":5,"images":["questions/008-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":9,"prompt":"A junior member of the data engineering team is exploring the language interoperability of Databricks notebooks. The intended outcome of the\nbelow code is to register a view of all sales that occurred in countries on the continent of Africa that appear in the geo_lookup table.\nBefore executing the code, running SHOW TABLES on the current database indicates the database contains only two tables: geo_lookup and\nsales.\nWhich statement correctly describes the outcome of executing these command cells in order in an interactive notebook?","options":[{"id":"A","text":"Both commands will succeed. Executing show tables will show that countries_af and sales_af have been registered as views.","rationale":"Python assignment does not register a SQL view.","isCorrect":false},{"id":"B","text":"Cmd 1 will succeed. Cmd 2 will search all accessible databases for a table or view named countries_af: if this entity exists, Cmd 2 will\nsucceed.","rationale":"SQL does not search arbitrary databases for Python variables.","isCorrect":false},{"id":"C","text":"Cmd 1 will succeed and Cmd 2 will fail. countries_af will be a Python variable representing a PySpark DataFrame.","rationale":"The comprehension produces a list, not a DataFrame.","isCorrect":false},{"id":"D","text":"Both commands will fail. No new variables, tables, or views will be created.","rationale":"The Python list-building command succeeds.","isCorrect":false},{"id":"E","text":"Cmd 1 will succeed and Cmd 2 will fail. countries_af will be a Python variable containing a list of strings.","rationale":"The list exists only in Python; the SQL statement fails.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"The list exists only in Python; the SQL statement fails.","topic":"notebooks","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/notebooks-code","sourceTitle":"Develop code in Databricks notebooks | Databricks on AWS","sourcePage":5,"images":["questions/009-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":10,"prompt":"A Delta table of weather records is partitioned by date and has the below schema: date DATE, device_id INT, temp FLOAT, latitude FLOAT, longitude\nFLOAT\nTo find all the records from within the Arctic Circle, you execute a query with the below filter: latitude > 66.3\nWhich statement describes how the Delta engine identifies which files to load?","options":[{"id":"A","text":"All records are cached to an operational database and then the filter is applied","rationale":"No operational-database cache is required for skipping.","isCorrect":false},{"id":"B","text":"The Parquet file footers are scanned for min and max statistics for the latitude column","rationale":"Delta uses logged statistics, not a required footer scan.","isCorrect":false},{"id":"C","text":"All records are cached to attached storage and then the filter is applied","rationale":"Caching every record is unnecessary for file pruning.","isCorrect":false},{"id":"D","text":"The Delta log is scanned for min and max statistics for the latitude column","rationale":"Logged per-file latitude statistics identify candidate files.","isCorrect":true},{"id":"E","text":"The Hive metastore is scanned for min and max statistics for the latitude column","rationale":"The metastore does not hold these Delta per-file statistics.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Logged per-file latitude statistics identify candidate files.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":6,"images":["questions/010-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":11,"prompt":"The data engineering team has configured a job to process customer requests to be forgotten (have their data deleted). All user data that needs\nto be deleted is stored in Delta Lake tables using default table settings.\nThe team has decided to process all deletions from the previous week as a batch job at 1am each Sunday. The total duration of this job is less\nthan one hour. Every Monday at 3am, a batch job executes a series of VACUUM commands on all Delta Lake tables throughout the organization.\nThe compliance officer has recently learned about Delta Lake's time travel functionality. They are concerned that this might allow continued\naccess to deleted data.\nAssuming all delete logic is correctly implemented, which statement correctly addresses this concern?","options":[{"id":"A","text":"Because the VACUUM command permanently deletes all files containing deleted records, deleted records may be accessible with time\ntravel for around 24 hours.","rationale":"Next-day vacuum cannot remove seven-day-retained files.","isCorrect":false},{"id":"B","text":"Because the default data retention threshold is 24 hours, data files containing deleted records will be retained until the VACUUM job is run\nthe following day.","rationale":"The stated default retention is seven days, not 24 hours.","isCorrect":false},{"id":"C","text":"Because Delta Lake time travel provides full access to the entire history of a table, deleted records can always be recreated by users with\nfull admin privileges.","rationale":"Time travel cannot recover files after physical removal.","isCorrect":false},{"id":"D","text":"Because Delta Lake's delete statements have ACID guarantees, deleted records will be permanently purged from all storage systems as\nsoon as a delete job completes.","rationale":"ACID deletion does not immediately purge historical files.","isCorrect":false},{"id":"E","text":"Because the default data retention threshold is 7 days, data files containing deleted records will be retained until the VACUUM job is run 8\ndays later.","rationale":"The following week's Monday vacuum is the first eligible scheduled run.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"scoped","explanation":"The following week's Monday vacuum is the first eligible scheduled run.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":6,"images":["questions/011-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":11,"prompt":"The data engineering team has configured a job to process customer requests to be forgotten (have their data deleted). All user data that needs\nto be deleted is stored in Delta Lake tables using default table settings.\nThe team has decided to process all deletions from the previous week as a batch job at 1am each Sunday. The total duration of this job is less\nthan one hour. Every Monday at 3am, a batch job executes a series of VACUUM commands on all Delta Lake tables throughout the organization.\nThe compliance officer has recently learned about Delta Lake's time travel functionality. They are concerned that this might allow continued\naccess to deleted data.\nAssuming all delete logic is correctly implemented, which statement correctly addresses this concern?","options":[{"id":"A","text":"Because the VACUUM command permanently deletes all files containing deleted records, deleted records may be accessible with time\ntravel for around 24 hours."},{"id":"B","text":"Because the default data retention threshold is 24 hours, data files containing deleted records will be retained until the VACUUM job is run\nthe following day."},{"id":"C","text":"Because Delta Lake time travel provides full access to the entire history of a table, deleted records can always be recreated by users with\nfull admin privileges."},{"id":"D","text":"Because Delta Lake's delete statements have ACID guarantees, deleted records will be permanently purged from all storage systems as\nsoon as a delete job completes."},{"id":"E","text":"Because the default data retention threshold is 7 days, data files containing deleted records will be retained until the VACUUM job is run 8\ndays later."}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"legacy","explanation":"With seven-day deleted-file retention, the next day's VACUUM is too early; the following Monday is about eight days after deletion. This assumes rewritten files; deletion vectors may additionally require REORG APPLY PURGE.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":6,"images":["questions/011-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Assume seven-day deleted-file retention, no deletion vectors, and DELETE rewrites the affected files. Measure retention from deletion, not the original file creation.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":12,"prompt":"A junior data engineer has configured a workload that posts the following JSON to the Databricks REST API endpoint 2.0/jobs/create.\nAssuming that all configurations and referenced resources are available, which statement describes the result of executing this workload three\ntimes?","options":[{"id":"A","text":"Three new jobs named \"Ingest new data\" will be defined in the workspace, and they will each run once daily.","rationale":"The payload does not contain a daily schedule.","isCorrect":false},{"id":"B","text":"The logic defined in the referenced notebook will be executed three times on new clusters with the configurations of the provided cluster ID.","rationale":"Creating a job does not execute its notebook.","isCorrect":false},{"id":"C","text":"Three new jobs named \"Ingest new data\" will be defined in the workspace, but no jobs will be executed.","rationale":"Each create call creates a definition without running it.","isCorrect":true},{"id":"D","text":"One new job named \"Ingest new data\" will be defined in the workspace, but it will not be executed.","rationale":"Job names are not an idempotency key.","isCorrect":false},{"id":"E","text":"The logic defined in the referenced notebook will be executed three times on the referenced existing all purpose cluster.","rationale":"The create endpoint does not trigger notebook runs.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Each create call creates a definition without running it.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":7,"images":["questions/012-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":13,"prompt":"An upstream system is emitting change data capture (CDC) logs that are being written to a cloud object storage directory. Each record in the log\nindicates the change type (insert, update, or delete) and the values for each field after the change. The source table has a primary key identified by\nthe field pk_id.\nFor auditing purposes, the data governance team wishes to maintain a full record of all values that have ever been valid in the source system. For\nanalytical purposes, only the most recent value for each record needs to be recorded. The Databricks job to ingest these records occurs once per\nhour, but each individual record may have changed multiple times over the course of an hour.\nWhich solution meets these requirements?","options":[{"id":"A","text":"Create a separate history table for each pk_id resolve the current state of the table by running a union all filtering the history tables for the\nmost recent state.","rationale":"Per-key tables and unions do not provide the intended scalable design.","isCorrect":false},{"id":"B","text":"Use MERGE INTO to insert, update, or delete the most recent entry for each pk_id into a bronze table, then propagate all changes\nthroughout the system.","rationale":"Latest-only bronze data loses intermediate audit events.","isCorrect":false},{"id":"C","text":"Iterate through an ordered set of changes to the table, applying each in turn; rely on Delta Lake's versioning ability to create an audit log.","rationale":"Finite-retention table versions are not a durable CDC archive.","isCorrect":false},{"id":"D","text":"Use Delta Lake's change data feed to automatically process CDC data from an external system, propagating all changes to all dependent\ntables in the Lakehouse.","rationale":"CDF does not automatically ingest external CDC logs.","isCorrect":false},{"id":"E","text":"Ingest all log information into a bronze table; use MERGE INTO to insert, update, or delete the most recent entry for each pk_id into a silver\ntable to recreate the current table state.","rationale":"Bronze retains every event; silver maintains the latest keyed state.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"Bronze retains every event; silver maintains the latest keyed state.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":7,"images":["questions/013-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":14,"prompt":"An hourly batch job is configured to ingest data files from a cloud object storage container where each batch represent all records produced by the\nsource system in a given hour. The batch job to process these records into the Lakehouse is sufficiently delayed to ensure no late-arriving data is\nmissed. The user_id field represents a unique key for the data, which has the following schema: user_id BIGINT, username STRING, user_utc\nSTRING, user_region STRING, last_login BIGINT, auto_pay BOOLEAN, last_updated BIGINT\nNew records are all ingested into a table named account_history which maintains a full record of all data in the same schema as the source. The\nnext table in the system is named account_current and is implemented as a Type 1 table representing the most recent value for each unique\nuser_id.\nAssuming there are millions of user accounts and tens of thousands of records processed hourly, which implementation can be used to efficiently\nupdate the described account_current table as part of each hourly batch job?","options":[{"id":"A","text":"Use Auto Loader to subscribe to new files in the account_history directory; configure a Structured Streaming trigger once job to batch\nupdate newly detected files into the account_current table.","rationale":"File discovery alone does not implement latest-state upserts.","isCorrect":false},{"id":"B","text":"Overwrite the account_current table with each batch using the results of a query against the account_history table grouping by user_id and\nfiltering for the max value of last_updated.","rationale":"A full-history rebuild is not the requested incremental approach.","isCorrect":false},{"id":"C","text":"Read the newly ingested hourly account_history records. For each user_id, retain the row with greatest last_updated (using a deterministic source sequence to break ties), then MERGE on user_id to update or insert the latest state.","rationale":"Order changes by update sequence and merge once per user.","isCorrect":true},{"id":"D","text":"Use Delta Lake version history to get the difference between the latest version of account_history and one version prior, then write these\nrecords to account_current.","rationale":"Table versions alone are not a complete incremental row-change processor.","isCorrect":false},{"id":"E","text":"Filter records in account_history using the last_updated field and the most recent hour processed, making sure to deduplicate on username;\nwrite a merge statement to update or insert the most recent value for each username.","rationale":"Username is not the stated stable unique key.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Order changes by update sequence and merge once per user.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":8,"images":["questions/014-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":14,"prompt":"An hourly batch job is configured to ingest data files from a cloud object storage container where each batch represent all records produced by the\nsource system in a given hour. The batch job to process these records into the Lakehouse is sufficiently delayed to ensure no late-arriving data is\nmissed. The user_id field represents a unique key for the data, which has the following schema: user_id BIGINT, username STRING, user_utc\nSTRING, user_region STRING, last_login BIGINT, auto_pay BOOLEAN, last_updated BIGINT\nNew records are all ingested into a table named account_history which maintains a full record of all data in the same schema as the source. The\nnext table in the system is named account_current and is implemented as a Type 1 table representing the most recent value for each unique\nuser_id.\nAssuming there are millions of user accounts and tens of thousands of records processed hourly, which implementation can be used to efficiently\nupdate the described account_current table as part of each hourly batch job?","options":[{"id":"A","text":"Use Auto Loader to subscribe to new files in the account_history directory; configure a Structured Streaming trigger once job to batch\nupdate newly detected files into the account_current table."},{"id":"B","text":"Overwrite the account_current table with each batch using the results of a query against the account_history table grouping by user_id and\nfiltering for the max value of last_updated."},{"id":"C","text":"Filter records in account_history using the last_updated field and the most recent hour processed, as well as the max last_iogin by user_id\nwrite a merge statement to update or insert the most recent value for each user_id."},{"id":"D","text":"Use Delta Lake version history to get the difference between the latest version of account_history and one version prior, then write these\nrecords to account_current."},{"id":"E","text":"Filter records in account_history using the last_updated field and the most recent hour processed, making sure to deduplicate on username;\nwrite a merge statement to update or insert the most recent value for each username."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["C"],"status":"review","explanation":"C is the likely intended incremental MERGE approach, but it orders by max last_login instead of last_updated. Login time does not reliably identify the newest account change. Rewrite this option before scoring; username is also not the stated key.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":8,"images":["questions/014-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected last_login to last_updated when choosing the newest account change.","studyContext":"The hourly batch boundary is reliable and a deterministic source sequence resolves any equal last_updated values.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":15,"prompt":"A table in the Lakehouse named customer_churn_params is used in churn prediction by the machine learning team. The table contains\ninformation about customers derived from a number of upstream sources. Currently, the data engineering team populates this table nightly by\noverwriting the table with the current valid values derived from upstream data sources.\nThe churn prediction model used by the ML team is fairly stable in production. The team is only interested in making predictions on records that\nhave changed in the past 24 hours.\nWhich approach would simplify the identification of these changed records?","options":[{"id":"A","text":"Apply the churn model to all rows in the customer_churn_params table, but implement logic to perform an upsert into the predictions table\nthat ignores rows where predictions have not changed.","rationale":"This still evaluates predictions for every input record.","isCorrect":false},{"id":"B","text":"Convert the batch job to a Structured Streaming job using the complete output mode; configure a Structured Streaming job to read from the\ncustomer_churn_params table and incrementally predict against the churn model.","rationale":"Complete-mode rewrites do not isolate logically changed rows.","isCorrect":false},{"id":"C","text":"Calculate the difference between the previous model predictions and the current customer_churn_params on a key identifying unique\ncustomers before making new predictions; only make predictions on those customers not in the previous predictions.","rationale":"Previously predicted customers may have changed features.","isCorrect":false},{"id":"D","text":"Modify the overwrite logic to include a field populated by calling spark.sql.functions.current_timestamp() as data are being written; use this\nfield to identify records written on a particular date.","rationale":"Timestamping every rewritten row marks unchanged rows too.","isCorrect":false},{"id":"E","text":"Replace the current overwrite logic with a merge statement to modify only those records that have changed; write logic to make predictions\non the changed records identified by the change data feed.","rationale":"Conditional MERGE plus CDF isolates actual changed records.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"Conditional MERGE plus CDF isolates actual changed records.","topic":"cdf","sourceUrl":"https://docs.databricks.com/aws/en/tables/features/change-data-feed","sourceTitle":"Use change data feed on Databricks | Databricks on AWS","sourcePage":8,"images":["questions/015-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":16,"prompt":"A table is registered with the following code:\nBoth users and orders are Delta Lake tables. Which statement describes the results of querying recent_orders?","options":[{"id":"A","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query finishes.","rationale":"A physical CTAS result is not recomputed at query completion.","isCorrect":false},{"id":"B","text":"All logic will execute when the table is defined and store the result of joining tables to the DBFS; this stored data will be returned when the\ntable is queried.","rationale":"CTAS stores its query result when the table is created.","isCorrect":true},{"id":"C","text":"Results will be computed and cached when the table is defined; these cached results will incrementally update as new records are inserted\ninto source tables.","rationale":"CTAS does not automatically maintain a live incremental cache.","isCorrect":false},{"id":"D","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query began.","rationale":"This describes a logical view, not CTAS.","isCorrect":false},{"id":"E","text":"The versions of each source table will be stored in the table transaction log; query results will be saved to DBFS with each query.","rationale":"The table stores data, not only references to source versions.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"CTAS stores its query result when the table is created.","topic":"ctas","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-create-table-using","sourceTitle":"CREATE TABLE [USING] | Databricks on AWS","sourcePage":9,"images":["questions/016-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A table is registered with the following code:\nBoth users and orders are Delta Lake tables. Which statement describes the results of querying recent_orders?","options":[{"id":"A","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query finishes."},{"id":"B","text":"All logic will execute when the table is defined and store the result of joining tables to the DBFS; this stored data will be returned when the\ntable is queried."},{"id":"C","text":"Results will be computed and cached when the table is defined; these cached results will incrementally update as new records are inserted\ninto source tables."},{"id":"D","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query began."},{"id":"E","text":"The versions of each source table will be stored in the table transaction log; query results will be saved to DBFS with each query."}],"correctAnswers":["B"],"explanation":"The image uses CREATE TABLE AS SELECT, so results are materialized at creation and stored. It is not a logical view, a continuously refreshed cache, or a query evaluated on every table read.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"studyContext":"Use a legacy Hive-metastore managed Delta table with the configured DBFS warehouse location; this is not a statement that modern Unity Catalog tables use DBFS root.","reviewNote":"Second audit: The storage answer is scoped to a legacy Hive-metastore managed table.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":17,"prompt":"A production workload incrementally applies updates from an external Change Data Capture feed to a Delta Lake table as an always-on Structured\nStream job. When data was initially migrated for this table, OPTIMIZE was executed and most data files were resized to 1 GB. Auto Optimize and\nAuto Compaction were both turned on for the streaming production job. Recent review of data files shows that most data files are under 64 MB,\nalthough each partition in the table contains at least 1 GB of data and the total table size is over 10 TB.\nWhich of the following likely explains these smaller file sizes?","options":[{"id":"A","text":"Databricks has autotuned to a smaller target file size to reduce duration of MERGE operations","rationale":"Rewrite-heavy MERGE workloads can tune toward smaller files.","isCorrect":true},{"id":"B","text":"Z-order indices calculated on the table are preventing file compaction","rationale":"Z-ordering does not inherently block compaction.","isCorrect":false},{"id":"C","text":"Bloom filter indices calculated on the table are preventing file compaction","rationale":"Bloom filters do not inherently block compaction.","isCorrect":false},{"id":"D","text":"Databricks has autotuned to a smaller target file size based on the overall size of data in the table","rationale":"A very large table does not explain this small size under table-size tuning.","isCorrect":false},{"id":"E","text":"Databricks has autotuned to a smaller target file size based on the amount of data in each partition","rationale":"Per-partition size is not the described rewrite-workload tuning mechanism.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Rewrite-heavy MERGE workloads can tune toward smaller files.","topic":"filesize","sourceUrl":"https://docs.databricks.com/aws/en/tables/tune-file-size","sourceTitle":"Control data file size | Databricks on AWS","sourcePage":9,"images":["questions/017-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":18,"prompt":"Which statement regarding stream-static joins and static Delta tables is correct?","options":[{"id":"A","text":"Each microbatch of a stream-static join will use the most recent version of the static Delta table as of each microbatch.","rationale":"Each microbatch uses the current static Delta snapshot.","isCorrect":true},{"id":"B","text":"Each microbatch of a stream-static join will use the most recent version of the static Delta table as of the job's initialization.","rationale":"The static snapshot is not frozen at stream initialization.","isCorrect":false},{"id":"C","text":"The checkpoint directory will be used to track state information for the unique keys present in the join.","rationale":"This join does not maintain per-key streaming join state.","isCorrect":false},{"id":"D","text":"Stream-static joins cannot use static Delta tables because of consistency issues.","rationale":"Static Delta tables are supported.","isCorrect":false},{"id":"E","text":"The checkpoint directory will be used to track updates to the static Delta table.","rationale":"The checkpoint does not subscribe to static-table updates.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Each microbatch uses the current static Delta snapshot.","topic":"joins","sourceUrl":"https://docs.databricks.com/aws/en/transform/join","sourceTitle":"Work with joins on Databricks | Databricks on AWS","sourcePage":9,"images":["questions/018-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":19,"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Events are recorded once per minute per\ndevice.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nChoose the response that correctly fills in the blank within the code block to complete this task.","options":[{"id":"A","text":"to_interval(\"event_time\", \"5 minutes\").alias(\"time\")","rationale":"to_interval is not the required grouping-window function.","isCorrect":false},{"id":"B","text":"window(\"event_time\", \"5 minutes\").alias(\"time\")","rationale":"A five-minute window with no slide argument is tumbling.","isCorrect":true},{"id":"C","text":"\"event_time\"","rationale":"Grouping exact timestamps does not form five-minute intervals.","isCorrect":false},{"id":"D","text":"window(\"event_time\", \"10 minutes\").alias(\"time\")","rationale":"This creates ten-minute intervals instead.","isCorrect":false},{"id":"E","text":"lag(\"event_time\", \"10 minutes\").alias(\"time\")","rationale":"lag accesses preceding values rather than creating time windows.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"A five-minute window with no slide argument is tumbling.","topic":"window","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/window.html","sourceTitle":"Window — PySpark 4.2.0 documentation","sourcePage":10,"images":["questions/019-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Events are recorded once per minute per\ndevice.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nChoose the response that correctly fills in the blank within the code block to complete this task.","options":[{"id":"A","text":"to_interval(\"event_time\", \"5 minutes\").alias(\"time\")"},{"id":"B","text":"window(\"event_time\", \"5 minutes\").alias(\"time\")"},{"id":"C","text":"\"event_time\""},{"id":"D","text":"window(\"event_time\", \"10 minutes\").alias(\"time\")"},{"id":"E","text":"lag(\"event_time\", \"10 minutes\").alias(\"time\")"}],"correctAnswers":["B"],"explanation":"window(event_time, '5 minutes') defines non-overlapping five-minute windows when no separate slide is supplied. A raw timestamp, lag, ten-minute window or nonexistent helper does not satisfy this interval.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"studyContext":"df is a streaming DataFrame; checkpoint_path is a writable, query-specific persistent location.","code":"from pyspark.sql.functions import avg, window\n# Replace WINDOW_EXPRESSION with the selected expression.\n(df.withWatermark(\"event_time\", \"10 minutes\")\n .groupBy(WINDOW_EXPRESSION, \"device_id\")\n .agg(avg(\"temp\").alias(\"avg_temp\"), avg(\"humidity\").alias(\"avg_humidity\"))\n .writeStream.format(\"delta\").outputMode(\"append\")\n .option(\"checkpointLocation\", checkpoint_path)\n .toTable(\"sensor_avg\"))","reviewNote":"Second audit: Replaced the invalid streaming saveAsTable call with toTable and an explicit checkpoint.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":20,"prompt":"A data architect has designed a system in which two Structured Streaming jobs will concurrently write to a single bronze Delta table. Each job is\nsubscribing to a different topic from an Apache Kafka source, but they will write data with the same schema. To keep the directory structure\nsimple, a data engineer has decided to nest a checkpoint directory to be shared by both streams.\nThe proposed directory structure is displayed below:\nWhich statement describes whether this checkpoint directory structure is valid for the given scenario and why?","options":[{"id":"A","text":"No; Delta Lake manages streaming checkpoints in the transaction log.","rationale":"The stream checkpoint is distinct from the Delta transaction log.","isCorrect":false},{"id":"B","text":"Yes; both of the streams can share a single checkpoint directory.","rationale":"Independent queries must not share one checkpoint.","isCorrect":false},{"id":"C","text":"No; only one stream can write to a Delta Lake table.","rationale":"Multiple streams can write the same Delta table.","isCorrect":false},{"id":"D","text":"Yes; Delta Lake supports infinite concurrent writers.","rationale":"Concurrent-write support does not permit shared checkpoints.","isCorrect":false},{"id":"E","text":"No; each of the streams needs to have its own checkpoint directory.","rationale":"Each query requires its own checkpoint directory.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"Each query requires its own checkpoint directory.","topic":"checkpoints","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/checkpoints","sourceTitle":"Structured Streaming checkpoints | Databricks on AWS","sourcePage":10,"images":["questions/020-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":21,"prompt":"A Structured Streaming job deployed to production has been experiencing delays during peak hours of the day. At present, during normal\nexecution, each microbatch of data is processed in less than 3 seconds. During peak hours of the day, execution time for each microbatch\nbecomes very inconsistent, sometimes exceeding 30 seconds. The streaming write is currently configured with a trigger interval of 10 seconds.\nWhich listed adjustment is a reasonable first experiment to reduce batch size and spill while keeping the current micro-batch execution model?","options":[{"id":"A","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently allows idle executors to begin processing the next batch\nwhile longer running tasks from previous batches finish.","rationale":"Microbatches do not overlap in the described execution mode.","isCorrect":false},{"id":"B","text":"Increase the trigger interval to 30 seconds; setting the trigger interval near the maximum execution time observed for each batch is always\nbest practice to ensure no records are dropped.","rationale":"Longer triggers do not guarantee smaller batches or no dropped records.","isCorrect":false},{"id":"C","text":"The trigger interval cannot be modified without modifying the checkpoint directory; to maintain the current stream state, increase the\nnumber of shuffle partitions to maximize parallelism.","rationale":"A trigger change does not inherently require a new checkpoint.","isCorrect":false},{"id":"D","text":"Use the trigger once option and configure a Databricks job to execute the query every 10 seconds; this ensures all backlogged records are\nprocessed with each batch.","rationale":"Repeated finite jobs do not preserve the requested execution model.","isCorrect":false},{"id":"E","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently may prevent records from backing up and large batches from\ncausing spill.","rationale":"A shorter interval is a reasonable batch-size experiment.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"A shorter interval is a reasonable batch-size experiment.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":11,"images":["questions/021-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":21,"prompt":"A Structured Streaming job deployed to production has been experiencing delays during peak hours of the day. At present, during normal\nexecution, each microbatch of data is processed in less than 3 seconds. During peak hours of the day, execution time for each microbatch\nbecomes very inconsistent, sometimes exceeding 30 seconds. The streaming write is currently configured with a trigger interval of 10 seconds.\nHolding all other variables constant and assuming records need to be processed in less than 10 seconds, which adjustment will meet the\nrequirement?","options":[{"id":"A","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently allows idle executors to begin processing the next batch\nwhile longer running tasks from previous batches finish."},{"id":"B","text":"Increase the trigger interval to 30 seconds; setting the trigger interval near the maximum execution time observed for each batch is always\nbest practice to ensure no records are dropped."},{"id":"C","text":"The trigger interval cannot be modified without modifying the checkpoint directory; to maintain the current stream state, increase the\nnumber of shuffle partitions to maximize parallelism."},{"id":"D","text":"Use the trigger once option and configure a Databricks job to execute the query every 10 seconds; this ensures all backlogged records are\nprocessed with each batch."},{"id":"E","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently may prevent records from backing up and large batches from\ncausing spill."}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"best_fit","explanation":"Smaller batches may reduce backlog and spill, making E the best proposed change. Microbatches do not overlap as A claims. No trigger setting alone guarantees sub-ten-second latency during a sustained capacity bottleneck.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":11,"images":["questions/021-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Removed an unsupported guarantee that a trigger change alone meets a strict latency deadline.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":22,"prompt":"For an external Delta table with delta.autoOptimize.autoCompact = 'true' (fixed-size mode), which statement describes auto compaction?","options":[{"id":"A","text":"An asynchronous job runs after the write completes to detect if files could be further compacted; if yes, an OPTIMIZE job is executed\ntoward a default of 1 GB.","rationale":"This confuses asynchronous maintenance with fixed-mode auto compaction.","isCorrect":false},{"id":"B","text":"Before a Jobs cluster terminates, OPTIMIZE is executed on all tables modified during the most recent job.","rationale":"Cluster termination is not the trigger described.","isCorrect":false},{"id":"C","text":"Optimized writes use logical partitions instead of directory partitions; because partition boundaries are only represented in metadata, fewer\nsmall files are written.","rationale":"Delta partitions are not replaced by logical-only boundaries.","isCorrect":false},{"id":"D","text":"Data is queued in a messaging bus instead of committing data directly to memory; all data is committed from the messaging bus in one\nbatch once the job is complete.","rationale":"Auto compaction is not a messaging-bus write queue.","isCorrect":false},{"id":"E","text":"After a successful write, auto compaction runs synchronously on the writing cluster and combines eligible small files, using a 128 MB target in this mode.","rationale":"This matches synchronous post-write compaction in the stated mode.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"This matches synchronous post-write compaction in the stated mode.","topic":"filesize","sourceUrl":"https://docs.databricks.com/aws/en/tables/tune-file-size","sourceTitle":"Control data file size | Databricks on AWS","sourcePage":11,"images":["questions/022-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":22,"prompt":"Which statement describes Delta Lake Auto Compaction?","options":[{"id":"A","text":"An asynchronous job runs after the write completes to detect if files could be further compacted; if yes, an OPTIMIZE job is executed\ntoward a default of 1 GB."},{"id":"B","text":"Before a Jobs cluster terminates, OPTIMIZE is executed on all tables modified during the most recent job."},{"id":"C","text":"Optimized writes use logical partitions instead of directory partitions; because partition boundaries are only represented in metadata, fewer\nsmall files are written."},{"id":"D","text":"Data is queued in a messaging bus instead of committing data directly to memory; all data is committed from the messaging bus in one\nbatch once the job is complete."},{"id":"E","text":"An asynchronous job runs after the write completes to detect if files could be further compacted; if yes, an OPTIMIZE job is executed\ntoward a default of 128 MB."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["E"],"status":"review","explanation":"No option is fully correct. E resembles the older 128-MB target, but auto compaction runs synchronously after a successful write, not asynchronously. Current auto sizing can vary. Exclude until corrected.","topic":"filesize","sourceUrl":"https://docs.databricks.com/aws/en/tables/tune-file-size","sourceTitle":"Control data file size | Databricks on AWS","sourcePage":11,"images":["questions/022-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected synchronous auto compaction and specified the fixed-size legacy setting.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":23,"prompt":"Which statement characterizes the general programming model used by Spark Structured Streaming?","options":[{"id":"A","text":"Structured Streaming leverages the parallel processing of GPUs to achieve highly parallel data throughput.","rationale":"GPUs are not the Structured Streaming programming abstraction.","isCorrect":false},{"id":"B","text":"Structured Streaming is implemented as a messaging bus and is derived from Apache Kafka.","rationale":"Structured Streaming is a processing engine, not a Kafka-derived bus.","isCorrect":false},{"id":"C","text":"Structured Streaming uses specialized hardware and I/O streams to achieve sub-second latency for data transfer.","rationale":"The model does not require specialized transfer hardware.","isCorrect":false},{"id":"D","text":"Structured Streaming models new data arriving in a data stream as new rows appended to an unbounded table.","rationale":"New events are modeled as rows in an unbounded table.","isCorrect":true},{"id":"E","text":"Structured Streaming relies on a distributed network of nodes that hold incremental state values for cached stages.","rationale":"State storage is an implementation detail, not the general model.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"New events are modeled as rows in an unbounded table.","topic":"streammodel","sourceUrl":"https://spark.apache.org/docs/4.0.3/streaming/apis-on-dataframes-and-datasets.html","sourceTitle":"Structured Streaming Programming Guide - Spark 4.0.3 Documentation","sourcePage":11,"images":["questions/023-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":24,"prompt":"Which Spark SQL setting specifies the maximum bytes to pack into one input partition when reading files?","options":[{"id":"A","text":"spark.sql.files.maxPartitionBytes","rationale":"This specifies the maximum bytes packed into a file-read partition.","isCorrect":true},{"id":"B","text":"spark.sql.autoBroadcastJoinThreshold","rationale":"This controls join broadcast selection, not read-partition byte limits.","isCorrect":false},{"id":"C","text":"spark.sql.files.openCostInBytes","rationale":"This estimates file-open cost; it is not the maximum byte setting.","isCorrect":false},{"id":"D","text":"spark.sql.adaptive.coalescePartitions.minPartitionNum","rationale":"This concerns adaptive shuffle coalescing, not initial file reads.","isCorrect":false},{"id":"E","text":"spark.sql.adaptive.advisoryPartitionSizeInBytes","rationale":"This targets adaptive shuffle partition sizes.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"This specifies the maximum bytes packed into a file-read partition.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Official documentation for this question","sourcePage":12,"images":["questions/024-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"Which configuration parameter directly affects the size of a spark-partition upon ingestion of data into Spark?","options":[{"id":"A","text":"spark.sql.files.maxPartitionBytes"},{"id":"B","text":"spark.sql.autoBroadcastJoinThreshold"},{"id":"C","text":"spark.sql.files.openCostInBytes"},{"id":"D","text":"spark.sql.adaptive.coalescePartitions.minPartitionNum"},{"id":"E","text":"spark.sql.adaptive.advisoryPartitionSizeInBytes"}],"correctAnswers":["A"],"explanation":"spark.sql.files.maxPartitionBytes controls the maximum bytes packed into an input file partition. The other settings target broadcasting, file-open cost or post-shuffle adaptive coalescing.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: The original wording also allowed file-open cost to affect partition packing.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":25,"prompt":"A Spark job is taking longer than expected. Using the Spark UI, a data engineer notes that the Min, Median, and Max Durations for tasks in a\nparticular stage show the minimum and median time to complete a task as roughly the same, but the max duration for a task to be roughly 100\ntimes as long as the minimum.\nWhich situation is causing increased duration of the overall job?","options":[{"id":"A","text":"Task queueing resulting from improper thread pool assignment.","rationale":"The stated evidence does not establish thread-pool queueing.","isCorrect":false},{"id":"B","text":"Spill resulting from attached volume storage being too small.","rationale":"Spill is not caused by insufficient disk capacity itself.","isCorrect":false},{"id":"C","text":"Network latency due to some cluster nodes being in different regions from the source data","rationale":"Cross-region placement is not established by the task-duration pattern.","isCorrect":false},{"id":"D","text":"Skew caused by more data being assigned to a subset of spark-partitions.","rationale":"A few heavily loaded partitions can create extreme task skew.","isCorrect":true},{"id":"E","text":"Credential validation errors while pulling data from an external system.","rationale":"No credential errors are reported.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"A few heavily loaded partitions can create extreme task skew.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":12,"images":["questions/025-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":25,"prompt":"A Spark job is taking longer than expected. Using the Spark UI, a data engineer notes that the Min, Median, and Max Durations for tasks in a\nparticular stage show the minimum and median time to complete a task as roughly the same, but the max duration for a task to be roughly 100\ntimes as long as the minimum.\nWhich situation is causing increased duration of the overall job?","options":[{"id":"A","text":"Task queueing resulting from improper thread pool assignment."},{"id":"B","text":"Spill resulting from attached volume storage being too small."},{"id":"C","text":"Network latency due to some cluster nodes being in different regions from the source data"},{"id":"D","text":"Skew caused by more data being assigned to a subset of spark-partitions."},{"id":"E","text":"Credential validation errors while pulling data from an external system."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"best_fit","explanation":"A few exceptionally long tasks are a classic sign of partition skew. The timing pattern supports this diagnosis but is not proof without task-size and spill metrics; the other explanations are not supported by the stated evidence.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":12,"images":["questions/025-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Choose the most likely diagnosis to investigate from the stated task-duration pattern, rather than a proven root cause.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":26,"prompt":"Each configuration below is identical to the extent that each cluster has 400 GB total of RAM, 160 total cores and only one Executor per VM.\nGiven a job with at least one wide transformation, which of the following cluster configurations will result in maximum performance?","options":[{"id":"A","text":"• Total VMs; 1\n• 400 GB per Executor\n• 160 Cores / Executor","rationale":"One worker minimizes inter-worker exchange under the stated criterion.","isCorrect":true},{"id":"B","text":"• Total VMs: 8\n• 50 GB per Executor\n• 20 Cores / Executor","rationale":"Eight workers introduce more inter-worker exchange boundaries.","isCorrect":false},{"id":"C","text":"• Total VMs: 16\n• 25 GB per Executor\n• 10 Cores/Executor","rationale":"Sixteen workers maximize those boundaries among these options.","isCorrect":false},{"id":"D","text":"• Total VMs: 4\n• 100 GB per Executor\n• 40 Cores/Executor","rationale":"Four workers still require inter-worker exchange.","isCorrect":false},{"id":"E","text":"• Total VMs:2\n• 200 GB per Executor\n• 80 Cores / Executor","rationale":"Two workers still require inter-worker exchange.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"One worker minimizes inter-worker exchange under the stated criterion.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":12,"images":["questions/026-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":26,"prompt":"Each configuration below is identical to the extent that each cluster has 400 GB total of RAM, 160 total cores and only one Executor per VM.\nGiven a job with at least one wide transformation, which of the following cluster configurations will result in maximum performance?","options":[{"id":"A","text":"• Total VMs; 1\n• 400 GB per Executor\n• 160 Cores / Executor"},{"id":"B","text":"• Total VMs: 8\n• 50 GB per Executor\n• 20 Cores / Executor"},{"id":"C","text":"• Total VMs: 16\n• 25 GB per Executor\n• 10 Cores/Executor"},{"id":"D","text":"• Total VMs: 4\n• 100 GB per Executor\n• 40 Cores/Executor"},{"id":"E","text":"• Total VMs:2\n• 200 GB per Executor\n• 80 Cores / Executor"}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"A is the intended choice because one large node minimizes inter-node shuffle for equal resources. Maximum performance cannot be guaranteed from core and RAM totals alone; workload, disk, garbage collection and parallelism matter.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":12,"images":["questions/026-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Assume inter-node shuffle is the dominant cost and each proposed VM configuration is available. Choose the layout minimizing that cost, not a universal performance guarantee.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":27,"prompt":"A junior data engineer on your team has implemented the following code block.\nThe view new_events contains a batch of records with the same schema as the events Delta table. The event_id field serves as a unique key for\nthis table.\nWhen this query is executed, what will happen with new records that have the same event_id as an existing record?","options":[{"id":"A","text":"They are merged.","rationale":"No matched-row merge action is defined.","isCorrect":false},{"id":"B","text":"They are ignored.","rationale":"Matching source keys have no applicable action and are ignored.","isCorrect":true},{"id":"C","text":"They are updated.","rationale":"There is no WHEN MATCHED UPDATE clause.","isCorrect":false},{"id":"D","text":"They are inserted.","rationale":"The insert clause applies only to unmatched keys.","isCorrect":false},{"id":"E","text":"They are deleted.","rationale":"No DELETE clause is present.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Matching source keys have no applicable action and are ignored.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":13,"images":["questions/027-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":28,"prompt":"The bronze Delta table has CDF enabled from version 0 and all required change versions are retained. What change records does the following batch append to bronze_history?","options":[{"id":"A","text":"Each time the job is executed, newly updated records will be merged into the target table, overwriting previous values with the same\nprimary keys.","rationale":"There is no keyed MERGE or overwrite of existing rows.","isCorrect":false},{"id":"B","text":"Each time the job is executed, the entire available history of inserted or updated records will be appended to the target table, resulting in\nmany duplicate entries.","rationale":"Reading from version zero and appending replays retained changes.","isCorrect":true},{"id":"C","text":"Each time the job is executed, the target table will be overwritten using the entire history of inserted or updated records, giving the desired\nresult.","rationale":"The write mode is append, not overwrite.","isCorrect":false},{"id":"D","text":"Each time the job is executed, the differences between the original and current versions are calculated; this may result in duplicate entries\nfor some records.","rationale":"CDF enumerates changes; it is not a snapshot-difference query.","isCorrect":false},{"id":"E","text":"Each time the job is executed, only those records that have been inserted or updated since the last execution will be appended to the target\ntable, giving the desired result.","rationale":"A batch read has no saved incremental offset here.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Reading from version zero and appending replays retained changes.","topic":"cdf","sourceUrl":"https://docs.databricks.com/aws/en/tables/features/change-data-feed","sourceTitle":"Use change data feed on Databricks | Databricks on AWS","sourcePage":13,"images":["questions/028-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A junior data engineer seeks to leverage Delta Lake's Change Data Feed functionality to create a Type 1 table representing all of the values that\nhave ever been valid for all rows in a bronze table created with the property delta.enableChangeDataFeed = true. They plan to execute the\nfollowing code as a daily job:\nWhich statement describes the execution and results of running the above query multiple times?","options":[{"id":"A","text":"Each time the job is executed, newly updated records will be merged into the target table, overwriting previous values with the same\nprimary keys."},{"id":"B","text":"Each time the job is executed, the entire available history of inserted or updated records will be appended to the target table, resulting in\nmany duplicate entries."},{"id":"C","text":"Each time the job is executed, the target table will be overwritten using the entire history of inserted or updated records, giving the desired\nresult."},{"id":"D","text":"Each time the job is executed, the differences between the original and current versions are calculated; this may result in duplicate entries\nfor some records."},{"id":"E","text":"Each time the job is executed, only those records that have been inserted or updated since the last execution will be appended to the target\ntable, giving the desired result."}],"correctAnswers":["B"],"explanation":"The batch CDF read starts at version 0 every time and appends, replaying available changes and producing duplicates. It has no incremental checkpoint or MERGE. A Type 1 table would not itself retain every historical value.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"(spark.read.format(\"delta\")\n .option(\"readChangeFeed\", \"true\")\n .option(\"startingVersion\", 0)\n .table(\"bronze\")\n .filter(\"_change_type IN ('insert', 'update_postimage')\")\n .write.format(\"delta\").mode(\"append\")\n .saveAsTable(\"bronze_history\"))","reviewNote":"Second audit: Corrected the batch writer API and described the result as an event history, not an SCD Type 1 table.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":29,"prompt":"A new data engineer notices that a critical field was omitted from an application that writes its Kafka source to Delta Lake. This happened even\nthough the critical field was in the Kafka source. That field was further missing from data written to dependent, long-term storage. The retention\nthreshold on the Kafka service is seven days. The pipeline has been in production for three months.\nWhich describes how Delta Lake can help to avoid data loss of this nature in the future?","options":[{"id":"A","text":"The Delta log and Structured Streaming checkpoints record the full history of the Kafka producer.","rationale":"Checkpoints and transaction metadata do not archive full Kafka payloads.","isCorrect":false},{"id":"B","text":"Delta Lake schema evolution can retroactively calculate the correct value for newly added fields, as long as the data was in the original\nsource.","rationale":"Schema evolution cannot reconstruct values that were never retained.","isCorrect":false},{"id":"C","text":"Delta Lake automatically checks that all fields present in the source data are included in the ingestion layer.","rationale":"Completeness requires explicit ingestion design, not an automatic guarantee.","isCorrect":false},{"id":"D","text":"Data can never be permanently dropped or deleted from Delta Lake, so data loss is not possible under any circumstance.","rationale":"Delta data can be permanently removed.","isCorrect":false},{"id":"E","text":"Ingesting all raw data and metadata from Kafka to a bronze Delta table creates a permanent, replayable history of the data state.","rationale":"Retaining complete raw payloads allows later replay.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"Retaining complete raw payloads allows later replay.","topic":"medallion","sourceUrl":"https://docs.databricks.com/aws/en/lakehouse/medallion","sourceTitle":"What is the medallion lakehouse architecture? | Databricks on AWS","sourcePage":14,"images":["questions/029-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":30,"prompt":"A nightly job ingests data into a Delta Lake table using the following code:\nThe next step in the pipeline requires a function that returns an object that can be used to manipulate new records that have not yet been\nprocessed to the next table in the pipeline.\nWhich code snippet completes this function definition?\ndef new_records():","options":[{"id":"A","text":"return spark.readStream.table(\"bronze\")","rationale":"A streaming table read supports checkpointed downstream incremental processing.","isCorrect":true},{"id":"B","text":"return spark.readStream.load(\"bronze\")","rationale":"load treats bronze as a path, not a registered table name.","isCorrect":false},{"id":"C","text":"[Code choice shown in the original PDF image]","rationale":"Equality with the current timestamp does not identify unprocessed rows.","isCorrect":false},{"id":"D","text":"return spark.read.option(\"readChangeFeed\", \"true\").table (\"bronze\")","rationale":"A batch CDF read alone does not maintain processing progress.","isCorrect":false},{"id":"E","text":"[Code choice shown in the original PDF image]","rationale":"A source-path filter does not track all unprocessed batches.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A streaming table read supports checkpointed downstream incremental processing.","topic":"deltastream","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/delta-lake","sourceTitle":"Delta Lake table streaming reads and writes | Databricks on AWS","sourcePage":14,"images":["questions/030-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":31,"prompt":"A junior data engineer is working to implement logic for a Lakehouse table named silver_device_recordings. The source data contains 100 unique\nfields in a highly nested JSON structure.\nThe silver_device_recordings table will be used downstream to power several production monitoring dashboards and a production model. At\npresent, 45 of the 100 fields are being used in at least one of these applications.\nThe data engineer is trying to determine the best approach for dealing with schema declaration given the highly-nested structure of the data and\nthe numerous fields.\nWhich of the following accurately presents information about Delta Lake and Databricks that may impact their decision-making process?","options":[{"id":"A","text":"The Tungsten encoding used by Databricks is optimized for storing string data; newly-added native support for querying JSON strings\nmeans that string types are always most efficient.","rationale":"Strings are not universally the most efficient representation.","isCorrect":false},{"id":"B","text":"Because Delta Lake uses Parquet for data storage, data types can be easily evolved by just modifying file footer information in place.","rationale":"Parquet types cannot be changed merely by editing footers.","isCorrect":false},{"id":"C","text":"Human labor in writing code is the largest cost associated with data engineering workloads; as such, automating table declaration logic\nshould be a priority in all migration workloads.","rationale":"Labor cost is workload-dependent, not a universal schema rule.","isCorrect":false},{"id":"D","text":"Because Databricks will infer schema using types that allow all observed data to be processed, setting types manually provides greater\nassurance of data quality enforcement.","rationale":"Explicit schemas enforce intended types more deliberately.","isCorrect":true},{"id":"E","text":"Schema inference and evolution on Databricks ensure that inferred types will always accurately match the data types used by downstream\nsystems.","rationale":"Inferred types need not match downstream contracts.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Explicit schemas enforce intended types more deliberately.","topic":"schema","sourceUrl":"https://docs.databricks.com/aws/en/tables/update-schema","sourceTitle":"Update table schemas with schema evolution | Databricks on AWS","sourcePage":15,"images":["questions/031-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":32,"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source tables has been de-duplicated and validated, which\nstatement describes what will occur when this code is executed?","options":[{"id":"A","text":"A batch job will update the enriched_itemized_orders_by_account table, replacing only those rows that have different values than the\ncurrent version of the table, using accountID as the primary key.","rationale":"Overwrite is not a primary-key upsert.","isCorrect":false},{"id":"B","text":"The enriched_itemized_orders_by_account table will be overwritten using the current valid version of data in each of the three tables\nreferenced in the join logic.","rationale":"The batch join result replaces the target table.","isCorrect":true},{"id":"C","text":"An incremental job will leverage information in the state store to identify unjoined rows in the source tables and write these rows to the\nenriched_iteinized_orders_by_account table.","rationale":"No streaming state store is used.","isCorrect":false},{"id":"D","text":"An incremental job will detect if new rows have been written to any of the source tables; if new rows are detected, all results will be\nrecalculated and used to overwrite the enriched_itemized_orders_by_account table.","rationale":"The code is a batch computation, not a change detector.","isCorrect":false},{"id":"E","text":"No computation will occur until enriched_itemized_orders_by_account is queried; upon query materialization, results will be calculated\nusing the current valid version of data in each of the three tables referenced in the join logic.","rationale":"A write executes the computation; this is not a deferred view.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"The batch join result replaces the target table.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":16,"images":["questions/032-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source tables has been de-duplicated and validated, which\nstatement describes what will occur when this code is executed?","options":[{"id":"A","text":"A batch job will update the enriched_itemized_orders_by_account table, replacing only those rows that have different values than the\ncurrent version of the table, using accountID as the primary key."},{"id":"B","text":"The enriched_itemized_orders_by_account table will be overwritten using the current valid version of data in each of the three tables\nreferenced in the join logic."},{"id":"C","text":"An incremental job will leverage information in the state store to identify unjoined rows in the source tables and write these rows to the\nenriched_iteinized_orders_by_account table."},{"id":"D","text":"An incremental job will detect if new rows have been written to any of the source tables; if new rows are detected, all results will be\nrecalculated and used to overwrite the enriched_itemized_orders_by_account table."},{"id":"E","text":"No computation will occur until enriched_itemized_orders_by_account is queried; upon query materialization, results will be calculated\nusing the current valid version of data in each of the three tables referenced in the join logic."}],"correctAnswers":["B"],"explanation":"These are batch reads followed by mode('overwrite'). The current joined results replace the target; there is no incremental state, key-based upsert or deferred view evaluation.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"accountDF = spark.table(\"accounts\")\norderDF = spark.table(\"orders\")\nitemDF = spark.table(\"items\")\norderWithItemDF = (orderDF.join(itemDF, \"itemID\")\n .select(orderDF.accountID, orderDF.itemID, itemDF.itemName))\nfinalDF = (accountDF.join(orderWithItemDF, \"accountID\")\n .select(orderWithItemDF[\"*\"], accountDF.city))\n(finalDF.write.format(\"delta\").mode(\"overwrite\")\n .saveAsTable(\"enriched_itemized_orders_by_account\"))","reviewNote":"Second audit: Corrected DataFrameWriter.table to saveAsTable; the operation remains a batch overwrite.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":33,"prompt":"The data engineering team is migrating an enterprise system with thousands of tables and views into the Lakehouse. They plan to implement the\ntarget architecture using a series of bronze, silver, and gold tables. Bronze tables will almost exclusively be used by production data engineering\nworkloads, while silver tables will be used to support both data engineering and machine learning workloads. Gold tables will largely serve\nbusiness intelligence and reporting purposes. While personal identifying information (PII) exists in all tiers of data, pseudonymization and\nanonymization rules are in place for all data at the silver and gold levels.\nThe organization is interested in reducing security concerns while maximizing the ability to collaborate across diverse teams.\nWhich statement exemplifies best practices for implementing this system?","options":[{"id":"A","text":"Isolating tables in separate databases based on data quality tiers allows for easy permissions management through database ACLs and\nallows physical separation of default storage locations for managed tables.","rationale":"Tier-specific schemas simplify grants and managed storage separation.","isCorrect":true},{"id":"B","text":"Because databases on Databricks are merely a logical construct, choices around database organization do not impact security or\ndiscoverability in the Lakehouse.","rationale":"Schema organization does affect governance and discovery.","isCorrect":false},{"id":"C","text":"Storing all production tables in a single database provides a unified view of all data assets available throughout the Lakehouse, simplifying\ndiscoverability by granting all users view privileges on this database.","rationale":"Broad access in one schema weakens the required isolation.","isCorrect":false},{"id":"D","text":"Working in the default Databricks database provides the greatest security when working with managed tables, as these will be created in\nthe DBFS root.","rationale":"The default database is not inherently most secure.","isCorrect":false},{"id":"E","text":"Because all tables must live in the same storage containers used for the database they're created in, organizations should be prepared to\ncreate between dozens and thousands of databases depending on their data isolation requirements.","rationale":"External tables need not share one schema storage location.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Tier-specific schemas simplify grants and managed storage separation.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":17,"images":["questions/033-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":34,"prompt":"The data architect has mandated that all tables in the Lakehouse should be configured as external Delta Lake tables.\nWhich approach will ensure that this requirement is met?","options":[{"id":"A","text":"Whenever a database is being created, make sure that the LOCATION keyword is used","rationale":"A database location does not make contained tables external.","isCorrect":false},{"id":"B","text":"When configuring an external data warehouse for all table storage, leverage Databricks for all ELT.","rationale":"An external warehouse is unrelated to the table type.","isCorrect":false},{"id":"C","text":"Whenever a table is being created, make sure that the LOCATION keyword is used.","rationale":"A table-level LOCATION specifies external storage.","isCorrect":true},{"id":"D","text":"When tables are created, make sure that the EXTERNAL keyword is used in the CREATE TABLE statement.","rationale":"EXTERNAL alone lacks the required storage location.","isCorrect":false},{"id":"E","text":"When the workspace is being configured, make sure that external cloud object storage has been mounted.","rationale":"Mounting storage does not determine a table's management type.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"A table-level LOCATION specifies external storage.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":17,"images":["questions/034-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":35,"prompt":"To reduce storage and compute costs, the data engineering team has been tasked with curating a series of aggregate tables leveraged by\nbusiness intelligence dashboards, customer-facing applications, production machine learning models, and ad hoc analytical queries.\nThe data engineering team has been made aware of new requirements from a customer-facing application, which is the only downstream\nworkload they manage entirely. As a result, an aggregate table used by numerous teams across the organization will need to have a number of\nfields renamed, and additional fields will also be added.\nWhich of the solutions addresses the situation while minimally interrupting other teams in the organization without increasing the number of\ntables that need to be managed?","options":[{"id":"A","text":"Send all users notice that the schema for the table will be changing; include in the communication the logic necessary to revert the new\ntable schema to match historic queries.","rationale":"Notification alone breaks existing consumers at cutover.","isCorrect":false},{"id":"B","text":"Configure a new table with all the requisite fields and new names and use this as the source for the customer-facing application; create a\nview that maintains the original data schema and table name by aliasing select fields from the new table.","rationale":"A compatibility view preserves old names with one physical table.","isCorrect":true},{"id":"C","text":"Create a new table with the required schema and new fields and use Delta Lake's deep clone functionality to sync up changes committed to\none table to the corresponding table.","rationale":"Deep clones are independent snapshots, not automatic bidirectional sync.","isCorrect":false},{"id":"D","text":"Replace the current table definition with a logical view defined with the query logic currently writing the aggregate table; create a new table\nto power the customer-facing application.","rationale":"Recomputing original aggregation through a view increases ongoing compute.","isCorrect":false},{"id":"E","text":"Add a table comment warning all users that the table schema and field names will be changing on a given date; overwrite the table in place\nto the specifications of the customer-facing application.","rationale":"Comments do not preserve the existing schema contract.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"A compatibility view preserves old names with one physical table.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":18,"images":["questions/035-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":35,"prompt":"To reduce storage and compute costs, the data engineering team has been tasked with curating a series of aggregate tables leveraged by\nbusiness intelligence dashboards, customer-facing applications, production machine learning models, and ad hoc analytical queries.\nThe data engineering team has been made aware of new requirements from a customer-facing application, which is the only downstream\nworkload they manage entirely. As a result, an aggregate table used by numerous teams across the organization will need to have a number of\nfields renamed, and additional fields will also be added.\nWhich of the solutions addresses the situation while minimally interrupting other teams in the organization without increasing the number of\ntables that need to be managed?","options":[{"id":"A","text":"Send all users notice that the schema for the table will be changing; include in the communication the logic necessary to revert the new\ntable schema to match historic queries."},{"id":"B","text":"Configure a new table with all the requisite fields and new names and use this as the source for the customer-facing application; create a\nview that maintains the original data schema and table name by aliasing select fields from the new table."},{"id":"C","text":"Create a new table with the required schema and new fields and use Delta Lake's deep clone functionality to sync up changes committed to\none table to the corresponding table."},{"id":"D","text":"Replace the current table definition with a logical view defined with the query logic currently writing the aggregate table; create a new table\nto power the customer-facing application."},{"id":"E","text":"Add a table comment warning all users that the table schema and field names will be changing on a given date; overwrite the table in place\nto the specifications of the customer-facing application."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Replace the physical table with the new schema and preserve the old contract using a view under the old name. This avoids maintaining two physical tables; deployment must migrate/rename the original table to free its name.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":18,"images":["questions/035-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"The migration retires the old physical table and frees its name for a compatibility view. Count physical tables after cutover.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":36,"prompt":"A Delta Lake table representing metadata about content posts from users has the following schema: user_id LONG, post_text STRING, post_id\nSTRING, longitude FLOAT, latitude FLOAT, post_time TIMESTAMP, date DATE\nThis table is partitioned by the date column. A query is run with the following filter: longitude < 20 & longitude > -20\nWhich statement describes how data will be filtered?","options":[{"id":"A","text":"Statistics in the Delta Log will be used to identify partitions that might Include files in the filtered range.","rationale":"Skipping uses candidate data files, not only partition boundaries.","isCorrect":false},{"id":"B","text":"No file skipping will occur because the optimizer does not know the relationship between the partition column and the longitude.","rationale":"Nonpartition columns can still use file statistics.","isCorrect":false},{"id":"C","text":"The Delta Engine will use row-level statistics in the transaction log to identify the flies that meet the filter criteria.","rationale":"The statistics are file-level, not row-level indexes.","isCorrect":false},{"id":"D","text":"Statistics in the Delta Log will be used to identify data files that might include records in the filtered range.","rationale":"Logged longitude ranges can exclude irrelevant data files.","isCorrect":true},{"id":"E","text":"The Delta Engine will scan the parquet file footers to identify each row that meets the filter criteria.","rationale":"Parquet footers do not identify every matching row.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Logged longitude ranges can exclude irrelevant data files.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":18,"images":["questions/036-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":37,"prompt":"A small company based in the United States has recently contracted a consulting firm in India to implement several new data engineering\npipelines to power artificial intelligence applications. All the company's data is stored in regional cloud storage in the United States.\nThe workspace administrator at the company is uncertain about where the Databricks workspace used by the contractors should be deployed.\nAssuming that all data governance considerations are accounted for, which statement accurately informs this decision?","options":[{"id":"A","text":"Databricks runs HDFS on cloud volume storage; as such, cloud virtual machines must be deployed in the region where the data is stored.","rationale":"Databricks does not require HDFS-backed data placement.","isCorrect":false},{"id":"B","text":"Databricks workspaces do not rely on any regional infrastructure; as such, the decision should be made based upon what is most\nconvenient for the workspace administrator.","rationale":"Workspaces and compute have regional infrastructure.","isCorrect":false},{"id":"C","text":"Cross-region reads and writes can incur significant costs and latency; whenever possible, compute should be deployed in the same region\nthe data is stored.","rationale":"Colocating compute and storage reduces network cost and latency.","isCorrect":true},{"id":"D","text":"Databricks leverages user workstations as the driver during interactive development; as such, users should always use a workspace\ndeployed in a region they are physically near.","rationale":"The user's workstation is not the Spark driver.","isCorrect":false},{"id":"E","text":"Databricks notebooks send all executable code from the user’s browser to virtual machines over the open internet; whenever possible,\nchoosing a workspace region near the end users is the most secure.","rationale":"Browser proximity is not the main data-locality security criterion.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Colocating compute and storage reduces network cost and latency.","topic":"regions","sourceUrl":"https://docs.databricks.com/aws/en/resources/supported-regions","sourceTitle":"Databricks clouds and regions | Databricks on AWS","sourcePage":19,"images":["questions/037-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":38,"prompt":"The downstream consumers of a Delta Lake table have been complaining about data quality issues impacting performance in their applications.\nSpecifically, they have complained that invalid latitude and longitude values in the activity_details table have been breaking their ability to use\nother geolocation processes.\nA junior engineer has written the following code to add CHECK constraints to the Delta Lake table:\nA senior engineer has confirmed the above logic is correct and the valid ranges for latitude and longitude are provided, but the code fails when\nexecuted.\nWhich statement explains the cause of this failure?","options":[{"id":"A","text":"Because another team uses this table to support a frequently running application, two-phase locking is preventing the operation from\ncommitting.","rationale":"Optimistic transactions are not blocked by the alleged two-phase locking.","isCorrect":false},{"id":"B","text":"The activity_details table already exists; CHECK constraints can only be added during initial table creation.","rationale":"CHECK constraints can be added to existing tables.","isCorrect":false},{"id":"C","text":"The activity_details table already contains records that violate the constraints; all existing data must pass CHECK constraints in order to\nadd them to an existing table.","rationale":"Existing rows must satisfy the new constraint.","isCorrect":true},{"id":"D","text":"The activity_details table already contains records; CHECK constraints can only be added prior to inserting values into a table.","rationale":"Existing valid data does not prevent adding constraints.","isCorrect":false},{"id":"E","text":"The current table schema does not contain the field valid_coordinates; schema evolution will need to be enabled before altering the table to\nadd a constraint.","rationale":"valid_coordinates names a constraint, not a required data column.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Existing rows must satisfy the new constraint.","topic":"constraints","sourceUrl":"https://docs.databricks.com/aws/en/tables/constraints","sourceTitle":"Constraints on Databricks | Databricks on AWS","sourcePage":19,"images":["questions/038-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":39,"prompt":"Which of the following is true of Delta Lake and the Lakehouse?","options":[{"id":"A","text":"Because Parquet compresses data row by row. strings will only be compressed when a character is repeated multiple times.","rationale":"Parquet is columnar, not row-by-row string compression.","isCorrect":false},{"id":"B","text":"Delta Lake automatically collects statistics on the first 32 columns of each table which are leveraged in data skipping based on query\nfilters.","rationale":"The stated traditional configuration covers the first 32 columns.","isCorrect":true},{"id":"C","text":"Views in the Lakehouse maintain a valid cache of the most recent versions of source tables at all times.","rationale":"Ordinary views do not maintain an automatic data cache.","isCorrect":false},{"id":"D","text":"Primary and foreign key constraints can be leveraged to ensure duplicate values are never entered into a dimension table.","rationale":"Primary and foreign keys are informational, not enforced uniqueness.","isCorrect":false},{"id":"E","text":"Z-order can only be applied to numeric values stored in Delta Lake tables.","rationale":"Z-ordering is not limited to numeric columns.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"The stated traditional configuration covers the first 32 columns.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":20,"images":["questions/039-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":39,"prompt":"Which of the following is true of Delta Lake and the Lakehouse?","options":[{"id":"A","text":"Because Parquet compresses data row by row. strings will only be compressed when a character is repeated multiple times."},{"id":"B","text":"Delta Lake automatically collects statistics on the first 32 columns of each table which are leveraged in data skipping based on query\nfilters."},{"id":"C","text":"Views in the Lakehouse maintain a valid cache of the most recent versions of source tables at all times."},{"id":"D","text":"Primary and foreign key constraints can be leveraged to ensure duplicate values are never entered into a dimension table."},{"id":"E","text":"Z-order can only be applied to numeric values stored in Delta Lake tables."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"legacy","explanation":"B describes the traditional default statistics coverage. It is not universal today: predictive optimization on Unity Catalog managed tables can choose columns beyond the first 32. Keys are informational, views are not automatic caches, and ZORDER is not numeric-only.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":20,"images":["questions/039-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use a Delta table with the traditional default data-skipping statistics configuration; predictive optimization and custom statistics-column settings are disabled.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":40,"prompt":"The view updates represents an incremental batch of all newly ingested data to be inserted or updated in the customers table.\nThe following logic is used to process these records.\nWhich statement describes this implementation?","options":[{"id":"A","text":"The customers table is implemented as a Type 3 table; old values are maintained as a new column alongside the current value.","rationale":"Type 3 keeps a previous value in another column.","isCorrect":false},{"id":"B","text":"The customers table is implemented as a Type 2 table; old values are maintained but marked as no longer current and new values are\ninserted.","rationale":"Old versions remain with current=false and new versions are inserted.","isCorrect":true},{"id":"C","text":"The customers table is implemented as a Type 0 table; all writes are append only with no changes to existing values.","rationale":"Existing rows are updated, so this is not Type 0.","isCorrect":false},{"id":"D","text":"The customers table is implemented as a Type 1 table; old values are overwritten by new values and no history is maintained.","rationale":"History is preserved rather than overwritten in place.","isCorrect":false},{"id":"E","text":"The customers table is implemented as a Type 2 table; old values are overwritten and new customers are appended.","rationale":"Type 2 does not overwrite away the old versions.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Old versions remain with current=false and new versions are inserted.","topic":"scd","sourceUrl":"https://docs.delta.io/delta-update/","sourceTitle":"Table deletes, updates, and merges | Delta Lake","sourcePage":20,"images":["questions/040-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"The view updates represents an incremental batch of all newly ingested data to be inserted or updated in the customers table.\nThe following logic is used to process these records.\nWhich statement describes this implementation?","options":[{"id":"A","text":"The customers table is implemented as a Type 3 table; old values are maintained as a new column alongside the current value."},{"id":"B","text":"The customers table is implemented as a Type 2 table; old values are maintained but marked as no longer current and new values are\ninserted."},{"id":"C","text":"The customers table is implemented as a Type 0 table; all writes are append only with no changes to existing values."},{"id":"D","text":"The customers table is implemented as a Type 1 table; old values are overwritten by new values and no history is maintained."},{"id":"E","text":"The customers table is implemented as a Type 2 table; old values are overwritten and new customers are appended."}],"correctAnswers":["B"],"explanation":"The MERGE closes the old current row and inserts a new version with effective dates. That is Type 2 history, rather than overwriting in place or storing an old value in an extra column.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"studyContext":"updates has at most one change per customer_id in this batch; customers has one current row per existing customer.","code":"MERGE INTO customers AS c\nUSING (\n  SELECT u.customer_id AS merge_key, u.* FROM updates AS u\n  UNION ALL\n  SELECT NULL AS merge_key, u.*\n  FROM updates AS u JOIN customers AS old\n    ON u.customer_id = old.customer_id\n  WHERE old.current = true AND NOT (u.address <=> old.address)\n) AS s\nON c.customer_id = s.merge_key\nWHEN MATCHED AND c.current = true AND NOT (c.address <=> s.address)\n  THEN UPDATE SET current = false, end_date = s.effective_date\nWHEN NOT MATCHED THEN INSERT\n  (customer_id, address, current, effective_date, end_date)\n  VALUES (s.customer_id, s.address, true, s.effective_date, NULL)","reviewNote":"Second audit: Normalized inconsistent merge-key aliases and used null-safe address comparison.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":41,"prompt":"The DevOps team has configured a production workload as a collection of notebooks scheduled to run daily using the Jobs UI. A new data\nengineering hire is onboarding to the team and has requested access to one of these notebooks to review the production logic.\nWhat are the maximum notebook permissions that can be granted to the user without allowing accidental changes to production code or data?","options":[{"id":"A","text":"Can Manage","rationale":"CAN MANAGE permits more than read-only inspection.","isCorrect":false},{"id":"B","text":"Can Edit","rationale":"CAN EDIT permits production-code changes.","isCorrect":false},{"id":"C","text":"No permissions","rationale":"No permissions prevents the requested inspection.","isCorrect":false},{"id":"D","text":"Can Read","rationale":"CAN READ permits inspection without edit or execution rights.","isCorrect":true},{"id":"E","text":"Can Run","rationale":"CAN RUN can execute code that modifies data.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"CAN READ permits inspection without edit or execution rights.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":21,"images":["questions/041-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":42,"prompt":"A table named user_ltv is being used to create a view that will be used by data analysts on various teams. Users in the workspace are configured\ninto groups, which are used for setting up data access using ACLs.\nThe user_ltv table has the following schema:\nemail STRING, age INT, ltv INT\nThe following view definition is executed:\nAn analyst who is not a member of the marketing group executes the following query:\nSELECT * FROM email_ltv -\nWhich statement describes the results returned by this query?","options":[{"id":"A","text":"Three columns will be returned, but one column will be named \"REDACTED\" and contain only null values.","rationale":"The alias remains email and values are strings, not nulls.","isCorrect":false},{"id":"B","text":"Only the email and ltv columns will be returned; the email column will contain all null values.","rationale":"The CASE returns REDACTED, not null.","isCorrect":false},{"id":"C","text":"The email and ltv columns will be returned with the values in user_ltv.","rationale":"Nonmarketing users do not receive raw emails.","isCorrect":false},{"id":"D","text":"The email.age, and ltv columns will be returned with the values in user_ltv.","rationale":"The view does not select age.","isCorrect":false},{"id":"E","text":"Only the email and ltv columns will be returned; the email column will contain the string \"REDACTED\" in each row.","rationale":"The view selects email and ltv and masks email with REDACTED.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"The view selects email and ltv and masks email with REDACTED.","topic":"dynamicviews","sourceUrl":"https://docs.databricks.com/aws/en/views/dynamic","sourceTitle":"Create a dynamic view | Databricks on AWS","sourcePage":21,"images":["questions/042-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":43,"prompt":"The data governance team has instituted a requirement that all tables containing Personal Identifiable Information (PH) must be clearly\nannotated. This includes adding column comments, table comments, and setting the custom table property \"contains_pii\" = true.\nThe following SQL DDL statement is executed to create a new table:\nWhich command allows manual confirmation that these three requirements have been met?","options":[{"id":"A","text":"DESCRIBE EXTENDED dev.pii_test","rationale":"Extended describe includes columns, comments and table properties.","isCorrect":true},{"id":"B","text":"DESCRIBE DETAIL dev.pii_test","rationale":"Detail omits the required per-column comments.","isCorrect":false},{"id":"C","text":"SHOW TBLPROPERTIES dev.pii_test","rationale":"Table properties alone omit column and table comments.","isCorrect":false},{"id":"D","text":"DESCRIBE HISTORY dev.pii_test","rationale":"History lists operations, not the full current column definition.","isCorrect":false},{"id":"E","text":"SHOW TABLES dev","rationale":"SHOW TABLES lists relations, not all required metadata.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Extended describe includes columns, comments and table properties.","topic":"describe","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-aux-describe-table","sourceTitle":"DESCRIBE TABLE | Databricks on AWS","sourcePage":22,"images":["questions/043-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":44,"prompt":"The data governance team is reviewing code used for deleting records for compliance with GDPR. They note the following logic is used to delete\nrecords from the Delta Lake table named users.\nAssuming that user_id is a unique identifying key and that delete_requests contains all users that have requested deletion, which statement\ndescribes whether successfully executing the above logic guarantees that the records to be deleted are no longer accessible and why?","options":[{"id":"A","text":"Yes; Delta Lake ACID guarantees provide assurance that the DELETE command succeeded fully and permanently purged these records.","rationale":"ACID changes the current snapshot; it does not purge history.","isCorrect":false},{"id":"B","text":"No; the Delta cache may return records from previous versions of the table until the cluster is restarted.","rationale":"Historical retention is the issue, not a stale-cache guarantee.","isCorrect":false},{"id":"C","text":"Yes; the Delta cache immediately updates to reflect the latest data files recorded to disk.","rationale":"Cache refresh does not prove physical removal of old files.","isCorrect":false},{"id":"D","text":"No; the Delta Lake DELETE command only provides ACID guarantees when combined with the MERGE INTO command.","rationale":"DELETE is independently transactional without MERGE.","isCorrect":false},{"id":"E","text":"No; files containing deleted records may still be accessible with time travel until a VACUUM command is used to remove invalidated data\nfiles.","rationale":"Retained historical files remain accessible until eligible physical cleanup.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"Retained historical files remain accessible until eligible physical cleanup.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":22,"images":["questions/044-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":45,"prompt":"An external object storage container has been mounted to the location /mnt/finance_eda_bucket.\nThe following logic was executed to create a database for the finance team:\nAfter the database was successfully created and permissions configured, a member of the finance team runs the following code:\nIf all users on the finance team are members of the finance group, which statement describes how the tx_sales table will be created?","options":[{"id":"A","text":"A logical table will persist the query plan to the Hive Metastore in the Databricks control plane.","rationale":"CTAS creates data, not a logical view plan.","isCorrect":false},{"id":"B","text":"An external table will be created in the storage container mounted to /mnt/finance_eda_bucket.","rationale":"No table-level LOCATION makes this external.","isCorrect":false},{"id":"C","text":"A logical table will persist the physical plan to the Hive Metastore in the Databricks control plane.","rationale":"CTAS is not a stored physical-plan view.","isCorrect":false},{"id":"D","text":"An managed table will be created in the storage container mounted to /mnt/finance_eda_bucket.","rationale":"The managed table inherits the database's mounted storage location.","isCorrect":true},{"id":"E","text":"A managed table will be created in the DBFS root storage container.","rationale":"An explicit database location overrides the default root location.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The managed table inherits the database's mounted storage location.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":23,"images":["questions/045-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"original":{"id":45,"prompt":"An external object storage container has been mounted to the location /mnt/finance_eda_bucket.\nThe following logic was executed to create a database for the finance team:\nAfter the database was successfully created and permissions configured, a member of the finance team runs the following code:\nIf all users on the finance team are members of the finance group, which statement describes how the tx_sales table will be created?","options":[{"id":"A","text":"A logical table will persist the query plan to the Hive Metastore in the Databricks control plane."},{"id":"B","text":"An external table will be created in the storage container mounted to /mnt/finance_eda_bucket."},{"id":"C","text":"A logical table will persist the physical plan to the Hive Metastore in the Databricks control plane."},{"id":"D","text":"An managed table will be created in the storage container mounted to /mnt/finance_eda_bucket."},{"id":"E","text":"A managed table will be created in the DBFS root storage container."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"With the shown Hive-metastore database LOCATION and CTAS without a table LOCATION, this is a managed table stored under the database's mounted location. External database storage does not automatically make the table external.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":23,"images":["questions/045-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use the legacy Hive metastore and its managed-table behavior, not Unity Catalog. The shown database and table definitions apply.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":46,"prompt":"Although the Databricks Utilities Secrets module provides tools to store sensitive credentials and avoid accidentally displaying them in plain text\nusers should still be careful with which credentials are stored here and which users have access to using these secrets.\nWhich statement describes a limitation of Databricks Secrets?","options":[{"id":"A","text":"Because the SHA256 hash is used to obfuscate stored secrets, reversing this hash will display the value in plain text.","rationale":"Secrets are not protected by a reversible SHA-256 hash.","isCorrect":false},{"id":"B","text":"Account administrators can see all secrets in plain text by logging on to the Databricks Accounts console.","rationale":"The account console does not provide the claimed plaintext listing.","isCorrect":false},{"id":"C","text":"Secrets are stored in an administrators-only table within the Hive Metastore; database administrators have permission to query this table by\ndefault.","rationale":"Secrets are not an administrators-only Hive table.","isCorrect":false},{"id":"D","text":"Iterating through a stored secret and printing each character will display secret contents in plain text.","rationale":"Transforming or splitting secrets can bypass display redaction.","isCorrect":true},{"id":"E","text":"The GET /api/2.0/secrets/list endpoint returns the plaintext values of all secrets in a scope.","rationale":"The list endpoint returns metadata, not plaintext secret values.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Transforming or splitting secrets can bypass display redaction.","topic":"secrets","sourceUrl":"https://docs.databricks.com/aws/en/security/secrets/","sourceTitle":"Secret management | Databricks on AWS","sourcePage":23,"images":["questions/046-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"Although the Databricks Utilities Secrets module provides tools to store sensitive credentials and avoid accidentally displaying them in plain text\nusers should still be careful with which credentials are stored here and which users have access to using these secrets.\nWhich statement describes a limitation of Databricks Secrets?","options":[{"id":"A","text":"Because the SHA256 hash is used to obfuscate stored secrets, reversing this hash will display the value in plain text."},{"id":"B","text":"Account administrators can see all secrets in plain text by logging on to the Databricks Accounts console."},{"id":"C","text":"Secrets are stored in an administrators-only table within the Hive Metastore; database administrators have permission to query this table by\ndefault."},{"id":"D","text":"Iterating through a stored secret and printing each character will display secret contents in plain text."},{"id":"E","text":"The Databricks REST API can be used to list secrets in plain text if the personal access token has proper credentials."}],"correctAnswers":["D"],"explanation":"Redaction is a best-effort output safeguard, not protection from an authorized reader intentionally transforming a secret. Character-by-character printing can bypass literal-value redaction; the other explanations misdescribe storage or access.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Distinguished metadata listing from authorized secret-value retrieval.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":47,"prompt":"What statement is true regarding the retention of job run history?","options":[{"id":"A","text":"It is retained until you export or delete job run logs","rationale":"Run history is not retained indefinitely until manual deletion.","isCorrect":false},{"id":"B","text":"It is retained for 30 days, during which time you can deliver job run logs to DBFS or S3","rationale":"The stated Jobs run-history retention is not 30 days.","isCorrect":false},{"id":"C","text":"It is retained for 60 days, during which you can export notebook run results to HTML","rationale":"Jobs retains runs up to 60 days; export before expiry.","isCorrect":true},{"id":"D","text":"It is retained for 60 days, after which logs are archived","rationale":"There is no automatic permanent archive promised here.","isCorrect":false},{"id":"E","text":"It is retained for 90 days or until the run-id is re-used through custom run configuration","rationale":"Run IDs are not reused to extend history retention.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Jobs retains runs up to 60 days; export before expiry.","topic":"jobmonitor","sourceUrl":"https://docs.databricks.com/aws/en/jobs/monitor","sourceTitle":"Monitor Lakeflow Jobs | Databricks on AWS","sourcePage":23,"images":["questions/047-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":48,"prompt":"A data engineer, User A, has promoted a new pipeline to production by using the REST API to programmatically create several jobs. A DevOps\nengineer, User B, has configured an external orchestration tool to trigger job runs through the REST API. Both users authorized the REST API calls\nusing their personal access tokens.\nWhich statement describes the contents of the workspace audit logs concerning these events?","options":[{"id":"A","text":"Because the REST API was used for job creation and triggering runs, a Service Principal will be automatically used to identify these events.","rationale":"A personal token does not automatically become a service principal.","isCorrect":false},{"id":"B","text":"Because User B last configured the jobs, their identity will be associated with both the job creation events and the job run events.","rationale":"The trigger caller does not replace the job-creation actor.","isCorrect":false},{"id":"C","text":"Because these events are managed separately, User A will have their identity associated with the job creation events and User B will have\ntheir identity associated with the job run events.","rationale":"Audit events record the authenticated actor for each action.","isCorrect":true},{"id":"D","text":"Because the REST API was used for job creation and triggering runs, user identity will not be captured in the audit logs.","rationale":"API actions still have authenticated audit identities.","isCorrect":false},{"id":"E","text":"Because User A created the jobs, their identity will be associated with both the job creation events and the job run events.","rationale":"The creator does not become the actor for another user's API call.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Audit events record the authenticated actor for each action.","topic":"audit","sourceUrl":"https://docs.databricks.com/aws/en/admin/account-settings/audit-logs","sourceTitle":"Audit log reference | Databricks on AWS","sourcePage":24,"images":["questions/048-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":49,"prompt":"A user new to Databricks is trying to troubleshoot long execution times for some pipeline logic they are working on. Presently, the user is\nexecuting code cell-by-cell, using display() calls to confirm code is producing the logically correct results as new transformations are added to an\noperation. To get a measure of average time to execute, the user is running each cell multiple times interactively.\nWhich of the following adjustments will get a more accurate measure of how code is likely to perform in production?","options":[{"id":"A","text":"Scala is the only language that can be accurately tested using interactive notebooks; because the best performance is achieved by using\nScala code compiled to JARs, all PySpark and Spark SQL logic should be refactored.","rationale":"Scala is not the only language that can be benchmarked.","isCorrect":false},{"id":"B","text":"The only way to meaningfully troubleshoot code execution times in development notebooks Is to use production-sized data and production-\nsized clusters with Run All execution.","rationale":"Production-scale runs are useful but not the only diagnostic technique.","isCorrect":false},{"id":"C","text":"Production code development should only be done using an IDE; executing code against a local build of open source Spark and Delta Lake\nwill provide the most accurate benchmarks for how code will perform in production.","rationale":"A local Spark environment need not reproduce Databricks performance.","isCorrect":false},{"id":"D","text":"Benchmark the production write without intermediate display actions, and measure cold and warm-cache runs separately so repeated execution does not hide costs.","rationale":"Use production-like actions and distinguish cold from warm-cache runs.","isCorrect":true},{"id":"E","text":"The Jobs UI should be leveraged to occasionally run the notebook as a job and track execution time during incremental code development\nbecause Photon can only be enabled on clusters launched for scheduled jobs.","rationale":"Photon is not limited to scheduled-job compute.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Use production-like actions and distinguish cold from warm-cache runs.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":24,"images":["questions/049-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A user new to Databricks is trying to troubleshoot long execution times for some pipeline logic they are working on. Presently, the user is\nexecuting code cell-by-cell, using display() calls to confirm code is producing the logically correct results as new transformations are added to an\noperation. To get a measure of average time to execute, the user is running each cell multiple times interactively.\nWhich of the following adjustments will get a more accurate measure of how code is likely to perform in production?","options":[{"id":"A","text":"Scala is the only language that can be accurately tested using interactive notebooks; because the best performance is achieved by using\nScala code compiled to JARs, all PySpark and Spark SQL logic should be refactored."},{"id":"B","text":"The only way to meaningfully troubleshoot code execution times in development notebooks Is to use production-sized data and production-\nsized clusters with Run All execution."},{"id":"C","text":"Production code development should only be done using an IDE; executing code against a local build of open source Spark and Delta Lake\nwill provide the most accurate benchmarks for how code will perform in production."},{"id":"D","text":"Calling display() forces a job to trigger, while many transformations will only add to the logical query plan; because of caching, repeated\nexecution of the same logic does not provide meaningful results."},{"id":"E","text":"The Jobs UI should be leveraged to occasionally run the notebook as a job and track execution time during incremental code development\nbecause Photon can only be enabled on clusters launched for scheduled jobs."}],"correctAnswers":["D"],"explanation":"display triggers execution and interactive reruns may reuse cached data. Those measurements can differ from a production run; PySpark, notebooks and all-purpose Photon compute are not intrinsically invalid for development.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Replaced an overly absolute caching claim with a concrete repeatable benchmarking procedure.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":50,"prompt":"A production cluster has 3 executor nodes and uses the same virtual machine type for the driver and executor.\nWhen evaluating the Ganglia Metrics for this cluster, which indicator would signal a bottleneck caused by code executing on the driver?","options":[{"id":"A","text":"The five Minute Load Average remains consistent/flat","rationale":"Flat load alone does not establish driver saturation.","isCorrect":false},{"id":"B","text":"Bytes Received never exceeds 80 million bytes per second","rationale":"This arbitrary network threshold does not identify driver work.","isCorrect":false},{"id":"C","text":"Total Disk Space remains constant","rationale":"Constant disk capacity does not identify CPU execution placement.","isCorrect":false},{"id":"D","text":"Network I/O never spikes","rationale":"Quiet networking alone does not establish driver saturation.","isCorrect":false},{"id":"E","text":"Overall cluster CPU utilization is around 25%","rationale":"One busy node among four equal nodes approximates 25% aggregate CPU.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"scoped","explanation":"One busy node among four equal nodes approximates 25% aggregate CPU.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":24,"images":["questions/050-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":50,"prompt":"A production cluster has 3 executor nodes and uses the same virtual machine type for the driver and executor.\nWhen evaluating the Ganglia Metrics for this cluster, which indicator would signal a bottleneck caused by code executing on the driver?","options":[{"id":"A","text":"The five Minute Load Average remains consistent/flat"},{"id":"B","text":"Bytes Received never exceeds 80 million bytes per second"},{"id":"C","text":"Total Disk Space remains constant"},{"id":"D","text":"Network I/O never spikes"},{"id":"E","text":"Overall cluster CPU utilization is around 25%"}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"best_fit","explanation":"If only one of four equally sized nodes is busy, overall CPU can be around 25%, suggesting driver-bound work. It is a diagnostic clue, not proof; inspect per-node metrics. The other listed metrics do not identify driver execution.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":24,"images":["questions/050-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Treat the metric as an aggregate across four equally sized nodes. Choose the listed symptom consistent with a saturated driver and mostly idle workers, not proof of causation.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":51,"prompt":"Where in the Spark UI can one diagnose a performance problem induced by not leveraging predicate push-down?","options":[{"id":"A","text":"In the Executor’s log file, by grepping for \"predicate push-down\"","rationale":"Searching logs for a phrase is not direct plan inspection.","isCorrect":false},{"id":"B","text":"In the Stage’s Detail screen, in the Completed Stages table, by noting the size of data read from the Input column","rationale":"Input size can suggest inefficiency but does not show pushdown decisions.","isCorrect":false},{"id":"C","text":"In the Storage Detail screen, by noting which RDDs are not stored on disk","rationale":"Cache storage does not show predicate pushdown.","isCorrect":false},{"id":"D","text":"In the Delta Lake transaction log. by noting the column statistics","rationale":"Table statistics do not show the executed query plan.","isCorrect":false},{"id":"E","text":"In the Query Detail screen, by interpreting the Physical Plan","rationale":"The physical plan exposes scan filters and pushed predicates.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"The physical plan exposes scan filters and pushed predicates.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":25,"images":["questions/051-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":52,"prompt":"Review the following error traceback:\nWhich statement describes the error being raised?","options":[{"id":"A","text":"The code executed was PySpark but was executed in a Scala notebook.","rationale":"The traceback shows Python/PySpark execution.","isCorrect":false},{"id":"B","text":"There is no column in the table named heartrateheartrateheartrate","rationale":"Python repeats the string, producing a nonexistent column name.","isCorrect":true},{"id":"C","text":"There is a type error because a column object cannot be multiplied.","rationale":"A Column can be multiplied; the expression used a string.","isCorrect":false},{"id":"D","text":"There is a type error because a DataFrame object cannot be multiplied.","rationale":"The code does not multiply a DataFrame.","isCorrect":false},{"id":"E","text":"There is a syntax error because the heartrate column is not correctly identified as a column.","rationale":"The expression is valid Python syntax but resolves a nonexistent column.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Python repeats the string, producing a nonexistent column name.","topic":"python","sourceUrl":"https://docs.python.org/3/tutorial/modules.html","sourceTitle":"6. Modules — Python 3.14.8 documentation","sourcePage":25,"images":["questions/052-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":53,"prompt":"Which distribution does Databricks support for installing custom Python code packages?","options":[{"id":"A","text":"sbt","rationale":"sbt builds Scala/JVM projects, not Python wheel distributions.","isCorrect":false},{"id":"B","text":"CRAN","rationale":"CRAN distributes R packages.","isCorrect":false},{"id":"C","text":"npm","rationale":"npm distributes JavaScript packages.","isCorrect":false},{"id":"D","text":"Wheels","rationale":"Wheels are supported Python distribution artifacts.","isCorrect":true},{"id":"E","text":"jars","rationale":"JARs package JVM code, not Python distributions.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Wheels are supported Python distribution artifacts.","topic":"libraries","sourceUrl":"https://docs.databricks.com/aws/en/libraries/notebooks-python-libraries","sourceTitle":"Notebook-scoped Python libraries | Databricks on AWS","sourcePage":26,"images":["questions/053-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":54,"prompt":"Which Python variable contains a list of directories to be searched when trying to locate required modules?","options":[{"id":"A","text":"importlib.resource_path","rationale":"This is not Python's module search-path variable.","isCorrect":false},{"id":"B","text":"sys.path","rationale":"sys.path contains module search directories.","isCorrect":true},{"id":"C","text":"os.path","rationale":"os.path provides path operations, not the import search list.","isCorrect":false},{"id":"D","text":"pypi.path","rationale":"This is not the standard module search variable.","isCorrect":false},{"id":"E","text":"pylib.source","rationale":"This is not the standard module search variable.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"sys.path contains module search directories.","topic":"python","sourceUrl":"https://docs.python.org/3/tutorial/modules.html","sourceTitle":"6. Modules — Python 3.14.8 documentation","sourcePage":26,"images":["questions/054-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":55,"prompt":"Incorporating unit tests into a PySpark application requires upfront attention to the design of your jobs, or a potentially significant refactoring of\nexisting code.\nWhich statement describes a main benefit that offset this additional effort?","options":[{"id":"A","text":"Improves the quality of your data","rationale":"Better data quality can be indirect; it is not the specific isolation benefit.","isCorrect":false},{"id":"B","text":"Validates a complete use case of your application","rationale":"A complete use case belongs to broader functional/end-to-end testing.","isCorrect":false},{"id":"C","text":"Troubleshooting is easier since all steps are isolated and tested individually","rationale":"Isolated tests help localize failing components.","isCorrect":true},{"id":"D","text":"Yields faster deployment and execution times","rationale":"Tests do not guarantee faster execution or deployment.","isCorrect":false},{"id":"E","text":"Ensures that all steps interact correctly to achieve the desired end result","rationale":"Inter-step behavior is integration testing, not isolated unit testing.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Isolated tests help localize failing components.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":26,"images":["questions/055-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":56,"prompt":"Which statement describes integration testing?","options":[{"id":"A","text":"Validates interactions between subsystems of your application","rationale":"Integration tests exercise interactions between components.","isCorrect":true},{"id":"B","text":"Requires an automated testing framework","rationale":"Automation is useful but not a defining requirement.","isCorrect":false},{"id":"C","text":"Requires manual intervention","rationale":"Manual execution is not a defining requirement.","isCorrect":false},{"id":"D","text":"Validates an application use case","rationale":"A complete use case describes functional/end-to-end scope.","isCorrect":false},{"id":"E","text":"Validates behavior of individual elements of your application","rationale":"Individual elements describe unit-test scope.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Integration tests exercise interactions between components.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":26,"images":["questions/056-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":57,"prompt":"Which REST API call can be used to review the notebooks configured to run as tasks in a multi-task job?","options":[{"id":"A","text":"/jobs/runs/list","rationale":"Lists executions rather than directly fetching the saved job definition.","isCorrect":false},{"id":"B","text":"/jobs/runs/get-output","rationale":"Returns task output, not the saved job configuration.","isCorrect":false},{"id":"C","text":"/jobs/runs/get","rationale":"Returns a run snapshot, not the dedicated saved-job definition.","isCorrect":false},{"id":"D","text":"/jobs/get","rationale":"Fetches the known job's definition and notebook task settings.","isCorrect":true},{"id":"E","text":"/jobs/list","rationale":"Enumerates jobs rather than retrieving one by the specified job_id.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Fetches the known job's definition and notebook task settings.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/job","sourceTitle":"Jobs API: get a single job","sourcePage":27,"images":["questions/057-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":57,"prompt":"Which REST API call can be used to review the notebooks configured to run as tasks in a multi-task job?","options":[{"id":"A","text":"/jobs/runs/list"},{"id":"B","text":"/jobs/runs/get-output"},{"id":"C","text":"/jobs/runs/get"},{"id":"D","text":"/jobs/get"},{"id":"E","text":"/jobs/list"}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"best_fit","explanation":"jobs/get retrieves a particular job definition and its task notebook paths. Run endpoints describe executions. Some current jobs/list responses can also include task settings, so D is the most direct answer, not the only possible endpoint in all API versions.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":27,"images":["questions/057-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"The job_id is known. Choose the dedicated endpoint for retrieving one saved job definition, rather than enumerating jobs or inspecting an execution.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":58,"prompt":"A Databricks job has been configured with 3 tasks, each of which is a Databricks notebook. Task A does not depend on other tasks. Tasks B and C\nrun in parallel, with each having a serial dependency on task A.\nIf tasks A and B complete successfully but task C fails during a scheduled run, which statement describes the resulting state?","options":[{"id":"A","text":"All logic expressed in the notebook associated with tasks A and B will have been successfully completed; some operations in task C may\nhave completed successfully.","rationale":"Completed tasks persist; earlier successful operations in C may persist too.","isCorrect":true},{"id":"B","text":"All logic expressed in the notebook associated with tasks A and B will have been successfully completed; any changes made in task C will\nbe rolled back due to task failure.","rationale":"Task failure does not automatically roll back prior committed operations.","isCorrect":false},{"id":"C","text":"All logic expressed in the notebook associated with task A will have been successfully completed; tasks B and C will not commit any\nchanges because of stage failure.","rationale":"A later failure does not undo successful independent B work.","isCorrect":false},{"id":"D","text":"Because all tasks are managed as a dependency graph, no changes will be committed to the Lakehouse until ail tasks have successfully\nbeen completed.","rationale":"A job graph is not one atomic multi-table transaction.","isCorrect":false},{"id":"E","text":"Unless all tasks complete successfully, no changes will be committed to the Lakehouse; because task C failed, all commits will be rolled\nback automatically.","rationale":"There is no implicit job-wide rollback.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Completed tasks persist; earlier successful operations in C may persist too.","topic":"jobs","sourceUrl":"https://docs.databricks.com/aws/en/jobs/","sourceTitle":"Lakeflow Jobs | Databricks on AWS","sourcePage":27,"images":["questions/058-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":59,"prompt":"A Delta Lake table was created with the below query:\nRealizing that the original query had a typographical error, the below code was executed:\nALTER TABLE prod.sales_by_stor RENAME TO prod.sales_by_store\nWhich result will occur after running the second command?","options":[{"id":"A","text":"The table reference in the metastore is updated and no data is changed.","rationale":"Renaming the external table updates catalog metadata only.","isCorrect":true},{"id":"B","text":"The table name change is recorded in the Delta transaction log.","rationale":"The rename is a catalog operation, not a data-log commit.","isCorrect":false},{"id":"C","text":"All related files and metadata are dropped and recreated in a single ACID transaction.","rationale":"It does not drop and recreate the files.","isCorrect":false},{"id":"D","text":"The table reference in the metastore is updated and all data files are moved.","rationale":"The explicit external data path does not move.","isCorrect":false},{"id":"E","text":"A new Delta transaction log Is created for the renamed table.","rationale":"The existing Delta transaction log is retained.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Renaming the external table updates catalog metadata only.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":27,"images":["questions/059-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":60,"prompt":"The data engineering team maintains a table of aggregate statistics through batch nightly updates. This includes total sales for the previous day\nalongside totals and averages for a variety of time periods including the 7 previous days, year-to-date, and quarter-to-date. This table is named\nstore_saies_summary and the schema is as follows:\nThe table daily_store_sales contains all the information needed to update store_sales_summary. The schema for this table is: store_id INT,\nsales_date DATE, total_sales FLOAT\nIf daily_store_sales is implemented as a Type 1 table and the total_sales column might be adjusted after manual data auditing, which approach is\nthe safest to generate accurate reports in the store_sales_summary table?","options":[{"id":"A","text":"Implement the appropriate aggregate logic as a batch read against the daily_store_sales table and overwrite the store_sales_summary\ntable with each Update.","rationale":"Full snapshot replacement captures historical corrections simply.","isCorrect":true},{"id":"B","text":"Implement the appropriate aggregate logic as a batch read against the daily_store_sales table and append new rows nightly to the\nstore_sales_summary table.","rationale":"Append retains stale summaries and creates duplicate summary rows.","isCorrect":false},{"id":"C","text":"Implement the appropriate aggregate logic as a batch read against the daily_store_sales table and use upsert logic to update results in the\nstore_sales_summary table.","rationale":"Upsert can work, but requires the excluded custom merge/reconciliation logic.","isCorrect":false},{"id":"D","text":"Implement the appropriate aggregate logic as a Structured Streaming read against the daily_store_sales table and use upsert logic to\nupdate results in the store_sales_summary table.","rationale":"Ordinary streaming reads do not automatically propagate all source updates.","isCorrect":false},{"id":"E","text":"Use Structured Streaming to subscribe to the change data feed for daily_store_sales and apply changes to the aggregates in the\nstore_sales_summary table with each update.","rationale":"CDF aggregation requires incremental correction logic excluded by this criterion.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"Full snapshot replacement captures historical corrections simply.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":28,"images":["questions/060-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"original":{"id":60,"prompt":"The data engineering team maintains a table of aggregate statistics through batch nightly updates. This includes total sales for the previous day\nalongside totals and averages for a variety of time periods including the 7 previous days, year-to-date, and quarter-to-date. This table is named\nstore_saies_summary and the schema is as follows:\nThe table daily_store_sales contains all the information needed to update store_sales_summary. The schema for this table is: store_id INT,\nsales_date DATE, total_sales FLOAT\nIf daily_store_sales is implemented as a Type 1 table and the total_sales column might be adjusted after manual data auditing, which approach is\nthe safest to generate accurate reports in the store_sales_summary table?","options":[{"id":"A","text":"Implement the appropriate aggregate logic as a batch read against the daily_store_sales table and overwrite the store_sales_summary\ntable with each Update."},{"id":"B","text":"Implement the appropriate aggregate logic as a batch read against the daily_store_sales table and append new rows nightly to the\nstore_sales_summary table."},{"id":"C","text":"Implement the appropriate aggregate logic as a batch read against the daily_store_sales table and use upsert logic to update results in the\nstore_sales_summary table."},{"id":"D","text":"Implement the appropriate aggregate logic as a Structured Streaming read against the daily_store_sales table and use upsert logic to\nupdate results in the store_sales_summary table."},{"id":"E","text":"Use Structured Streaming to subscribe to the change data feed for daily_store_sales and apply changes to the aggregates in the\nstore_sales_summary table with each update."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Recomputing the full snapshot and overwriting the small summary captures corrections to historical sales and is the simplest safe option. A correctly designed full-key upsert can also work; C is not inherently impossible. Streaming requires explicit handling of source changes.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":28,"images":["questions/060-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"The summary is small enough to rebuild nightly. Choose the simplest complete-snapshot replacement, avoiding custom incremental upsert logic and stale summary rows.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":61,"prompt":"A member of the data engineering team has submitted a short notebook that they wish to schedule as part of a larger data pipeline. Assume that\nthe commands provided below produce the logically correct results when run as presented.\nWhich command should be removed from the notebook before scheduling it as a job?","options":[{"id":"A","text":"Cmd 2","rationale":"printSchema reports metadata and need not execute the full result.","isCorrect":false},{"id":"B","text":"Cmd 3","rationale":"The select is a required lazy transformation.","isCorrect":false},{"id":"C","text":"Cmd 4","rationale":"The drop is a required lazy transformation.","isCorrect":false},{"id":"D","text":"Cmd 5","rationale":"explain inspects the plan rather than materializing the display.","isCorrect":false},{"id":"E","text":"Cmd 6","rationale":"display adds an unnecessary interactive action before the required write.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"display adds an unnecessary interactive action before the required write.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":29,"images":["questions/061-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":62,"prompt":"The business reporting team requires that data for their dashboards be updated every hour. The total processing time for the pipeline that extracts\ntransforms, and loads the data for their pipeline runs in 10 minutes.\nAssuming normal operating conditions, which configuration will meet their service-level agreement requirements with the lowest cost?","options":[{"id":"A","text":"Manually trigger a job anytime the business reporting team refreshes their dashboards","rationale":"Manual refresh does not guarantee hourly delivery.","isCorrect":false},{"id":"B","text":"Schedule a job to execute the pipeline once an hour on a new job cluster","rationale":"Hourly job compute can stop between ten-minute runs.","isCorrect":true},{"id":"C","text":"Schedule a Structured Streaming job with a trigger interval of 60 minutes","rationale":"Always-on streaming compute idles between hourly batches.","isCorrect":false},{"id":"D","text":"Schedule a job to execute the pipeline once an hour on a dedicated interactive cluster","rationale":"A dedicated interactive cluster need not stop between runs.","isCorrect":false},{"id":"E","text":"Configure a job that executes every time new data lands in a given directory","rationale":"Unbounded file-arrival frequency need not minimize cost.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Hourly job compute can stop between ten-minute runs.","topic":"jobs","sourceUrl":"https://docs.databricks.com/aws/en/jobs/","sourceTitle":"Lakeflow Jobs | Databricks on AWS","sourcePage":29,"images":["questions/062-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":63,"prompt":"A Databricks SQL dashboard has been configured to monitor the total number of records present in a collection of Delta Lake tables using the\nfollowing query pattern:\nSELECT COUNT (*) FROM table -\nWhich of the following describes how results are generated each time the dashboard is updated?","options":[{"id":"A","text":"The total count of rows is calculated by scanning all data files","rationale":"A full data scan is unnecessary under the metadata-count assumptions.","isCorrect":false},{"id":"B","text":"The total count of rows will be returned from cached results unless REFRESH is run","rationale":"The question bypasses result cache and reads the current snapshot.","isCorrect":false},{"id":"C","text":"The total count of records is calculated from the Delta transaction logs","rationale":"Delta transaction metadata contains the needed row counts.","isCorrect":true},{"id":"D","text":"The total count of records is calculated from the parquet file metadata","rationale":"A fresh scan of Parquet footers is unnecessary.","isCorrect":false},{"id":"E","text":"The total count of records is calculated from the Hive metastore","rationale":"The metastore does not provide the exact Delta snapshot row count.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Delta transaction metadata contains the needed row counts.","topic":"count","sourceUrl":"https://delta.io/blog/2023-04-19-faster-aggregations-metadata/","sourceTitle":"How Delta Lake uses metadata to make certain aggregations much faster | Delta Lake","sourcePage":30,"images":["questions/063-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A Databricks SQL dashboard has been configured to monitor the total number of records present in a collection of Delta Lake tables using the\nfollowing query pattern:\nSELECT COUNT (*) FROM table -\nWhich of the following describes how results are generated each time the dashboard is updated?","options":[{"id":"A","text":"The total count of rows is calculated by scanning all data files"},{"id":"B","text":"The total count of rows will be returned from cached results unless REFRESH is run"},{"id":"C","text":"The total count of records is calculated from the Delta transaction logs"},{"id":"D","text":"The total count of records is calculated from the parquet file metadata"},{"id":"E","text":"The total count of records is calculated from the Hive metastore"}],"correctAnswers":["C"],"explanation":"For this unfiltered Delta COUNT(*), record-count metadata in the transaction log can answer the query without scanning every row. The Hive metastore is not the row-count source.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"All required record counts are available in Delta metadata, metadata-only count optimization is supported and enabled, and this unfiltered query has no row masks or row filters. Result caching is bypassed.","reviewNote":"Second audit: COUNT(*) metadata optimization is conditional.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":64,"prompt":"A Delta Lake table was created with the below query:\nConsider the following query:\nDROP TABLE prod.sales_by_store -\nIf this statement is executed by a workspace admin, which result will occur?","options":[{"id":"A","text":"Nothing will occur until a COMMIT command is executed.","rationale":"DROP TABLE does not wait for a separate COMMIT here.","isCorrect":false},{"id":"B","text":"The table will be removed from the catalog but the data will remain in storage.","rationale":"This describes dropping an external table.","isCorrect":false},{"id":"C","text":"The table will be removed from the catalog and the data will be deleted.","rationale":"Legacy managed-table drop removes catalog metadata and managed data.","isCorrect":true},{"id":"D","text":"An error will occur because Delta Lake prevents the deletion of production data.","rationale":"The prod schema name does not prevent authorized deletion.","isCorrect":false},{"id":"E","text":"Data will be marked as deleted but still recoverable with Time Travel.","rationale":"Delta time travel alone cannot restore a dropped legacy managed table.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Legacy managed-table drop removes catalog metadata and managed data.","topic":"drop","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-drop-table","sourceTitle":"DROP TABLE | Databricks on AWS","sourcePage":30,"images":["questions/064-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"original":{"id":64,"prompt":"A Delta Lake table was created with the below query:\nConsider the following query:\nDROP TABLE prod.sales_by_store -\nIf this statement is executed by a workspace admin, which result will occur?","options":[{"id":"A","text":"Nothing will occur until a COMMIT command is executed."},{"id":"B","text":"The table will be removed from the catalog but the data will remain in storage."},{"id":"C","text":"The table will be removed from the catalog and the data will be deleted."},{"id":"D","text":"An error will occur because Delta Lake prevents the deletion of production data."},{"id":"E","text":"Data will be marked as deleted but still recoverable with Time Travel."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"legacy","explanation":"The image creates a managed table without LOCATION. In the legacy Hive-metastore context, DROP TABLE removes its metadata and managed data. Current Unity Catalog has delayed deletion and UNDROP retention, so this is context-dependent.","topic":"drop","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-drop-table","sourceTitle":"DROP TABLE | Databricks on AWS","sourcePage":30,"images":["questions/064-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use the legacy Hive metastore and its managed-table behavior, not Unity Catalog. The shown database and table definitions apply.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":65,"prompt":"Two of the most common data locations on Databricks are the DBFS root storage and external object storage mounted with dbutils.fs.mount().\nWhich of the following statements is correct?","options":[{"id":"A","text":"DBFS provides a file-style abstraction and familiar paths over distributed cloud storage; it does not guarantee every POSIX filesystem behavior.","rationale":"DBFS provides file-style access over object storage, with limitations.","isCorrect":true},{"id":"B","text":"By default, both the DBFS root and mounted data sources are only accessible to workspace administrators.","rationale":"Legacy DBFS data is not universally administrator-only.","isCorrect":false},{"id":"C","text":"The DBFS root is the most secure location to store data, because mounted storage volumes must have full public read and write\npermissions.","rationale":"Mounts do not require public read/write access.","isCorrect":false},{"id":"D","text":"Neither the DBFS root nor mounted storage can be accessed when using %sh in a Databricks notebook.","rationale":"Supported legacy compute can access DBFS through FUSE paths.","isCorrect":false},{"id":"E","text":"The DBFS root stores files in ephemeral block volumes attached to the driver, while mounted directories will always persist saved data to\nexternal storage between sessions.","rationale":"DBFS root is backed by object storage, not ephemeral driver disks.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"DBFS provides file-style access over object storage, with limitations.","topic":"dbfs","sourceUrl":"https://docs.databricks.com/aws/en/dbfs/","sourceTitle":"What is DBFS? | Databricks on AWS","sourcePage":31,"images":["questions/065-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":65,"prompt":"Two of the most common data locations on Databricks are the DBFS root storage and external object storage mounted with dbutils.fs.mount().\nWhich of the following statements is correct?","options":[{"id":"A","text":"DBFS is a file system protocol that allows users to interact with files stored in object storage using syntax and guarantees similar to Unix\nfile systems."},{"id":"B","text":"By default, both the DBFS root and mounted data sources are only accessible to workspace administrators."},{"id":"C","text":"The DBFS root is the most secure location to store data, because mounted storage volumes must have full public read and write\npermissions."},{"id":"D","text":"Neither the DBFS root nor mounted storage can be accessed when using %sh in a Databricks notebook."},{"id":"E","text":"The DBFS root stores files in ephemeral block volumes attached to the driver, while mounted directories will always persist saved data to\nexternal storage between sessions."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"legacy","explanation":"DBFS offers file-system-style paths over cloud object storage. Its root is not ephemeral driver storage, and mounts do not require public access. DBFS root and mounts are now deprecated for new designs; use Unity Catalog volumes/external locations.","topic":"dbfs","sourceUrl":"https://docs.databricks.com/aws/en/dbfs/","sourceTitle":"What is DBFS? | Databricks on AWS","sourcePage":31,"images":["questions/065-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":3,"reviewNote":"The answer is scored within the explicit context shown with this question. Second audit: Removed the claim of full Unix filesystem guarantees.","studyContext":"This question concerns an existing legacy workspace where DBFS root and mounts are enabled. They remain historical concepts, not a recommendation for new storage designs.","reviewedAt":"2026-10-04","practiceEligible":true,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":66,"prompt":"The following code has been migrated to a Databricks notebook from a legacy workload:\nThe code executes successfully and provides the logically correct results, however, it takes over 20 minutes to extract and load around 1 GB of\ndata.\nWhich statement is a possible explanation for this behavior?","options":[{"id":"A","text":"%sh triggers a cluster restart to collect and install Git. Most of the latency is related to cluster startup time.","rationale":"A shell cell does not require a cluster restart.","isCorrect":false},{"id":"B","text":"Instead of cloning, the code should use %sh pip install so that the Python code can get executed in parallel across all nodes in a cluster.","rationale":"Installing a package does not distribute its execution.","isCorrect":false},{"id":"C","text":"%sh does not distribute file moving operations; the final line of code should be updated to use %fs instead.","rationale":"Changing the file-copy command does not distribute the Python workload.","isCorrect":false},{"id":"D","text":"Python will always execute slower than Scala on Databricks. The run.py script should be refactored to Scala.","rationale":"Python is not always slower than Scala.","isCorrect":false},{"id":"E","text":"%sh executes shell code on the driver node. The code does not take advantage of the worker nodes or Databricks optimized Spark.","rationale":"Ordinary shell/Python work here runs on the driver only.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"Ordinary shell/Python work here runs on the driver only.","topic":"notebooks","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/notebooks-code","sourceTitle":"Develop code in Databricks notebooks | Databricks on AWS","sourcePage":31,"images":["questions/066-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":67,"prompt":"The data science team has requested assistance in accelerating queries on free form text from user reviews. The data is currently stored in\nParquet with the below schema:\nitem_id INT, user_id INT, review_id INT, rating FLOAT, review STRING\nThe review column contains the full text of the review left by the user. Specifically, the data science team is looking to identify if any of 30 key\nwords exist in this field.\nA junior data engineer suggests converting this data to Delta Lake will improve query performance.\nWhich response to the junior data engineer s suggestion is correct?","options":[{"id":"A","text":"Delta Lake statistics are not optimized for free text fields with high cardinality.","rationale":"File range statistics are poor indexes for arbitrary substring search.","isCorrect":true},{"id":"B","text":"Text data cannot be stored with Delta Lake.","rationale":"Delta can store text columns.","isCorrect":false},{"id":"C","text":"ZORDER ON review will need to be run to see performance gains.","rationale":"ZORDER does not create a full-text term index.","isCorrect":false},{"id":"D","text":"The Delta log creates a term matrix for free text fields to support selective filtering.","rationale":"The Delta log does not build the claimed term matrix.","isCorrect":false},{"id":"E","text":"Delta Lake statistics are only collected on the first 4 columns in a table.","rationale":"The traditional statistics default is not four columns.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"File range statistics are poor indexes for arbitrary substring search.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":32,"images":["questions/067-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":68,"prompt":"Assuming that the Databricks CLI has been installed and configured correctly, which Databricks CLI command can be used to upload a custom\nPython Wheel to object storage mounted with the DBFS for use with a production job?","options":[{"id":"A","text":"configure","rationale":"configure sets authentication, not file upload.","isCorrect":false},{"id":"B","text":"fs","rationale":"The fs group provides file-copy commands.","isCorrect":true},{"id":"C","text":"jobs","rationale":"jobs manages job definitions and runs.","isCorrect":false},{"id":"D","text":"libraries","rationale":"libraries manages installations rather than the requested file upload.","isCorrect":false},{"id":"E","text":"workspace","rationale":"workspace manages workspace assets, not DBFS-mounted object paths.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"The fs group provides file-copy commands.","topic":"cli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/fs-commands","sourceTitle":"fs command group | Databricks on AWS","sourcePage":32,"images":["questions/068-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":68,"prompt":"Assuming that the Databricks CLI has been installed and configured correctly, which Databricks CLI command can be used to upload a custom\nPython Wheel to object storage mounted with the DBFS for use with a production job?","options":[{"id":"A","text":"configure"},{"id":"B","text":"fs"},{"id":"C","text":"jobs"},{"id":"D","text":"libraries"},{"id":"E","text":"workspace"}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"legacy","explanation":"The fs command group copies files to supported DBFS paths. Other groups configure credentials or manage jobs/workspace assets. DBFS mounts are legacy storage; use volumes for new library deployments.","topic":"cli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/fs-commands","sourceTitle":"fs command group | Databricks on AWS","sourcePage":32,"images":["questions/068-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"This question concerns an existing legacy workspace where DBFS root and mounts are enabled. They remain historical concepts, not a recommendation for new storage designs.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":69,"prompt":"The business intelligence team has a dashboard configured to track various summary metrics for retail stores. This includes total sales for the\nprevious day alongside totals and averages for a variety of time periods. The fields required to populate this dashboard have the following\nschema:\nFor demand forecasting, the Lakehouse contains a validated table of all itemized sales updated incrementally in near real-time. This table, named\nproducts_per_order, includes the following fields:\nBecause reporting on long-term sales trends is less volatile, analysts using the new dashboard only require data to be refreshed once daily.\nBecause the dashboard will be queried interactively by many users throughout a normal business day, it should return results quickly and reduce\ntotal compute associated with each materialization.\nWhich solution meets the expectations of the end users while controlling and limiting possible costs?","options":[{"id":"A","text":"Populate the dashboard by configuring a nightly batch job to save the required values as a table overwritten with each update.","rationale":"A daily materialized summary avoids repeated full aggregation.","isCorrect":true},{"id":"B","text":"Use Structured Streaming to configure a live dashboard against the products_per_order table within a Databricks notebook.","rationale":"Continuous recomputation exceeds the daily freshness requirement.","isCorrect":false},{"id":"C","text":"Configure a webhook to execute an incremental read against products_per_order each time the dashboard is refreshed.","rationale":"Per-refresh processing increases unnecessary repeated work.","isCorrect":false},{"id":"D","text":"Use the Delta Cache to persist the products_per_order table in memory to quickly update the dashboard with each query.","rationale":"Disk caching is not an in-memory persisted aggregate result.","isCorrect":false},{"id":"E","text":"Define a view against the products_per_order table and define the dashboard against this view.","rationale":"A regular view can recompute the expensive aggregation per query.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A daily materialized summary avoids repeated full aggregation.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":33,"images":["questions/069-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":70,"prompt":"A data ingestion task requires a one-TB JSON dataset to be written out to Parquet with a target part-file size of 512 MB. Because Parquet is being\nused instead of Delta Lake, built-in file-sizing features such as Auto-Optimize & Auto-Compaction cannot be used.\nWhich strategy will yield the best performance without shuffling data?","options":[{"id":"A","text":"Set spark.sql.files.maxPartitionBytes to 512 MB, ingest the data, execute the narrow transformations, and then write to parquet.","rationale":"This directly sets file-read input partition size without a shuffle.","isCorrect":true},{"id":"B","text":"Set spark.sql.shuffle.partitions to 2,048 partitions (1TB*1024*1024/512), ingest the data, execute the narrow transformations, optimize the\ndata by sorting it (which automatically repartitions the data), and then write to parquet.","rationale":"Sorting and repartitioning introduce a shuffle.","isCorrect":false},{"id":"C","text":"Set spark.sql.adaptive.advisoryPartitionSizeInBytes to 512 MB bytes, ingest the data, execute the narrow transformations, coalesce to\n2,048 partitions (1TB*1024*1024/512), and then write to parquet.","rationale":"Adaptive shuffle settings do not set file-read partition size.","isCorrect":false},{"id":"D","text":"Ingest the data, execute the narrow transformations, repartition to 2,048 partitions (1TB* 1024*1024/512), and then write to parquet.","rationale":"Explicit repartitioning introduces a shuffle.","isCorrect":false},{"id":"E","text":"Set spark.sql.shuffle.partitions to 512, ingest the data, execute the narrow transformations, and then write to parquet.","rationale":"Shuffle partition count does not set initial file-read size.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"This directly sets file-read input partition size without a shuffle.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":33,"images":["questions/070-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":70,"prompt":"A data ingestion task requires a one-TB JSON dataset to be written out to Parquet with a target part-file size of 512 MB. Because Parquet is being\nused instead of Delta Lake, built-in file-sizing features such as Auto-Optimize & Auto-Compaction cannot be used.\nWhich strategy will yield the best performance without shuffling data?","options":[{"id":"A","text":"Set spark.sql.files.maxPartitionBytes to 512 MB, ingest the data, execute the narrow transformations, and then write to parquet."},{"id":"B","text":"Set spark.sql.shuffle.partitions to 2,048 partitions (1TB*1024*1024/512), ingest the data, execute the narrow transformations, optimize the\ndata by sorting it (which automatically repartitions the data), and then write to parquet."},{"id":"C","text":"Set spark.sql.adaptive.advisoryPartitionSizeInBytes to 512 MB bytes, ingest the data, execute the narrow transformations, coalesce to\n2,048 partitions (1TB*1024*1024/512), and then write to parquet."},{"id":"D","text":"Ingest the data, execute the narrow transformations, repartition to 2,048 partitions (1TB* 1024*1024/512), and then write to parquet."},{"id":"E","text":"Set spark.sql.shuffle.partitions to 512, ingest the data, execute the narrow transformations, and then write to parquet."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Input partition sizing preserves narrow execution without a shuffle, making A the intended choice. It does not guarantee 512-MB Parquet files because JSON size, compression and row expansion differ. B/D shuffle; C's adaptive setting does not size a nonshuffle stage.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":33,"images":["questions/070-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Choose a file-read partition setting for a pipeline consisting only of narrow transformations. 512 MB is an input partition target, not a guaranteed compressed Parquet output-file size.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":71,"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Incremental state information should be\nmaintained for 10 minutes for late-arriving data.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nChoose the response that correctly fills in the blank within the code block to complete this task.","options":[{"id":"A","text":"withWatermark(\"event_time\", \"10 minutes\")","rationale":"This configures the event-time lateness threshold.","isCorrect":true},{"id":"B","text":"awaitArrival(\"event_time\", \"10 minutes\")","rationale":"This is not the required DataFrame API.","isCorrect":false},{"id":"C","text":"await(\"event_time + ‘10 minutes'\")","rationale":"This is not a valid watermark API call.","isCorrect":false},{"id":"D","text":"slidingWindow(\"event_time\", \"10 minutes\")","rationale":"Window grouping is not the watermark declaration.","isCorrect":false},{"id":"E","text":"delayWrite(\"event_time\", \"10 minutes\")","rationale":"This is not the required DataFrame API.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"This configures the event-time lateness threshold.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Apply watermarks to control data processing thresholds | Databricks on AWS","sourcePage":34,"images":["questions/071-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Incremental state information should be\nmaintained for 10 minutes for late-arriving data.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nChoose the response that correctly fills in the blank within the code block to complete this task.","options":[{"id":"A","text":"withWatermark(\"event_time\", \"10 minutes\")"},{"id":"B","text":"awaitArrival(\"event_time\", \"10 minutes\")"},{"id":"C","text":"await(\"event_time + ‘10 minutes'\")"},{"id":"D","text":"slidingWindow(\"event_time\", \"10 minutes\")"},{"id":"E","text":"delayWrite(\"event_time\", \"10 minutes\")"}],"correctAnswers":["A"],"explanation":"withWatermark(event_time, '10 minutes') is the correct API for event-time lateness/state cleanup. It is not a wall-clock sleep, and late-data handling depends on the watermark and output mode.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"studyContext":"Use a 10-minute event-time lateness threshold; cleanup follows watermark progress and is not an exact 10-minute wall-clock timer. checkpoint_path is defined.","code":"from pyspark.sql.functions import avg, window\n# Replace WATERMARK_CALL with the selected method call on df.\n(df.WATERMARK_CALL\n .groupBy(window(\"event_time\", \"5 minutes\").alias(\"time\"), \"device_id\")\n .agg(avg(\"temp\").alias(\"avg_temp\"), avg(\"humidity\").alias(\"avg_humidity\"))\n .writeStream.format(\"delta\").outputMode(\"append\")\n .option(\"checkpointLocation\", checkpoint_path)\n .toTable(\"sensor_avg\"))","reviewNote":"Second audit: Corrected the sink API and specified event-time rather than wall-clock retention.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":72,"prompt":"An existing complete-mode streaming query groups item sales and computes count and average price. The replacement below adds promo_count. Which listed migration step is required because the aggregation state schema changes?","options":[{"id":"A","text":"Specify a new checkpointLocation","rationale":"The changed aggregation state needs a fresh compatible checkpoint.","isCorrect":true},{"id":"B","text":"Increase the shuffle partitions to account for additional aggregates","rationale":"More shuffle partitions do not migrate the existing state schema.","isCorrect":false},{"id":"C","text":"Run REFRESH TABLE delta.'/item_agg'","rationale":"Refreshing catalog metadata does not migrate state.","isCorrect":false},{"id":"D","text":"Register the data in the \"/item_agg\" directory to the Hive metastore","rationale":"Registering a table does not change the checkpoint state schema.","isCorrect":false},{"id":"E","text":"Remove .option(‘mergeSchema’, ‘true’) from the streaming write","rationale":"Disabling sink schema evolution does not fix state incompatibility.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"The changed aggregation state needs a fresh compatible checkpoint.","topic":"checkpoints","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/checkpoints","sourceTitle":"Structured Streaming checkpoints | Databricks on AWS","sourcePage":35,"images":["questions/072-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data team's Structured Streaming job is configured to calculate running aggregates for item sales to update a downstream marketing\ndashboard. The marketing team has introduced a new promotion, and they would like to add a new field to track the number of times this\npromotion code is used for each item. A junior data engineer suggests updating the existing query as follows. Note that proposed changes are in\nbold.\nOriginal query:\nProposed query:\nProposed query:\n.start(“/item_agg”)\nWhich step must also be completed to put the proposed query into production?","options":[{"id":"A","text":"Specify a new checkpointLocation"},{"id":"B","text":"Increase the shuffle partitions to account for additional aggregates"},{"id":"C","text":"Run REFRESH TABLE delta.'/item_agg'"},{"id":"D","text":"Register the data in the \"/item_agg\" directory to the Hive metastore"},{"id":"E","text":"Remove .option(‘mergeSchema’, ‘true’) from the streaming write"}],"correctAnswers":["A"],"explanation":"Adding an aggregate changes the streaming state schema, requiring a new checkpoint for this query. Output mergeSchema does not migrate aggregate state; REFRESH and shuffle settings do not fix it. The illustrated count expression also needs count_if or an equivalent conditional expression; a literal column-name string is not a SQL boolean predicate.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"studyContext":"Stop the old query before migration. The full input history remains replayable and the complete output will be rebuilt; changing the checkpoint alone does not recover expired source data.","code":"from pyspark.sql import functions as F\n# Original aggregate: count(item), mean(sale_price).\n# Proposed aggregate adds a promotion counter:\n(df.groupBy(\"item\")\n .agg(F.count(\"item\").alias(\"total_count\"),\n      F.mean(\"sale_price\").alias(\"avg_price\"),\n      F.sum(F.when(F.col(\"promo_id\") == \"PROMO\", 1).otherwise(0)).alias(\"promo_count\"))\n .writeStream.format(\"delta\").outputMode(\"complete\")\n .option(\"mergeSchema\", \"true\")\n .option(\"checkpointLocation\", \"/item_agg/__checkpoint\")\n .start(\"/item_agg\"))","reviewNote":"Second audit: The original proposed query omitted the new aggregate. Restored the intended state-schema change with valid code.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":73,"prompt":"A Structured Streaming job deployed to production has been resulting in higher than expected cloud storage costs. At present, during normal\nexecution, each microbatch of data is processed in less than 3s; at least 12 times per minute, a microbatch is processed that contains 0 records.\nThe streaming write was configured using the default trigger settings. The production job is currently scheduled alongside many other Databricks\njobs in a workspace with instance pools provisioned to reduce start-up time for jobs with batch execution.\nThe team wants to stop idle compute between finite ingestion runs. Startup and processing together take at most one minute. Which listed approach both reduces empty polling and leaves headroom under a ten-minute latency target?","options":[{"id":"A","text":"Set the trigger interval to 3 seconds; the default trigger interval is consuming too many records per batch, resulting in spill to disk that can\nincrease volume costs.","rationale":"Shorter triggers do not stop idle compute and the explanation is false.","isCorrect":false},{"id":"B","text":"Increase the number of shuffle partitions to maximize parallelism, since the trigger interval cannot be modified without modifying the\ncheckpoint directory.","rationale":"Triggers can change without necessarily replacing the checkpoint.","isCorrect":false},{"id":"C","text":"Set the trigger interval to 10 minutes; each batch calls APIs in the source storage account, so decreasing trigger frequency to maximum\nallowable threshold should minimize this cost.","rationale":"Ten-minute intervals leave no startup/processing headroom and keep compute running.","isCorrect":false},{"id":"D","text":"Set the trigger interval to 500 milliseconds; setting a small but non-zero trigger interval ensures that the source is not queried too\nfrequently.","rationale":"Half-second polling still creates frequent empty checks.","isCorrect":false},{"id":"E","text":"Use trigger(availableNow=True) with a persistent checkpoint, scheduled every eight minutes on a jobs cluster that stops after the run.","rationale":"Finite eight-minute scheduled runs meet the stated bound and stop compute.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"Finite eight-minute scheduled runs meet the stated bound and stop compute.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":36,"images":["questions/073-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":73,"prompt":"A Structured Streaming job deployed to production has been resulting in higher than expected cloud storage costs. At present, during normal\nexecution, each microbatch of data is processed in less than 3s; at least 12 times per minute, a microbatch is processed that contains 0 records.\nThe streaming write was configured using the default trigger settings. The production job is currently scheduled alongside many other Databricks\njobs in a workspace with instance pools provisioned to reduce start-up time for jobs with batch execution.\nHolding all other variables constant and assuming records need to be processed in less than 10 minutes, which adjustment will meet the\nrequirement?","options":[{"id":"A","text":"Set the trigger interval to 3 seconds; the default trigger interval is consuming too many records per batch, resulting in spill to disk that can\nincrease volume costs."},{"id":"B","text":"Increase the number of shuffle partitions to maximize parallelism, since the trigger interval cannot be modified without modifying the\ncheckpoint directory."},{"id":"C","text":"Set the trigger interval to 10 minutes; each batch calls APIs in the source storage account, so decreasing trigger frequency to maximum\nallowable threshold should minimize this cost."},{"id":"D","text":"Set the trigger interval to 500 milliseconds; setting a small but non-zero trigger interval ensures that the source is not queried too\nfrequently."},{"id":"E","text":"Use the trigger once option and configure a Databricks job to execute the query every 10 minutes; this approach minimizes costs for both\ncompute and storage."}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"best_fit","explanation":"Periodic finite runs avoid idle compute and repeated empty polls. Trigger.Once is deprecated in favor of AvailableNow. An exact ten-minute schedule cannot strictly guarantee latency below ten minutes once startup and processing are included; allow headroom.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":36,"images":["questions/073-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Updated the deprecated trigger and left startup/processing headroom in the schedule.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":74,"prompt":"Which statement describes the correct use of pyspark.sql.functions.broadcast?","options":[{"id":"A","text":"It marks a column as having low enough cardinality to properly map distinct values to available partitions, allowing a broadcast join.","rationale":"broadcast marks a DataFrame, not a column cardinality.","isCorrect":false},{"id":"B","text":"It marks a column as small enough to store in memory on all executors, allowing a broadcast join.","rationale":"The hint applies to a DataFrame, not one column.","isCorrect":false},{"id":"C","text":"It caches a copy of the indicated table on attached storage volumes for all active clusters within a Databricks workspace.","rationale":"It is not a workspace-wide disk cache.","isCorrect":false},{"id":"D","text":"It marks a DataFrame as small enough to store in memory on all executors, allowing a broadcast join.","rationale":"The hint identifies a small DataFrame as a broadcast-join input.","isCorrect":true},{"id":"E","text":"It caches a copy of the indicated table on all nodes in the cluster for use in all future queries during the cluster lifetime.","rationale":"It does not create a permanent all-query cache.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The hint identifies a small DataFrame as a broadcast-join input.","topic":"broadcast","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.functions.broadcast.html","sourceTitle":"pyspark.sql.functions.broadcast — PySpark 4.2.0 documentation","sourcePage":36,"images":["questions/074-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":75,"prompt":"A data engineer is configuring a pipeline that will potentially see late-arriving, duplicate records.\nIn addition to de-duplicating records within the batch, which of the following approaches allows the data engineer to deduplicate data against\npreviously processed records as it is inserted into a Delta table?","options":[{"id":"A","text":"Set the configuration delta.deduplicate = true.","rationale":"This is not a Delta deduplication configuration.","isCorrect":false},{"id":"B","text":"VACUUM the Delta table after each batch completes.","rationale":"VACUUM removes old files, not duplicate business keys.","isCorrect":false},{"id":"C","text":"Perform an insert-only merge with a matching condition on a unique key.","rationale":"An insert-only keyed MERGE excludes keys already present.","isCorrect":true},{"id":"D","text":"Perform a full outer join on a unique key and overwrite existing data.","rationale":"An outer join plus overwrite needs additional reconciliation and is not this insert pattern.","isCorrect":false},{"id":"E","text":"Rely on Delta Lake schema enforcement to prevent duplicate records.","rationale":"Schema enforcement validates types, not key uniqueness.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"An insert-only keyed MERGE excludes keys already present.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":36,"images":["questions/075-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":76,"prompt":"A data pipeline uses Structured Streaming to ingest data from Apache Kafka to Delta Lake. Data is being stored in a bronze table, and includes the\nKafka-generated timestamp, key, and value. Three months after the pipeline is deployed, the data engineering team has noticed some latency\nissues during certain times of the day.\nA senior data engineer updates the Delta Table's schema and ingestion logic to include the current timestamp (as recorded by Apache Spark) as\nwell as the Kafka topic and partition. The team plans to use these additional metadata fields to diagnose the transient processing delays.\nWhich limitation will the team face while diagnosing this problem?","options":[{"id":"A","text":"New fields will not be computed for historic records.","rationale":"New ingestion metadata is not retroactively computed for old rows.","isCorrect":true},{"id":"B","text":"Spark cannot capture the topic and partition fields from a Kafka source.","rationale":"Kafka topic and partition metadata are available.","isCorrect":false},{"id":"C","text":"New fields cannot be added to a production Delta table.","rationale":"Delta schemas can evolve.","isCorrect":false},{"id":"D","text":"Updating the table schema will invalidate the Delta transaction log metadata.","rationale":"Schema evolution is recorded rather than invalidating the log.","isCorrect":false},{"id":"E","text":"Updating the table schema requires a default value provided for each field added.","rationale":"New nullable columns do not require a supplied default value.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"New ingestion metadata is not retroactively computed for old rows.","topic":"schema","sourceUrl":"https://docs.databricks.com/aws/en/tables/update-schema","sourceTitle":"Update table schemas with schema evolution | Databricks on AWS","sourcePage":37,"images":["questions/076-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":77,"prompt":"The helper reads incoming JSON files with Auto Loader. With job retries configured to restart after a supported additive schema change, which continuation provides ongoing incremental ingestion and evolves the Delta sink?","options":[{"id":"A","text":"incoming.writeStream.format(\"delta\").option(\"mergeSchema\", \"true\").start(target_table_path)","rationale":"A missing explicit checkpoint does not meet durable progress tracking.","isCorrect":false},{"id":"B","text":"(incoming.writeStream.format(\"delta\").option(\"checkpointLocation\", checkpoint_path + \"/stream\").option(\"mergeSchema\", \"true\").trigger(once=True).start(target_table_path))","rationale":"A finite trigger does not provide the requested always-on ingestion.","isCorrect":false},{"id":"C","text":"(incoming.write.format(\"delta\").option(\"checkpointLocation\", checkpoint_path + \"/stream\").option(\"mergeSchema\", \"true\").outputMode(\"append\").save(target_table_path))","rationale":"Batch write methods do not operate on this streaming DataFrame.","isCorrect":false},{"id":"D","text":"incoming.write.format(\"delta\").option(\"mergeSchema\", \"true\").mode(\"append\").save(target_table_path)","rationale":"A streaming DataFrame cannot use ordinary batch writes.","isCorrect":false},{"id":"E","text":"(incoming.writeStream.format(\"delta\").outputMode(\"append\").option(\"checkpointLocation\", checkpoint_path + \"/stream\").option(\"mergeSchema\", \"true\").start(target_table_path))","rationale":"The streaming writer includes checkpointing, schema merging and continuous polling.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"The streaming writer includes checkpointing, schema merging and continuous polling.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/","sourceTitle":"What is Auto Loader? | Databricks on AWS","sourcePage":38,"images":["questions/077-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"In order to facilitate near real-time workloads, a data engineer is creating a helper function to leverage the schema detection and evolution\nfunctionality of Databricks Auto Loader. The desired function will automatically detect the schema of the source directly, incrementally process\nJSON files as they arrive in a source directory, and automatically evolve the schema of the table when new fields are detected.\nThe function is displayed below with a blank:\nWhich response correctly fills in the blank to meet the specified requirements?","options":[{"id":"A","text":"[Code choice shown in the original PDF image]"},{"id":"B","text":"[Code choice shown in the original PDF image]"},{"id":"C","text":"[Code choice shown in the original PDF image]"},{"id":"D","text":"[Code choice shown in the original PDF image]"},{"id":"E","text":"[Code choice shown in the original PDF image]"}],"correctAnswers":["E"],"explanation":"E combines a streaming writer, persistent checkpoint and mergeSchema without stopping after one trigger. A omits the checkpoint, B is a one-shot run and C/D use a batch writer on a streaming DataFrame.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"def auto_load_json(source_path, checkpoint_path, target_table_path):\n    incoming = (spark.readStream.format(\"cloudFiles\")\n        .option(\"cloudFiles.format\", \"json\")\n        .option(\"cloudFiles.schemaLocation\", checkpoint_path + \"/schema\")\n        .option(\"cloudFiles.schemaEvolutionMode\", \"addNewColumns\")\n        .load(source_path))\n    # Return the selected writer expression below.","reviewNote":"Second audit: Schema additions can stop Auto Loader; configured retries perform recovery. Made the Delta sink and checkpoints explicit.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":78,"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source table has been de-duplicated and validated, which statement\ndescribes what will occur when this code is executed?","options":[{"id":"A","text":"The silver_customer_sales table will be overwritten by aggregated values calculated from all records in the\ngold_customer_lifetime_sales_summary table as a batch job.","rationale":"The named source and target are reversed.","isCorrect":false},{"id":"B","text":"A batch job will update the gold_customer_lifetime_sales_summary table, replacing only those rows that have different values than the\ncurrent version of the table, using customer_id as the primary key.","rationale":"Overwrite is not a primary-key upsert.","isCorrect":false},{"id":"C","text":"The gold_customer_lifetime_sales_summary table will be overwritten by aggregated values calculated from all records in the\nsilver_customer_sales table as a batch job.","rationale":"The batch aggregates replace the target summary.","isCorrect":true},{"id":"D","text":"An incremental job will leverage running information in the state store to update aggregate values in the\ngold_customer_lifetime_sales_summary table.","rationale":"There is no stateful streaming aggregation.","isCorrect":false},{"id":"E","text":"An incremental job will detect if new rows have been written to the silver_customer_sales table; if new rows are detected, all aggregates will\nbe recalculated and used to overwrite the gold_customer_lifetime_sales_summary table.","rationale":"No incremental source change detection is implemented.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The batch aggregates replace the target summary.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":39,"images":["questions/078-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source table has been de-duplicated and validated, which statement\ndescribes what will occur when this code is executed?","options":[{"id":"A","text":"The silver_customer_sales table will be overwritten by aggregated values calculated from all records in the\ngold_customer_lifetime_sales_summary table as a batch job."},{"id":"B","text":"A batch job will update the gold_customer_lifetime_sales_summary table, replacing only those rows that have different values than the\ncurrent version of the table, using customer_id as the primary key."},{"id":"C","text":"The gold_customer_lifetime_sales_summary table will be overwritten by aggregated values calculated from all records in the\nsilver_customer_sales table as a batch job."},{"id":"D","text":"An incremental job will leverage running information in the state store to update aggregate values in the\ngold_customer_lifetime_sales_summary table."},{"id":"E","text":"An incremental job will detect if new rows have been written to the silver_customer_sales table; if new rows are detected, all aggregates will\nbe recalculated and used to overwrite the gold_customer_lifetime_sales_summary table."}],"correctAnswers":["C"],"explanation":"The code uses spark.table and batch write.mode('overwrite'). It recomputes all customer aggregates and replaces the gold table; it is not incremental or a reverse write into silver.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"from pyspark.sql import functions as F\n(spark.table(\"silver_customer_sales\")\n .groupBy(\"customer_id\")\n .agg(F.min(\"sale_date\").alias(\"first_transaction_date\"),\n      F.max(\"sale_date\").alias(\"last_transaction_date\"),\n      F.mean(\"sale_total\").alias(\"average_sales\"),\n      F.countDistinct(\"order_id\").alias(\"total_orders\"),\n      F.sum(\"sale_total\").alias(\"lifetime_value\"))\n .write.format(\"delta\").mode(\"overwrite\")\n .saveAsTable(\"gold_customer_lifetime_sales_summary\"))","reviewNote":"Second audit: Corrected the batch writer API to saveAsTable.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":79,"prompt":"The data architect has mandated that all tables in the Lakehouse should be configured as external (also known as \"unmanaged\") Delta Lake\ntables.\nWhich approach will ensure that this requirement is met?","options":[{"id":"A","text":"When a database is being created, make sure that the LOCATION keyword is used.","rationale":"A schema location does not establish external table ownership semantics.","isCorrect":false},{"id":"B","text":"When configuring an external data warehouse for all table storage, leverage Databricks for all ELT.","rationale":"An external warehouse is irrelevant to the table registration.","isCorrect":false},{"id":"C","text":"Create each registered Delta table with CREATE TABLE ... USING DELTA LOCATION '<approved-external-path>' (or an equivalent saveAsTable with an explicit path).","rationale":"The explicit table path registers external Delta storage.","isCorrect":true},{"id":"D","text":"When tables are created, make sure that the EXTERNAL keyword is used in the CREATE TABLE statement.","rationale":"The EXTERNAL keyword alone lacks a required location.","isCorrect":false},{"id":"E","text":"When the workspace is being configured, make sure that external cloud object storage has been mounted.","rationale":"Mounting a path does not make every table external.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The explicit table path registers external Delta storage.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":39,"images":["questions/079-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":79,"prompt":"The data architect has mandated that all tables in the Lakehouse should be configured as external (also known as \"unmanaged\") Delta Lake\ntables.\nWhich approach will ensure that this requirement is met?","options":[{"id":"A","text":"When a database is being created, make sure that the LOCATION keyword is used."},{"id":"B","text":"When configuring an external data warehouse for all table storage, leverage Databricks for all ELT."},{"id":"C","text":"When data is saved to a table, make sure that a full file path is specified alongside the Delta format."},{"id":"D","text":"When tables are created, make sure that the EXTERNAL keyword is used in the CREATE TABLE statement."},{"id":"E","text":"When the workspace is being configured, make sure that external cloud object storage has been mounted."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"A path-backed Delta write used to register an external table is the intended answer. A full path alone writes files, so table registration must also be explicit. Database LOCATION or mounting storage does not make every table external.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":39,"images":["questions/079-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Made the table-level external location explicit; a file write by itself does not register a table.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":80,"prompt":"The marketing team is looking to share data in an aggregate table with the sales organization, but the field names used by the teams do not\nmatch, and a number of marketing-specific fields have not been approved for the sales org.\nWhich of the following solutions addresses the situation while emphasizing simplicity?","options":[{"id":"A","text":"Create a view on the marketing table selecting only those fields approved for the sales team; alias the names of any fields that should be\nstandardized to the sales naming conventions.","rationale":"A projection view aliases approved columns without duplicating data.","isCorrect":true},{"id":"B","text":"Create a new table with the required schema and use Delta Lake's DEEP CLONE functionality to sync up changes committed to one table to\nthe corresponding table.","rationale":"A deep clone is not automatic synchronization.","isCorrect":false},{"id":"C","text":"Use a CTAS statement to create a derivative table from the marketing table; configure a production job to propagate changes.","rationale":"CTAS plus scheduled copying adds avoidable maintenance.","isCorrect":false},{"id":"D","text":"Add a parallel table write to the current production pipeline, updating a new sales table that varies as required from the marketing table.","rationale":"A parallel physical table adds avoidable writes and maintenance.","isCorrect":false},{"id":"E","text":"Instruct the marketing team to download results as a CSV and email them to the sales organization.","rationale":"Emailing snapshots adds manual work and loses a governed live interface.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A projection view aliases approved columns without duplicating data.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":40,"images":["questions/080-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":81,"prompt":"A CHECK constraint has been successfully added to the Delta table named activity_details using the following logic:\nA batch job is attempting to insert new records to the table, including a record where latitude = 45.50 and longitude = 212.67.\nWhich statement describes the outcome of this batch insert?","options":[{"id":"A","text":"The write will fail when the violating record is reached; any records previously processed will be recorded to the target table.","rationale":"A constraint violation aborts the entire write transaction.","isCorrect":false},{"id":"B","text":"The write will fail completely because of the constraint violation and no records will be inserted into the target table.","rationale":"No rows from the failed write transaction are committed.","isCorrect":true},{"id":"C","text":"The write will insert all records except those that violate the table constraints; the violating records will be recorded to a quarantine table.","rationale":"CHECK does not automatically route invalid rows to quarantine.","isCorrect":false},{"id":"D","text":"The write will include all records in the target table; any violations will be indicated in the boolean column named valid_coordinates.","rationale":"A constraint name is not a generated Boolean column.","isCorrect":false},{"id":"E","text":"The write will insert all records except those that violate the table constraints; the violating records will be reported in a warning log.","rationale":"CHECK does not silently drop invalid rows and commit the rest.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"No rows from the failed write transaction are committed.","topic":"constraints","sourceUrl":"https://docs.databricks.com/aws/en/tables/constraints","sourceTitle":"Constraints on Databricks | Databricks on AWS","sourcePage":40,"images":["questions/081-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":82,"prompt":"A junior data engineer has manually configured a series of jobs using the Databricks Jobs UI. Upon reviewing their work, the engineer realizes that\nthey are listed as the \"Owner\" for each job. They attempt to transfer \"Owner\" privileges to the \"DevOps\" group, but cannot successfully accomplish\nthis task.\nWhich statement explains what is preventing this privilege transfer?","options":[{"id":"A","text":"Databricks jobs must have exactly one owner; \"Owner\" privileges cannot be assigned to a group.","rationale":"A job has one owner, and a group cannot hold ownership.","isCorrect":true},{"id":"B","text":"The creator of a Databricks job will always have \"Owner\" privileges; this configuration cannot be changed.","rationale":"Ownership can be transferred to another eligible identity.","isCorrect":false},{"id":"C","text":"Other than the default \"admins\" group, only individual users can be granted privileges on jobs.","rationale":"Groups can receive other job permissions.","isCorrect":false},{"id":"D","text":"A user can only transfer job ownership to a group if they are also a member of that group.","rationale":"Group membership does not make group ownership valid.","isCorrect":false},{"id":"E","text":"Only workspace administrators can grant \"Owner\" privileges to a group.","rationale":"Administrator status does not make a group eligible for ownership.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A job has one owner, and a group cannot hold ownership.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":41,"images":["questions/082-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":83,"prompt":"All records from an Apache Kafka producer are being ingested into a single Delta Lake table with the following schema:\nkey BINARY, value BINARY, topic STRING, partition LONG, offset LONG, timestamp LONG\nThere are 5 unique topics being ingested. Only the \"registration\" topic contains Personal Identifiable Information (PII). The company wishes to\nrestrict access to PII. The company also wishes to only retain records containing PII in this table for 14 days after initial ingestion. However, for\nnon-PII information, it would like to retain these records indefinitely.\nWhich of the following solutions meets the requirements?","options":[{"id":"A","text":"All data should be deleted biweekly; Delta Lake's time travel functionality should be leveraged to maintain a history of non-PII information.","rationale":"Deleting all data also destroys the required non-PII history.","isCorrect":false},{"id":"B","text":"Data should be partitioned by the registration field, allowing ACLs and delete statements to be set for the PII directory.","rationale":"registration is a topic value, not the stated partition column.","isCorrect":false},{"id":"C","text":"Because the value field is stored as binary data, this information is not considered PII and no special precautions should be taken.","rationale":"Binary encoding does not remove sensitivity.","isCorrect":false},{"id":"D","text":"Separate object storage containers should be specified based on the partition field, allowing isolation at the storage level.","rationale":"Kafka partition number does not identify the PII topic or retention policy.","isCorrect":false},{"id":"E","text":"Track ingestion time; enforce a topic-based row filter or restricted dynamic views with no bypass access. Delete registration rows after 14 days and schedule file purge/VACUUM with retention configured for the physical-removal deadline; retain other topics. Topic partitioning may help selective maintenance.","rationale":"The complete policy combines access enforcement, expiry and physical cleanup.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"The complete policy combines access enforcement, expiry and physical cleanup.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Unity Catalog row filters and column masks","sourcePage":41,"images":["questions/083-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":83,"prompt":"All records from an Apache Kafka producer are being ingested into a single Delta Lake table with the following schema:\nkey BINARY, value BINARY, topic STRING, partition LONG, offset LONG, timestamp LONG\nThere are 5 unique topics being ingested. Only the \"registration\" topic contains Personal Identifiable Information (PII). The company wishes to\nrestrict access to PII. The company also wishes to only retain records containing PII in this table for 14 days after initial ingestion. However, for\nnon-PII information, it would like to retain these records indefinitely.\nWhich of the following solutions meets the requirements?","options":[{"id":"A","text":"All data should be deleted biweekly; Delta Lake's time travel functionality should be leveraged to maintain a history of non-PII information."},{"id":"B","text":"Data should be partitioned by the registration field, allowing ACLs and delete statements to be set for the PII directory."},{"id":"C","text":"Because the value field is stored as binary data, this information is not considered PII and no special precautions should be taken."},{"id":"D","text":"Separate object storage containers should be specified based on the partition field, allowing isolation at the storage level."},{"id":"E","text":"Data should be partitioned by the topic field, allowing ACLs and delete statements to leverage partition boundaries."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["E"],"status":"review","explanation":"Partitioning by topic helps targeted retention, but partitioning alone does not impose SQL row-level ACLs or a 14-day purge policy. E is the intended layout, yet no option fully implements the security and retention requirements. Keep unscored.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":41,"images":["questions/083-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Added actual row access controls and retention operations; directory partitioning alone does neither.","studyContext":"The deployment permits the required retention configuration. Prevent direct storage and historical-version access from bypassing the PII policy.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":84,"prompt":"The data architect has decided that once data has been ingested from external sources into the\nDatabricks Lakehouse, table access controls will be leveraged to manage permissions for all production tables and views.\nThe following logic was executed to grant privileges for interactive queries on a production database to the core engineering group.\nGRANT USAGE ON DATABASE prod TO eng;\nGRANT SELECT ON DATABASE prod TO eng;\nAssuming these are the only privileges that have been granted to the eng group and that these users are not workspace administrators, which\nstatement describes their privileges?","options":[{"id":"A","text":"Group members have full permissions on the prod database and can also assign permissions to other users or groups.","rationale":"SELECT and USAGE do not grant administration.","isCorrect":false},{"id":"B","text":"Group members are able to list all tables in the prod database but are not able to see the results of any queries on those tables.","rationale":"SELECT permits reading table data.","isCorrect":false},{"id":"C","text":"Group members are able to query and modify all tables and views in the prod database, but cannot create new tables or views.","rationale":"No modification privilege was granted.","isCorrect":false},{"id":"D","text":"Group members are able to query all tables and views in the prod database, but cannot create or edit anything in the database.","rationale":"The grants allow querying without creating or modifying objects.","isCorrect":true},{"id":"E","text":"Group members are able to create, query, and modify all tables and views in the prod database, but cannot define custom functions.","rationale":"No CREATE or MODIFY privileges were granted.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The grants allow querying without creating or modifying objects.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":42,"images":["questions/084-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":84,"prompt":"The data architect has decided that once data has been ingested from external sources into the\nDatabricks Lakehouse, table access controls will be leveraged to manage permissions for all production tables and views.\nThe following logic was executed to grant privileges for interactive queries on a production database to the core engineering group.\nGRANT USAGE ON DATABASE prod TO eng;\nGRANT SELECT ON DATABASE prod TO eng;\nAssuming these are the only privileges that have been granted to the eng group and that these users are not workspace administrators, which\nstatement describes their privileges?","options":[{"id":"A","text":"Group members have full permissions on the prod database and can also assign permissions to other users or groups."},{"id":"B","text":"Group members are able to list all tables in the prod database but are not able to see the results of any queries on those tables."},{"id":"C","text":"Group members are able to query and modify all tables and views in the prod database, but cannot create new tables or views."},{"id":"D","text":"Group members are able to query all tables and views in the prod database, but cannot create or edit anything in the database."},{"id":"E","text":"Group members are able to create, query, and modify all tables and views in the prod database, but cannot define custom functions."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"Under the stated Hive-metastore ACL model, USAGE plus SELECT permits reading database tables/views without CREATE or MODIFY. It does not grant permission administration.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":42,"images":["questions/084-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use legacy Hive-metastore table access controls with only the grants stated in the question.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":85,"prompt":"A distributed team of data analysts share computing resources on an interactive cluster with autoscaling configured. In order to better manage\ncosts and query throughput, the workspace administrator is hoping to evaluate whether cluster upscaling is caused by many concurrent users or\nresource-intensive queries.\nIn which location can one review the timeline for cluster resizing events?","options":[{"id":"A","text":"Workspace audit logs","rationale":"Audit logs are not the dedicated compute-lifecycle timeline.","isCorrect":false},{"id":"B","text":"Driver's log file","rationale":"Driver logs are not the primary cluster-resize event timeline.","isCorrect":false},{"id":"C","text":"Ganglia","rationale":"Resource metrics do not replace the lifecycle event log.","isCorrect":false},{"id":"D","text":"Cluster Event Log","rationale":"The compute event log records resizing events.","isCorrect":true},{"id":"E","text":"Executor's log file","rationale":"Executor logs do not provide the dedicated cluster-wide lifecycle timeline.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The compute event log records resizing events.","topic":"compute","sourceUrl":"https://docs.databricks.com/aws/en/compute/clusters-manage","sourceTitle":"Manage classic compute | Databricks on AWS","sourcePage":42,"images":["questions/085-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":86,"prompt":"When evaluating the Ganglia Metrics for a given cluster with 3 executor nodes, which indicator would signal proper utilization of the VM's\nresources?","options":[{"id":"A","text":"The five Minute Load Average remains consistent/flat","rationale":"A flat load average does not establish the stated CPU distribution.","isCorrect":false},{"id":"B","text":"Bytes Received never exceeds 80 million bytes per second","rationale":"This network threshold does not establish worker utilization.","isCorrect":false},{"id":"C","text":"Network I/O never spikes","rationale":"Quiet networking does not establish CPU utilization.","isCorrect":false},{"id":"D","text":"Total Disk Space remains constant","rationale":"Disk capacity is unrelated to this CPU calculation.","isCorrect":false},{"id":"E","text":"CPU Utilization is around 75%","rationale":"Three busy nodes out of four equal nodes gives about 75%.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"scoped","explanation":"Three busy nodes out of four equal nodes gives about 75%.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":42,"images":["questions/086-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":86,"prompt":"When evaluating the Ganglia Metrics for a given cluster with 3 executor nodes, which indicator would signal proper utilization of the VM's\nresources?","options":[{"id":"A","text":"The five Minute Load Average remains consistent/flat"},{"id":"B","text":"Bytes Received never exceeds 80 million bytes per second"},{"id":"C","text":"Network I/O never spikes"},{"id":"D","text":"Total Disk Space remains constant"},{"id":"E","text":"CPU Utilization is around 75%"}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"best_fit","explanation":"With three busy workers and a mostly idle similarly sized driver, aggregate CPU near 75% can indicate worker utilization. This is a heuristic, not a universal optimum; flat load or quiet networking alone cannot establish efficiency.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":42,"images":["questions/086-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Assume three equally sized busy workers and one equally sized mostly idle driver. Choose the approximate aggregate CPU utilization consistent with that condition.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":87,"prompt":"Which listed technology is a pattern notation designed to match and extract substrings in text?","options":[{"id":"A","text":"Regex","rationale":"Regular expressions directly describe text-matching patterns.","isCorrect":true},{"id":"B","text":"Julia","rationale":"Julia is a programming language, not the requested pattern notation.","isCorrect":false},{"id":"C","text":"pyspsark.ml.feature","rationale":"This misspelled package name is not a pattern-matching notation.","isCorrect":false},{"id":"D","text":"Scala Datasets","rationale":"Datasets are a typed distributed-data API, not text-pattern syntax.","isCorrect":false},{"id":"E","text":"C++","rationale":"C++ is a programming language, not the requested pattern notation.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"Regular expressions directly describe text-matching patterns.","topic":"python","sourceUrl":"https://docs.python.org/3/tutorial/modules.html","sourceTitle":"6. Modules — Python 3.14.8 documentation","sourcePage":43,"images":["questions/087-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"Which of the following technologies can be used to identify key areas of text when parsing Spark Driver log4j output?","options":[{"id":"A","text":"Regex"},{"id":"B","text":"Julia"},{"id":"C","text":"pyspsark.ml.feature"},{"id":"D","text":"Scala Datasets"},{"id":"E","text":"C++"}],"correctAnswers":["A"],"explanation":"Regular expressions identify structured text patterns in log output. The other choices are languages or unrelated APIs, not the specific pattern-matching technique asked for.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: General-purpose languages can also process text; the question now asks specifically for a pattern notation.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":88,"prompt":"You are testing a collection of mathematical functions, one of which calculates the area under a curve as described by another function.\nassert(myIntegrate(lambda x: x*x, 0, 3) [0] == 9)\nWhich kind of test would the above line exemplify?","options":[{"id":"A","text":"Unit","rationale":"The assertion checks one mathematical function in isolation.","isCorrect":true},{"id":"B","text":"Manual","rationale":"It is a programmatic assertion, not necessarily manual testing.","isCorrect":false},{"id":"C","text":"Functional","rationale":"The isolated-function scope is more specifically unit testing.","isCorrect":false},{"id":"D","text":"Integration","rationale":"Mathematical integration is not subsystem integration testing.","isCorrect":false},{"id":"E","text":"End-to-end","rationale":"No complete application workflow is exercised.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"The assertion checks one mathematical function in isolation.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":43,"images":["questions/088-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":89,"prompt":"A Databricks job has been configured with 3 tasks, each of which is a Databricks notebook. Task A does not depend on other tasks. Tasks B and C\nrun in parallel, with each having a serial dependency on Task A.\nIf task A fails during a scheduled run, which statement describes the results of this run?","options":[{"id":"A","text":"Because all tasks are managed as a dependency graph, no changes will be committed to the Lakehouse until all tasks have successfully\nbeen completed.","rationale":"Jobs do not commit every task as one transaction.","isCorrect":false},{"id":"B","text":"Tasks B and C will attempt to run as configured; any changes made in task A will be rolled back due to task failure.","rationale":"Default downstream dependencies require upstream success; no automatic rollback occurs.","isCorrect":false},{"id":"C","text":"Unless all tasks complete successfully, no changes will be committed to the Lakehouse; because task A failed, all commits will be rolled\nback automatically.","rationale":"There is no implicit job-wide rollback.","isCorrect":false},{"id":"D","text":"Tasks B and C will be skipped; some logic expressed in task A may have been committed before task failure.","rationale":"With default success dependencies, B/C skip; earlier A commits may remain.","isCorrect":true},{"id":"E","text":"Tasks B and C will be skipped; task A will not commit any changes because of stage failure.","rationale":"An earlier successful operation in A may already have committed.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"With default success dependencies, B/C skip; earlier A commits may remain.","topic":"jobs","sourceUrl":"https://docs.databricks.com/aws/en/jobs/","sourceTitle":"Lakeflow Jobs | Databricks on AWS","sourcePage":43,"images":["questions/089-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A Databricks job has been configured with 3 tasks, each of which is a Databricks notebook. Task A does not depend on other tasks. Tasks B and C\nrun in parallel, with each having a serial dependency on Task A.\nIf task A fails during a scheduled run, which statement describes the results of this run?","options":[{"id":"A","text":"Because all tasks are managed as a dependency graph, no changes will be committed to the Lakehouse until all tasks have successfully\nbeen completed."},{"id":"B","text":"Tasks B and C will attempt to run as configured; any changes made in task A will be rolled back due to task failure."},{"id":"C","text":"Unless all tasks complete successfully, no changes will be committed to the Lakehouse; because task A failed, all commits will be rolled\nback automatically."},{"id":"D","text":"Tasks B and C will be skipped; some logic expressed in task A may have been committed before task failure."},{"id":"E","text":"Tasks B and C will be skipped; task A will not commit any changes because of stage failure."}],"correctAnswers":["D"],"explanation":"With the default all-success dependency condition, B and C are skipped when A fails. Earlier writes in A can remain committed; orchestration does not imply rollback across its commands.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The downstream tasks use the default Run if condition, All succeeded, and no alternate failure-handling branches.","reviewNote":"Second audit: Skipped downstream tasks depend on their Run if setting.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":90,"prompt":"Which statement regarding Spark configuration on the Databricks platform is true?","options":[{"id":"A","text":"The Databricks REST API can be used to modify the Spark configuration properties for an interactive cluster without interrupting jobs\ncurrently running on the cluster.","rationale":"Editing cluster Spark configuration can restart compute.","isCorrect":false},{"id":"B","text":"Spark configurations set within a notebook will affect all SparkSessions attached to the same interactive cluster.","rationale":"Notebook/session settings do not automatically affect all sessions.","isCorrect":false},{"id":"C","text":"Spark configuration properties can only be set for an interactive cluster by creating a global init script.","rationale":"The cluster UI also supports Spark configuration.","isCorrect":false},{"id":"D","text":"Spark configuration properties set for an interactive cluster with the Clusters UI will impact all notebooks attached to that cluster.","rationale":"Cluster-level configuration supplies settings to attached notebooks.","isCorrect":true},{"id":"E","text":"When the same Spark configuration property is set for an interactive cluster and a notebook attached to that cluster, the notebook setting\nwill always be ignored.","rationale":"Supported session settings can override cluster defaults.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Cluster-level configuration supplies settings to attached notebooks.","topic":"compute","sourceUrl":"https://docs.databricks.com/aws/en/compute/clusters-manage","sourceTitle":"Manage classic compute | Databricks on AWS","sourcePage":44,"images":["questions/090-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":91,"prompt":"A developer has successfully configured their credentials for Databricks Repos and cloned a remote Git repository. They do not have privileges to\nmake changes to the main branch, which is the only branch currently visible in their workspace.\nWhich approach allows this user to share their code updates without the risk of overwriting the work of their teammates?","options":[{"id":"A","text":"Use Repos to checkout all changes and send the git diff log to the team.","rationale":"Sending a diff is not the requested normal branch-sharing workflow.","isCorrect":false},{"id":"B","text":"Use Repos to create a fork of the remote repository, commit all changes, and make a pull request on the source repository.","rationale":"Fork creation is done at the Git host, not by this Repos operation.","isCorrect":false},{"id":"C","text":"Use Repos to pull changes from the remote Git repository; commit and push changes to a branch that appeared as changes were pulled.","rationale":"An arbitrary newly fetched branch is not the developer's isolated branch.","isCorrect":false},{"id":"D","text":"Use Repos to merge all differences and make a pull request back to the remote repository.","rationale":"Merging differences first risks changing unrelated work.","isCorrect":false},{"id":"E","text":"Use Repos to create a new branch, commit all changes, and push changes to the remote Git repository.","rationale":"A separate branch allows commits without overwriting main.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"A separate branch allows commits without overwriting main.","topic":"git","sourceUrl":"https://docs.databricks.com/aws/en/repos/git-operations-with-repos","sourceTitle":"Create and manage Git folders | Databricks on AWS","sourcePage":44,"images":["questions/091-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":92,"prompt":"In order to prevent accidental commits to production data, a senior data engineer has instituted a policy that all development work will reference\nclones of Delta Lake tables. After testing both DEEP and SHALLOW CLONE, development tables are created using SHALLOW CLONE.\nA few weeks after initial table creation, the cloned versions of several tables implemented as Type 1 Slowly Changing Dimension (SCD) stop\nworking. The transaction logs for the source tables show that VACUUM was run the day before.\nWhich statement describes why the cloned tables are no longer working?","options":[{"id":"A","text":"Because Type 1 changes overwrite existing records, Delta Lake cannot guarantee data consistency for cloned tables.","rationale":"Type 1 updates do not inherently invalidate every clone.","isCorrect":false},{"id":"B","text":"Running VACUUM automatically invalidates any shallow clones of a table; DEEP CLONE should always be used when a cloned table will be\nrepeatedly queried.","rationale":"Vacuum only breaks clones when referenced files are removed.","isCorrect":false},{"id":"C","text":"Tables created with SHALLOW CLONE are automatically deleted after their default retention threshold of 7 days.","rationale":"Shallow clone tables do not automatically expire after seven days.","isCorrect":false},{"id":"D","text":"The metadata created by the CLONE operation is referencing data files that were purged as invalid by the VACUUM command.","rationale":"The clone references source files removed by vacuum.","isCorrect":true},{"id":"E","text":"The data files compacted by VACUUM are not tracked by the cloned metadata; running REFRESH on the cloned table will pull in recent\nchanges.","rationale":"VACUUM does not compact data; REFRESH does not reconstruct deleted files.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The clone references source files removed by vacuum.","topic":"clone","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/clone","sourceTitle":"Clone a table on Databricks | Databricks on AWS","sourcePage":44,"images":["questions/092-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":92,"prompt":"In order to prevent accidental commits to production data, a senior data engineer has instituted a policy that all development work will reference\nclones of Delta Lake tables. After testing both DEEP and SHALLOW CLONE, development tables are created using SHALLOW CLONE.\nA few weeks after initial table creation, the cloned versions of several tables implemented as Type 1 Slowly Changing Dimension (SCD) stop\nworking. The transaction logs for the source tables show that VACUUM was run the day before.\nWhich statement describes why the cloned tables are no longer working?","options":[{"id":"A","text":"Because Type 1 changes overwrite existing records, Delta Lake cannot guarantee data consistency for cloned tables."},{"id":"B","text":"Running VACUUM automatically invalidates any shallow clones of a table; DEEP CLONE should always be used when a cloned table will be\nrepeatedly queried."},{"id":"C","text":"Tables created with SHALLOW CLONE are automatically deleted after their default retention threshold of 7 days."},{"id":"D","text":"The metadata created by the CLONE operation is referencing data files that were purged as invalid by the VACUUM command."},{"id":"E","text":"The data files compacted by VACUUM are not tracked by the cloned metadata; running REFRESH on the cloned table will pull in recent\nchanges."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"A legacy shallow clone references source data files; source VACUUM can remove those files and break it. Unity Catalog managed shallow clones on supported runtimes have different retention protection, so do not generalize this to every modern clone.","topic":"clone","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/clone","sourceTitle":"Clone a table on Databricks | Databricks on AWS","sourcePage":44,"images":["questions/092-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use a Hive-metastore shallow clone that references source files; Unity Catalog managed shallow-clone retention protections do not apply.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":93,"prompt":"You are performing a join operation to combine values from a static userLookup table with a streaming DataFrame streamingDF.\nWhich code block attempts to perform an invalid stream-static join?","options":[{"id":"A","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"inner\")","rationale":"An inner static/stream join is supported.","isCorrect":false},{"id":"B","text":"streamingDF.join(userLookup, [\"user_id\"], how=\"outer\")","rationale":"A full outer stream/static join is unsupported.","isCorrect":true},{"id":"C","text":"streamingDF.join(userLookup, [\"user_id\"], how=\"left\")","rationale":"A left outer join can preserve the streaming left side.","isCorrect":false},{"id":"D","text":"streamingDF.join(userLookup, [\"user_id\"], how=\"inner\")","rationale":"An inner stream/static join is supported.","isCorrect":false},{"id":"E","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"right\")","rationale":"A right outer join can preserve the streaming right side.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"A full outer stream/static join is unsupported.","topic":"joins","sourceUrl":"https://docs.databricks.com/aws/en/transform/join","sourceTitle":"Work with joins on Databricks | Databricks on AWS","sourcePage":45,"images":["questions/093-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"You are performing a join operation to combine values from a static userLookup table with a streaming DataFrame streamingDF.\nWhich code block attempts to perform an invalid stream-static join?","options":[{"id":"A","text":"userLookup.join(streamingDF, [\"userid\"], how=\"inner\")"},{"id":"B","text":"streamingDF.join(userLookup, [\"user_id\"], how=\"outer\")"},{"id":"C","text":"streamingDF.join(userLookup, [\"user_id”], how=\"left\")"},{"id":"D","text":"streamingDF.join(userLookup, [\"userid\"], how=\"inner\")"},{"id":"E","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"right\")"}],"correctAnswers":["B"],"explanation":"A full outer stream-static join is unsupported. Inner joins and outer joins that preserve the streaming side are supported; the shown user_id/userid spelling must match the actual schemas.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Normalized column names and quotes so the join type, rather than a typo, determines the answer.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":94,"prompt":"Spill occurs as a result of executing various wide transformations. However, diagnosing spill requires one to proactively look for key indicators.\nWhere in the Spark UI are two of the primary indicators that a partition is spilling to disk?","options":[{"id":"A","text":"Query’s detail screen and Job’s detail screen","rationale":"The jobs page does not provide both requested spill operator/task metrics.","isCorrect":false},{"id":"B","text":"Stage’s detail screen and Executor’s log files","rationale":"Log files are not the pair of native UI metric views requested.","isCorrect":false},{"id":"C","text":"Driver’s and Executor’s log files","rationale":"Logs are not the requested Spark UI detail views.","isCorrect":false},{"id":"D","text":"Executor’s detail screen and Executor’s log files","rationale":"Executor views do not replace stage and query operator metrics.","isCorrect":false},{"id":"E","text":"Stage’s detail screen and Query’s detail screen","rationale":"Stage task metrics and query operators expose spill information.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"Stage task metrics and query operators expose spill information.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":45,"images":["questions/094-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":95,"prompt":"An hourly job reads new Parquet order files on Databricks Runtime 13.3 LTS or newer. customer_id and order_id form the business key; time is the enqueue timestamp. Duplicate events can have different enqueue timestamps. The same persistent checkpoint is reused on every run. With the code below, which statement is correct?","options":[{"id":"A","text":"Duplicate records enqueued more than 2 hours apart may be retained and the orders table may contain duplicate records with the same\ncustomer_id and order_id.","rationale":"Duplicates beyond the supported watermark interval may survive.","isCorrect":true},{"id":"B","text":"All records will be held in the state store for 2 hours before being deduplicated and committed to the orders table.","rationale":"Rows need not wait two hours before output.","isCorrect":false},{"id":"C","text":"The orders table will contain only the most recent 2 hours of records and no duplicates will be present.","rationale":"The watermark bounds state, not total target history.","isCorrect":false},{"id":"D","text":"Duplicate records arriving more than 2 hours apart will be dropped, but duplicates that arrive in the same batch may both be written to the\norders table.","rationale":"Within-batch duplicates are removed; older duplicates are not always removed.","isCorrect":false},{"id":"E","text":"The orders table will not contain duplicates, but records arriving more than 2 hours late will be ignored and missing from the table.","rationale":"The operator does not guarantee deduplication outside the watermark interval.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"Duplicates beyond the supported watermark interval may survive.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Drop duplicates within a watermark","sourcePage":46,"images":["questions/095-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":95,"prompt":"A task orchestrator has been configured to run two hourly tasks. First, an outside system writes Parquet data to a directory mounted at\n/mnt/raw_orders/. After this data is written, a Databricks job containing the following code is executed:\nAssume that the fields customer_id and order_id serve as a composite key to uniquely identify each order, and that the time field indicates when\nthe record was queued in the source system.\nIf the upstream system is known to occasionally enqueue duplicate entries for a single order hours apart, which statement is correct?","options":[{"id":"A","text":"Duplicate records enqueued more than 2 hours apart may be retained and the orders table may contain duplicate records with the same\ncustomer_id and order_id."},{"id":"B","text":"All records will be held in the state store for 2 hours before being deduplicated and committed to the orders table."},{"id":"C","text":"The orders table will contain only the most recent 2 hours of records and no duplicates will be present."},{"id":"D","text":"Duplicate records arriving more than 2 hours apart will be dropped, but duplicates that arrive in the same batch may both be written to the\norders table."},{"id":"E","text":"The orders table will not contain duplicates, but records arriving more than 2 hours late will be ignored and missing from the table."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"The printed code uses dropDuplicates on business keys only, without the time column, and omits checkpoint configuration. It is not dropDuplicatesWithinWatermark. A's assumed two-hour state eviction is not established; do not score this question without specifying runtime/checkpoint and correcting the deduplication claim.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Apply watermarks to control data processing thresholds | Databricks on AWS","sourcePage":46,"images":["questions/095-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Specified watermark-aware deduplication and a stable checkpoint; the original dropDuplicates code did not establish the intended eviction behavior.","studyContext":"","code":"(spark.readStream.schema(order_schema).format(\"parquet\")\n .load(\"/mnt/raw_orders/\")\n .withWatermark(\"time\", \"2 hours\")\n .dropDuplicatesWithinWatermark([\"customer_id\", \"order_id\"])\n .writeStream.option(\"checkpointLocation\", \"/mnt/checkpoints/orders\")\n .trigger(availableNow=True).toTable(\"orders\"))","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":96,"prompt":"A junior data engineer is migrating a workload from a relational database system to the Databricks Lakehouse. The source system uses a star\nschema, leveraging foreign key constraints and multi-table inserts to validate records on write.\nWhich consideration will impact the decisions made by the engineer while migrating this workload?","options":[{"id":"A","text":"Databricks only allows foreign key constraints on hashed identifiers, which avoid collisions in highly-parallel writes.","rationale":"Foreign keys are not restricted to collision-free hash identifiers.","isCorrect":false},{"id":"B","text":"Databricks supports Spark SQL and JDBC; all logic can be directly migrated from the source system without refactoring.","rationale":"APIs do not remove semantic migration differences.","isCorrect":false},{"id":"C","text":"Committing to multiple tables simultaneously requires taking out multiple table locks and can lead to a state of deadlock.","rationale":"Delta does not use the described mandatory multi-table lock protocol.","isCorrect":false},{"id":"D","text":"All Delta Lake transactions are ACID compliant against a single table, and Databricks does not enforce foreign key constraints.","rationale":"The scoped legacy deployment has per-table ACID and unenforced foreign keys.","isCorrect":true},{"id":"E","text":"Foreign keys must reference a primary key field; multi-table inserts must leverage Delta Lake’s upsert functionality.","rationale":"MERGE does not implement arbitrary atomic multi-table inserts.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The scoped legacy deployment has per-table ACID and unenforced foreign keys.","topic":"transactions","sourceUrl":"https://docs.databricks.com/aws/en/transactions/","sourceTitle":"Transactions | Databricks on AWS","sourcePage":46,"images":["questions/096-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":96,"prompt":"A junior data engineer is migrating a workload from a relational database system to the Databricks Lakehouse. The source system uses a star\nschema, leveraging foreign key constraints and multi-table inserts to validate records on write.\nWhich consideration will impact the decisions made by the engineer while migrating this workload?","options":[{"id":"A","text":"Databricks only allows foreign key constraints on hashed identifiers, which avoid collisions in highly-parallel writes."},{"id":"B","text":"Databricks supports Spark SQL and JDBC; all logic can be directly migrated from the source system without refactoring."},{"id":"C","text":"Committing to multiple tables simultaneously requires taking out multiple table locks and can lead to a state of deadlock."},{"id":"D","text":"All Delta Lake transactions are ACID compliant against a single table, and Databricks does not enforce foreign key constraints."},{"id":"E","text":"Foreign keys must reference a primary key field; multi-table inserts must leverage Delta Lake’s upsert functionality."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"The traditional Delta model provides atomic transactions per table and does not enforce foreign keys. Current Databricks also offers scoped multi-statement/multi-table transactions, so the single-table statement is historical rather than universal.","topic":"transactions","sourceUrl":"https://docs.databricks.com/aws/en/transactions/","sourceTitle":"Transactions | Databricks on AWS","sourcePage":46,"images":["questions/096-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use standalone Delta table transactions in a legacy Hive-metastore deployment, without Unity Catalog catalog-commit multi-table transactions.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":97,"prompt":"A data architect has heard about Delta Lake’s built-in versioning and time travel capabilities. For auditing purposes, they have a requirement to\nmaintain a full record of all valid street addresses as they appear in the customers table.\nThe architect is interested in implementing a Type 1 table, overwriting existing records with new values and relying on Delta Lake time travel to\nsupport long-term auditing. A data engineer on the project feels that a Type 2 table will provide better performance and scalability.\nWhich piece of information is critical to this decision?","options":[{"id":"A","text":"Data corruption can occur if a query fails in a partially completed state because Type 2 tables require setting multiple fields in a single\nupdate.","rationale":"Delta writes remain atomic even when multiple columns change.","isCorrect":false},{"id":"B","text":"Shallow clones can be combined with Type 1 tables to accelerate historic queries for long-term versioning.","rationale":"A shallow clone is not a durable independent historical archive.","isCorrect":false},{"id":"C","text":"Delta Lake time travel cannot be used to query previous versions of these tables because Type 1 changes modify data files in place.","rationale":"Delta updates do not destroy all previous versions in place.","isCorrect":false},{"id":"D","text":"Delta tables support efficient current-state queries and retention-bounded time travel; preserve an explicit CDC/SCD history table when a durable row-level audit history is required.","rationale":"Finite-retention snapshots are not a substitute for durable row-version history.","isCorrect":true},{"id":"E","text":"Delta Lake only supports Type 0 tables; once records are inserted to a Delta Lake table, they cannot be modified.","rationale":"Delta supports updates, deletes and multiple SCD designs.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Finite-retention snapshots are not a substitute for durable row-version history.","topic":"history","sourceUrl":"https://docs.databricks.com/aws/en/tables/history","sourceTitle":"Work with table history | Databricks on AWS","sourcePage":47,"images":["questions/097-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data architect has heard about Delta Lake’s built-in versioning and time travel capabilities. For auditing purposes, they have a requirement to\nmaintain a full record of all valid street addresses as they appear in the customers table.\nThe architect is interested in implementing a Type 1 table, overwriting existing records with new values and relying on Delta Lake time travel to\nsupport long-term auditing. A data engineer on the project feels that a Type 2 table will provide better performance and scalability.\nWhich piece of information is critical to this decision?","options":[{"id":"A","text":"Data corruption can occur if a query fails in a partially completed state because Type 2 tables require setting multiple fields in a single\nupdate."},{"id":"B","text":"Shallow clones can be combined with Type 1 tables to accelerate historic queries for long-term versioning."},{"id":"C","text":"Delta Lake time travel cannot be used to query previous versions of these tables because Type 1 changes modify data files in place."},{"id":"D","text":"Delta Lake time travel does not scale well in cost or latency to provide a long-term versioning solution."},{"id":"E","text":"Delta Lake only supports Type 0 tables; once records are inserted to a Delta Lake table, they cannot be modified."}],"correctAnswers":["D"],"explanation":"Time travel depends on retained files/logs and is not a durable business-history model. An SCD Type 2 table explicitly stores historical versions; shallow clones are not an archival substitute.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Time travel is limited by retention and is not a permanent audit archive.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":98,"prompt":"A table named user_ltv is being used to create a view that will be used by data analysts on various teams. Users in the workspace are configured\ninto groups, which are used for setting up data access using ACLs.\nThe user_ltv table has the following schema:\nemail STRING, age INT, ltv INT\nThe following view definition is executed:\nAn analyst who is not a member of the auditing group executes the following query:\nSELECT * FROM user_ltv_no_minors\nWhich statement describes the results returned by this query?","options":[{"id":"A","text":"All columns will be displayed normally for those records that have an age greater than 17; records not meeting this condition will be\nomitted.","rationale":"Non-auditors retain every selected column only for adult rows.","isCorrect":true},{"id":"B","text":"All age values less than 18 will be returned as null values, all other columns will be returned with the values in user_ltv.","rationale":"This filters rows rather than replacing age with null.","isCorrect":false},{"id":"C","text":"All values for the age column will be returned as null values, all other columns will be returned with the values in user_ltv.","rationale":"Age is not masked to null.","isCorrect":false},{"id":"D","text":"All records from all columns will be displayed with the values in user_ltv.","rationale":"The age predicate removes minors for this user.","isCorrect":false},{"id":"E","text":"All columns will be displayed normally for those records that have an age greater than 18; records not meeting this condition will be\nomitted.","rationale":"The predicate includes age 18, not only ages above 18.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Non-auditors retain every selected column only for adult rows.","topic":"dynamicviews","sourceUrl":"https://docs.databricks.com/aws/en/views/dynamic","sourceTitle":"Create a dynamic view | Databricks on AWS","sourcePage":48,"images":["questions/098-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":99,"prompt":"Delete events from user_lookup are read through its enabled change data feed and propagated to user_aggregates using the code below. Assume the chosen time interval exists in retained CDF history and contains all relevant deletion requests. Does successful execution guarantee the deleted target records are no longer accessible through retained historical data?","options":[{"id":"A","text":"No; the Delta Lake DELETE command only provides ACID guarantees when combined with the MERGE INTO command.","rationale":"DELETE has its own ACID guarantees.","isCorrect":false},{"id":"B","text":"No; files containing deleted records may still be accessible with time travel until a VACUUM command is used to remove invalidated data\nfiles.","rationale":"Historical files can remain after the logical delete.","isCorrect":true},{"id":"C","text":"Yes; the change data feed uses foreign keys to ensure delete consistency throughout the Lakehouse.","rationale":"CDF does not enforce foreign-key consistency.","isCorrect":false},{"id":"D","text":"Yes; Delta Lake ACID guarantees provide assurance that the DELETE command succeeded fully and permanently purged these records.","rationale":"Atomic logical deletion is not an immediate physical purge.","isCorrect":false},{"id":"E","text":"No; the change data feed only tracks inserts and updates, not deleted records.","rationale":"CDF includes delete events.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Historical files can remain after the logical delete.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":49,"images":["questions/099-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":99,"prompt":"The data governance team is reviewing code used for deleting records for compliance with GDPR. The following logic has been implemented to\npropagate delete requests from the user_lookup table to the user_aggregates table.\nAssuming that user_id is a unique identifying key and that all users that have requested deletion have been removed from the user_lookup table,\nwhich statement describes whether successfully executing the above logic guarantees that the records to be deleted from the user_aggregates\ntable are no longer accessible and why?","options":[{"id":"A","text":"No; the Delta Lake DELETE command only provides ACID guarantees when combined with the MERGE INTO command."},{"id":"B","text":"No; files containing deleted records may still be accessible with time travel until a VACUUM command is used to remove invalidated data\nfiles."},{"id":"C","text":"Yes; the change data feed uses foreign keys to ensure delete consistency throughout the Lakehouse."},{"id":"D","text":"Yes; Delta Lake ACID guarantees provide assurance that the DELETE command succeeded fully and permanently purged these records."},{"id":"E","text":"No; the change data feed only tracks inserts and updates, not deleted records."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Deleting target rows changes the current snapshot but does not immediately remove retained historical files. CDF includes deletes but does not enforce cross-table foreign-key consistency or permanent purge. The image uses readChangeData; the supported option is readChangeFeed. The conclusion assumes that typo is fixed, as the question assumes successful execution.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":49,"images":["questions/099-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected readChangeData to readChangeFeed in the source code.","studyContext":"","code":"(spark.read.format(\"delta\")\n .option(\"readChangeFeed\", \"true\")\n .option(\"startingTimestamp\", \"2021-08-22 00:00:00\")\n .option(\"endingTimestamp\", \"2021-08-29 00:00:00\")\n .table(\"user_lookup\").createOrReplaceTempView(\"changes\"))\nspark.sql(\"\"\"DELETE FROM user_aggregates\n WHERE user_id IN (SELECT user_id FROM changes WHERE _change_type = 'delete')\"\"\")","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":100,"prompt":"The data engineering team has been tasked with configuring connections to an external database that does not have a supported native\nconnector with Databricks. The external database already has data security configured by group membership. These groups map directly to user\ngroups already created in Databricks that represent various teams within the company.\nA new login credential has been created for each group in the external database. The Databricks Utilities Secrets module will be used to make\nthese credentials available to Databricks users.\nAssuming that all the credentials are configured correctly on the external database and group membership is properly configured on Databricks,\nwhich statement describes how teams can be granted the minimum necessary access to using these credentials?","options":[{"id":"A","text":"\"Manage\" permissions should be set on a secret key mapped to those credentials that will be used by a given team.","rationale":"Scope permissions cannot be granted per secret key this way.","isCorrect":false},{"id":"B","text":"\"Read\" permissions should be set on a secret key mapped to those credentials that will be used by a given team.","rationale":"The ACL boundary is the scope, not an individual key.","isCorrect":false},{"id":"C","text":"\"Read\" permissions should be set on a secret scope containing only those credentials that will be used by a given team.","rationale":"READ on a team-specific scope grants the needed least privilege.","isCorrect":true},{"id":"D","text":"\"Manage\" permissions should be set on a secret scope containing only those credentials that will be used by a given team.","rationale":"MANAGE unnecessarily allows changing the scope's permissions.","isCorrect":false},{"id":"E","text":"No additional configuration is necessary as long as all users are configured as administrators in the workspace where secrets have been\nadded.","rationale":"Administrator access is far broader than required.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"READ on a team-specific scope grants the needed least privilege.","topic":"secrets","sourceUrl":"https://docs.databricks.com/aws/en/security/secrets/","sourceTitle":"Secret management | Databricks on AWS","sourcePage":49,"images":["questions/100-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":101,"prompt":"Which indicators would you look for in the Spark UI’s Storage tab to signal that a cached table is not performing optimally? Assume you are using\nSpark’s MEMORY_ONLY storage level.","options":[{"id":"A","text":"Size on Disk is < Size in Memory","rationale":"Zero disk use is normal under MEMORY_ONLY.","isCorrect":false},{"id":"B","text":"The RDD Block Name includes the “*” annotation signaling a failure to cache","rationale":"No such star annotation establishes a cache failure.","isCorrect":false},{"id":"C","text":"Size on Disk is > 0","rationale":"MEMORY_ONLY does not store evicted cached partitions on disk.","isCorrect":false},{"id":"D","text":"After a full action has materialized the cache, the number of Cached Partitions is less than the total number of Spark partitions.","rationale":"Missing cached partitions require recomputation after full materialization.","isCorrect":true},{"id":"E","text":"On Heap Memory Usage is within 75% of Off Heap Memory Usage","rationale":"This arbitrary heap comparison is not a cache completeness measure.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Missing cached partitions require recomputation after full materialization.","topic":"rdd","sourceUrl":"https://spark.apache.org/docs/latest/rdd-programming-guide.html","sourceTitle":"RDD Programming Guide - Spark 4.2.0 Documentation","sourcePage":50,"images":["questions/101-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":101,"prompt":"Which indicators would you look for in the Spark UI’s Storage tab to signal that a cached table is not performing optimally? Assume you are using\nSpark’s MEMORY_ONLY storage level.","options":[{"id":"A","text":"Size on Disk is < Size in Memory"},{"id":"B","text":"The RDD Block Name includes the “*” annotation signaling a failure to cache"},{"id":"C","text":"Size on Disk is > 0"},{"id":"D","text":"The number of Cached Partitions > the number of Spark Partitions"},{"id":"E","text":"On Heap Memory Usage is within 75% of Off Heap Memory Usage"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"No option correctly diagnoses MEMORY_ONLY caching. Evicted or uncached partitions are recomputed, not persisted to disk under this level. Look for fewer cached partitions than total partitions; the question's greater-than comparison is reversed.","topic":"rdd","sourceUrl":"https://spark.apache.org/docs/latest/rdd-programming-guide.html","sourceTitle":"RDD Programming Guide - Spark 4.2.0 Documentation","sourcePage":50,"images":["questions/101-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected the cached-partition comparison from greater-than to less-than.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":102,"prompt":"What is the first line of a Databricks Python notebook when viewed in a text editor?","options":[{"id":"A","text":"%python","rationale":"Language magics do not replace the source-format header.","isCorrect":false},{"id":"B","text":"// Databricks notebook source","rationale":"Double slash is the Scala header style, not Python.","isCorrect":false},{"id":"C","text":"# Databricks notebook source","rationale":"Python source-export notebooks use this comment header.","isCorrect":true},{"id":"D","text":"-- Databricks notebook source","rationale":"Double dash is the SQL comment header style.","isCorrect":false},{"id":"E","text":"# MAGIC %python","rationale":"MAGIC marks a magic command, not the required first-line header.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Python source-export notebooks use this comment header.","topic":"notebooks","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/notebooks-code","sourceTitle":"Develop code in Databricks notebooks | Databricks on AWS","sourcePage":50,"images":["questions/102-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"What is the first line of a Databricks Python notebook when viewed in a text editor?","options":[{"id":"A","text":"%python"},{"id":"B","text":"// Databricks notebook source"},{"id":"C","text":"# Databricks notebook source"},{"id":"D","text":"-- Databricks notebook source"},{"id":"E","text":"# MAGIC %python"}],"correctAnswers":["C"],"explanation":"A Python source-format Databricks notebook begins with # Databricks notebook source. Scala uses // and SQL uses --; a language magic is not the source-format header.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The file is a Python notebook exported in Databricks SOURCE format, not an .ipynb export.","reviewNote":"Second audit: Notebook headers apply to source exports, not every export format.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":103,"prompt":"Which statement describes a key benefit of an end-to-end test?","options":[{"id":"A","text":"Makes it easier to automate your test suite","rationale":"End-to-end tests can be harder, not inherently easier, to automate.","isCorrect":false},{"id":"B","text":"Pinpoints errors in the building blocks of your application","rationale":"Unit tests generally localize component failures more directly.","isCorrect":false},{"id":"C","text":"Provides testing coverage for all code paths and branches","rationale":"End-to-end coverage does not guarantee every branch is exercised.","isCorrect":false},{"id":"D","text":"Closely simulates real world usage of your application","rationale":"The complete workflow approximates user-visible application behavior.","isCorrect":true},{"id":"E","text":"Ensures code is optimized for a real-life workflow","rationale":"Passing does not establish performance optimization.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The complete workflow approximates user-visible application behavior.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":50,"images":["questions/103-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":104,"prompt":"The Databricks CLI is used to trigger a run of an existing job by passing the job_id parameter. The response that the job run request has been\nsubmitted successfully includes a field run_id.\nWhich statement describes what the number alongside this field represents?","options":[{"id":"A","text":"The job_id and number of times the job has been run are concatenated and returned.","rationale":"A run ID is not formed by concatenating a job ID and count.","isCorrect":false},{"id":"B","text":"The total number of jobs that have been run in the workspace.","rationale":"It is an identifier, not the workspace's job count.","isCorrect":false},{"id":"C","text":"The number of times the job definition has been run in this workspace.","rationale":"It is not the per-job execution count.","isCorrect":false},{"id":"D","text":"The job_id is returned in this field.","rationale":"The run ID differs from the job definition ID.","isCorrect":false},{"id":"E","text":"The response contains a run_id that uniquely identifies the newly created run within the workspace.","rationale":"It identifies the newly created run within the workspace.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"corrected","explanation":"It identifies the newly created run within the workspace.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":50,"images":["questions/104-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"The Databricks CLI is used to trigger a run of an existing job by passing the job_id parameter. The response that the job run request has been\nsubmitted successfully includes a field run_id.\nWhich statement describes what the number alongside this field represents?","options":[{"id":"A","text":"The job_id and number of times the job has been run are concatenated and returned."},{"id":"B","text":"The total number of jobs that have been run in the workspace."},{"id":"C","text":"The number of times the job definition has been run in this workspace."},{"id":"D","text":"The job_id is returned in this field."},{"id":"E","text":"The globally unique ID of the newly triggered run."}],"correctAnswers":["E"],"explanation":"run_id uniquely identifies the run across jobs, while job_id identifies its reusable definition. It is not a per-job run count or a concatenation of those values.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Scoped identifier uniqueness to the workspace.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":105,"prompt":"The data science team has created and logged a production model using MLflow. The model accepts a list of column names and returns a new\ncolumn of type DOUBLE.\nThe following code correctly imports the production model, loads the customers table containing the customer_id key column into a DataFrame,\nand defines the feature columns needed for the model.\nWhich code block will output a DataFrame with the schema \"customer_id LONG, predictions DOUBLE\"?","options":[{"id":"A","text":"df.map(lambda x:model(x[columns])).select(\"customer_id, predictions\")","rationale":"A Spark DataFrame does not expose this map-and-select pattern.","isCorrect":false},{"id":"B","text":"df.select(\"customer_id\", model(*columns).alias(\"predictions\"))","rationale":"The UDF returns a Column; selecting it with customer_id gives the schema.","isCorrect":true},{"id":"C","text":"model.predict(df, columns)","rationale":"The returned Spark UDF is not a model object with this predict method.","isCorrect":false},{"id":"D","text":"df.select(\"customer_id\", pandas_udf(model, columns).alias(\"predictions\"))","rationale":"Wrapping the Spark UDF with this pandas_udf signature is invalid.","isCorrect":false},{"id":"E","text":"df.apply(model, columns).select(\"customer_id, predictions\")","rationale":"Spark DataFrames do not expose this pandas-style apply call.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"The UDF returns a Column; selecting it with customer_id gives the schema.","topic":"mlflow","sourceUrl":"https://mlflow.org/docs/latest/api_reference/python_api/mlflow.pyfunc.html","sourceTitle":"mlflow.pyfunc","sourcePage":51,"images":["questions/105-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":106,"prompt":"A nightly batch job is configured to ingest all data files from a cloud object storage container where records are stored in a nested directory\nstructure YYYY/MM/DD. The data for each date represents all records that were processed by the source system on that date, noting that some\nrecords may be delayed as they await moderator approval. Each entry represents a user review of a product and has the following schema:\nuser_id STRING, review_id BIGINT, product_id BIGINT, review_timestamp TIMESTAMP, review_text STRING\nThe ingestion job is configured to append all data for the previous date to a target table reviews_raw with an identical schema to the source\nsystem. The next step in the pipeline is a batch write to propagate all new records inserted into reviews_raw to a table where data is fully\ndeduplicated, validated, and enriched.\nWhich solution minimizes the compute costs to propagate this batch of data?","options":[{"id":"A","text":"Perform a batch read on the reviews_raw table and perform an insert-only merge using the natural composite key user_id, review_id,\nproduct_id, review_timestamp.","rationale":"A full batch read repeatedly scans already processed history.","isCorrect":false},{"id":"B","text":"Configure a Structured Streaming read against the reviews_raw table using the trigger once execution mode to process new records as a\nbatch job.","rationale":"A finite checkpointed stream processes the new Delta input.","isCorrect":true},{"id":"C","text":"Use Delta Lake version history to get the difference between the latest version of reviews_raw and one version prior, then write these\nrecords to the next table.","rationale":"Version history metadata alone does not compute the necessary row changes.","isCorrect":false},{"id":"D","text":"Filter all records in the reviews_raw table based on the review_timestamp; batch append those records produced in the last 48 hours.","rationale":"Review timestamps can exclude delayed moderator-approved records.","isCorrect":false},{"id":"E","text":"Reprocess all records in reviews_raw and overwrite the next table in the pipeline.","rationale":"Full rebuild repeatedly processes the entire history.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"A finite checkpointed stream processes the new Delta input.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":51,"images":["questions/106-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":106,"prompt":"A nightly batch job is configured to ingest all data files from a cloud object storage container where records are stored in a nested directory\nstructure YYYY/MM/DD. The data for each date represents all records that were processed by the source system on that date, noting that some\nrecords may be delayed as they await moderator approval. Each entry represents a user review of a product and has the following schema:\nuser_id STRING, review_id BIGINT, product_id BIGINT, review_timestamp TIMESTAMP, review_text STRING\nThe ingestion job is configured to append all data for the previous date to a target table reviews_raw with an identical schema to the source\nsystem. The next step in the pipeline is a batch write to propagate all new records inserted into reviews_raw to a table where data is fully\ndeduplicated, validated, and enriched.\nWhich solution minimizes the compute costs to propagate this batch of data?","options":[{"id":"A","text":"Perform a batch read on the reviews_raw table and perform an insert-only merge using the natural composite key user_id, review_id,\nproduct_id, review_timestamp."},{"id":"B","text":"Configure a Structured Streaming read against the reviews_raw table using the trigger once execution mode to process new records as a\nbatch job."},{"id":"C","text":"Use Delta Lake version history to get the difference between the latest version of reviews_raw and one version prior, then write these\nrecords to the next table."},{"id":"D","text":"Filter all records in the reviews_raw table based on the review_timestamp; batch append those records produced in the last 48 hours."},{"id":"E","text":"Reprocess all records in reviews_raw and overwrite the next table in the pipeline."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"legacy","explanation":"A checkpointed finite streaming read processes only new Delta input rather than rescanning history. Event timestamps can miss delayed reviews. Use AvailableNow in new implementations because Trigger.Once is deprecated.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":51,"images":["questions/106-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Interpret trigger once as the supported finite trigger in the legacy runtime used by this question. Reuse a persistent checkpoint between runs. New code should use AvailableNow.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":107,"prompt":"Which statement describes Delta Lake optimized writes?","options":[{"id":"A","text":"Before a Jobs cluster terminates, OPTIMIZE is executed on all tables modified during the most recent job.","rationale":"Optimized writes are not a cluster-termination hook.","isCorrect":false},{"id":"B","text":"An asynchronous job runs after the write completes to detect if files could be further compacted; if yes, an OPTIMIZE job is executed\ntoward a default of 1 GB.","rationale":"This describes a different post-write maintenance concept.","isCorrect":false},{"id":"C","text":"Data is queued in a messaging bus instead of committing data directly to memory; all data is committed from the messaging bus in one\nbatch once the job is complete.","rationale":"No messaging bus is involved in optimized writes.","isCorrect":false},{"id":"D","text":"Optimized writes use logical partitions instead of directory partitions; because partition boundaries are only represented in metadata, fewer\nsmall files are written.","rationale":"Optimized writes do not eliminate physical partition directories.","isCorrect":false},{"id":"E","text":"A shuffle occurs prior to writing to try to group similar data together resulting in fewer files instead of each executor writing multiple files\nbased on directory partitions.","rationale":"A pre-write shuffle groups data to produce fewer small files.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"A pre-write shuffle groups data to produce fewer small files.","topic":"filesize","sourceUrl":"https://docs.databricks.com/aws/en/tables/tune-file-size","sourceTitle":"Control data file size | Databricks on AWS","sourcePage":52,"images":["questions/107-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":108,"prompt":"Which statement describes the default execution mode for Databricks Auto Loader?","options":[{"id":"A","text":"Cloud vendor-specific queue storage and notification services are configured to track newly arriving files; the target table is materialized by\ndirectly querying all valid files in the source directory.","rationale":"Notification discovery is not the stated configuration; target materialization is also wrong.","isCorrect":false},{"id":"B","text":"New files are identified by listing the input directory; the target table is materialized by directly querying all valid files in the source directory.","rationale":"Auto Loader loads new files rather than querying all files as a view.","isCorrect":false},{"id":"C","text":"Webhooks trigger a Databricks job to run anytime new data arrives in a source directory; new data are automatically merged into target\ntables using rules inferred from the data.","rationale":"It does not infer CDC merge rules from webhooks.","isCorrect":false},{"id":"D","text":"New files are identified by listing the input directory; new files are incrementally and idempotently loaded into the target Delta Lake table.","rationale":"The scoped default lists files and incrementally loads them with tracked progress.","isCorrect":true},{"id":"E","text":"Cloud vendor-specific queue storage and notification services are configured to track newly arriving files; new files are incrementally and\nidempotently loaded into the target Delta Lake table.","rationale":"Notification mode was explicitly excluded by the context.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The scoped default lists files and incrementally loads them with tracked progress.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/release-notes/runtime/18.1","sourceTitle":"Runtime 18.1: change to Auto Loader file-event defaults","sourcePage":52,"images":["questions/108-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":108,"prompt":"Which statement describes the default execution mode for Databricks Auto Loader?","options":[{"id":"A","text":"Cloud vendor-specific queue storage and notification services are configured to track newly arriving files; the target table is materialized by\ndirectly querying all valid files in the source directory."},{"id":"B","text":"New files are identified by listing the input directory; the target table is materialized by directly querying all valid files in the source directory."},{"id":"C","text":"Webhooks trigger a Databricks job to run anytime new data arrives in a source directory; new data are automatically merged into target\ntables using rules inferred from the data."},{"id":"D","text":"New files are identified by listing the input directory; new files are incrementally and idempotently loaded into the target Delta Lake table."},{"id":"E","text":"Cloud vendor-specific queue storage and notification services are configured to track newly arriving files; new files are incrementally and\nidempotently loaded into the target Delta Lake table."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"Directory listing was the default file-discovery mode, with incremental processing tracked in checkpoints. Newer runtimes can default to managed file events when available, so the answer depends on runtime and external-location setup.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/","sourceTitle":"What is Auto Loader? | Databricks on AWS","sourcePage":52,"images":["questions/108-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use Databricks Runtime 17.3 LTS, without managed file events or notification mode configured.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":109,"prompt":"A Delta Lake table representing metadata about content posts from users has the following schema:\nuser_id LONG, post_text STRING, post_id STRING, longitude FLOAT, latitude FLOAT, post_time TIMESTAMP, date DATE\nBased on the above schema, which column is a good candidate for partitioning the Delta Table?","options":[{"id":"A","text":"post_time","rationale":"A precise timestamp usually creates excessive partition cardinality.","isCorrect":false},{"id":"B","text":"latitude","rationale":"Continuous latitude values are poor directory partition keys here.","isCorrect":false},{"id":"C","text":"post_id","rationale":"Per-post identifiers create excessive small partitions.","isCorrect":false},{"id":"D","text":"user_id","rationale":"Per-user keys do not match the stated date-filter workload.","isCorrect":false},{"id":"E","text":"date","rationale":"Date matches the assumed daily volume and filter pattern.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"scoped","explanation":"Date matches the assumed daily volume and filter pattern.","topic":"partitioning","sourceUrl":"https://docs.databricks.com/aws/en/tables/partitions","sourceTitle":"When to partition tables on Databricks | Databricks on AWS","sourcePage":52,"images":["questions/109-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":109,"prompt":"A Delta Lake table representing metadata about content posts from users has the following schema:\nuser_id LONG, post_text STRING, post_id STRING, longitude FLOAT, latitude FLOAT, post_time TIMESTAMP, date DATE\nBased on the above schema, which column is a good candidate for partitioning the Delta Table?","options":[{"id":"A","text":"post_time"},{"id":"B","text":"latitude"},{"id":"C","text":"post_id"},{"id":"D","text":"user_id"},{"id":"E","text":"date"}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"best_fit","explanation":"Date is the most suitable traditional partition key among these choices; IDs and precise timestamps risk high cardinality. Partition only when table/partition sizes justify it; liquid clustering is preferred for many current workloads.","topic":"partitioning","sourceUrl":"https://docs.databricks.com/aws/en/tables/partitions","sourceTitle":"When to partition tables on Databricks | Databricks on AWS","sourcePage":52,"images":["questions/109-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Traditional directory partitioning is required and the table is large enough to justify it. Assume substantial daily data, common date filters and manageable date cardinality.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":110,"prompt":"A large company seeks to implement a near real-time solution involving hundreds of pipelines with parallel updates of many tables with extremely\nhigh volume and high velocity data.\nWhich of the following solutions would you implement to achieve this requirement?","options":[{"id":"A","text":"Use Databricks High Concurrency clusters, which leverage optimized cloud storage connections to maximize data throughput.","rationale":"Shared compute does not remove a cloud-storage request quota.","isCorrect":false},{"id":"B","text":"Partition ingestion tables by a small time duration to allow for many data files to be written in parallel.","rationale":"Fine partitioning can create small files and does not remove account quotas.","isCorrect":false},{"id":"C","text":"Configure Databricks to save all data to attached SSD volumes instead of object storage, increasing file I/O significantly.","rationale":"Executor disks are not durable replacement table storage.","isCorrect":false},{"id":"D","text":"Distribute the Delta tables across storage accounts or bucket/prefix capacity domains that have independent request-rate limits, according to the cloud provider.","rationale":"Independent storage capacity domains can spread throttled request load.","isCorrect":true},{"id":"E","text":"Store all tables in a single database to ensure that the Databricks Catalyst Metastore can load balance overall throughput.","rationale":"A catalog does not load-balance cloud-storage quotas.","isCorrect":false}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Independent storage capacity domains can spread throttled request load.","topic":"storage","sourceUrl":"https://docs.databricks.com/aws/en/lakehouse-architecture/performance-efficiency/best-practices","sourceTitle":"Best practices for performance efficiency | Databricks on AWS","sourcePage":53,"images":["questions/110-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":110,"prompt":"A large company seeks to implement a near real-time solution involving hundreds of pipelines with parallel updates of many tables with extremely\nhigh volume and high velocity data.\nWhich of the following solutions would you implement to achieve this requirement?","options":[{"id":"A","text":"Use Databricks High Concurrency clusters, which leverage optimized cloud storage connections to maximize data throughput."},{"id":"B","text":"Partition ingestion tables by a small time duration to allow for many data files to be written in parallel."},{"id":"C","text":"Configure Databricks to save all data to attached SSD volumes instead of object storage, increasing file I/O significantly."},{"id":"D","text":"Isolate Delta Lake tables in their own storage containers to avoid API limits imposed by cloud vendors."},{"id":"E","text":"Store all tables in a single database to ensure that the Databricks Catalyst Metastore can load balance overall throughput."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"best_fit","explanation":"Distributing tables across independent storage accounts/buckets can avoid a shared cloud request-rate bottleneck. A container alone does not bypass account-level limits on every cloud. The other options confuse compute concurrency, local disks or excessive partitioning with storage limits.","topic":"storage","sourceUrl":"https://docs.databricks.com/aws/en/lakehouse-architecture/performance-efficiency/best-practices","sourceTitle":"Best practices for performance efficiency | Databricks on AWS","sourcePage":53,"images":["questions/110-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Replaced the cloud-dependent container claim with independent capacity/quota domains.","studyContext":"Monitoring has confirmed cloud object-storage request throttling, rather than a compute bottleneck.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":111,"prompt":"Which describes a method of installing a Python package scoped at the notebook level to all nodes in the currently active cluster?","options":[{"id":"A","text":"Run source env/bin/activate in a notebook setup script","rationale":"Activating a driver virtual environment does not distribute notebook dependencies.","isCorrect":false},{"id":"B","text":"Use %sh conda install in a notebook cell","rationale":"A shell conda install is driver-local rather than notebook-scoped distribution.","isCorrect":false},{"id":"C","text":"Use %pip install in a notebook cell","rationale":"The supported notebook package magic installs notebook-scoped dependencies.","isCorrect":true},{"id":"D","text":"Use %sh pip install in a notebook cell","rationale":"A shell pip install is driver-local, not the notebook library mechanism.","isCorrect":false},{"id":"E","text":"Install libraries from PyPI using the cluster UI","rationale":"Cluster UI libraries are compute-scoped, not notebook-scoped.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The supported notebook package magic installs notebook-scoped dependencies.","topic":"libraries","sourceUrl":"https://docs.databricks.com/aws/en/libraries/notebooks-python-libraries","sourceTitle":"Notebook-scoped Python libraries | Databricks on AWS","sourcePage":53,"images":["questions/111-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"Which describes a method of installing a Python package scoped at the notebook level to all nodes in the currently active cluster?","options":[{"id":"A","text":"Run source env/bin/activate in a notebook setup script"},{"id":"B","text":"Use b in a notebook cell"},{"id":"C","text":"Use %pip install in a notebook cell"},{"id":"D","text":"Use %sh pip install in a notebook cell"},{"id":"E","text":"Install libraries from PyPI using the cluster UI"}],"correctAnswers":["C"],"explanation":"%pip installs notebook-scoped Python dependencies for that notebook on the compute nodes. %sh pip runs on the driver; cluster libraries are not scoped only to the notebook.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Use Databricks Runtime 14.3 LTS or later with supported notebook-scoped Python package management.","reviewNote":"Second audit: Replaced an unreadable distractor and specified a supported modern runtime.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":112,"prompt":"Each configuration below is identical to the extent that each cluster has 400 GB total of RAM 160 total cores and only one Executor per VM.\nAssume the driver stays healthy and task retry/replacement capacity is available. Which configuration loses the smallest fraction of total worker memory and CPU when one executor VM fails?","options":[{"id":"A","text":"• Total VMs: 8\n• 50 GB per Executor\n• 20 Cores / Executor","rationale":"One failure removes one eighth of worker capacity.","isCorrect":false},{"id":"B","text":"• Total VMs: 16\n• 25 GB per Executor\n• 10 Cores / Executor","rationale":"One failure removes only one sixteenth, the smallest listed fraction.","isCorrect":true},{"id":"C","text":"• Total VMs: 1\n• 400 GB per Executor\n• 160 Cores/Executor","rationale":"One failure removes all worker capacity.","isCorrect":false},{"id":"D","text":"• Total VMs: 4\n• 100 GB per Executor\n• 40 Cores / Executor","rationale":"One failure removes one quarter of worker capacity.","isCorrect":false},{"id":"E","text":"• Total VMs: 2\n• 200 GB per Executor\n• 80 Cores / Executor","rationale":"One failure removes one half of worker capacity.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"One failure removes only one sixteenth, the smallest listed fraction.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":53,"images":["questions/112-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":112,"prompt":"Each configuration below is identical to the extent that each cluster has 400 GB total of RAM 160 total cores and only one Executor per VM.\nGiven an extremely long-running job for which completion must be guaranteed, which cluster configuration will be able to guarantee completion of\nthe job in light of one or more VM failures?","options":[{"id":"A","text":"• Total VMs: 8\n• 50 GB per Executor\n• 20 Cores / Executor"},{"id":"B","text":"• Total VMs: 16\n• 25 GB per Executor\n• 10 Cores / Executor"},{"id":"C","text":"• Total VMs: 1\n• 400 GB per Executor\n• 160 Cores/Executor"},{"id":"D","text":"• Total VMs: 4\n• 100 GB per Executor\n• 40 Cores / Executor"},{"id":"E","text":"• Total VMs: 2\n• 200 GB per Executor\n• 80 Cores / Executor"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["B"],"status":"review","explanation":"B is the likely intended resilience preference, because each worker contains a smaller fraction of total capacity. No listed VM count guarantees completion after unspecified failures; driver loss, retry limits and unavailable replacement capacity remain possible.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":53,"images":["questions/112-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Replaced an impossible completion guarantee with the measurable fraction of capacity lost per worker failure.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":113,"prompt":"A Delta Lake table in the Lakehouse named customer_churn_params is used in churn prediction by the machine learning team. The table contains\ninformation about customers derived from a number of upstream sources. Currently, the data engineering team populates this table nightly by\noverwriting the table with the current valid values derived from upstream data sources.\nImmediately after each update succeeds, the data engineering team would like to determine the difference between the new version and the\nprevious version of the table.\nGiven the current implementation, which method can be used?","options":[{"id":"A","text":"Execute a query to calculate the difference between the new version and the previous version using Delta Lake’s built-in versioning and lime\ntravel functionality.","rationale":"Comparing retained snapshots identifies logical row differences.","isCorrect":true},{"id":"B","text":"Parse the Delta Lake transaction log to identify all newly written data files.","rationale":"New file names do not distinguish changed rows from unchanged rewrites.","isCorrect":false},{"id":"C","text":"Parse the Spark event logs to identify those rows that were updated, inserted, or deleted.","rationale":"Spark event logs are not a row-level change archive.","isCorrect":false},{"id":"D","text":"Execute DESCRIBE HISTORY customer_churn_params to obtain the full operation metrics for the update, including a log of all records that\nhave been added or modified.","rationale":"History provides operation metadata, not every changed row.","isCorrect":false},{"id":"E","text":"Use Delta Lake’s change data feed to identify those records that have been updated, inserted, or deleted.","rationale":"Without prior CDF capture, it cannot reconstruct those historical changes.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"Comparing retained snapshots identifies logical row differences.","topic":"history","sourceUrl":"https://docs.databricks.com/aws/en/tables/history","sourceTitle":"Work with table history | Databricks on AWS","sourcePage":54,"images":["questions/113-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A Delta Lake table in the Lakehouse named customer_churn_params is used in churn prediction by the machine learning team. The table contains\ninformation about customers derived from a number of upstream sources. Currently, the data engineering team populates this table nightly by\noverwriting the table with the current valid values derived from upstream data sources.\nImmediately after each update succeeds, the data engineering team would like to determine the difference between the new version and the\nprevious version of the table.\nGiven the current implementation, which method can be used?","options":[{"id":"A","text":"Execute a query to calculate the difference between the new version and the previous version using Delta Lake’s built-in versioning and lime\ntravel functionality."},{"id":"B","text":"Parse the Delta Lake transaction log to identify all newly written data files."},{"id":"C","text":"Parse the Spark event logs to identify those rows that were updated, inserted, or deleted."},{"id":"D","text":"Execute DESCRIBE HISTORY customer_churn_params to obtain the full operation metrics for the update, including a log of all records that\nhave been added or modified."},{"id":"E","text":"Use Delta Lake’s change data feed to identify those records that have been updated, inserted, or deleted."}],"correctAnswers":["A"],"explanation":"Compare the new and previous table snapshots using time travel. A full overwrite rewrites unchanged rows too; file lists/history metrics are not a row-level semantic diff, and CDF is not stated to have been enabled.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"CDF was not enabled before the overwrite. The required table versions and data files are retained. Identify logical row differences, not merely rewritten file names.","reviewNote":"Second audit: Historical CDF is unavailable unless it was captured; logical snapshot differences are requested.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":114,"prompt":"An existing complete-mode streaming query groups item sales and computes count and average price. The replacement below adds promo_count. Which listed migration step is required because the aggregation state schema changes?","options":[{"id":"A","text":"Specify a new checkpointLocation","rationale":"The changed aggregation state needs a fresh compatible checkpoint.","isCorrect":true},{"id":"B","text":"Remove .option(‘mergeSchema’, ‘true’) from the streaming write","rationale":"Disabling sink schema evolution does not fix state incompatibility.","isCorrect":false},{"id":"C","text":"Increase the shuffle partitions to account for additional aggregates","rationale":"More shuffle partitions do not migrate the existing state schema.","isCorrect":false},{"id":"D","text":"Run REFRESH TABLE delta.'/item_agg'","rationale":"Refreshing catalog metadata does not migrate state.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"The changed aggregation state needs a fresh compatible checkpoint.","topic":"checkpoints","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/checkpoints","sourceTitle":"Structured Streaming checkpoints | Databricks on AWS","sourcePage":55,"images":["questions/114-1.png"],"hasEmbeddedCode":false,"relatedQuestion":72,"practiceEligible":true,"code":"from pyspark.sql import functions as F\n# Original aggregate: count(item), mean(sale_price).\n# Proposed aggregate adds a promotion counter:\n(df.groupBy(\"item\")\n .agg(F.count(\"item\").alias(\"total_count\"),\n      F.mean(\"sale_price\").alias(\"avg_price\"),\n      F.sum(F.when(F.col(\"promo_id\") == \"PROMO\", 1).otherwise(0)).alias(\"promo_count\"))\n .writeStream.format(\"delta\").outputMode(\"complete\")\n .option(\"mergeSchema\", \"true\")\n .option(\"checkpointLocation\", \"/item_agg/__checkpoint\")\n .start(\"/item_agg\"))","studyContext":"Stop the old query before migration. The full input history remains replayable and the complete output will be rebuilt; changing the checkpoint alone does not recover expired source data.","reviewNote":"Second audit: The original proposed query omitted the new aggregate. Restored the intended state-schema change with valid code.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A data team’s Structured Streaming job is configured to calculate running aggregates for item sales to update a downstream marketing\ndashboard. The marketing team has introduced a new promotion, and they would like to add a new field to track the number of times this\npromotion code is used for each item. A junior data engineer suggests updating the existing query as follows. Note that proposed changes are in\nbold.\nOriginal query:\nProposed query:\nWhich step must also be completed to put the proposed query into production?","options":[{"id":"A","text":"Specify a new checkpointLocation"},{"id":"B","text":"Remove .option('mergeSchema', 'true') from the streaming write"},{"id":"C","text":"Increase the shuffle partitions to account for additional aggregates"},{"id":"D","text":"Run REFRESH TABLE delta. ‛ /item_agg ‛"}],"correctAnswers":["A"],"explanation":"Adding an aggregate changes the streaming state schema, requiring a new checkpoint for this query. Output mergeSchema does not migrate aggregate state; REFRESH and shuffle settings do not fix it. The illustrated count expression also needs count_if or an equivalent conditional expression; a literal column-name string is not a SQL boolean predicate.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":115,"prompt":"When using CLI or REST API to get results from jobs with multiple tasks, which statement correctly describes the response structure?","options":[{"id":"A","text":"Each run of a job will have a unique job_id; all tasks within this job will have a unique job_id","rationale":"Job IDs identify definitions, not each run and task execution.","isCorrect":false},{"id":"B","text":"Each run of a job will have a unique job_id; all tasks within this job will have a unique task_id","rationale":"The parent is a run_id, not a new job_id.","isCorrect":false},{"id":"C","text":"Each run of a job will have a unique orchestration_id; all tasks within this job will have a unique run_id","rationale":"orchestration_id is not the described Jobs API identifier.","isCorrect":false},{"id":"D","text":"Each run of a job will have a unique run_id; all tasks within this job will have a unique task_id","rationale":"Task executions also have run_id; task_key identifies the definition.","isCorrect":false},{"id":"E","text":"Each run of a job will have a unique run_id; all tasks within this job will also have a unique run_id","rationale":"The parent run and task runs have their own run identifiers.","isCorrect":true}],"selectionCount":1,"correctAnswers":["E"],"suggestedAnswers":[],"status":"confirmed","explanation":"The parent run and task runs have their own run identifiers.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":55,"images":["questions/115-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":116,"prompt":"The data engineering team is configuring environments for development, testing, and production before beginning migration on a new data\npipeline. The team requires extensive testing on both the code and data resulting from code execution, and the team wants to develop and test\nagainst data as similar to production data as possible.\nA junior data engineer suggests that production data can be mounted to the development and testing environments, allowing pre-production code\nto execute against production data. Because all users have admin privileges in the development environment, the junior data engineer has offered\nto configure permissions and mount this data for the team.\nWhich statement captures best practices for this situation?","options":[{"id":"A","text":"All development, testing, and production code and data should exist in a single, unified workspace; creating separate environments for\ntesting and development complicates administrative overhead.","rationale":"Combining all environments weakens the requested isolation.","isCorrect":false},{"id":"B","text":"In environments where interactive code will be executed, production data should only be accessible with read permissions; creating\nisolated databases for each environment further reduces risks.","rationale":"Read-only production access and isolated writable environments reduce risk.","isCorrect":true},{"id":"C","text":"As long as code in the development environment declares USE dev_db at the top of each notebook, there is no possibility of inadvertently\ncommitting changes back to production data sources.","rationale":"USE changes name resolution, not storage permissions.","isCorrect":false},{"id":"D","text":"Because Delta Lake versions all data and supports time travel, it is not possible for user error or malicious actors to permanently delete\nproduction data; as such, it is generally safe to mount production data anywhere.","rationale":"Time travel does not prevent permanent deletion.","isCorrect":false},{"id":"E","text":"Because access to production data will always be verified using passthrough credentials, it is safe to mount data to any Databricks\ndevelopment environment.","rationale":"Passthrough is not universally enforced for every mount.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Read-only production access and isolated writable environments reduce risk.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":56,"images":["questions/116-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":117,"prompt":"User A creates a saved job. User B triggers its runs. User C later becomes the job owner. All three accounts still exist. An application requests GET /api/2.2/jobs/get for this job. Which statement correctly interprets the creator_user_name field?","options":[{"id":"A","text":"It is the current job owner, so it automatically becomes User C when ownership changes.","rationale":"The creator field is distinct from ownership.","isCorrect":false},{"id":"B","text":"It always identifies User B because User B triggers the runs.","rationale":"Triggering a run does not make the caller the job creator.","isCorrect":false},{"id":"C","text":"It identifies the job creator, User A; it is separate from the current owner and run_as identity.","rationale":"The field represents the saved job's creator.","isCorrect":true},{"id":"D","text":"It changes from User B to User C when ownership changes.","rationale":"Ownership transfer does not redefine the creator field as a trigger actor.","isCorrect":false},{"id":"E","text":"It identifies whichever user most recently opened the job in the UI.","rationale":"Opening the UI does not create the job.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The field represents the saved job's creator.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/job","sourceTitle":"Jobs API response: creator and Run as identity","sourcePage":56,"images":["questions/117-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":117,"prompt":"A data engineer, User A, has promoted a pipeline to production by using the REST API to programmatically create several jobs. A DevOps engineer,\nUser B, has configured an external orchestration tool to trigger job runs through the REST API. Both users authorized the REST API calls using their\npersonal access tokens.\nA workspace admin, User C, inherits responsibility for managing this pipeline. User C uses the Databricks Jobs UI to take \"Owner\" privileges of\neach job. Jobs continue to be triggered using the credentials and tooling configured by User B.\nAn application has been configured to collect and parse run information returned by the REST API. Which statement describes the value returned\nin the creator_user_name field?","options":[{"id":"A","text":"Once User C takes \"Owner\" privileges, their email address will appear in this field; prior to this, User A’s email address will appear in this\nfield."},{"id":"B","text":"User B’s email address will always appear in this field, as their credentials are always used to trigger the run."},{"id":"C","text":"User A’s email address will always appear in this field, as they still own the underlying notebooks."},{"id":"D","text":"Once User C takes \"Owner\" privileges, their email address will appear in this field; prior to this, User B’s email address will appear in this\nfield."},{"id":"E","text":"User C will only ever appear in this field if they manually trigger the job, otherwise it will indicate User B."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["A"],"status":"review","explanation":"A is the likely legacy answer, but the current Run API only describes creator_user_name as the creator name and does not establish the stated ownership-transfer behavior. It is not a reliable trigger-actor field. Confirm against the target API/version; use audit logs for the caller.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":56,"images":["questions/117-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Separated job creator identity from job ownership, run identity and notebook ownership.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":118,"prompt":"A member of the data engineering team has submitted a short notebook that they wish to schedule as part of a larger data pipeline. Assume that\nthe commands provided below produce the logically correct results when run as presented.\nWhich command should be removed from the notebook before scheduling it as a job?","options":[{"id":"A","text":"Cmd 2","rationale":"Schema inspection is metadata work, not the unnecessary display action.","isCorrect":false},{"id":"B","text":"Cmd 3","rationale":"The select is part of the required transformation.","isCorrect":false},{"id":"C","text":"Cmd 4","rationale":"Dropping the nested field is part of the required transformation.","isCorrect":false},{"id":"D","text":"Cmd 5","rationale":"The display action is unnecessary before the production write.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The display action is unnecessary before the production write.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":57,"images":["questions/118-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":119,"prompt":"Which statement regarding Spark configuration on the Databricks platform is true?","options":[{"id":"A","text":"The Databricks REST API can be used to modify the Spark configuration properties for an interactive cluster without interrupting jobs\ncurrently running on the cluster.","rationale":"Editing cluster Spark configuration can restart compute.","isCorrect":false},{"id":"B","text":"Spark configurations set within a notebook will affect all SparkSessions attached to the same interactive cluster.","rationale":"Notebook/session settings do not automatically affect all sessions.","isCorrect":false},{"id":"C","text":"When the same Spark configuration property is set for an interactive cluster and a notebook attached to that cluster, the notebook setting\nwill always be ignored.","rationale":"Supported session settings can override cluster defaults.","isCorrect":false},{"id":"D","text":"Spark configuration properties set for an interactive cluster with the Clusters UI will impact all notebooks attached to that cluster.","rationale":"Cluster-level configuration supplies settings to attached notebooks.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Cluster-level configuration supplies settings to attached notebooks.","topic":"compute","sourceUrl":"https://docs.databricks.com/aws/en/compute/clusters-manage","sourceTitle":"Manage classic compute | Databricks on AWS","sourcePage":57,"images":["questions/119-1.png"],"hasEmbeddedCode":false,"relatedQuestion":90,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":120,"prompt":"The business reporting team requires that data for their dashboards be updated every hour. The total processing time for the pipeline that\nextracts, transforms, and loads the data for their pipeline runs in 10 minutes.\nAssuming normal operating conditions, which configuration will meet their service-level agreement requirements with the lowest cost?","options":[{"id":"A","text":"Configure a job that executes every time new data lands in a given directory","rationale":"Unbounded file-arrival frequency need not minimize cost.","isCorrect":false},{"id":"B","text":"Schedule a job to execute the pipeline once an hour on a new job cluster","rationale":"Hourly job compute can stop between ten-minute runs.","isCorrect":true},{"id":"C","text":"Schedule a Structured Streaming job with a trigger interval of 60 minutes","rationale":"Always-on streaming compute idles between hourly batches.","isCorrect":false},{"id":"D","text":"Schedule a job to execute the pipeline once an hour on a dedicated interactive cluster","rationale":"A dedicated interactive cluster need not stop between runs.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Hourly job compute can stop between ten-minute runs.","topic":"jobs","sourceUrl":"https://docs.databricks.com/aws/en/jobs/","sourceTitle":"Lakeflow Jobs | Databricks on AWS","sourcePage":58,"images":["questions/120-1.png"],"hasEmbeddedCode":false,"relatedQuestion":62,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":121,"prompt":"A Databricks SQL dashboard has been configured to monitor the total number of records present in a collection of Delta Lake tables using the\nfollowing query pattern:\nSELECT COUNT (*) FROM table -\nWhich of the following describes how results are generated each time the dashboard is updated?","options":[{"id":"A","text":"The total count of rows is calculated by scanning all data files","rationale":"A full data scan is unnecessary under the metadata-count assumptions.","isCorrect":false},{"id":"B","text":"The total count of rows will be returned from cached results unless REFRESH is run","rationale":"The question bypasses result cache and reads the current snapshot.","isCorrect":false},{"id":"C","text":"The total count of records is calculated from the Delta transaction logs","rationale":"Delta transaction metadata contains the needed row counts.","isCorrect":true},{"id":"D","text":"The total count of records is calculated from the parquet file metadata","rationale":"A fresh scan of Parquet footers is unnecessary.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Delta transaction metadata contains the needed row counts.","topic":"count","sourceUrl":"https://delta.io/blog/2023-04-19-faster-aggregations-metadata/","sourceTitle":"How Delta Lake uses metadata to make certain aggregations much faster | Delta Lake","sourcePage":58,"images":["questions/121-1.png"],"hasEmbeddedCode":false,"relatedQuestion":63,"practiceEligible":true,"studyContext":"All required record counts are available in Delta metadata, metadata-only count optimization is supported and enabled, and this unfiltered query has no row masks or row filters. Result caching is bypassed.","reviewNote":"Second audit: COUNT(*) metadata optimization is conditional.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A Databricks SQL dashboard has been configured to monitor the total number of records present in a collection of Delta Lake tables using the\nfollowing query pattern:\nSELECT COUNT (*) FROM table -\nWhich of the following describes how results are generated each time the dashboard is updated?","options":[{"id":"A","text":"The total count of rows is calculated by scanning all data files"},{"id":"B","text":"The total count of rows will be returned from cached results unless REFRESH is run"},{"id":"C","text":"The total count of records is calculated from the Delta transaction logs"},{"id":"D","text":"The total count of records is calculated from the parquet file metadata"}],"correctAnswers":["C"],"explanation":"For this unfiltered Delta COUNT(*), record-count metadata in the transaction log can answer the query without scanning every row. The Hive metastore is not the row-count source.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":122,"prompt":"A Delta Lake table was created with the below query:\nConsider the following query:\nDROP TABLE prod.sales_by_store -\nIf this statement is executed by a workspace admin, which result will occur?","options":[{"id":"A","text":"Data will be marked as deleted but still recoverable with Time Travel.","rationale":"Delta time travel alone cannot restore a dropped legacy managed table.","isCorrect":false},{"id":"B","text":"The table will be removed from the catalog but the data will remain in storage.","rationale":"This describes dropping an external table.","isCorrect":false},{"id":"C","text":"The table will be removed from the catalog and the data will be deleted.","rationale":"Legacy managed-table drop removes catalog metadata and managed data.","isCorrect":true},{"id":"D","text":"An error will occur because Delta Lake prevents the deletion of production data.","rationale":"The prod schema name does not prevent authorized deletion.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Legacy managed-table drop removes catalog metadata and managed data.","topic":"drop","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-drop-table","sourceTitle":"DROP TABLE | Databricks on AWS","sourcePage":58,"images":["questions/122-1.png"],"hasEmbeddedCode":true,"relatedQuestion":64,"original":{"id":122,"prompt":"A Delta Lake table was created with the below query:\nConsider the following query:\nDROP TABLE prod.sales_by_store -\nIf this statement is executed by a workspace admin, which result will occur?","options":[{"id":"A","text":"Data will be marked as deleted but still recoverable with Time Travel."},{"id":"B","text":"The table will be removed from the catalog but the data will remain in storage."},{"id":"C","text":"The table will be removed from the catalog and the data will be deleted."},{"id":"D","text":"An error will occur because Delta Lake prevents the deletion of production data."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"legacy","explanation":"The image creates a managed table without LOCATION. In the legacy Hive-metastore context, DROP TABLE removes its metadata and managed data. Current Unity Catalog has delayed deletion and UNDROP retention, so this is context-dependent.","topic":"drop","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-drop-table","sourceTitle":"DROP TABLE | Databricks on AWS","sourcePage":58,"images":["questions/122-1.png"],"hasEmbeddedCode":true,"relatedQuestion":64},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use the legacy Hive metastore and its managed-table behavior, not Unity Catalog. The shown database and table definitions apply.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":123,"prompt":"A developer has successfully configured their credentials for Databricks Repos and cloned a remote Git repository. They do not have privileges to\nmake changes to the main branch, which is the only branch currently visible in their workspace.\nWhich approach allows this user to share their code updates without the risk of overwriting the work of their teammates?","options":[{"id":"A","text":"Use Repos to create a new branch, commit all changes, and push changes to the remote Git repository.","rationale":"A separate branch allows commits without overwriting main.","isCorrect":true},{"id":"B","text":"Use Repos to create a fork of the remote repository, commit all changes, and make a pull request on the source repository.","rationale":"Fork creation is done at the Git host, not by this Repos operation.","isCorrect":false},{"id":"C","text":"Use Repos to pull changes from the remote Git repository; commit and push changes to a branch that appeared as changes were pulled.","rationale":"An arbitrary newly fetched branch is not the developer's isolated branch.","isCorrect":false},{"id":"D","text":"Use Repos to merge all differences and make a pull request back to the remote repository.","rationale":"Merging differences first risks changing unrelated work.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A separate branch allows commits without overwriting main.","topic":"git","sourceUrl":"https://docs.databricks.com/aws/en/repos/git-operations-with-repos","sourceTitle":"Create and manage Git folders | Databricks on AWS","sourcePage":59,"images":["questions/123-1.png"],"hasEmbeddedCode":false,"relatedQuestion":91,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":124,"prompt":"The security team is exploring whether or not the Databricks secrets module can be leveraged for connecting to an external database.\nAfter testing the code with all Python variables being defined with strings, they upload the password to the secrets module and configure the\ncorrect permissions for the currently active user. They then modify their code to the following (leaving all other variables unchanged).\nWhich statement describes what will happen when the above code is executed?","options":[{"id":"A","text":"The connection to the external table will succeed; the string \"REDACTED\" will be printed.","rationale":"JDBC receives the secret while notebook output is redacted.","isCorrect":true},{"id":"B","text":"An interactive input box will appear in the notebook; if the right password is provided, the connection will succeed and the encoded\npassword will be saved to DBFS.","rationale":"Secret retrieval is not an interactive password prompt.","isCorrect":false},{"id":"C","text":"An interactive input box will appear in the notebook; if the right password is provided, the connection will succeed and the password will be\nprinted in plain text.","rationale":"Secret retrieval does not prompt or normally print plaintext.","isCorrect":false},{"id":"D","text":"The connection to the external table will succeed; the string value of password will be printed in plain text.","rationale":"Direct notebook display of the retrieved secret is redacted.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"JDBC receives the secret while notebook output is redacted.","topic":"secrets","sourceUrl":"https://docs.databricks.com/aws/en/security/secrets/","sourceTitle":"Secret management | Databricks on AWS","sourcePage":59,"images":["questions/124-1.png"],"hasEmbeddedCode":true,"relatedQuestion":6,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":125,"prompt":"The data science team has created and logged a production model using MLflow. The model accepts a list of column names and returns a new\ncolumn of type DOUBLE.\nThe following code correctly imports the production model, loads the customers table containing the customer_id key column into a DataFrame,\nand defines the feature columns needed for the model.\nWhich code block will output a DataFrame with the schema \"customer_id LONG, predictions DOUBLE\"?","options":[{"id":"A","text":"df.map(lambda x:model(x[columns])).select(\"customer_id, predictions\")","rationale":"A Spark DataFrame does not expose this map-and-select pattern.","isCorrect":false},{"id":"B","text":"df.select(\"customer_id\",\nmodel(*columns).alias(\"predictions\"))","rationale":"The UDF returns a Column; selecting it with customer_id gives the schema.","isCorrect":true},{"id":"C","text":"model.predict(df, columns)","rationale":"The returned Spark UDF is not a model object with this predict method.","isCorrect":false},{"id":"D","text":"df.apply(model, columns).select(\"customer_id, predictions\")","rationale":"Spark DataFrames do not expose this pandas-style apply call.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"The UDF returns a Column; selecting it with customer_id gives the schema.","topic":"mlflow","sourceUrl":"https://mlflow.org/docs/latest/api_reference/python_api/mlflow.pyfunc.html","sourceTitle":"mlflow.pyfunc","sourcePage":60,"images":["questions/125-1.png"],"hasEmbeddedCode":true,"relatedQuestion":105,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":126,"prompt":"A junior member of the data engineering team is exploring the language interoperability of Databricks notebooks. The intended outcome of the\nbelow code is to register a view of all sales that occurred in countries on the continent of Africa that appear in the geo_lookup table.\nBefore executing the code, running SHOW TABLES on the current database indicates the database contains only two tables: geo_lookup and\nsales.\nWhat will be the outcome of executing these command cells m order m an interactive notebook?","options":[{"id":"A","text":"Both commands will succeed. Executing SHOW TABLES will show that countries_af and sales_af have been registered as views.","rationale":"Python assignment does not register a SQL view.","isCorrect":false},{"id":"B","text":"Cmd 1 will succeed. Cmd 2 will search all accessible databases for a table or view named countries_af: if this entity exists, Cmd 2 will\nsucceed.","rationale":"SQL does not search arbitrary databases for Python variables.","isCorrect":false},{"id":"C","text":"Cmd 1 will succeed and Cmd 2 will fail. countries_af will be a Python variable representing a PySpark DataFrame.","rationale":"The comprehension produces a list, not a DataFrame.","isCorrect":false},{"id":"D","text":"Cmd 1 will succeed and Cmd 2 will fail. countries_af will be a Python variable containing a list of strings.","rationale":"The list exists only in Python; the SQL statement fails.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The list exists only in Python; the SQL statement fails.","topic":"notebooks","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/notebooks-code","sourceTitle":"Develop code in Databricks notebooks | Databricks on AWS","sourcePage":60,"images":["questions/126-1.png"],"hasEmbeddedCode":true,"relatedQuestion":9,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":127,"prompt":"The data science team has requested assistance in accelerating queries on free-form text from user reviews. The data is currently stored in\nParquet with the below schema:\nitem_id INT, user_id INT, review_id INT, rating FLOAT, review STRING\nThe review column contains the full text of the review left by the user. Specifically, the data science team is looking to identify if any of 30 key\nwords exist in this field.\nA junior data engineer suggests converting this data to Delta Lake will improve query performance.\nWhich response to the junior data engineer’s suggestion is correct?","options":[{"id":"A","text":"Delta Lake statistics are not optimized for free text fields with high cardinality.","rationale":"File range statistics are poor indexes for arbitrary substring search.","isCorrect":true},{"id":"B","text":"Delta Lake statistics are only collected on the first 4 columns in a table.","rationale":"The traditional statistics default is not four columns.","isCorrect":false},{"id":"C","text":"ZORDER ON review will need to be run to see performance gains.","rationale":"ZORDER does not create a full-text term index.","isCorrect":false},{"id":"D","text":"The Delta log creates a term matrix for free text fields to support selective filtering.","rationale":"The Delta log does not build the claimed term matrix.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"File range statistics are poor indexes for arbitrary substring search.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":61,"images":["questions/127-1.png"],"hasEmbeddedCode":false,"relatedQuestion":67,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":128,"prompt":"The data engineering team has configured a job to process customer requests to be forgotten (have their data deleted). All user data that needs\nto be deleted is stored in Delta Lake tables using default table settings.\nThe team has decided to process all deletions from the previous week as a batch job at 1am each Sunday. The total duration of this job is less\nthan one hour. Every Monday at 3am, a batch job executes a series of VACUUM commands on all Delta Lake tables throughout the organization.\nThe compliance officer has recently learned about Delta Lake's time travel functionality. They are concerned that this might allow continued\naccess to deleted data.\nAssuming all delete logic is correctly implemented, which statement correctly addresses this concern?","options":[{"id":"A","text":"Because the VACUUM command permanently deletes all files containing deleted records, deleted records may be accessible with time\ntravel for around 24 hours.","rationale":"Next-day vacuum cannot remove seven-day-retained files.","isCorrect":false},{"id":"B","text":"Because the default data retention threshold is 24 hours, data files containing deleted records will be retained until the VACUUM job is run\nthe following day.","rationale":"The stated default retention is seven days, not 24 hours.","isCorrect":false},{"id":"C","text":"Because the default data retention threshold is 7 days, data files containing deleted records will be retained until the VACUUM job is run 8\ndays later.","rationale":"The following week's Monday vacuum is the first eligible scheduled run.","isCorrect":true},{"id":"D","text":"Because Delta Lake's delete statements have ACID guarantees, deleted records will be permanently purged from all storage systems as\nsoon as a delete job completes.","rationale":"ACID deletion does not immediately purge historical files.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"The following week's Monday vacuum is the first eligible scheduled run.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":61,"images":["questions/128-1.png"],"hasEmbeddedCode":false,"relatedQuestion":11,"original":{"id":128,"prompt":"The data engineering team has configured a job to process customer requests to be forgotten (have their data deleted). All user data that needs\nto be deleted is stored in Delta Lake tables using default table settings.\nThe team has decided to process all deletions from the previous week as a batch job at 1am each Sunday. The total duration of this job is less\nthan one hour. Every Monday at 3am, a batch job executes a series of VACUUM commands on all Delta Lake tables throughout the organization.\nThe compliance officer has recently learned about Delta Lake's time travel functionality. They are concerned that this might allow continued\naccess to deleted data.\nAssuming all delete logic is correctly implemented, which statement correctly addresses this concern?","options":[{"id":"A","text":"Because the VACUUM command permanently deletes all files containing deleted records, deleted records may be accessible with time\ntravel for around 24 hours."},{"id":"B","text":"Because the default data retention threshold is 24 hours, data files containing deleted records will be retained until the VACUUM job is run\nthe following day."},{"id":"C","text":"Because the default data retention threshold is 7 days, data files containing deleted records will be retained until the VACUUM job is run 8\ndays later."},{"id":"D","text":"Because Delta Lake's delete statements have ACID guarantees, deleted records will be permanently purged from all storage systems as\nsoon as a delete job completes."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"legacy","explanation":"With seven-day deleted-file retention, the next day's VACUUM is too early; the following Monday is about eight days after deletion. This assumes rewritten files; deletion vectors may additionally require REORG APPLY PURGE.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":61,"images":["questions/128-1.png"],"hasEmbeddedCode":false,"relatedQuestion":11},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Assume seven-day deleted-file retention, no deletion vectors, and DELETE rewrites the affected files. Measure retention from deletion, not the original file creation.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":129,"prompt":"Assuming that the Databricks CLI has been installed and configured correctly, which Databricks CLI command can be used to upload a custom\nPython Wheel to object storage mounted with the DBFS for use with a production job?","options":[{"id":"A","text":"configure","rationale":"configure sets authentication, not file upload.","isCorrect":false},{"id":"B","text":"fs","rationale":"The fs group provides file-copy commands.","isCorrect":true},{"id":"C","text":"workspace","rationale":"workspace manages workspace assets, not DBFS-mounted object paths.","isCorrect":false},{"id":"D","text":"libraries","rationale":"libraries manages installations rather than the requested file upload.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"The fs group provides file-copy commands.","topic":"cli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/fs-commands","sourceTitle":"fs command group | Databricks on AWS","sourcePage":62,"images":["questions/129-1.png"],"hasEmbeddedCode":false,"relatedQuestion":68,"original":{"id":129,"prompt":"Assuming that the Databricks CLI has been installed and configured correctly, which Databricks CLI command can be used to upload a custom\nPython Wheel to object storage mounted with the DBFS for use with a production job?","options":[{"id":"A","text":"configure"},{"id":"B","text":"fs"},{"id":"C","text":"workspace"},{"id":"D","text":"libraries"}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"legacy","explanation":"The fs command group copies files to supported DBFS paths. Other groups configure credentials or manage jobs/workspace assets. DBFS mounts are legacy storage; use volumes for new library deployments.","topic":"cli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/fs-commands","sourceTitle":"fs command group | Databricks on AWS","sourcePage":62,"images":["questions/129-1.png"],"hasEmbeddedCode":false,"relatedQuestion":68},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"This question concerns an existing legacy workspace where DBFS root and mounts are enabled. They remain historical concepts, not a recommendation for new storage designs.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":130,"prompt":"The following table consists of items found in user carts within an e-commerce website.\nThe following MERGE statement is used to update this table using an updates view, with schema evolution enabled on this table.\nHow would the following update be handled?","options":[{"id":"A","text":"The update throws an error because changes to existing columns in the target schema are not supported.","rationale":"Additive nested schema evolution is supported in the specified runtime.","isCorrect":false},{"id":"B","text":"The new nested Field is added to the target schema, and dynamically read as NULL for existing unmatched records.","rationale":"The new nested field is added; unmatched old rows read as NULL without rewriting them.","isCorrect":true},{"id":"C","text":"The update is moved to a separate \"rescued\" column because it is missing a column expected in the target schema.","rationale":"MERGE schema evolution does not automatically create a rescued-data column.","isCorrect":false},{"id":"D","text":"The new nested field is added to the target schema, and files underlying existing records are updated to include NULL values for the new\nfield.","rationale":"Adding a nullable field does not require rewriting all old Parquet files.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"The new nested field is added; unmatched old rows read as NULL without rewriting them.","topic":"schema","sourceUrl":"https://docs.databricks.com/aws/en/tables/update-schema","sourceTitle":"Update table schemas with schema evolution","sourcePage":62,"images":["questions/130-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"The following table consists of items found in user carts within an e-commerce website.\nThe following MERGE statement is used to update this table using an updates view, with schema evolution enabled on this table.\nHow would the following update be handled?","options":[{"id":"A","text":"The update throws an error because changes to existing columns in the target schema are not supported."},{"id":"B","text":"The new nested Field is added to the target schema, and dynamically read as NULL for existing unmatched records."},{"id":"C","text":"The update is moved to a separate \"rescued\" column because it is missing a column expected in the target schema."},{"id":"D","text":"The new nested field is added to the target schema, and files underlying existing records are updated to include NULL values for the new\nfield."}],"correctAnswers":["B"],"explanation":"With MERGE schema evolution, the nested field is added and older unmatched rows read as NULL without rewriting their files. Missing source fields and newly added fields have distinct evolution rules; there is no automatic rescued-data column for MERGE.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"studyContext":"Use Databricks Runtime 15.4 LTS or later. The target schema contains id BIGINT, items ARRAY<STRUCT<id:STRING,count:INT>>, email STRING. The source contains id and items, adding coupon STRING inside each item. Unmatched target records remain.","code":"-- Existing carts include:\n-- 1001, [{id: \"DESK65\", count: 1}], \"u1@domain.com\"\n-- 1002, [{id: \"KYBD45\", count: 1}], \"u2@domain.com\"\n-- updates contains:\n-- 1001, [{id: \"DESK65\", count: 2, coupon: \"BOGO50\"}]\nMERGE WITH SCHEMA EVOLUTION INTO carts AS c\nUSING updates AS u ON c.id = u.id\nWHEN MATCHED THEN UPDATE SET *","reviewNote":"Second audit: Corrected the nested item ID type and missing email schema field; specified supported nested MERGE evolution.","reviewRevision":3,"auditModified":true,"additionalSources":[{"url":"https://docs.delta.io/delta-update/","title":"Delta MERGE: schema evolution for arrays of structs"}],"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":131,"prompt":"An upstream system is emitting change data capture (CDC) logs that are being written to a cloud object storage directory. Each record in the log\nindicates the change type (insert, update, or delete) and the values for each field after the change. The source table has a primary key identified by\nthe field pk_id.\nFor auditing purposes, the data governance team wishes to maintain a full record of all values that have ever been valid in the source system. For\nanalytical purposes, only the most recent value for each record needs to be recorded. The Databricks job to ingest these records occurs once per\nhour, but each individual record may have changed multiple times over the course of an hour.\nWhich solution meets these requirements?","options":[{"id":"A","text":"Append every CDC event, including operation and source sequence, to an immutable bronze history table. Apply keyed and sequenced changes from that history to a separate current-state silver table, using MERGE or AUTO CDC with delete handling.","rationale":"An immutable event history preserves intermediate changes; the sequenced current-state table serves analytics.","isCorrect":true},{"id":"B","text":"Use merge into to insert, update, or delete the most recent entry for each pk_id into a table, then propagate all changes throughout the\nsystem.","rationale":"Keeping only the latest row loses intermediate source values needed for the audit.","isCorrect":false},{"id":"C","text":"Deduplicate records in each batch by pk_id and overwrite the target table.","rationale":"Per-batch deduplication and overwrite lose history and potentially unaffected keys.","isCorrect":false},{"id":"D","text":"Use Delta Lake’s change data feed to automatically process CDC data from an external system, propagating all changes to all dependent\ntables in the Lakehouse.","rationale":"Delta CDF describes changes to Delta tables; it does not ingest and apply external CDC by itself.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"An immutable event history preserves intermediate changes; the sequenced current-state table serves analytics.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":63,"images":["questions/131-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":131,"prompt":"An upstream system is emitting change data capture (CDC) logs that are being written to a cloud object storage directory. Each record in the log\nindicates the change type (insert, update, or delete) and the values for each field after the change. The source table has a primary key identified by\nthe field pk_id.\nFor auditing purposes, the data governance team wishes to maintain a full record of all values that have ever been valid in the source system. For\nanalytical purposes, only the most recent value for each record needs to be recorded. The Databricks job to ingest these records occurs once per\nhour, but each individual record may have changed multiple times over the course of an hour.\nWhich solution meets these requirements?","options":[{"id":"A","text":"Iterate through an ordered set of changes to the table, applying each in turn to create the current state of the table, (insert, update, delete),\ntimestamp of change, and the values."},{"id":"B","text":"Use merge into to insert, update, or delete the most recent entry for each pk_id into a table, then propagate all changes throughout the\nsystem."},{"id":"C","text":"Deduplicate records in each batch by pk_id and overwrite the target table."},{"id":"D","text":"Use Delta Lake’s change data feed to automatically process CDC data from an external system, propagating all changes to all dependent\ntables in the Lakehouse."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"No option clearly preserves every intermediate CDC event for a durable audit and also maintains current state. A is incomplete; B keeps only the most recent value, C discards history, and D incorrectly claims automatic external CDC ingestion. The valid bronze-history plus silver-MERGE answer from Q13 is missing.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":63,"images":["questions/131-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Restored the missing design that preserves the full CDC audit trail and maintains latest state.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":132,"prompt":"An hourly batch job is configured to ingest data files from a cloud object storage container where each batch represent all records produced by the\nsource system in a given hour. The batch job to process these records into the Lakehouse is sufficiently delayed to ensure no late-arriving data is\nmissed. The user_id field represents a unique key for the data, which has the following schema:\nuser_id BIGINT, username STRING, user_utc STRING, user_region STRING, last_login BIGINT, auto_pay BOOLEAN, last_updated BIGINT\nNew records are all ingested into a table named account_history which maintains a full record of all data in the same schema as the source. The\nnext table in the system is named account_current and is implemented as a Type 1 table representing the most recent value for each unique\nuser_id.\nWhich implementation can be used to efficiently update the described account_current table as part of each hourly batch job assuming there are\nmillions of user accounts and tens of thousands of records processed hourly?","options":[{"id":"A","text":"Filter records in account_history using the last_updated field and the most recent hour processed, making sure to deduplicate on username;\nwrite a merge statement to update or insert the most recent value for each username.","rationale":"Username is not the stated stable unique key.","isCorrect":false},{"id":"B","text":"Use Auto Loader to subscribe to new files in the account_history directory; configure a Structured Streaming trigger available job to batch\nupdate newly detected files into the account_current table.","rationale":"File discovery alone does not implement latest-state upserts.","isCorrect":false},{"id":"C","text":"Overwrite the account_current table with each batch using the results of a query against the account_history table grouping by user_id and\nfiltering for the max value of last_updated.","rationale":"A full-history rebuild is not the requested incremental approach.","isCorrect":false},{"id":"D","text":"Read the newly ingested hourly account_history records. For each user_id, retain the row with greatest last_updated (using a deterministic source sequence to break ties), then MERGE on user_id to update or insert the latest state.","rationale":"Order changes by update sequence and merge once per user.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Order changes by update sequence and merge once per user.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":63,"images":["questions/132-1.png"],"hasEmbeddedCode":false,"relatedQuestion":14,"original":{"id":132,"prompt":"An hourly batch job is configured to ingest data files from a cloud object storage container where each batch represent all records produced by the\nsource system in a given hour. The batch job to process these records into the Lakehouse is sufficiently delayed to ensure no late-arriving data is\nmissed. The user_id field represents a unique key for the data, which has the following schema:\nuser_id BIGINT, username STRING, user_utc STRING, user_region STRING, last_login BIGINT, auto_pay BOOLEAN, last_updated BIGINT\nNew records are all ingested into a table named account_history which maintains a full record of all data in the same schema as the source. The\nnext table in the system is named account_current and is implemented as a Type 1 table representing the most recent value for each unique\nuser_id.\nWhich implementation can be used to efficiently update the described account_current table as part of each hourly batch job assuming there are\nmillions of user accounts and tens of thousands of records processed hourly?","options":[{"id":"A","text":"Filter records in account_history using the last_updated field and the most recent hour processed, making sure to deduplicate on username;\nwrite a merge statement to update or insert the most recent value for each username."},{"id":"B","text":"Use Auto Loader to subscribe to new files in the account_history directory; configure a Structured Streaming trigger available job to batch\nupdate newly detected files into the account_current table."},{"id":"C","text":"Overwrite the account_current table with each batch using the results of a query against the account_history table grouping by user_id and\nfiltering for the max value of last_updated."},{"id":"D","text":"Filter records in account_history using the last_updated field and the most recent hour processed, as well as the max last_login by user_id\nwrite a merge statement to update or insert the most recent value for each user_id."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["D"],"status":"review","explanation":"D is the likely intended incremental MERGE approach, but it orders by max last_login instead of last_updated. Login time does not reliably identify the newest account change. Rewrite this option before scoring; username is also not the stated key.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":63,"images":["questions/132-1.png"],"hasEmbeddedCode":false,"relatedQuestion":14},"reviewRevision":2,"reviewNote":"Corrected last_login to last_updated when choosing the newest account change.","studyContext":"The hourly batch boundary is reliable and a deterministic source sequence resolves any equal last_updated values.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":133,"prompt":"The business intelligence team has a dashboard configured to track various summary metrics for retail stores. This includes total sales for the\nprevious day alongside totals and averages for a variety of time periods. The fields required to populate this dashboard have the following\nschema:\nFor demand forecasting, the Lakehouse contains a validated table of all itemized sales updated incrementally in near real-time. This table, named\nproducts_per_order, includes the following fields:\nBecause reporting on long-term sales trends is less volatile, analysts using the new dashboard only require data to be refreshed once daily.\nBecause the dashboard will be queried interactively by many users throughout a normal business day, it should return results quickly and reduce\ntotal compute associated with each materialization.\nWhich solution meets the expectations of the end users while controlling and limiting possible costs?","options":[{"id":"A","text":"Populate the dashboard by configuring a nightly batch job to save the required values as a table overwritten with each update.","rationale":"A daily materialized summary avoids repeated full aggregation.","isCorrect":true},{"id":"B","text":"Use Structured Streaming to configure a live dashboard against the products_per_order table within a Databricks notebook.","rationale":"Continuous recomputation exceeds the daily freshness requirement.","isCorrect":false},{"id":"C","text":"Define a view against the products_per_order table and define the dashboard against this view.","rationale":"A regular view can recompute the expensive aggregation per query.","isCorrect":false},{"id":"D","text":"Use the Delta Cache to persist the products_per_order table in memory to quickly update the dashboard with each query.","rationale":"Disk caching is not an in-memory persisted aggregate result.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A daily materialized summary avoids repeated full aggregation.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":64,"images":["questions/133-1.png"],"hasEmbeddedCode":true,"relatedQuestion":69,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":134,"prompt":"A Delta lake table with CDF enabled table in the Lakehouse named customer_churn_params is used in churn prediction by the machine learning\nteam. The table contains information about customers derived from a number of upstream sources. Currently, the data engineering team\npopulates this table nightly by overwriting the table with the current valid values derived from upstream data sources.\nThe churn prediction model used by the ML team is fairly stable in production. The team is only interested in making predictions on records that\nhave changed in the past 24 hours.\nWhich approach would simplify the identification of these changed records?","options":[{"id":"A","text":"Apply the churn model to all rows in the customer_churn_params table, but implement logic to perform an upsert into the predictions table\nthat ignores rows where predictions have not changed.","rationale":"This still evaluates predictions for every input record.","isCorrect":false},{"id":"B","text":"Convert the batch job to a Structured Streaming job using the complete output mode; configure a Structured Streaming job to read from the\ncustomer_churn_params table and incrementally predict against the churn model.","rationale":"Complete-mode rewrites do not isolate logically changed rows.","isCorrect":false},{"id":"C","text":"Replace the current overwrite logic with a merge statement to modify only those records that have changed; write logic to make predictions\non the changed records identified by the change data feed.","rationale":"Conditional MERGE plus CDF isolates actual changed records.","isCorrect":true},{"id":"D","text":"Modify the overwrite logic to include a field populated by calling spark.sql.functions.current_timestamp() as data are being written; use this\nfield to identify records written on a particular date.","rationale":"Timestamping every rewritten row marks unchanged rows too.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Conditional MERGE plus CDF isolates actual changed records.","topic":"cdf","sourceUrl":"https://docs.databricks.com/aws/en/tables/features/change-data-feed","sourceTitle":"Use change data feed on Databricks | Databricks on AWS","sourcePage":64,"images":["questions/134-1.png"],"hasEmbeddedCode":false,"relatedQuestion":15,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":135,"prompt":"A view is registered with the following code:\nBoth users and orders are Delta Lake tables.\nWhich statement describes the results of querying recent_orders?","options":[{"id":"A","text":"All logic will execute when the view is defined and store the result of joining tables to the DBFS; this stored data will be returned when the\nview is queried.","rationale":"A regular view stores a query definition, not materialized join results.","isCorrect":false},{"id":"B","text":"Results will be computed and cached when the view is defined; these cached results will incrementally update as new records are inserted\ninto source tables.","rationale":"A regular view is not an automatically maintained result cache.","isCorrect":false},{"id":"C","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query finishes.","rationale":"The query does not switch to snapshots committed while it is running.","isCorrect":false},{"id":"D","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query began.","rationale":"The query reads consistent source snapshots selected for that query, rather than materializing data when the view is created.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The query reads consistent source snapshots selected for that query, rather than materializing data when the view is created.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":65,"images":["questions/135-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":136,"prompt":"A data ingestion task requires a one-TB JSON dataset to be written out to Parquet with a target part-file size of 512 MB. Because Parquet is being\nused instead of Delta Lake, built-in file-sizing features such as Auto-Optimize & Auto-Compaction cannot be used.\nWhich strategy will yield the best performance without shuffling data?","options":[{"id":"A","text":"Set spark.sql.files.maxPartitionBytes to 512 MB, ingest the data, execute the narrow transformations, and then write to parquet.","rationale":"This directly sets file-read input partition size without a shuffle.","isCorrect":true},{"id":"B","text":"Set spark.sql.shuffle.partitions to 2,048 partitions (1TB*1024*1024/512), ingest the data, execute the narrow transformations, optimize the\ndata by sorting it (which automatically repartitions the data), and then write to parquet.","rationale":"Sorting and repartitioning introduce a shuffle.","isCorrect":false},{"id":"C","text":"Set spark.sql.adaptive.advisoryPartitionSizeInBytes to 512 MB bytes, ingest the data, execute the narrow transformations, coalesce to\n2,048 partitions (1TB*1024*1024/512), and then write to parquet.","rationale":"Adaptive shuffle settings do not set file-read partition size.","isCorrect":false},{"id":"D","text":"Ingest the data, execute the narrow transformations, repartition to 2,048 partitions (1TB* 1024*1024/512), and then write to parquet.","rationale":"Explicit repartitioning introduces a shuffle.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"This directly sets file-read input partition size without a shuffle.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":65,"images":["questions/136-1.png"],"hasEmbeddedCode":false,"relatedQuestion":70,"original":{"id":136,"prompt":"A data ingestion task requires a one-TB JSON dataset to be written out to Parquet with a target part-file size of 512 MB. Because Parquet is being\nused instead of Delta Lake, built-in file-sizing features such as Auto-Optimize & Auto-Compaction cannot be used.\nWhich strategy will yield the best performance without shuffling data?","options":[{"id":"A","text":"Set spark.sql.files.maxPartitionBytes to 512 MB, ingest the data, execute the narrow transformations, and then write to parquet."},{"id":"B","text":"Set spark.sql.shuffle.partitions to 2,048 partitions (1TB*1024*1024/512), ingest the data, execute the narrow transformations, optimize the\ndata by sorting it (which automatically repartitions the data), and then write to parquet."},{"id":"C","text":"Set spark.sql.adaptive.advisoryPartitionSizeInBytes to 512 MB bytes, ingest the data, execute the narrow transformations, coalesce to\n2,048 partitions (1TB*1024*1024/512), and then write to parquet."},{"id":"D","text":"Ingest the data, execute the narrow transformations, repartition to 2,048 partitions (1TB* 1024*1024/512), and then write to parquet."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Input partition sizing preserves narrow execution without a shuffle, making A the intended choice. It does not guarantee 512-MB Parquet files because JSON size, compression and row expansion differ. B/D shuffle; C's adaptive setting does not size a nonshuffle stage.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":65,"images":["questions/136-1.png"],"hasEmbeddedCode":false,"relatedQuestion":70},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Choose a file-read partition setting for a pipeline consisting only of narrow transformations. 512 MB is an input partition target, not a guaranteed compressed Parquet output-file size.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":137,"prompt":"Which statement regarding stream-static joins and static Delta tables is correct?","options":[{"id":"A","text":"The checkpoint directory will be used to track updates to the static Delta table.","rationale":"A stream checkpoint does not track changes to the static lookup as input events.","isCorrect":false},{"id":"B","text":"Each microbatch joins its new streaming rows to the latest valid snapshot of the static Delta table at that microbatch; the join is stateless.","rationale":"Each microbatch joins incoming rows to a static snapshot without maintaining join state between batches.","isCorrect":true},{"id":"C","text":"The checkpoint directory will be used to track state information for the unique keys present in the join.","rationale":"A stream-static join does not maintain a streaming key state store for this join.","isCorrect":false},{"id":"D","text":"Stream-static joins cannot use static Delta tables because of consistency issues.","rationale":"Static Delta tables are supported in stream-static joins.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Each microbatch joins incoming rows to a static snapshot without maintaining join state between batches.","topic":"joins","sourceUrl":"https://docs.databricks.com/aws/en/transform/join","sourceTitle":"Databricks stream-static joins","sourcePage":65,"images":["questions/137-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":137,"prompt":"Which statement regarding stream-static joins and static Delta tables is correct?","options":[{"id":"A","text":"The checkpoint directory will be used to track updates to the static Delta table."},{"id":"B","text":"Each microbatch of a stream-static join will use the most recent version of the static Delta table as of the job's initialization."},{"id":"C","text":"The checkpoint directory will be used to track state information for the unique keys present in the join."},{"id":"D","text":"Stream-static joins cannot use static Delta tables because of consistency issues."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"The correct statement from Q18 is missing. A static Delta table is read at the latest snapshot for each microbatch; the join is stateless. None of A-D correctly states that behavior.","topic":"joins","sourceUrl":"https://docs.databricks.com/aws/en/transform/join","sourceTitle":"Work with joins on Databricks | Databricks on AWS","sourcePage":65,"images":["questions/137-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected the static snapshot boundary from job initialization to each microbatch.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":138,"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Events are recorded once per minute per\ndevice.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nChoose the response that correctly fills in the blank within the code block to complete this task.","options":[{"id":"A","text":"to_interval(\"event_time\", \"5 minutes\").alias(\"time\")","rationale":"to_interval is not the required grouping-window function.","isCorrect":false},{"id":"B","text":"window(\"event_time\", \"5 minutes\").alias(\"time\")","rationale":"A five-minute window with no slide argument is tumbling.","isCorrect":true},{"id":"C","text":"\"event_time\"","rationale":"Grouping exact timestamps does not form five-minute intervals.","isCorrect":false},{"id":"D","text":"lag(\"event_time\", \"10 minutes\").alias(\"time\")","rationale":"lag accesses preceding values rather than creating time windows.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"A five-minute window with no slide argument is tumbling.","topic":"window","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/window.html","sourceTitle":"Window — PySpark 4.2.0 documentation","sourcePage":66,"images":["questions/138-1.png"],"hasEmbeddedCode":false,"relatedQuestion":19,"practiceEligible":true,"code":"from pyspark.sql.functions import avg, window\n# Replace WINDOW_EXPRESSION with the selected expression.\n(df.withWatermark(\"event_time\", \"10 minutes\")\n .groupBy(WINDOW_EXPRESSION, \"device_id\")\n .agg(avg(\"temp\").alias(\"avg_temp\"), avg(\"humidity\").alias(\"avg_humidity\"))\n .writeStream.format(\"delta\").outputMode(\"append\")\n .option(\"checkpointLocation\", checkpoint_path)\n .toTable(\"sensor_avg\"))","studyContext":"df is a streaming DataFrame; checkpoint_path is a writable, query-specific persistent location.","reviewNote":"Second audit: Replaced the invalid streaming saveAsTable call with toTable and an explicit checkpoint.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Events are recorded once per minute per\ndevice.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nWhich line of code correctly fills in the blank within the code block to complete this task?","options":[{"id":"A","text":"to_interval(\"event_time\", \"5 minutes\").alias(\"time\")"},{"id":"B","text":"window(\"event_time\", \"5 minutes\").alias(\"time\")"},{"id":"C","text":"\"event_time\""},{"id":"D","text":"lag(\"event_time\", \"10 minutes\").alias(\"time\")"}],"correctAnswers":["B"],"explanation":"window(event_time, '5 minutes') defines non-overlapping five-minute windows when no separate slide is supplied. A raw timestamp, lag, ten-minute window or nonexistent helper does not satisfy this interval.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":139,"prompt":"A Structured Streaming job deployed to production has been resulting in higher than expected cloud storage costs. At present, during normal\nexecution, each microbatch of data is processed in less than 3s; at least 12 times per minute, a microbatch is processed that contains 0 records.\nThe streaming write was configured using the default trigger settings. The production job is currently scheduled alongside many other Databricks\njobs in a workspace with instance pools provisioned to reduce start-up time for jobs with batch execution.\nThe team wants to stop idle compute between finite ingestion runs. Startup and processing together take at most one minute. Which listed approach both reduces empty polling and leaves headroom under a ten-minute latency target?","options":[{"id":"A","text":"Set the trigger interval to 3 seconds; the default trigger interval is consuming too many records per batch, resulting in spill to disk that can\nincrease volume costs.","rationale":"Shorter triggers do not stop idle compute and the explanation is false.","isCorrect":false},{"id":"B","text":"Use trigger(availableNow=True) with a persistent checkpoint, scheduled every eight minutes on a jobs cluster that stops after the run.","rationale":"Finite eight-minute scheduled runs meet the stated bound and stop compute.","isCorrect":true},{"id":"C","text":"Set the trigger interval to 10 minutes; each batch calls APIs in the source storage account, so decreasing trigger frequency to maximum\nallowable threshold should minimize this cost.","rationale":"Ten-minute intervals leave no startup/processing headroom and keep compute running.","isCorrect":false},{"id":"D","text":"Set the trigger interval to 500 milliseconds; setting a small but non-zero trigger interval ensures that the source is not queried too\nfrequently.","rationale":"Half-second polling still creates frequent empty checks.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Finite eight-minute scheduled runs meet the stated bound and stop compute.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":66,"images":["questions/139-1.png"],"hasEmbeddedCode":false,"relatedQuestion":73,"original":{"id":139,"prompt":"A Structured Streaming job deployed to production has been resulting in higher than expected cloud storage costs. At present, during normal\nexecution, each microbatch of data is processed in less than 3s; at least 12 times per minute, a microbatch is processed that contains 0 records.\nThe streaming write was configured using the default trigger settings. The production job is currently scheduled alongside many other Databricks\njobs in a workspace with instance pools provisioned to reduce start-up time for jobs with batch execution.\nHolding all other variables constant and assuming records need to be processed in less than 10 minutes, which adjustment will meet the\nrequirement?","options":[{"id":"A","text":"Set the trigger interval to 3 seconds; the default trigger interval is consuming too many records per batch, resulting in spill to disk that can\nincrease volume costs."},{"id":"B","text":"Use the trigger once option and configure a Databricks job to execute the query every 10 minutes; this approach minimizes costs for both\ncompute and storage."},{"id":"C","text":"Set the trigger interval to 10 minutes; each batch calls APIs in the source storage account, so decreasing trigger frequency to maximum\nallowable threshold should minimize this cost."},{"id":"D","text":"Set the trigger interval to 500 milliseconds; setting a small but non-zero trigger interval ensures that the source is not queried too\nfrequently."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Periodic finite runs avoid idle compute and repeated empty polls. Trigger.Once is deprecated in favor of AvailableNow. An exact ten-minute schedule cannot strictly guarantee latency below ten minutes once startup and processing are included; allow headroom.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":66,"images":["questions/139-1.png"],"hasEmbeddedCode":false,"relatedQuestion":73},"reviewRevision":2,"reviewNote":"Updated the deprecated trigger and left startup/processing headroom in the schedule.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":140,"prompt":"Which statement describes Delta Lake optimized writes?","options":[{"id":"A","text":"Before a Jobs cluster terminates, OPTIMIZE is executed on all tables modified during the most recent job.","rationale":"Optimized writes are not a cluster-termination hook.","isCorrect":false},{"id":"B","text":"An asynchronous job runs after the write completes to detect if files could be further compacted; if yes, an OPTIMIZE job is executed\ntoward a default of 1 GB.","rationale":"This describes a different post-write maintenance concept.","isCorrect":false},{"id":"C","text":"A shuffle occurs prior to writing to try to group similar data together resulting in fewer files instead of each executor writing multiple files\nbased on directory partitions.","rationale":"A pre-write shuffle groups data to produce fewer small files.","isCorrect":true},{"id":"D","text":"Optimized writes use logical partitions instead of directory partitions; because partition boundaries are only represented in metadata, fewer\nsmall files are written.","rationale":"Optimized writes do not eliminate physical partition directories.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"A pre-write shuffle groups data to produce fewer small files.","topic":"filesize","sourceUrl":"https://docs.databricks.com/aws/en/tables/tune-file-size","sourceTitle":"Control data file size | Databricks on AWS","sourcePage":67,"images":["questions/140-1.png"],"hasEmbeddedCode":false,"relatedQuestion":107,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":141,"prompt":"Which statement characterizes the general programming model used by Spark Structured Streaming?","options":[{"id":"A","text":"Structured Streaming leverages the parallel processing of GPUs to achieve highly parallel data throughput.","rationale":"GPUs are not the Structured Streaming programming abstraction.","isCorrect":false},{"id":"B","text":"Structured Streaming is implemented as a messaging bus and is derived from Apache Kafka.","rationale":"Structured Streaming is a processing engine, not a Kafka-derived bus.","isCorrect":false},{"id":"C","text":"Structured Streaming relies on a distributed network of nodes that hold incremental state values for cached stages.","rationale":"State storage is an implementation detail, not the general model.","isCorrect":false},{"id":"D","text":"Structured Streaming models new data arriving in a data stream as new rows appended to an unbounded table.","rationale":"New events are modeled as rows in an unbounded table.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"New events are modeled as rows in an unbounded table.","topic":"streammodel","sourceUrl":"https://spark.apache.org/docs/4.0.3/streaming/apis-on-dataframes-and-datasets.html","sourceTitle":"Structured Streaming Programming Guide - Spark 4.0.3 Documentation","sourcePage":67,"images":["questions/141-1.png"],"hasEmbeddedCode":false,"relatedQuestion":23,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":142,"prompt":"Which Spark SQL setting specifies the maximum bytes to pack into one input partition when reading files?","options":[{"id":"A","text":"spark.sql.files.maxPartitionBytes","rationale":"This specifies the maximum bytes packed into a file-read partition.","isCorrect":true},{"id":"B","text":"spark.sql.autoBroadcastJoinThreshold","rationale":"This controls join broadcast selection, not read-partition byte limits.","isCorrect":false},{"id":"C","text":"spark.sql.adaptive.advisoryPartitionSizeInBytes","rationale":"This targets adaptive shuffle partition sizes.","isCorrect":false},{"id":"D","text":"spark.sql.adaptive.coalescePartitions.minPartitionNum","rationale":"This concerns adaptive shuffle coalescing, not initial file reads.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"This specifies the maximum bytes packed into a file-read partition.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Official documentation for this question","sourcePage":67,"images":["questions/142-1.png"],"hasEmbeddedCode":false,"relatedQuestion":24,"practiceEligible":true,"reviewNote":"Second audit: The original wording also allowed file-open cost to affect partition packing.","reviewRevision":3,"auditModified":true,"original":{"prompt":"Which configuration parameter directly affects the size of a spark-partition upon ingestion of data into Spark?","options":[{"id":"A","text":"spark.sql.files.maxPartitionBytes"},{"id":"B","text":"spark.sql.autoBroadcastJoinThreshold"},{"id":"C","text":"spark.sql.adaptive.advisoryPartitionSizeInBytes"},{"id":"D","text":"spark.sql.adaptive.coalescePartitions.minPartitionNum"}],"correctAnswers":["A"],"explanation":"spark.sql.files.maxPartitionBytes controls the maximum bytes packed into an input file partition. The other settings target broadcasting, file-open cost or post-shuffle adaptive coalescing.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":143,"prompt":"A Spark job is taking longer than expected. Using the Spark UI, a data engineer notes that the Min, Median, and Max Durations for tasks in a\nparticular stage show the minimum and median time to complete a task as roughly the same, but the max duration for a task to be roughly 100\ntimes as long as the minimum.\nWhich situation is causing increased duration of the overall job?","options":[{"id":"A","text":"Task queueing resulting from improper thread pool assignment.","rationale":"The stated evidence does not establish thread-pool queueing.","isCorrect":false},{"id":"B","text":"Spill resulting from attached volume storage being too small.","rationale":"Spill is not caused by insufficient disk capacity itself.","isCorrect":false},{"id":"C","text":"Network latency due to some cluster nodes being in different regions from the source data","rationale":"Cross-region placement is not established by the task-duration pattern.","isCorrect":false},{"id":"D","text":"Skew caused by more data being assigned to a subset of spark-partitions.","rationale":"A few heavily loaded partitions can create extreme task skew.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"A few heavily loaded partitions can create extreme task skew.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":67,"images":["questions/143-1.png"],"hasEmbeddedCode":false,"relatedQuestion":25,"original":{"id":143,"prompt":"A Spark job is taking longer than expected. Using the Spark UI, a data engineer notes that the Min, Median, and Max Durations for tasks in a\nparticular stage show the minimum and median time to complete a task as roughly the same, but the max duration for a task to be roughly 100\ntimes as long as the minimum.\nWhich situation is causing increased duration of the overall job?","options":[{"id":"A","text":"Task queueing resulting from improper thread pool assignment."},{"id":"B","text":"Spill resulting from attached volume storage being too small."},{"id":"C","text":"Network latency due to some cluster nodes being in different regions from the source data"},{"id":"D","text":"Skew caused by more data being assigned to a subset of spark-partitions."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"best_fit","explanation":"A few exceptionally long tasks are a classic sign of partition skew. The timing pattern supports this diagnosis but is not proof without task-size and spill metrics; the other explanations are not supported by the stated evidence.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":67,"images":["questions/143-1.png"],"hasEmbeddedCode":false,"relatedQuestion":25},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Choose the most likely diagnosis to investigate from the stated task-duration pattern, rather than a proven root cause.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":144,"prompt":"Each configuration below is identical to the extent that each cluster has 400 GB total of RAM, 160 total cores and only one Executor per VM.\nAssume the driver stays healthy and task retry/replacement capacity is available. Which configuration loses the smallest fraction of total worker memory and CPU when one executor VM fails?","options":[{"id":"A","text":"• Total VMs: 8\n• 50 GB per Executor\n• 20 Cores / Executor","rationale":"One failure removes one eighth of worker capacity.","isCorrect":false},{"id":"B","text":"• Total VMs: 16\n• 25 GB per Executor\n• 10 Cores / Executor","rationale":"One failure removes only one sixteenth, the smallest listed fraction.","isCorrect":true},{"id":"C","text":"• Total VMs: 1\n• 400 GB per Executor\n• 160 Cores/Executor","rationale":"One failure removes all worker capacity.","isCorrect":false},{"id":"D","text":"• Total VMs: 4\n• 100 GB per Executor\n• 40 Cores / Executor","rationale":"One failure removes one quarter of worker capacity.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"One failure removes only one sixteenth, the smallest listed fraction.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":68,"images":["questions/144-1.png"],"hasEmbeddedCode":false,"relatedQuestion":112,"original":{"id":144,"prompt":"Each configuration below is identical to the extent that each cluster has 400 GB total of RAM, 160 total cores and only one Executor per VM.\nGiven an extremely long-running job for which completion must be guaranteed, which cluster configuration will be able to guarantee completion of\nthe job in light of one or more VM failures?","options":[{"id":"A","text":"• Total VMs: 8\n• 50 GB per Executor\n• 20 Cores / Executor"},{"id":"B","text":"• Total VMs: 16\n• 25 GB per Executor\n• 10 Cores / Executor"},{"id":"C","text":"• Total VMs: 1\n• 400 GB per Executor\n• 160 Cores/Executor"},{"id":"D","text":"• Total VMs: 4\n• 100 GB per Executor\n• 40 Cores / Executor"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["B"],"status":"review","explanation":"B is the likely intended resilience preference, because each worker contains a smaller fraction of total capacity. No listed VM count guarantees completion after unspecified failures; driver loss, retry limits and unavailable replacement capacity remain possible.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":68,"images":["questions/144-1.png"],"hasEmbeddedCode":false,"relatedQuestion":112},"reviewRevision":2,"reviewNote":"Replaced an impossible completion guarantee with the measurable fraction of capacity lost per worker failure.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":145,"prompt":"An hourly job reads new Parquet order files on Databricks Runtime 13.3 LTS or newer. customer_id and order_id form the business key; time is the enqueue timestamp. Duplicate events can have different enqueue timestamps. The same persistent checkpoint is reused on every run. With the code below, which statement is correct?","options":[{"id":"A","text":"Duplicate records enqueued more than 2 hours apart may be retained and the orders table may contain duplicate records with the same\ncustomer_id and order_id.","rationale":"Duplicates beyond the supported watermark interval may survive.","isCorrect":true},{"id":"B","text":"All records will be held in the state store for 2 hours before being deduplicated and committed to the orders table.","rationale":"Rows need not wait two hours before output.","isCorrect":false},{"id":"C","text":"The orders table will contain only the most recent 2 hours of records and no duplicates will be present.","rationale":"The watermark bounds state, not total target history.","isCorrect":false},{"id":"D","text":"The orders table will not contain duplicates, but records arriving more than 2 hours late will be ignored and missing from the table.","rationale":"The operator does not guarantee deduplication outside the watermark interval.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"Duplicates beyond the supported watermark interval may survive.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Drop duplicates within a watermark","sourcePage":68,"images":["questions/145-1.png"],"hasEmbeddedCode":false,"relatedQuestion":95,"original":{"id":145,"prompt":"A task orchestrator has been configured to run two hourly tasks. First, an outside system writes Parquet data to a directory mounted at\n/mnt/raw_orders/. After this data is written, a Databricks job containing the following code is executed:\nAssume that the fields customer_id and order_id serve as a composite key to uniquely identify each order, and that the time field indicates when\nthe record was queued in the source system.\nIf the upstream system is known to occasionally enqueue duplicate entries for a single order hours apart, which statement is correct?","options":[{"id":"A","text":"Duplicate records enqueued more than 2 hours apart may be retained and the orders table may contain duplicate records with the same\ncustomer_id and order_id."},{"id":"B","text":"All records will be held in the state store for 2 hours before being deduplicated and committed to the orders table."},{"id":"C","text":"The orders table will contain only the most recent 2 hours of records and no duplicates will be present."},{"id":"D","text":"The orders table will not contain duplicates, but records arriving more than 2 hours late will be ignored and missing from the table."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"The printed code uses dropDuplicates on business keys only, without the time column, and omits checkpoint configuration. It is not dropDuplicatesWithinWatermark. A's assumed two-hour state eviction is not established; do not score this question without specifying runtime/checkpoint and correcting the deduplication claim.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Apply watermarks to control data processing thresholds | Databricks on AWS","sourcePage":68,"images":["questions/145-1.png"],"hasEmbeddedCode":true,"relatedQuestion":95},"reviewRevision":2,"reviewNote":"Specified watermark-aware deduplication and a stable checkpoint; the original dropDuplicates code did not establish the intended eviction behavior.","studyContext":"","code":"(spark.readStream.schema(order_schema).format(\"parquet\")\n .load(\"/mnt/raw_orders/\")\n .withWatermark(\"time\", \"2 hours\")\n .dropDuplicatesWithinWatermark([\"customer_id\", \"order_id\"])\n .writeStream.option(\"checkpointLocation\", \"/mnt/checkpoints/orders\")\n .trigger(availableNow=True).toTable(\"orders\"))","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":146,"prompt":"A data engineer is configuring a pipeline that will potentially see late-arriving, duplicate records.\nIn addition to de-duplicating records within the batch, which of the following approaches allows the data engineer to deduplicate data against\npreviously processed records as it is inserted into a Delta table?","options":[{"id":"A","text":"Rely on Delta Lake schema enforcement to prevent duplicate records.","rationale":"Schema enforcement validates types, not key uniqueness.","isCorrect":false},{"id":"B","text":"VACUUM the Delta table after each batch completes.","rationale":"VACUUM removes old files, not duplicate business keys.","isCorrect":false},{"id":"C","text":"Perform an insert-only merge with a matching condition on a unique key.","rationale":"An insert-only keyed MERGE excludes keys already present.","isCorrect":true},{"id":"D","text":"Perform a full outer join on a unique key and overwrite existing data.","rationale":"An outer join plus overwrite needs additional reconciliation and is not this insert pattern.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"An insert-only keyed MERGE excludes keys already present.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":69,"images":["questions/146-1.png"],"hasEmbeddedCode":false,"relatedQuestion":75,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":147,"prompt":"The bronze Delta table has CDF enabled from version 0 and all required change versions are retained. What change records does the following batch append to bronze_history?","options":[{"id":"A","text":"Each time the job is executed, newly updated records will be merged into the target table, overwriting previous values with the same\nprimary keys.","rationale":"There is no keyed MERGE or overwrite of existing rows.","isCorrect":false},{"id":"B","text":"Each time the job is executed, the entire available history of inserted or updated records will be appended to the target table, resulting in\nmany duplicate entries.","rationale":"Reading from version zero and appending replays retained changes.","isCorrect":true},{"id":"C","text":"Each time the job is executed, only those records that have been inserted or updated since the last execution will be appended to the target\ntable, giving the desired result.","rationale":"A batch read has no saved incremental offset here.","isCorrect":false},{"id":"D","text":"Each time the job is executed, the differences between the original and current versions are calculated; this may result in duplicate entries\nfor some records.","rationale":"CDF enumerates changes; it is not a snapshot-difference query.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Reading from version zero and appending replays retained changes.","topic":"cdf","sourceUrl":"https://docs.databricks.com/aws/en/tables/features/change-data-feed","sourceTitle":"Use change data feed on Databricks | Databricks on AWS","sourcePage":69,"images":["questions/147-1.png"],"hasEmbeddedCode":false,"relatedQuestion":28,"practiceEligible":true,"code":"(spark.read.format(\"delta\")\n .option(\"readChangeFeed\", \"true\")\n .option(\"startingVersion\", 0)\n .table(\"bronze\")\n .filter(\"_change_type IN ('insert', 'update_postimage')\")\n .write.format(\"delta\").mode(\"append\")\n .saveAsTable(\"bronze_history\"))","reviewNote":"Second audit: Corrected the batch writer API and described the result as an event history, not an SCD Type 1 table.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A junior data engineer seeks to leverage Delta Lake's Change Data Feed functionality to create a Type 1 table representing all of the values that\nhave ever been valid for all rows in a bronze table created with the property delta.enableChangeDataFeed = true. They plan to execute the\nfollowing code as a daily job:\nWhich statement describes the execution and results of running the above query multiple times?","options":[{"id":"A","text":"Each time the job is executed, newly updated records will be merged into the target table, overwriting previous values with the same\nprimary keys."},{"id":"B","text":"Each time the job is executed, the entire available history of inserted or updated records will be appended to the target table, resulting in\nmany duplicate entries."},{"id":"C","text":"Each time the job is executed, only those records that have been inserted or updated since the last execution will be appended to the target\ntable, giving the desired result."},{"id":"D","text":"Each time the job is executed, the differences between the original and current versions are calculated; this may result in duplicate entries\nfor some records."}],"correctAnswers":["B"],"explanation":"The batch CDF read starts at version 0 every time and appends, replaying available changes and producing duplicates. It has no incremental checkpoint or MERGE. A Type 1 table would not itself retain every historical value.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":148,"prompt":"A DLT pipeline includes the following streaming tables:\n• raw_iot ingests raw device measurement data from a heart rate tracking device.\n• bpm_stats incrementally computes user statistics based on BPM measurements from raw_iot.\nHow can the data engineer configure this pipeline to be able to retain manually deleted or updated records in the raw_iot table, while recomputing\nthe downstream table bpm_stats table when a pipeline update is run?","options":[{"id":"A","text":"Set the pipelines.reset.allowed property to false on raw_iot","rationale":"This prevents full-refresh reset of the corrected raw table while downstream data is rebuilt.","isCorrect":true},{"id":"B","text":"Set the skipChangeCommits flag to true on raw_iot","rationale":"Skipping change commits affects stream reads, not protection against a full reset.","isCorrect":false},{"id":"C","text":"Set the pipelines.reset.allowed property to false on bpm_stats","rationale":"Protecting the downstream table would prevent the requested rebuild.","isCorrect":false},{"id":"D","text":"Set the skipChangeCommits flag to true on bpm_stats","rationale":"Skipping upstream changes does not preserve raw data during a full reset.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"This prevents full-refresh reset of the corrected raw table while downstream data is rebuilt.","topic":"ldprefresh","sourceUrl":"https://docs.databricks.com/aws/en/ldp/transform","sourceTitle":"Retain manual deletes or updates","sourcePage":70,"images":["questions/148-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":148,"prompt":"A DLT pipeline includes the following streaming tables:\n• raw_iot ingests raw device measurement data from a heart rate tracking device.\n• bpm_stats incrementally computes user statistics based on BPM measurements from raw_iot.\nHow can the data engineer configure this pipeline to be able to retain manually deleted or updated records in the raw_iot table, while recomputing\nthe downstream table bpm_stats table when a pipeline update is run?","options":[{"id":"A","text":"Set the pipelines.reset.allowed property to false on raw_iot"},{"id":"B","text":"Set the skipChangeCommits flag to true on raw_iot"},{"id":"C","text":"Set the pipelines.reset.allowed property to false on bpm_stats"},{"id":"D","text":"Set the skipChangeCommits flag to true on bpm_stats"}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Preventing full reset of raw_iot preserves its manual corrections during a full refresh while downstream data can be rebuilt. Setting this property alone does not make an ordinary incremental downstream stream process updates/deletes; the refresh/rebuild mode must be appropriate.","topic":"ldprefresh","sourceUrl":"https://docs.databricks.com/aws/en/ldp/transform","sourceTitle":"Retain manual deletes or updates","sourcePage":70,"images":["questions/148-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"A full refresh rebuilds the downstream bpm_stats table. The raw_iot source must retain its existing manually corrected contents during that refresh.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":149,"prompt":"A data pipeline uses Structured Streaming to ingest data from Apache Kafka to Delta Lake. Data is being stored in a bronze table, and includes the\nKafka-generated timestamp, key, and value. Three months after the pipeline is deployed, the data engineering team has noticed some latency\nissues during certain times of the day.\nA senior data engineer updates the Delta Table's schema and ingestion logic to include the current timestamp (as recorded by Apache Spark) as\nwell as the Kafka topic and partition. The team plans to use these additional metadata fields to diagnose the transient processing delays.\nWhich limitation will the team face while diagnosing this problem?","options":[{"id":"A","text":"New fields will not be computed for historic records.","rationale":"New ingestion metadata is not retroactively computed for old rows.","isCorrect":true},{"id":"B","text":"Spark cannot capture the topic and partition fields from a Kafka source.","rationale":"Kafka topic and partition metadata are available.","isCorrect":false},{"id":"C","text":"Updating the table schema requires a default value provided for each field added.","rationale":"New nullable columns do not require a supplied default value.","isCorrect":false},{"id":"D","text":"Updating the table schema will invalidate the Delta transaction log metadata.","rationale":"Schema evolution is recorded rather than invalidating the log.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"New ingestion metadata is not retroactively computed for old rows.","topic":"schema","sourceUrl":"https://docs.databricks.com/aws/en/tables/update-schema","sourceTitle":"Update table schemas with schema evolution | Databricks on AWS","sourcePage":70,"images":["questions/149-1.png"],"hasEmbeddedCode":false,"relatedQuestion":76,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":150,"prompt":"A nightly job ingests data into a Delta Lake table using the following code:\nThe next step in the pipeline requires a function that returns an object that can be used to manipulate new records that have not yet been\nprocessed to the next table in the pipeline.\nWhich code snippet completes this function definition?\ndef new_records():","options":[{"id":"A","text":"return spark.readStream.table(\"bronze\")","rationale":"A streaming table read supports checkpointed downstream incremental processing.","isCorrect":true},{"id":"B","text":"return spark.read.option(\"readChangeFeed\", \"true\").table (\"bronze\")","rationale":"A batch CDF read alone does not maintain processing progress.","isCorrect":false},{"id":"C","text":"[Code choice shown in the original PDF image]","rationale":"Equality with the current timestamp does not identify unprocessed rows.","isCorrect":false},{"id":"D","text":"[Code choice shown in the original PDF image]","rationale":"A source-path filter does not track all unprocessed batches.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A streaming table read supports checkpointed downstream incremental processing.","topic":"deltastream","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/delta-lake","sourceTitle":"Delta Lake table streaming reads and writes | Databricks on AWS","sourcePage":71,"images":["questions/150-1.png"],"hasEmbeddedCode":true,"relatedQuestion":30,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":151,"prompt":"A junior data engineer is working to implement logic for a Lakehouse table named silver_device_recordings. The source data contains 100 unique\nfields in a highly nested JSON structure.\nThe silver_device_recordings table will be used downstream to power several production monitoring dashboards and a production model. At\npresent, 45 of the 100 fields are being used in at least one of these applications.\nThe data engineer is trying to determine the best approach for dealing with schema declaration given the highly-nested structure of the data and\nthe numerous fields.\nWhich of the following accurately presents information about Delta Lake and Databricks that may impact their decision-making process?","options":[{"id":"A","text":"The Tungsten encoding used by Databricks is optimized for storing string data; newly-added native support for querying JSON strings\nmeans that string types are always most efficient.","rationale":"Strings are not universally the most efficient representation.","isCorrect":false},{"id":"B","text":"Because Delta Lake uses Parquet for data storage, data types can be easily evolved by just modifying file footer information in place.","rationale":"Parquet types cannot be changed merely by editing footers.","isCorrect":false},{"id":"C","text":"Schema inference and evolution on Databricks ensure that inferred types will always accurately match the data types used by downstream\nsystems.","rationale":"Inferred types need not match downstream contracts.","isCorrect":false},{"id":"D","text":"Because Databricks will infer schema using types that allow all observed data to be processed, setting types manually provides greater\nassurance of data quality enforcement.","rationale":"Explicit schemas enforce intended types more deliberately.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Explicit schemas enforce intended types more deliberately.","topic":"schema","sourceUrl":"https://docs.databricks.com/aws/en/tables/update-schema","sourceTitle":"Update table schemas with schema evolution | Databricks on AWS","sourcePage":72,"images":["questions/151-1.png"],"hasEmbeddedCode":false,"relatedQuestion":31,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":152,"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source tables has been de-duplicated and validated, which\nstatement describes what will occur when this code is executed?","options":[{"id":"A","text":"A batch job will update the enriched_itemized_orders_by_account table, replacing only those rows that have different values than the\ncurrent version of the table, using accountID as the primary key.","rationale":"Overwrite is not a primary-key upsert.","isCorrect":false},{"id":"B","text":"The enriched_itemized_orders_by_account table will be overwritten using the current valid version of data in each of the three tables\nreferenced in the join logic.","rationale":"The batch join result replaces the target table.","isCorrect":true},{"id":"C","text":"No computation will occur until enriched_itemized_orders_by_account is queried; upon query materialization, results will be calculated\nusing the current valid version of data in each of the three tables referenced in the join logic.","rationale":"A write executes the computation; this is not a deferred view.","isCorrect":false},{"id":"D","text":"An incremental job will detect if new rows have been written to any of the source tables; if new rows are detected, all results will be\nrecalculated and used to overwrite the enriched_itemized_orders_by_account table.","rationale":"The code is a batch computation, not a change detector.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"The batch join result replaces the target table.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":73,"images":["questions/152-1.png"],"hasEmbeddedCode":false,"relatedQuestion":32,"practiceEligible":true,"code":"accountDF = spark.table(\"accounts\")\norderDF = spark.table(\"orders\")\nitemDF = spark.table(\"items\")\norderWithItemDF = (orderDF.join(itemDF, \"itemID\")\n .select(orderDF.accountID, orderDF.itemID, itemDF.itemName))\nfinalDF = (accountDF.join(orderWithItemDF, \"accountID\")\n .select(orderWithItemDF[\"*\"], accountDF.city))\n(finalDF.write.format(\"delta\").mode(\"overwrite\")\n .saveAsTable(\"enriched_itemized_orders_by_account\"))","reviewNote":"Second audit: Corrected DataFrameWriter.table to saveAsTable; the operation remains a batch overwrite.","reviewRevision":3,"auditModified":true,"original":{"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source tables has been de-duplicated and validated, which\nstatement describes what will occur when this code is executed?","options":[{"id":"A","text":"A batch job will update the enriched_itemized_orders_by_account table, replacing only those rows that have different values than the\ncurrent version of the table, using accountID as the primary key."},{"id":"B","text":"The enriched_itemized_orders_by_account table will be overwritten using the current valid version of data in each of the three tables\nreferenced in the join logic."},{"id":"C","text":"No computation will occur until enriched_itemized_orders_by_account is queried; upon query materialization, results will be calculated\nusing the current valid version of data in each of the three tables referenced in the join logic."},{"id":"D","text":"An incremental job will detect if new rows have been written to any of the source tables; if new rows are detected, all results will be\nrecalculated and used to overwrite the enriched_itemized_orders_by_account table."}],"correctAnswers":["B"],"explanation":"These are batch reads followed by mode('overwrite'). The current joined results replace the target; there is no incremental state, key-based upsert or deferred view evaluation.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":153,"prompt":"The data engineering team is configuring environments for development, testing, and production before beginning migration on a new data\npipeline. The team requires extensive testing on both the code and data resulting from code execution, and the team wants to develop and test\nagainst data as similar to production data as possible.\nA junior data engineer suggests that production data can be mounted to the development and testing environments, allowing pre-production code\nto execute against production data. Because all users have admin privileges in the development environment, the junior data engineer has offered\nto configure permissions and mount this data for the team.\nWhich statement captures best practices for this situation?","options":[{"id":"A","text":"All development, testing, and production code and data should exist in a single, unified workspace; creating separate environments for\ntesting and development complicates administrative overhead.","rationale":"Combining all environments weakens the requested isolation.","isCorrect":false},{"id":"B","text":"In environments where interactive code will be executed, production data should only be accessible with read permissions; creating\nisolated databases for each environment further reduces risks.","rationale":"Read-only production access and isolated writable environments reduce risk.","isCorrect":true},{"id":"C","text":"Because access to production data will always be verified using passthrough credentials, it is safe to mount data to any Databricks\ndevelopment environment.","rationale":"Passthrough is not universally enforced for every mount.","isCorrect":false},{"id":"D","text":"Because Delta Lake versions all data and supports time travel, it is not possible for user error or malicious actors to permanently delete\nproduction data; as such, it is generally safe to mount production data anywhere.","rationale":"Time travel does not prevent permanent deletion.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Read-only production access and isolated writable environments reduce risk.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":74,"images":["questions/153-1.png"],"hasEmbeddedCode":false,"relatedQuestion":116,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":154,"prompt":"The data architect has mandated that all tables in the Lakehouse should be configured as external Delta Lake tables.\nWhich approach will ensure that this requirement is met?","options":[{"id":"A","text":"Whenever a database is being created, make sure that the LOCATION keyword is used.","rationale":"A database location does not make contained tables external.","isCorrect":false},{"id":"B","text":"When the workspace is being configured, make sure that external cloud object storage has been mounted.","rationale":"Mounting storage does not determine a table's management type.","isCorrect":false},{"id":"C","text":"Whenever a table is being created, make sure that the LOCATION keyword is used.","rationale":"A table-level LOCATION specifies external storage.","isCorrect":true},{"id":"D","text":"When tables are created, make sure that the UNMANAGED keyword is used in the CREATE TABLE statement.","rationale":"EXTERNAL alone lacks the required storage location.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"A table-level LOCATION specifies external storage.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":74,"images":["questions/154-1.png"],"hasEmbeddedCode":false,"relatedQuestion":34,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":155,"prompt":"The marketing team is looking to share data in an aggregate table with the sales organization, but the field names used by the teams do not\nmatch, and a number of marketing-specific fields have not been approved for the sales org.\nWhich of the following solutions addresses the situation while emphasizing simplicity?","options":[{"id":"A","text":"Create a view on the marketing table selecting only those fields approved for the sales team; alias the names of any fields that should be\nstandardized to the sales naming conventions.","rationale":"A projection view aliases approved columns without duplicating data.","isCorrect":true},{"id":"B","text":"Create a new table with the required schema and use Delta Lake's DEEP CLONE functionality to sync up changes committed to one table to\nthe corresponding table.","rationale":"A deep clone is not automatic synchronization.","isCorrect":false},{"id":"C","text":"Use a CTAS statement to create a derivative table from the marketing table; configure a production job to propagate changes.","rationale":"CTAS plus scheduled copying adds avoidable maintenance.","isCorrect":false},{"id":"D","text":"Add a parallel table write to the current production pipeline, updating a new sales table that varies as required from the marketing table.","rationale":"A parallel physical table adds avoidable writes and maintenance.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A projection view aliases approved columns without duplicating data.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":74,"images":["questions/155-1.png"],"hasEmbeddedCode":false,"relatedQuestion":80,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":156,"prompt":"A Delta Lake table representing metadata about content posts from users has the following schema:\nuser_id LONG, post_text STRING, post_id STRING, longitude FLOAT, latitude FLOAT, post_time TIMESTAMP, date DATE\nThis table is partitioned by the date column. A query is run with the following filter:\nlongitude < 20 & longitude > -20\nWhich statement describes how data will be filtered?","options":[{"id":"A","text":"Statistics in the Delta Log will be used to identify partitions that might Include files in the filtered range.","rationale":"Skipping uses candidate data files, not only partition boundaries.","isCorrect":false},{"id":"B","text":"No file skipping will occur because the optimizer does not know the relationship between the partition column and the longitude.","rationale":"Nonpartition columns can still use file statistics.","isCorrect":false},{"id":"C","text":"The Delta Engine will scan the parquet file footers to identify each row that meets the filter criteria.","rationale":"Parquet footers do not identify every matching row.","isCorrect":false},{"id":"D","text":"Statistics in the Delta Log will be used to identify data files that might include records in the filtered range.","rationale":"Logged longitude ranges can exclude irrelevant data files.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Logged longitude ranges can exclude irrelevant data files.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":75,"images":["questions/156-1.png"],"hasEmbeddedCode":false,"relatedQuestion":36,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":157,"prompt":"A small company based in the United States has recently contracted a consulting firm in India to implement several new data engineering\npipelines to power artificial intelligence applications. All the company's data is stored in regional cloud storage in the United States.\nThe workspace administrator at the company is uncertain about where the Databricks workspace used by the contractors should be deployed.\nAssuming that all data governance considerations are accounted for, which statement accurately informs this decision?","options":[{"id":"A","text":"Databricks runs HDFS on cloud volume storage; as such, cloud virtual machines must be deployed in the region where the data is stored.","rationale":"Databricks does not require HDFS-backed data placement.","isCorrect":false},{"id":"B","text":"Databricks workspaces do not rely on any regional infrastructure; as such, the decision should be made based upon what is most\nconvenient for the workspace administrator.","rationale":"Workspaces and compute have regional infrastructure.","isCorrect":false},{"id":"C","text":"Cross-region reads and writes can incur significant costs and latency; whenever possible, compute should be deployed in the same region\nthe data is stored.","rationale":"Colocating compute and storage reduces network cost and latency.","isCorrect":true},{"id":"D","text":"Databricks notebooks send all executable code from the user’s browser to virtual machines over the open internet; whenever possible,\nchoosing a workspace region near the end users is the most secure.","rationale":"Browser proximity is not the main data-locality security criterion.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Colocating compute and storage reduces network cost and latency.","topic":"regions","sourceUrl":"https://docs.databricks.com/aws/en/resources/supported-regions","sourceTitle":"Databricks clouds and regions | Databricks on AWS","sourcePage":75,"images":["questions/157-1.png"],"hasEmbeddedCode":false,"relatedQuestion":37,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":158,"prompt":"A CHECK constraint has been successfully added to the Delta table named activity_details using the following logic:\nA batch job is attempting to insert new records to the table, including a record where latitude = 45.50 and longitude = 212.67.\nWhich statement describes the outcome of this batch insert?","options":[{"id":"A","text":"The write will insert all records except those that violate the table constraints; the violating records will be reported in a warning log.","rationale":"CHECK does not silently drop invalid rows and commit the rest.","isCorrect":false},{"id":"B","text":"The write will fail completely because of the constraint violation and no records will be inserted into the target table.","rationale":"No rows from the failed write transaction are committed.","isCorrect":true},{"id":"C","text":"The write will insert all records except those that violate the table constraints; the violating records will be recorded to a quarantine table.","rationale":"CHECK does not automatically route invalid rows to quarantine.","isCorrect":false},{"id":"D","text":"The write will include all records in the target table; any violations will be indicated in the boolean column named valid_coordinates.","rationale":"A constraint name is not a generated Boolean column.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"No rows from the failed write transaction are committed.","topic":"constraints","sourceUrl":"https://docs.databricks.com/aws/en/tables/constraints","sourceTitle":"Constraints on Databricks | Databricks on AWS","sourcePage":76,"images":["questions/158-1.png"],"hasEmbeddedCode":true,"relatedQuestion":81,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":159,"prompt":"A junior data engineer is migrating a workload from a relational database system to the Databricks Lakehouse. The source system uses a star\nschema, leveraging foreign key constraints and multi-table inserts to validate records on write.\nWhich consideration will impact the decisions made by the engineer while migrating this workload?","options":[{"id":"A","text":"Databricks only allows foreign key constraints on hashed identifiers, which avoid collisions in highly-parallel writes.","rationale":"Foreign keys are not restricted to collision-free hash identifiers.","isCorrect":false},{"id":"B","text":"Foreign keys must reference a primary key field; multi-table inserts must leverage Delta Lake’s upsert functionality.","rationale":"MERGE does not implement arbitrary atomic multi-table inserts.","isCorrect":false},{"id":"C","text":"Committing to multiple tables simultaneously requires taking out multiple table locks and can lead to a state of deadlock.","rationale":"Delta does not use the described mandatory multi-table lock protocol.","isCorrect":false},{"id":"D","text":"All Delta Lake transactions are ACID compliant against a single table, and Databricks does not enforce foreign key constraints.","rationale":"The scoped legacy deployment has per-table ACID and unenforced foreign keys.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The scoped legacy deployment has per-table ACID and unenforced foreign keys.","topic":"transactions","sourceUrl":"https://docs.databricks.com/aws/en/transactions/","sourceTitle":"Transactions | Databricks on AWS","sourcePage":76,"images":["questions/159-1.png"],"hasEmbeddedCode":false,"relatedQuestion":96,"original":{"id":159,"prompt":"A junior data engineer is migrating a workload from a relational database system to the Databricks Lakehouse. The source system uses a star\nschema, leveraging foreign key constraints and multi-table inserts to validate records on write.\nWhich consideration will impact the decisions made by the engineer while migrating this workload?","options":[{"id":"A","text":"Databricks only allows foreign key constraints on hashed identifiers, which avoid collisions in highly-parallel writes."},{"id":"B","text":"Foreign keys must reference a primary key field; multi-table inserts must leverage Delta Lake’s upsert functionality."},{"id":"C","text":"Committing to multiple tables simultaneously requires taking out multiple table locks and can lead to a state of deadlock."},{"id":"D","text":"All Delta Lake transactions are ACID compliant against a single table, and Databricks does not enforce foreign key constraints."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"The traditional Delta model provides atomic transactions per table and does not enforce foreign keys. Current Databricks also offers scoped multi-statement/multi-table transactions, so the single-table statement is historical rather than universal.","topic":"transactions","sourceUrl":"https://docs.databricks.com/aws/en/transactions/","sourceTitle":"Transactions | Databricks on AWS","sourcePage":76,"images":["questions/159-1.png"],"hasEmbeddedCode":false,"relatedQuestion":96},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use standalone Delta table transactions in a legacy Hive-metastore deployment, without Unity Catalog catalog-commit multi-table transactions.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":160,"prompt":"A data architect has heard about Delta Lake’s built-in versioning and time travel capabilities. For auditing purposes, they have a requirement to\nmaintain a full record of all valid street addresses as they appear in the customers table.\nThe architect is interested in implementing a Type 1 table, overwriting existing records with new values and relying on Delta Lake time travel to\nsupport long-term auditing. A data engineer on the project feels that a Type 2 table will provide better performance and scalability.\nWhich piece of information is critical to this decision?","options":[{"id":"A","text":"Data corruption can occur if a query fails in a partially completed state because Type 2 tables require setting multiple fields in a single\nupdate.","rationale":"Delta writes remain atomic even when multiple columns change.","isCorrect":false},{"id":"B","text":"Shallow clones can be combined with Type 1 tables to accelerate historic queries for long-term versioning.","rationale":"A shallow clone is not a durable independent historical archive.","isCorrect":false},{"id":"C","text":"Delta Lake time travel cannot be used to query previous versions of these tables because Type 1 changes modify data files in place.","rationale":"Delta updates do not destroy all previous versions in place.","isCorrect":false},{"id":"D","text":"Delta tables support efficient current-state queries and retention-bounded time travel; preserve an explicit CDC/SCD history table when a durable row-level audit history is required.","rationale":"Finite-retention snapshots are not a substitute for durable row-version history.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Finite-retention snapshots are not a substitute for durable row-version history.","topic":"history","sourceUrl":"https://docs.databricks.com/aws/en/tables/history","sourceTitle":"Work with table history | Databricks on AWS","sourcePage":76,"images":["questions/160-1.png"],"hasEmbeddedCode":false,"relatedQuestion":97,"practiceEligible":true,"reviewNote":"Second audit: Time travel is limited by retention and is not a permanent audit archive.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A data architect has heard about Delta Lake’s built-in versioning and time travel capabilities. For auditing purposes, they have a requirement to\nmaintain a full record of all valid street addresses as they appear in the customers table.\nThe architect is interested in implementing a Type 1 table, overwriting existing records with new values and relying on Delta Lake time travel to\nsupport long-term auditing. A data engineer on the project feels that a Type 2 table will provide better performance and scalability.\nWhich piece of information is critical to this decision?","options":[{"id":"A","text":"Data corruption can occur if a query fails in a partially completed state because Type 2 tables require setting multiple fields in a single\nupdate."},{"id":"B","text":"Shallow clones can be combined with Type 1 tables to accelerate historic queries for long-term versioning."},{"id":"C","text":"Delta Lake time travel cannot be used to query previous versions of these tables because Type 1 changes modify data files in place."},{"id":"D","text":"Delta Lake time travel does not scale well in cost or latency to provide a long-term versioning solution."}],"correctAnswers":["D"],"explanation":"Time travel depends on retained files/logs and is not a durable business-history model. An SCD Type 2 table explicitly stores historical versions; shallow clones are not an archival substitute.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":161,"prompt":"Impression and click streams have event-time columns impressionTime and clickTime, with watermarks on both columns. Business rules allow a click from the impression timestamp through one hour later. The join currently has only an ad-key equality condition and growing state. Which additional condition bounds the match interval while preserving that rule?","options":[{"id":"A","text":"clickTime >= impressionTime AND clickTime <= impressionTime + INTERVAL 1 HOUR","rationale":"The bounded interval matches the business rule and, with watermarks, permits state cleanup.","isCorrect":true},{"id":"B","text":"Joining on event time constraint: clickTime + 3 hours < impressionTime - 2 hours","rationale":"This condition requires clicks far before impressions, contradicting the rule.","isCorrect":false},{"id":"C","text":"Joining on event time constraint: clickTime == impressionTime using a leftOuter join","rationale":"Timestamp equality excludes valid clicks arriving within the following hour.","isCorrect":false},{"id":"D","text":"Joining on event time constraint: clickTime >= impressionTime - interval 3 hours and removing watermarks","rationale":"Removing watermarks and the missing upper bound prevent the required bounded state.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"The bounded interval matches the business rule and, with watermarks, permits state cleanup.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Apply watermarks to control data processing thresholds | Databricks on AWS","sourcePage":77,"images":["questions/161-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":161,"prompt":"A data engineer wants to join a stream of advertisement impressions (when an ad was shown) with another stream of user clicks on\nadvertisements to correlate when impressions led to monetizable clicks.\nIn the code below, Impressions is a streaming DataFrame with a watermark (\"event_time\", \"10 minutes\")\nThe data engineer notices the query slowing down significantly.\nWhich solution would improve the performance?","options":[{"id":"A","text":"Joining on event time constraint: clickTime >= impressionTime AND clickTime <= impressionTime interval 1 hour"},{"id":"B","text":"Joining on event time constraint: clickTime + 3 hours < impressionTime - 2 hours"},{"id":"C","text":"Joining on event time constraint: clickTime == impressionTime using a leftOuter join"},{"id":"D","text":"Joining on event time constraint: clickTime >= impressionTime - interval 3 hours and removing watermarks"}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"A bounded event-time interval plus watermarks allows old join state to be discarded. The intended range is clickTime >= impressionTime AND clickTime <= impressionTime + INTERVAL 1 HOUR; the printed option is missing the plus sign.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Apply watermarks to control data processing thresholds | Databricks on AWS","sourcePage":77,"images":["questions/161-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Restored valid interval syntax and stated watermark assumptions.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":162,"prompt":"A junior data engineer has manually configured a series of jobs using the Databricks Jobs UI. Upon reviewing their work, the engineer realizes that\nthey are listed as the \"Owner\" for each job. They attempt to transfer \"Owner\" privileges to the \"DevOps\" group, but cannot successfully accomplish\nthis task.\nWhich statement explains what is preventing this privilege transfer?","options":[{"id":"A","text":"Databricks jobs must have exactly one owner; \"Owner\" privileges cannot be assigned to a group.","rationale":"A job has one owner, and a group cannot hold ownership.","isCorrect":true},{"id":"B","text":"The creator of a Databricks job will always have \"Owner\" privileges; this configuration cannot be changed.","rationale":"Ownership can be transferred to another eligible identity.","isCorrect":false},{"id":"C","text":"Only workspace administrators can grant \"Owner\" privileges to a group.","rationale":"Administrator status does not make a group eligible for ownership.","isCorrect":false},{"id":"D","text":"A user can only transfer job ownership to a group if they are also a member of that group.","rationale":"Group membership does not make group ownership valid.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A job has one owner, and a group cannot hold ownership.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":77,"images":["questions/162-1.png"],"hasEmbeddedCode":false,"relatedQuestion":82,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":163,"prompt":"A table named user_ltv is being used to create a view that will be used by data analysts on various teams. Users in the workspace are configured\ninto groups, which are used for setting up data access using ACLs.\nThe user_ltv table has the following schema:\nemail STRING, age INT, ltv INT\nThe following view definition is executed:\nAn analyst who is not a member of the auditing group executes the following query:\nSELECT * FROM user_ltv_no_minors\nWhich statement describes the results returned by this query?","options":[{"id":"A","text":"All columns will be displayed normally for those records that have an age greater than 17; records not meeting this condition will be\nomitted.","rationale":"Non-auditors retain every selected column only for adult rows.","isCorrect":true},{"id":"B","text":"All age values less than 18 will be returned as null values, all other columns will be returned with the values in user_ltv.","rationale":"This filters rows rather than replacing age with null.","isCorrect":false},{"id":"C","text":"All values for the age column will be returned as null values, all other columns will be returned with the values in user_ltv.","rationale":"Age is not masked to null.","isCorrect":false},{"id":"D","text":"All columns will be displayed normally for those records that have an age greater than 18; records not meeting this condition will be\nomitted.","rationale":"The predicate includes age 18, not only ages above 18.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Non-auditors retain every selected column only for adult rows.","topic":"dynamicviews","sourceUrl":"https://docs.databricks.com/aws/en/views/dynamic","sourceTitle":"Create a dynamic view | Databricks on AWS","sourcePage":78,"images":["questions/163-1.png"],"hasEmbeddedCode":true,"relatedQuestion":98,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":164,"prompt":"All records from an Apache Kafka producer are being ingested into a single Delta Lake table with the following schema:\nkey BINARY, value BINARY, topic STRING, partition LONG, offset LONG, timestamp LONG\nThere are 5 unique topics being ingested. Only the \"registration\" topic contains Personal Identifiable Information (PII). The company wishes to\nrestrict access to PII. The company also wishes to only retain records containing PII in this table for 14 days after initial ingestion. However, for\nnon-PII information, it would like to retain these records indefinitely.\nWhich solution meets the requirements?","options":[{"id":"A","text":"All data should be deleted biweekly; Delta Lake's time travel functionality should be leveraged to maintain a history of non-PII information.","rationale":"Deleting all data also destroys the required non-PII history.","isCorrect":false},{"id":"B","text":"Data should be partitioned by the registration field, allowing ACLs and delete statements to be set for the PII directory.","rationale":"registration is a topic value, not the stated partition column.","isCorrect":false},{"id":"C","text":"Track ingestion time; enforce a topic-based row filter or restricted dynamic views with no bypass access. Delete registration rows after 14 days and schedule file purge/VACUUM with retention configured for the physical-removal deadline; retain other topics. Topic partitioning may help selective maintenance.","rationale":"The complete policy combines access enforcement, expiry and physical cleanup.","isCorrect":true},{"id":"D","text":"Separate object storage containers should be specified based on the partition field, allowing isolation at the storage level.","rationale":"Kafka partition number does not identify the PII topic or retention policy.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The complete policy combines access enforcement, expiry and physical cleanup.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Unity Catalog row filters and column masks","sourcePage":79,"images":["questions/164-1.png"],"hasEmbeddedCode":false,"relatedQuestion":83,"original":{"id":164,"prompt":"All records from an Apache Kafka producer are being ingested into a single Delta Lake table with the following schema:\nkey BINARY, value BINARY, topic STRING, partition LONG, offset LONG, timestamp LONG\nThere are 5 unique topics being ingested. Only the \"registration\" topic contains Personal Identifiable Information (PII). The company wishes to\nrestrict access to PII. The company also wishes to only retain records containing PII in this table for 14 days after initial ingestion. However, for\nnon-PII information, it would like to retain these records indefinitely.\nWhich solution meets the requirements?","options":[{"id":"A","text":"All data should be deleted biweekly; Delta Lake's time travel functionality should be leveraged to maintain a history of non-PII information."},{"id":"B","text":"Data should be partitioned by the registration field, allowing ACLs and delete statements to be set for the PII directory."},{"id":"C","text":"Data should be partitioned by the topic field, allowing ACLs and delete statements to leverage partition boundaries."},{"id":"D","text":"Separate object storage containers should be specified based on the partition field, allowing isolation at the storage level."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["C"],"status":"review","explanation":"Partitioning by topic helps targeted retention, but partitioning alone does not impose SQL row-level ACLs or a 14-day purge policy. C is the intended layout, yet no option fully implements the security and retention requirements. Keep unscored.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":79,"images":["questions/164-1.png"],"hasEmbeddedCode":false,"relatedQuestion":83},"reviewRevision":2,"reviewNote":"Added actual row access controls and retention operations; directory partitioning alone does neither.","studyContext":"The deployment permits the required retention configuration. Prevent direct storage and historical-version access from bypassing the PII policy.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":165,"prompt":"Delete events from user_lookup are read through its enabled change data feed and propagated to user_aggregates using the code below. Assume the chosen time interval exists in retained CDF history and contains all relevant deletion requests. Does successful execution guarantee the deleted target records are no longer accessible through retained historical data?","options":[{"id":"A","text":"No; the Delta Lake DELETE command only provides ACID guarantees when combined with the MERGE INTO command.","rationale":"DELETE has its own ACID guarantees.","isCorrect":false},{"id":"B","text":"No; files containing deleted records may still be accessible with time travel until a VACUUM command is used to remove invalidated data\nfiles.","rationale":"Historical files can remain after the logical delete.","isCorrect":true},{"id":"C","text":"No; the change data feed only tracks inserts and updates, not deleted records.","rationale":"CDF includes delete events.","isCorrect":false},{"id":"D","text":"Yes; Delta Lake ACID guarantees provide assurance that the DELETE command succeeded fully and permanently purged these records.","rationale":"Atomic logical deletion is not an immediate physical purge.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Historical files can remain after the logical delete.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":79,"images":["questions/165-1.png"],"hasEmbeddedCode":false,"relatedQuestion":99,"original":{"id":165,"prompt":"The data governance team is reviewing code used for deleting records for compliance with GDPR. The following logic has been implemented to\npropagate delete requests from the user_lookup table to the user_aggregates table.\nAssuming that user_id is a unique identifying key and that all users that have requested deletion have been removed from the user_lookup table,\nwhich statement describes whether successfully executing the above logic guarantees that the records to be deleted from the user_aggregates\ntable are no longer accessible and why?","options":[{"id":"A","text":"No; the Delta Lake DELETE command only provides ACID guarantees when combined with the MERGE INTO command."},{"id":"B","text":"No; files containing deleted records may still be accessible with time travel until a VACUUM command is used to remove invalidated data\nfiles."},{"id":"C","text":"No; the change data feed only tracks inserts and updates, not deleted records."},{"id":"D","text":"Yes; Delta Lake ACID guarantees provide assurance that the DELETE command succeeded fully and permanently purged these records."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Deleting target rows changes the current snapshot but does not immediately remove retained historical files. CDF includes deletes but does not enforce cross-table foreign-key consistency or permanent purge. The image uses readChangeData; the supported option is readChangeFeed. The conclusion assumes that typo is fixed, as the question assumes successful execution.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":79,"images":["questions/165-1.png"],"hasEmbeddedCode":true,"relatedQuestion":99},"reviewRevision":2,"reviewNote":"Corrected readChangeData to readChangeFeed in the source code.","studyContext":"","code":"(spark.read.format(\"delta\")\n .option(\"readChangeFeed\", \"true\")\n .option(\"startingTimestamp\", \"2021-08-22 00:00:00\")\n .option(\"endingTimestamp\", \"2021-08-29 00:00:00\")\n .table(\"user_lookup\").createOrReplaceTempView(\"changes\"))\nspark.sql(\"\"\"DELETE FROM user_aggregates\n WHERE user_id IN (SELECT user_id FROM changes WHERE _change_type = 'delete')\"\"\")","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":166,"prompt":"An external object storage container has been mounted to the location /mnt/finance_eda_bucket.\nThe following logic was executed to create a database for the finance team:\nAfter the database was successfully created and permissions configured, a member of the finance team runs the following code:\nIf all users on the finance team are members of the finance group, which statement describes how the tx_sales table will be created?","options":[{"id":"A","text":"A logical table will persist the query plan to the Hive Metastore in the Databricks control plane.","rationale":"CTAS creates data, not a logical view plan.","isCorrect":false},{"id":"B","text":"An external table will be created in the storage container mounted to /mnt/finance_eda_bucket.","rationale":"No table-level LOCATION makes this external.","isCorrect":false},{"id":"C","text":"A managed table will be created in the DBFS root storage container.","rationale":"An explicit database location overrides the default root location.","isCorrect":false},{"id":"D","text":"An managed table will be created in the storage container mounted to /mnt/finance_eda_bucket.","rationale":"The managed table inherits the database's mounted storage location.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The managed table inherits the database's mounted storage location.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":80,"images":["questions/166-1.png"],"hasEmbeddedCode":true,"relatedQuestion":45,"original":{"id":166,"prompt":"An external object storage container has been mounted to the location /mnt/finance_eda_bucket.\nThe following logic was executed to create a database for the finance team:\nAfter the database was successfully created and permissions configured, a member of the finance team runs the following code:\nIf all users on the finance team are members of the finance group, which statement describes how the tx_sales table will be created?","options":[{"id":"A","text":"A logical table will persist the query plan to the Hive Metastore in the Databricks control plane."},{"id":"B","text":"An external table will be created in the storage container mounted to /mnt/finance_eda_bucket."},{"id":"C","text":"A managed table will be created in the DBFS root storage container."},{"id":"D","text":"An managed table will be created in the storage container mounted to /mnt/finance_eda_bucket."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"With the shown Hive-metastore database LOCATION and CTAS without a table LOCATION, this is a managed table stored under the database's mounted location. External database storage does not automatically make the table external.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":80,"images":["questions/166-1.png"],"hasEmbeddedCode":true,"relatedQuestion":45},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use the legacy Hive metastore and its managed-table behavior, not Unity Catalog. The shown database and table definitions apply.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":167,"prompt":"The data engineering team has been tasked with configuring connections to an external database that does not have a supported native\nconnector with Databricks. The external database already has data security configured by group membership. These groups map directly to user\ngroups already created in Databricks that represent various teams within the company.\nA new login credential has been created for each group in the external database. The Databricks Utilities Secrets module will be used to make\nthese credentials available to Databricks users.\nAssuming that all the credentials are configured correctly on the external database and group membership is properly configured on Databricks,\nwhich statement describes how teams can be granted the minimum necessary access to using these credentials?","options":[{"id":"A","text":"No additional configuration is necessary as long as all users are configured as administrators in the workspace where secrets have been\nadded.","rationale":"Administrator access is far broader than required.","isCorrect":false},{"id":"B","text":"\"Read\" permissions should be set on a secret key mapped to those credentials that will be used by a given team.","rationale":"The ACL boundary is the scope, not an individual key.","isCorrect":false},{"id":"C","text":"\"Read\" permissions should be set on a secret scope containing only those credentials that will be used by a given team.","rationale":"READ on a team-specific scope grants the needed least privilege.","isCorrect":true},{"id":"D","text":"\"Manage\" permissions should be set on a secret scope containing only those credentials that will be used by a given team.","rationale":"MANAGE unnecessarily allows changing the scope's permissions.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"READ on a team-specific scope grants the needed least privilege.","topic":"secrets","sourceUrl":"https://docs.databricks.com/aws/en/security/secrets/","sourceTitle":"Secret management | Databricks on AWS","sourcePage":80,"images":["questions/167-1.png"],"hasEmbeddedCode":false,"relatedQuestion":100,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":168,"prompt":"What is the retention of job run history?","options":[{"id":"A","text":"It is retained until you export or delete job run logs","rationale":"Run history is not retained indefinitely until manual deletion.","isCorrect":false},{"id":"B","text":"It is retained for 30 days, during which time you can deliver job run logs to DBFS or S3","rationale":"The stated Jobs run-history retention is not 30 days.","isCorrect":false},{"id":"C","text":"It is retained for 60 days, during which you can export notebook run results to HTML","rationale":"Jobs retains runs up to 60 days; export before expiry.","isCorrect":true},{"id":"D","text":"It is retained for 60 days, after which logs are archived","rationale":"There is no automatic permanent archive promised here.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Jobs retains runs up to 60 days; export before expiry.","topic":"jobmonitor","sourceUrl":"https://docs.databricks.com/aws/en/jobs/monitor","sourceTitle":"Monitor Lakeflow Jobs | Databricks on AWS","sourcePage":81,"images":["questions/168-1.png"],"hasEmbeddedCode":false,"relatedQuestion":47,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":169,"prompt":"A data engineer, User A, has promoted a new pipeline to production by using the REST API to programmatically create several jobs. A DevOps\nengineer, User B, has configured an external orchestration tool to trigger job runs through the REST API. Both users authorized the REST API calls\nusing their personal access tokens.\nWhich statement describes the contents of the workspace audit logs concerning these events?","options":[{"id":"A","text":"Because the REST API was used for job creation and triggering runs, a Service Principal will be automatically used to identify these events.","rationale":"A personal token does not automatically become a service principal.","isCorrect":false},{"id":"B","text":"Because User A created the jobs, their identity will be associated with both the job creation events and the job run events.","rationale":"The creator does not become the actor for another user's API call.","isCorrect":false},{"id":"C","text":"Because these events are managed separately, User A will have their identity associated with the job creation events and User B will have\ntheir identity associated with the job run events.","rationale":"Audit events record the authenticated actor for each action.","isCorrect":true},{"id":"D","text":"Because the REST API was used for job creation and triggering runs, user identity will not be captured in the audit logs.","rationale":"API actions still have authenticated audit identities.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Audit events record the authenticated actor for each action.","topic":"audit","sourceUrl":"https://docs.databricks.com/aws/en/admin/account-settings/audit-logs","sourceTitle":"Audit log reference | Databricks on AWS","sourcePage":81,"images":["questions/169-1.png"],"hasEmbeddedCode":false,"relatedQuestion":48,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":170,"prompt":"A distributed team of data analysts share computing resources on an interactive cluster with autoscaling configured. In order to better manage\ncosts and query throughput, the workspace administrator is hoping to evaluate whether cluster upscaling is caused by many concurrent users or\nresource-intensive queries.\nIn which location can one review the timeline for cluster resizing events?","options":[{"id":"A","text":"Workspace audit logs","rationale":"Audit logs are not the dedicated compute-lifecycle timeline.","isCorrect":false},{"id":"B","text":"Driver's log file","rationale":"Driver logs are not the primary cluster-resize event timeline.","isCorrect":false},{"id":"C","text":"Ganglia","rationale":"Resource metrics do not replace the lifecycle event log.","isCorrect":false},{"id":"D","text":"Cluster Event Log","rationale":"The compute event log records resizing events.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The compute event log records resizing events.","topic":"compute","sourceUrl":"https://docs.databricks.com/aws/en/compute/clusters-manage","sourceTitle":"Manage classic compute | Databricks on AWS","sourcePage":81,"images":["questions/170-1.png"],"hasEmbeddedCode":false,"relatedQuestion":85,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":171,"prompt":"When evaluating the Ganglia Metrics for a given cluster with 3 executor nodes, which indicator would signal proper utilization of the VM's\nresources?","options":[{"id":"A","text":"The five Minute Load Average remains consistent/flat","rationale":"A flat load average does not establish the stated CPU distribution.","isCorrect":false},{"id":"B","text":"CPU Utilization is around 75%","rationale":"Three busy nodes out of four equal nodes gives about 75%.","isCorrect":true},{"id":"C","text":"Network I/O never spikes","rationale":"Quiet networking does not establish CPU utilization.","isCorrect":false},{"id":"D","text":"Total Disk Space remains constant","rationale":"Disk capacity is unrelated to this CPU calculation.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"Three busy nodes out of four equal nodes gives about 75%.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":81,"images":["questions/171-1.png"],"hasEmbeddedCode":false,"relatedQuestion":86,"original":{"id":171,"prompt":"When evaluating the Ganglia Metrics for a given cluster with 3 executor nodes, which indicator would signal proper utilization of the VM's\nresources?","options":[{"id":"A","text":"The five Minute Load Average remains consistent/flat"},{"id":"B","text":"CPU Utilization is around 75%"},{"id":"C","text":"Network I/O never spikes"},{"id":"D","text":"Total Disk Space remains constant"}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"With three busy workers and a mostly idle similarly sized driver, aggregate CPU near 75% can indicate worker utilization. This is a heuristic, not a universal optimum; flat load or quiet networking alone cannot establish efficiency.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":81,"images":["questions/171-1.png"],"hasEmbeddedCode":false,"relatedQuestion":86},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Assume three equally sized busy workers and one equally sized mostly idle driver. Choose the approximate aggregate CPU utilization consistent with that condition.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":172,"prompt":"The data engineer is using Spark's MEMORY_ONLY storage level.\nWhich indicators should the data engineer look for in the Spark UI's Storage tab to signal that a cached table is not performing optimally?","options":[{"id":"A","text":"On Heap Memory Usage is within 75% of Off Heap Memory Usage","rationale":"This arbitrary heap comparison is not a cache completeness measure.","isCorrect":false},{"id":"B","text":"The RDD Block Name includes the “*” annotation signaling a failure to cache","rationale":"No such star annotation establishes a cache failure.","isCorrect":false},{"id":"C","text":"Size on Disk is > 0","rationale":"MEMORY_ONLY does not store evicted cached partitions on disk.","isCorrect":false},{"id":"D","text":"After a full action has materialized the cache, the number of Cached Partitions is less than the total number of Spark partitions.","rationale":"Missing cached partitions require recomputation after full materialization.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Missing cached partitions require recomputation after full materialization.","topic":"rdd","sourceUrl":"https://spark.apache.org/docs/latest/rdd-programming-guide.html","sourceTitle":"RDD Programming Guide - Spark 4.2.0 Documentation","sourcePage":82,"images":["questions/172-1.png"],"hasEmbeddedCode":false,"relatedQuestion":101,"original":{"id":172,"prompt":"The data engineer is using Spark's MEMORY_ONLY storage level.\nWhich indicators should the data engineer look for in the Spark UI's Storage tab to signal that a cached table is not performing optimally?","options":[{"id":"A","text":"On Heap Memory Usage is within 75% of Off Heap Memory Usage"},{"id":"B","text":"The RDD Block Name includes the “*” annotation signaling a failure to cache"},{"id":"C","text":"Size on Disk is > 0"},{"id":"D","text":"The number of Cached Partitions > the number of Spark Partitions"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"No option correctly diagnoses MEMORY_ONLY caching. Evicted or uncached partitions are recomputed, not persisted to disk under this level. Look for fewer cached partitions than total partitions; the question's greater-than comparison is reversed.","topic":"rdd","sourceUrl":"https://spark.apache.org/docs/latest/rdd-programming-guide.html","sourceTitle":"RDD Programming Guide - Spark 4.2.0 Documentation","sourcePage":82,"images":["questions/172-1.png"],"hasEmbeddedCode":false,"relatedQuestion":101},"reviewRevision":2,"reviewNote":"Corrected the cached-partition comparison from greater-than to less-than.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":173,"prompt":"Review the following error traceback:\nWhich statement describes the error being raised?","options":[{"id":"A","text":"There is a syntax error because the heartrate column is not correctly identified as a column.","rationale":"The expression is valid Python syntax but resolves a nonexistent column.","isCorrect":false},{"id":"B","text":"There is no column in the table named heartrateheartrateheartrate","rationale":"Python repeats the string, producing a nonexistent column name.","isCorrect":true},{"id":"C","text":"There is a type error because a column object cannot be multiplied.","rationale":"A Column can be multiplied; the expression used a string.","isCorrect":false},{"id":"D","text":"There is a type error because a DataFrame object cannot be multiplied.","rationale":"The code does not multiply a DataFrame.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Python repeats the string, producing a nonexistent column name.","topic":"python","sourceUrl":"https://docs.python.org/3/tutorial/modules.html","sourceTitle":"6. Modules — Python 3.14.8 documentation","sourcePage":82,"images":["questions/173-1.png"],"hasEmbeddedCode":true,"relatedQuestion":52,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":174,"prompt":"Which describes a method of installing a Python package scoped at the notebook level to all nodes in the currently active cluster?","options":[{"id":"A","text":"Run source env/bin/activate in a notebook setup script","rationale":"Activating a driver virtual environment does not distribute notebook dependencies.","isCorrect":false},{"id":"B","text":"Install libraries from PyPI using the cluster UI","rationale":"Cluster UI libraries are compute-scoped, not notebook-scoped.","isCorrect":false},{"id":"C","text":"Use %pip install in a notebook cell","rationale":"The supported notebook package magic installs notebook-scoped dependencies.","isCorrect":true},{"id":"D","text":"Use %sh pip install in a notebook cell","rationale":"A shell pip install is driver-local, not the notebook library mechanism.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The supported notebook package magic installs notebook-scoped dependencies.","topic":"libraries","sourceUrl":"https://docs.databricks.com/aws/en/libraries/notebooks-python-libraries","sourceTitle":"Notebook-scoped Python libraries | Databricks on AWS","sourcePage":83,"images":["questions/174-1.png"],"hasEmbeddedCode":false,"relatedQuestion":111,"practiceEligible":true,"studyContext":"Use Databricks Runtime 14.3 LTS or later with supported notebook-scoped Python package management.","reviewNote":"Second audit: Replaced an unreadable distractor and specified a supported modern runtime.","reviewRevision":3,"auditModified":true,"original":{"prompt":"What is a method of installing a Python package scoped at the notebook level to all nodes in the currently active cluster?","options":[{"id":"A","text":"Run source env/bin/activate in a notebook setup script"},{"id":"B","text":"Install libraries from PyPI using the cluster UI"},{"id":"C","text":"Use %pip install in a notebook cell"},{"id":"D","text":"Use %sh pip install in a notebook cell"}],"correctAnswers":["C"],"explanation":"%pip installs notebook-scoped Python dependencies for that notebook on the compute nodes. %sh pip runs on the driver; cluster libraries are not scoped only to the notebook.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":175,"prompt":"What is the first line of a Databricks Python notebook when viewed in a text editor?","options":[{"id":"A","text":"%python","rationale":"Language magics do not replace the source-format header.","isCorrect":false},{"id":"B","text":"// Databricks notebook source","rationale":"Double slash is the Scala header style, not Python.","isCorrect":false},{"id":"C","text":"# Databricks notebook source","rationale":"Python source-export notebooks use this comment header.","isCorrect":true},{"id":"D","text":"-- Databricks notebook source","rationale":"Double dash is the SQL comment header style.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Python source-export notebooks use this comment header.","topic":"notebooks","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/notebooks-code","sourceTitle":"Develop code in Databricks notebooks | Databricks on AWS","sourcePage":83,"images":["questions/175-1.png"],"hasEmbeddedCode":false,"relatedQuestion":102,"practiceEligible":true,"studyContext":"The file is a Python notebook exported in Databricks SOURCE format, not an .ipynb export.","reviewNote":"Second audit: Notebook headers apply to source exports, not every export format.","reviewRevision":3,"auditModified":true,"original":{"prompt":"What is the first line of a Databricks Python notebook when viewed in a text editor?","options":[{"id":"A","text":"%python"},{"id":"B","text":"// Databricks notebook source"},{"id":"C","text":"# Databricks notebook source"},{"id":"D","text":"-- Databricks notebook source"}],"correctAnswers":["C"],"explanation":"A Python source-format Databricks notebook begins with # Databricks notebook source. Scala uses // and SQL uses --; a language magic is not the source-format header.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":176,"prompt":"Incorporating unit tests into a PySpark application requires upfront attention to the design of your jobs, or a potentially significant refactoring of\nexisting code.\nWhich benefit offsets this additional effort?","options":[{"id":"A","text":"Improves the quality of your data","rationale":"Better data quality can be indirect; it is not the specific isolation benefit.","isCorrect":false},{"id":"B","text":"Validates a complete use case of your application","rationale":"A complete use case belongs to broader functional/end-to-end testing.","isCorrect":false},{"id":"C","text":"Troubleshooting is easier since all steps are isolated and tested individually","rationale":"Isolated tests help localize failing components.","isCorrect":true},{"id":"D","text":"Ensures that all steps interact correctly to achieve the desired end result","rationale":"Inter-step behavior is integration testing, not isolated unit testing.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Isolated tests help localize failing components.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":83,"images":["questions/176-1.png"],"hasEmbeddedCode":false,"relatedQuestion":55,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":177,"prompt":"What describes integration testing?","options":[{"id":"A","text":"It validates an application use case.","rationale":"A complete use case describes functional/end-to-end scope.","isCorrect":false},{"id":"B","text":"It validates behavior of individual elements of an application,","rationale":"Individual elements describe unit-test scope.","isCorrect":false},{"id":"C","text":"It requires an automated testing framework.","rationale":"Automation is useful but not a defining requirement.","isCorrect":false},{"id":"D","text":"It validates interactions between subsystems of your application.","rationale":"Integration tests exercise interactions between components.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Integration tests exercise interactions between components.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":83,"images":["questions/177-1.png"],"hasEmbeddedCode":false,"relatedQuestion":56,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":178,"prompt":"The Databricks CLI is used to trigger a run of an existing job by passing the job_id parameter. The response that the job run request has been\nsubmitted successfully includes a field run_id.\nWhich statement describes what the number alongside this field represents?","options":[{"id":"A","text":"The job_id and number of times the job has been run are concatenated and returned.","rationale":"A run ID is not formed by concatenating a job ID and count.","isCorrect":false},{"id":"B","text":"The response contains a run_id that uniquely identifies the newly created run within the workspace.","rationale":"It identifies the newly created run within the workspace.","isCorrect":true},{"id":"C","text":"The number of times the job definition has been run in this workspace.","rationale":"It is not the per-job execution count.","isCorrect":false},{"id":"D","text":"The job_id is returned in this field.","rationale":"The run ID differs from the job definition ID.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"It identifies the newly created run within the workspace.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":84,"images":["questions/178-1.png"],"hasEmbeddedCode":false,"relatedQuestion":104,"practiceEligible":true,"reviewNote":"Second audit: Scoped identifier uniqueness to the workspace.","reviewRevision":3,"auditModified":true,"original":{"prompt":"The Databricks CLI is used to trigger a run of an existing job by passing the job_id parameter. The response that the job run request has been\nsubmitted successfully includes a field run_id.\nWhich statement describes what the number alongside this field represents?","options":[{"id":"A","text":"The job_id and number of times the job has been run are concatenated and returned."},{"id":"B","text":"The globally unique ID of the newly triggered run."},{"id":"C","text":"The number of times the job definition has been run in this workspace."},{"id":"D","text":"The job_id is returned in this field."}],"correctAnswers":["B"],"explanation":"run_id uniquely identifies the run across jobs, while job_id identifies its reusable definition. It is not a per-job run count or a concatenation of those values.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":179,"prompt":"A Databricks job has been configured with three tasks, each of which is a Databricks notebook. Task A does not depend on other tasks. Tasks B\nand C run in parallel, with each having a serial dependency on task A.\nWhat will be the resulting state if tasks A and B complete successfully but task C fails during a scheduled run?","options":[{"id":"A","text":"All logic expressed in the notebook associated with tasks A and B will have been successfully completed; some operations in task C may\nhave completed successfully.","rationale":"Completed tasks persist; earlier successful operations in C may persist too.","isCorrect":true},{"id":"B","text":"Unless all tasks complete successfully, no changes will be committed to the Lakehouse; because task C failed, all commits will be rolled\nback automatically.","rationale":"There is no implicit job-wide rollback.","isCorrect":false},{"id":"C","text":"Because all tasks are managed as a dependency graph, no changes will be committed to the Lakehouse until all tasks have successfully\nbeen completed.","rationale":"A job graph is not one atomic multi-table transaction.","isCorrect":false},{"id":"D","text":"All logic expressed in the notebook associated with tasks A and B will have been successfully completed; any changes made in task C will\nbe rolled back due to task failure.","rationale":"Task failure does not automatically roll back prior committed operations.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Completed tasks persist; earlier successful operations in C may persist too.","topic":"jobs","sourceUrl":"https://docs.databricks.com/aws/en/jobs/","sourceTitle":"Lakeflow Jobs | Databricks on AWS","sourcePage":84,"images":["questions/179-1.png"],"hasEmbeddedCode":false,"relatedQuestion":58,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":180,"prompt":"When scheduling Structured Streaming jobs for production, which configuration automatically recovers from query failures and keeps costs low?","options":[{"id":"A","text":"Cluster: New Job Cluster;\nRetries: Unlimited;\nMaximum Concurrent Runs: 1","rationale":"Job compute, retries and one run support recovery.","isCorrect":true},{"id":"B","text":"Cluster: New Job Cluster;\nRetries: Unlimited;\nMaximum Concurrent Runs: Unlimited","rationale":"Concurrent copies must not share this stream checkpoint.","isCorrect":false},{"id":"C","text":"Cluster: Existing All-Purpose Cluster;\nRetries: Unlimited;\nMaximum Concurrent Runs: 1","rationale":"All-purpose compute is not the lowest-cost listed production setup.","isCorrect":false},{"id":"D","text":"Cluster: New Job Cluster;\nRetries: None;\nMaximum Concurrent Runs: 1","rationale":"Without retries, failures do not recover automatically.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Job compute, retries and one run support recovery.","topic":"streamprod","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/production","sourceTitle":"Production considerations for Structured Streaming | Databricks on AWS","sourcePage":84,"images":["questions/180-1.png"],"hasEmbeddedCode":false,"relatedQuestion":3,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":181,"prompt":"A Delta Lake table was created with the below query:\nRealizing that the original query had a typographical error, the below code was executed:\nALTER TABLE prod.sales_by_stor RENAME TO prod.sales_by_store\nWhich result will occur after running the second command?","options":[{"id":"A","text":"The table reference in the metastore is updated.","rationale":"Renaming the external table updates catalog metadata only.","isCorrect":true},{"id":"B","text":"All related files and metadata are dropped and recreated in a single ACID transaction.","rationale":"It does not drop and recreate the files.","isCorrect":false},{"id":"C","text":"The table name change is recorded in the Delta transaction log.","rationale":"The rename is a catalog operation, not a data-log commit.","isCorrect":false},{"id":"D","text":"A new Delta transaction log is created for the renamed table.","rationale":"The existing Delta transaction log is retained.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Renaming the external table updates catalog metadata only.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":85,"images":["questions/181-1.png"],"hasEmbeddedCode":true,"relatedQuestion":59,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":182,"prompt":"Each minute, a query computes AVG(temperature) AS mean_temperature grouped by sensor_id over the most recent five minutes. A SQL alert evaluates MAX(mean_temperature) > 120. It evaluates TRUE for three consecutive refreshes and FALSE on the next. Which statement is necessarily true for each of the three triggering refreshes?","options":[{"id":"A","text":"The total average temperature across all sensors exceeded 120 on three consecutive executions of the query","rationale":"One sensor mean does not determine the overall mean.","isCorrect":false},{"id":"B","text":"At least one sensor had an average temperature above 120 at each of the three triggering refreshes; it need not be the same sensor.","rationale":"At least one per-sensor mean exceeds the threshold.","isCorrect":true},{"id":"C","text":"The source query failed to update properly for three consecutive minutes and then restarted","rationale":"A true evaluation does not establish a failed refresh.","isCorrect":false},{"id":"D","text":"Every sensor had a maximum temperature above 120 on each of the three triggering refreshes.","rationale":"The condition does not require every sensor to exceed it.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"At least one per-sensor mean exceeds the threshold.","topic":"alerts","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/alerts/query-patterns","sourceTitle":"SQL alert aggregation and multi-column patterns","sourcePage":85,"images":["questions/182-1.png"],"hasEmbeddedCode":false,"relatedQuestion":4,"original":{"id":182,"prompt":"The data engineering team has configured a Databricks SQL query and alert to monitor the values in a Delta Lake table. The\nrecent_sensor_recordings table contains an identifying sensor_id alongside the timestamp and temperature for the most recent 5 minutes of\nrecordings.\nThe below query is used to create the alert:\nThe query is set to refresh each minute and always completes in less than 10 seconds. The alert is set to trigger when mean (temperature) > 120.\nNotifications are triggered to be sent at most every 1 minute.\nIf this alert raises notifications for 3 consecutive minutes and then stops, which statement must be true?","options":[{"id":"A","text":"The total average temperature across all sensors exceeded 120 on three consecutive executions of the query"},{"id":"B","text":"The average temperature recordings for at least one sensor exceeded 120 on three consecutive executions of the query"},{"id":"C","text":"The source query failed to update properly for three consecutive minutes and then restarted"},{"id":"D","text":"The maximum temperature recording for at least one sensor exceeded 120 on three consecutive executions of the query"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["B"],"status":"review","explanation":"B is the intended answer for a per-sensor mean alert, but D is also logically implied: if a sensor mean exceeds 120, its maximum must exceed 120. Alert aggregation settings are not fully specified. Keep this single-select question out of scoring until rewritten.","topic":"alerts","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/alerts/","sourceTitle":"Databricks SQL alerts | Databricks on AWS","sourcePage":85,"images":["questions/182-1.png"],"hasEmbeddedCode":true,"relatedQuestion":4},"reviewRevision":2,"reviewNote":"Disambiguated the alert aggregation and removed a second logically implied answer.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":183,"prompt":"A junior developer complains that the code in their notebook isn't producing the correct results in the development environment. A shared\nscreenshot reveals that while they're using a notebook versioned with Databricks Repos, they're using a personal branch that contains old logic.\nThe desired branch named dev-2.3.9 is not available from the branch selection dropdown.\nWhich approach will allow this developer to review the current logic for this notebook?","options":[{"id":"A","text":"Use Repos to make a pull request use the Databricks REST API to update the current branch to dev-2.3.9","rationale":"A pull request does not fetch the missing branch.","isCorrect":false},{"id":"B","text":"Use Repos to pull changes from the remote Git repository and select the dev-2.3.9 branch.","rationale":"Pull remote changes, then select the existing remote branch.","isCorrect":true},{"id":"C","text":"Use Repos to checkout the dev-2.3.9 branch and auto-resolve conflicts with the current branch","rationale":"The unavailable branch cannot simply be selected; conflicts are not auto-resolved.","isCorrect":false},{"id":"D","text":"Use Repos to merge the current branch and the dev-2.3.9 branch, then make a pull request to sync with the remote repository","rationale":"Merging unrelated work is unnecessary to inspect a branch.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Pull remote changes, then select the existing remote branch.","topic":"git","sourceUrl":"https://docs.databricks.com/aws/en/repos/git-operations-with-repos","sourceTitle":"Create and manage Git folders | Databricks on AWS","sourcePage":86,"images":["questions/183-1.png"],"hasEmbeddedCode":false,"relatedQuestion":5,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":184,"prompt":"Two of the most common data locations on Databricks are the DBFS root storage and external object storage mounted with dbutils.fs.mount().\nWhich of the following statements is correct?","options":[{"id":"A","text":"DBFS provides a file-style abstraction and familiar paths over distributed cloud storage; it does not guarantee every POSIX filesystem behavior.","rationale":"DBFS provides file-style access over object storage, with limitations.","isCorrect":true},{"id":"B","text":"By default, both the DBFS root and mounted data sources are only accessible to workspace administrators.","rationale":"Legacy DBFS data is not universally administrator-only.","isCorrect":false},{"id":"C","text":"The DBFS root is the most secure location to store data, because mounted storage volumes must have full public read and write\npermissions.","rationale":"Mounts do not require public read/write access.","isCorrect":false},{"id":"D","text":"The DBFS root stores files in ephemeral block volumes attached to the driver, while mounted directories will always persist saved data to\nexternal storage between sessions.","rationale":"DBFS root is backed by object storage, not ephemeral driver disks.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"DBFS provides file-style access over object storage, with limitations.","topic":"dbfs","sourceUrl":"https://docs.databricks.com/aws/en/dbfs/","sourceTitle":"What is DBFS? | Databricks on AWS","sourcePage":86,"images":["questions/184-1.png"],"hasEmbeddedCode":false,"relatedQuestion":65,"original":{"id":184,"prompt":"Two of the most common data locations on Databricks are the DBFS root storage and external object storage mounted with dbutils.fs.mount().\nWhich of the following statements is correct?","options":[{"id":"A","text":"DBFS is a file system protocol that allows users to interact with files stored in object storage using syntax and guarantees similar to Unix\nfile systems."},{"id":"B","text":"By default, both the DBFS root and mounted data sources are only accessible to workspace administrators."},{"id":"C","text":"The DBFS root is the most secure location to store data, because mounted storage volumes must have full public read and write\npermissions."},{"id":"D","text":"The DBFS root stores files in ephemeral block volumes attached to the driver, while mounted directories will always persist saved data to\nexternal storage between sessions."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"legacy","explanation":"DBFS offers file-system-style paths over cloud object storage. Its root is not ephemeral driver storage, and mounts do not require public access. DBFS root and mounts are now deprecated for new designs; use Unity Catalog volumes/external locations.","topic":"dbfs","sourceUrl":"https://docs.databricks.com/aws/en/dbfs/","sourceTitle":"What is DBFS? | Databricks on AWS","sourcePage":86,"images":["questions/184-1.png"],"hasEmbeddedCode":false,"relatedQuestion":65},"reviewRevision":3,"reviewNote":"The answer is scored within the explicit context shown with this question. Second audit: Removed the claim of full Unix filesystem guarantees.","studyContext":"This question concerns an existing legacy workspace where DBFS root and mounts are enabled. They remain historical concepts, not a recommendation for new storage designs.","reviewedAt":"2026-10-04","practiceEligible":true,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":185,"prompt":"An upstream system has been configured to pass the date for a given batch of data to the Databricks Jobs API as a parameter. The notebook to\nbe scheduled will use this parameter to load data with the following code: df = spark.read.format(\"parquet\").load(f\"/mnt/source/{date}\")\nWhich code block should be used to create the date Python variable used in the above code block?","options":[{"id":"A","text":"date = spark.conf.get(\"date\")","rationale":"Spark configuration is not the notebook task-parameter interface.","isCorrect":false},{"id":"B","text":"import sys\ndate = sys.argv[1]","rationale":"sys.argv is for script arguments, not notebook widgets.","isCorrect":false},{"id":"C","text":"date = dbutils.notebooks.getParam(\"date\")","rationale":"This notebook utility method does not exist.","isCorrect":false},{"id":"D","text":"dbutils.widgets.text(\"date\", \"null\")\ndate = dbutils.widgets.get(\"date\")","rationale":"Widgets expose notebook task parameters as strings.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Widgets expose notebook task parameters as strings.","topic":"widgets","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/widgets","sourceTitle":"Databricks widgets | Databricks on AWS","sourcePage":86,"images":["questions/185-1.png"],"hasEmbeddedCode":false,"relatedQuestion":1,"practiceEligible":true,"reviewNote":"Second audit: Corrected the f-string date placeholder.","reviewRevision":3,"auditModified":true,"original":{"prompt":"An upstream system has been configured to pass the date for a given batch of data to the Databricks Jobs API as a parameter. The notebook to\nbe scheduled will use this parameter to load data with the following code:\ndf = spark.read.format(\"parquet\").load(f\"/mnt/source/(date)\")\nWhich code block should be used to create the date Python variable used in the above code block?","options":[{"id":"A","text":"date = spark.conf.get(\"date\")"},{"id":"B","text":"import sys\ndate = sys.argv[1]"},{"id":"C","text":"date = dbutils.notebooks.getParam(\"date\")"},{"id":"D","text":"dbutils.widgets.text(\"date\", \"null\")\ndate = dbutils.widgets.get(\"date\")"}],"correctAnswers":["D"],"explanation":"Notebook task parameters are read through dbutils.widgets.get. Spark configuration, stdin and sys.argv are different mechanisms; dbutils.notebooks.getParam is not the supported API.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":186,"prompt":"The Databricks workspace administrator has configured interactive clusters for each of the data engineering groups. To control costs, clusters are\nset to terminate after 30 minutes of inactivity. Each user should be able to execute workloads against their assigned clusters at any time of the\nday.\nAssuming users have been added to a workspace but not granted any permissions, which of the following describes the minimal permissions a\nuser would need to start and attach to an already configured cluster.","options":[{"id":"A","text":"\"Can Manage\" privileges on the required cluster","rationale":"CAN MANAGE is broader than necessary.","isCorrect":false},{"id":"B","text":"Cluster creation allowed, \"Can Restart\" privileges on the required cluster","rationale":"Cluster creation adds an unnecessary privilege.","isCorrect":false},{"id":"C","text":"Cluster creation allowed, \"Can Attach To\" privileges on the required cluster","rationale":"CAN ATTACH TO cannot restart terminated compute.","isCorrect":false},{"id":"D","text":"\"Can Restart\" privileges on the required cluster","rationale":"CAN RESTART includes restart and attachment.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"CAN RESTART includes restart and attachment.","topic":"compute","sourceUrl":"https://docs.databricks.com/aws/en/compute/clusters-manage","sourceTitle":"Manage classic compute | Databricks on AWS","sourcePage":87,"images":["questions/186-1.png"],"hasEmbeddedCode":false,"relatedQuestion":2,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":187,"prompt":"The data science team has created and logged a production model using MLflow. The following code correctly imports and applies the production\nmodel to output the predictions as a new DataFrame named preds with the schema \"customer_id LONG, predictions DOUBLE, date DATE\".\nThe data science team would like predictions saved to a Delta Lake table with the ability to compare all predictions across time. Churn predictions\nwill be made at most once per day.\nWhich code block accomplishes this task while minimizing potential compute costs?","options":[{"id":"A","text":"preds.write.mode(\"append\").saveAsTable(\"churn_preds\")","rationale":"Append retains predictions from earlier dates.","isCorrect":true},{"id":"B","text":"preds.write.format(\"delta\").save(\"/preds/churn_preds\")","rationale":"Default save mode fails when the destination already exists.","isCorrect":false},{"id":"C","text":"[Code choice shown in the original PDF image]","rationale":"A batch DataFrame cannot use writeStream.","isCorrect":false},{"id":"D","text":"[Code choice shown in the original PDF image]","rationale":"Overwrite discards previously stored predictions.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Append retains predictions from earlier dates.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":87,"images":["questions/187-1.png"],"hasEmbeddedCode":true,"relatedQuestion":7,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":188,"prompt":"The following code has been migrated to a Databricks notebook from a legacy workload:\nThe code executes successfully and provides the logically correct results, however, it takes over 20 minutes to extract and load around 1 GB of\ndata.\nWhich statement is a possible explanation for this behavior?","options":[{"id":"A","text":"%sh triggers a cluster restart to collect and install Git. Most of the latency is related to cluster startup time.","rationale":"A shell cell does not require a cluster restart.","isCorrect":false},{"id":"B","text":"Instead of cloning, the code should use %sh pip install so that the Python code can get executed in parallel across all nodes in a cluster.","rationale":"Installing a package does not distribute its execution.","isCorrect":false},{"id":"C","text":"%sh does not distribute file moving operations; the final line of code should be updated to use %fs instead.","rationale":"Changing the file-copy command does not distribute the Python workload.","isCorrect":false},{"id":"D","text":"%sh executes shell code on the driver node. The code does not take advantage of the worker nodes or Databricks optimized Spark.","rationale":"Ordinary shell/Python work here runs on the driver only.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Ordinary shell/Python work here runs on the driver only.","topic":"notebooks","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/notebooks-code","sourceTitle":"Develop code in Databricks notebooks | Databricks on AWS","sourcePage":88,"images":["questions/188-1.png"],"hasEmbeddedCode":true,"relatedQuestion":66,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":189,"prompt":"A Delta table of weather records is partitioned by date and has the below schema:\ndate DATE, device_id INT, temp FLOAT, latitude FLOAT, longitude FLOAT\nTo find all the records from within the Arctic Circle, you execute a query with the below filter:\nlatitude > 66.3\nWhich statement describes how the Delta engine identifies which files to load?","options":[{"id":"A","text":"All records are cached to an operational database and then the filter is applied","rationale":"No operational-database cache is required for skipping.","isCorrect":false},{"id":"B","text":"The Parquet file footers are scanned for min and max statistics for the latitude column","rationale":"Delta uses logged statistics, not a required footer scan.","isCorrect":false},{"id":"C","text":"The Hive metastore is scanned for min and max statistics for the latitude column","rationale":"The metastore does not hold these Delta per-file statistics.","isCorrect":false},{"id":"D","text":"The Delta log is scanned for min and max statistics for the latitude column","rationale":"Logged per-file latitude statistics identify candidate files.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Logged per-file latitude statistics identify candidate files.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":88,"images":["questions/189-1.png"],"hasEmbeddedCode":false,"relatedQuestion":10,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":190,"prompt":"In order to prevent accidental commits to production data, a senior data engineer has instituted a policy that all development work will reference\nclones of Delta Lake tables. After testing both DEEP and SHALLOW CLONE, development tables are created using SHALLOW CLONE.\nA few weeks after initial table creation, the cloned versions of several tables implemented as Type 1 Slowly Changing Dimension (SCD) stop\nworking. The transaction logs for the source tables show that VACUUM was run the day before.\nWhich statement describes why the cloned tables are no longer working?","options":[{"id":"A","text":"Because Type 1 changes overwrite existing records, Delta Lake cannot guarantee data consistency for cloned tables.","rationale":"Type 1 updates do not inherently invalidate every clone.","isCorrect":false},{"id":"B","text":"Running VACUUM automatically invalidates any shallow clones of a table; DEEP CLONE should always be used when a cloned table will be\nrepeatedly queried.","rationale":"Vacuum only breaks clones when referenced files are removed.","isCorrect":false},{"id":"C","text":"The data files compacted by VACUUM are not tracked by the cloned metadata; running REFRESH on the cloned table will pull in recent\nchanges.","rationale":"VACUUM does not compact data; REFRESH does not reconstruct deleted files.","isCorrect":false},{"id":"D","text":"The metadata created by the CLONE operation is referencing data files that were purged as invalid by the VACUUM command.","rationale":"The clone references source files removed by vacuum.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The clone references source files removed by vacuum.","topic":"clone","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/clone","sourceTitle":"Clone a table on Databricks | Databricks on AWS","sourcePage":89,"images":["questions/190-1.png"],"hasEmbeddedCode":false,"relatedQuestion":92,"original":{"id":190,"prompt":"In order to prevent accidental commits to production data, a senior data engineer has instituted a policy that all development work will reference\nclones of Delta Lake tables. After testing both DEEP and SHALLOW CLONE, development tables are created using SHALLOW CLONE.\nA few weeks after initial table creation, the cloned versions of several tables implemented as Type 1 Slowly Changing Dimension (SCD) stop\nworking. The transaction logs for the source tables show that VACUUM was run the day before.\nWhich statement describes why the cloned tables are no longer working?","options":[{"id":"A","text":"Because Type 1 changes overwrite existing records, Delta Lake cannot guarantee data consistency for cloned tables."},{"id":"B","text":"Running VACUUM automatically invalidates any shallow clones of a table; DEEP CLONE should always be used when a cloned table will be\nrepeatedly queried."},{"id":"C","text":"The data files compacted by VACUUM are not tracked by the cloned metadata; running REFRESH on the cloned table will pull in recent\nchanges."},{"id":"D","text":"The metadata created by the CLONE operation is referencing data files that were purged as invalid by the VACUUM command."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"A legacy shallow clone references source data files; source VACUUM can remove those files and break it. Unity Catalog managed shallow clones on supported runtimes have different retention protection, so do not generalize this to every modern clone.","topic":"clone","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/clone","sourceTitle":"Clone a table on Databricks | Databricks on AWS","sourcePage":89,"images":["questions/190-1.png"],"hasEmbeddedCode":false,"relatedQuestion":92},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use a Hive-metastore shallow clone that references source files; Unity Catalog managed shallow-clone retention protections do not apply.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":191,"prompt":"A junior data engineer has configured a workload that posts the following JSON to the Databricks REST API endpoint 2.0/jobs/create.\nAssuming that all configurations and referenced resources are available, which statement describes the result of executing this workload three\ntimes?","options":[{"id":"A","text":"The logic defined in the referenced notebook will be executed three times on the referenced existing all purpose cluster.","rationale":"The create endpoint does not trigger notebook runs.","isCorrect":false},{"id":"B","text":"The logic defined in the referenced notebook will be executed three times on new clusters with the configurations of the provided cluster ID.","rationale":"Creating a job does not execute its notebook.","isCorrect":false},{"id":"C","text":"Three new jobs named \"Ingest new data\" will be defined in the workspace, but no jobs will be executed.","rationale":"Each create call creates a definition without running it.","isCorrect":true},{"id":"D","text":"One new job named \"Ingest new data\" will be defined in the workspace, but it will not be executed.","rationale":"Job names are not an idempotency key.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Each create call creates a definition without running it.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":89,"images":["questions/191-1.png"],"hasEmbeddedCode":true,"relatedQuestion":12,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":192,"prompt":"A Delta Lake table in the Lakehouse named customer_churn_params is used in churn prediction by the machine learning team. The table contains\ninformation about customers derived from a number of upstream sources. Currently, the data engineering team populates this table nightly by\noverwriting the table with the current valid values derived from upstream data sources.\nImmediately after each update succeeds, the data engineering team would like to determine the difference between the new version and the\nprevious version of the table.\nGiven the current implementation, which method can be used?","options":[{"id":"A","text":"Execute a query to calculate the difference between the new version and the previous version using Delta Lake’s built-in versioning and lime\ntravel functionality.","rationale":"Comparing retained snapshots identifies logical row differences.","isCorrect":true},{"id":"B","text":"Parse the Delta Lake transaction log to identify all newly written data files.","rationale":"New file names do not distinguish changed rows from unchanged rewrites.","isCorrect":false},{"id":"C","text":"Parse the Spark event logs to identify those rows that were updated, inserted, or deleted.","rationale":"Spark event logs are not a row-level change archive.","isCorrect":false},{"id":"D","text":"Execute DESCRIBE HISTORY customer_churn_params to obtain the full operation metrics for the update, including a log of all records that\nhave been added or modified.","rationale":"History provides operation metadata, not every changed row.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"Comparing retained snapshots identifies logical row differences.","topic":"history","sourceUrl":"https://docs.databricks.com/aws/en/tables/history","sourceTitle":"Work with table history | Databricks on AWS","sourcePage":90,"images":["questions/192-1.png"],"hasEmbeddedCode":false,"relatedQuestion":113,"practiceEligible":true,"studyContext":"CDF was not enabled before the overwrite. The required table versions and data files are retained. Identify logical row differences, not merely rewritten file names.","reviewNote":"Second audit: Historical CDF is unavailable unless it was captured; logical snapshot differences are requested.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A Delta Lake table in the Lakehouse named customer_churn_params is used in churn prediction by the machine learning team. The table contains\ninformation about customers derived from a number of upstream sources. Currently, the data engineering team populates this table nightly by\noverwriting the table with the current valid values derived from upstream data sources.\nImmediately after each update succeeds, the data engineering team would like to determine the difference between the new version and the\nprevious version of the table.\nGiven the current implementation, which method can be used?","options":[{"id":"A","text":"Execute a query to calculate the difference between the new version and the previous version using Delta Lake’s built-in versioning and lime\ntravel functionality."},{"id":"B","text":"Parse the Delta Lake transaction log to identify all newly written data files."},{"id":"C","text":"Parse the Spark event logs to identify those rows that were updated, inserted, or deleted."},{"id":"D","text":"Execute DESCRIBE HISTORY customer_churn_params to obtain the full operation metrics for the update, including a log of all records that\nhave been added or modified."}],"correctAnswers":["A"],"explanation":"Compare the new and previous table snapshots using time travel. A full overwrite rewrites unchanged rows too; file lists/history metrics are not a row-level semantic diff, and CDF is not stated to have been enabled.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":193,"prompt":"A view is registered with the following code:\nBoth users and orders are Delta Lake tables.\nWhich statement describes the results of querying recent_orders?","options":[{"id":"A","text":"The versions of each source table will be stored in the table transaction log; query results will be saved to DBFS with each query.","rationale":"A regular view does not maintain its own data transaction log or save every query result to DBFS.","isCorrect":false},{"id":"B","text":"All logic will execute when the table is defined and store the result of joining tables to the DBFS; this stored data will be returned when the\ntable is queried.","rationale":"A regular view stores a query definition, not materialized join results.","isCorrect":false},{"id":"C","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query finishes.","rationale":"The query does not switch to snapshots committed while it is running.","isCorrect":false},{"id":"D","text":"All logic will execute at query time and return the result of joining the valid versions of the source tables at the time the query began.","rationale":"The query reads consistent source snapshots selected for that query, rather than materializing data when the view is created.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The query reads consistent source snapshots selected for that query, rather than materializing data when the view is created.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":90,"images":["questions/193-1.png"],"hasEmbeddedCode":true,"relatedQuestion":135,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":194,"prompt":"A data engineer is performing a join operation to combine values from a static userLookup table with a streaming DataFrame streamingDF.\nWhich code block attempts to perform an invalid stream-static join?","options":[{"id":"A","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"right\")","rationale":"Right outer with the streaming side on the right is supported.","isCorrect":false},{"id":"B","text":"streamingDF.join(userLookup, [\"user_id\"], how=\"inner\")","rationale":"An inner stream-static join is supported.","isCorrect":false},{"id":"C","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"inner\")","rationale":"An inner join also supports the static side on the left.","isCorrect":false},{"id":"D","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"left\")","rationale":"Left outer with the static side on the left and stream on the right is unsupported.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Left outer with the static side on the left and stream on the right is unsupported.","topic":"joins","sourceUrl":"https://docs.databricks.com/aws/en/transform/join","sourceTitle":"Work with joins on Databricks | Databricks on AWS","sourcePage":91,"images":["questions/194-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":194,"prompt":"A data engineer is performing a join operation to combine values from a static userLookup table with a streaming DataFrame streamingDF.\nWhich code block attempts to perform an invalid stream-static join?","options":[{"id":"A","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"right\")"},{"id":"B","text":"streamingDF.join(userLookup, [\"user_id\"], how=\"inner\")"},{"id":"C","text":"userLookup.join(streamingDF, [\"user_id\"), how=\"inner\")"},{"id":"D","text":"userLookup.join(streamingDF, [\"user_id\"], how=\"left\")"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["D"],"status":"review","explanation":"D is the semantically unsupported join: it preserves the static left side against an unbounded stream. However, option C also has a mismatched bracket in the printed code. Fix that typo before using this as a single-answer scored item.","topic":"joins","sourceUrl":"https://docs.databricks.com/aws/en/transform/join","sourceTitle":"Work with joins on Databricks | Databricks on AWS","sourcePage":91,"images":["questions/194-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Fixed the mismatched bracket in option C so only the unsupported join semantics are tested.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":195,"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Incremental state information should be\nmaintained for 10 minutes for late-arriving data.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nChoose the response that correctly fills in the blank within the code block to complete this task.","options":[{"id":"A","text":"withWatermark(\"event_time\", \"10 minutes\")","rationale":"This configures the event-time lateness threshold.","isCorrect":true},{"id":"B","text":"awaitArrival(\"event_time\", \"10 minutes\")","rationale":"This is not the required DataFrame API.","isCorrect":false},{"id":"C","text":"await(\"event_time + ‘10 minutes'\")","rationale":"This is not a valid watermark API call.","isCorrect":false},{"id":"D","text":"slidingWindow(\"event_time\", \"10 minutes\")","rationale":"Window grouping is not the watermark declaration.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"This configures the event-time lateness threshold.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Apply watermarks to control data processing thresholds | Databricks on AWS","sourcePage":91,"images":["questions/195-1.png"],"hasEmbeddedCode":false,"relatedQuestion":71,"practiceEligible":true,"code":"from pyspark.sql.functions import avg, window\n# Replace WATERMARK_CALL with the selected method call on df.\n(df.WATERMARK_CALL\n .groupBy(window(\"event_time\", \"5 minutes\").alias(\"time\"), \"device_id\")\n .agg(avg(\"temp\").alias(\"avg_temp\"), avg(\"humidity\").alias(\"avg_humidity\"))\n .writeStream.format(\"delta\").outputMode(\"append\")\n .option(\"checkpointLocation\", checkpoint_path)\n .toTable(\"sensor_avg\"))","studyContext":"Use a 10-minute event-time lateness threshold; cleanup follows watermark progress and is not an exact 10-minute wall-clock timer. checkpoint_path is defined.","reviewNote":"Second audit: Corrected the sink API and specified event-time rather than wall-clock retention.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A junior data engineer has been asked to develop a streaming data pipeline with a grouped aggregation using DataFrame df. The pipeline needs to\ncalculate the average humidity and average temperature for each non-overlapping five-minute interval. Incremental state information should be\nmaintained for 10 minutes for late-arriving data.\nStreaming DataFrame df has the following schema:\n\"device_id INT, event_time TIMESTAMP, temp FLOAT, humidity FLOAT\"\nCode block:\nChoose the response that correctly fills in the blank within the code block to complete this task.","options":[{"id":"A","text":"withWatermark(\"event_time\", \"10 minutes\")"},{"id":"B","text":"awaitArrival(\"event_time\", \"10 minutes\")"},{"id":"C","text":"await(\"event_time + ‘10 minutes'\")"},{"id":"D","text":"slidingWindow(\"event_time\", \"10 minutes\")"}],"correctAnswers":["A"],"explanation":"withWatermark(event_time, '10 minutes') is the correct API for event-time lateness/state cleanup. It is not a wall-clock sleep, and late-data handling depends on the watermark and output mode.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":196,"prompt":"A data architect has designed a system in which two Structured Streaming jobs will concurrently write to a single bronze Delta table. Each job is\nsubscribing to a different topic from an Apache Kafka source, but they will write data with the same schema. To keep the directory structure\nsimple, a data engineer has decided to nest a checkpoint directory to be shared by both streams.\nThe proposed directory structure is displayed below:\nWhich statement describes whether this checkpoint directory structure is valid for the given scenario and why?","options":[{"id":"A","text":"No; Delta Lake manages streaming checkpoints in the transaction log.","rationale":"The stream checkpoint is distinct from the Delta transaction log.","isCorrect":false},{"id":"B","text":"Yes; both of the streams can share a single checkpoint directory.","rationale":"Independent queries must not share one checkpoint.","isCorrect":false},{"id":"C","text":"No; only one stream can write to a Delta Lake table.","rationale":"Multiple streams can write the same Delta table.","isCorrect":false},{"id":"D","text":"No; each of the streams needs to have its own checkpoint directory.","rationale":"Each query requires its own checkpoint directory.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Each query requires its own checkpoint directory.","topic":"checkpoints","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/checkpoints","sourceTitle":"Structured Streaming checkpoints | Databricks on AWS","sourcePage":92,"images":["questions/196-1.png"],"hasEmbeddedCode":true,"relatedQuestion":20,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":197,"prompt":"A Structured Streaming job deployed to production has been experiencing delays during peak hours of the day. At present, during normal\nexecution, each microbatch of data is processed in less than 3 seconds. During peak hours of the day, execution time for each microbatch\nbecomes very inconsistent, sometimes exceeding 30 seconds. The streaming write is currently configured with a trigger interval of 10 seconds.\nWhich listed adjustment is a reasonable first experiment to reduce batch size and spill while keeping the current micro-batch execution model?","options":[{"id":"A","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently allows idle executors to begin processing the next batch\nwhile longer running tasks from previous batches finish.","rationale":"Microbatches do not overlap in the described execution mode.","isCorrect":false},{"id":"B","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently may prevent records from backing up and large batches from\ncausing spill.","rationale":"A shorter interval is a reasonable batch-size experiment.","isCorrect":true},{"id":"C","text":"The trigger interval cannot be modified without modifying the checkpoint directory; to maintain the current stream state, increase the\nnumber of shuffle partitions to maximize parallelism.","rationale":"A trigger change does not inherently require a new checkpoint.","isCorrect":false},{"id":"D","text":"Use the trigger once option and configure a Databricks job to execute the query every 10 seconds; this ensures all backlogged records are\nprocessed with each batch.","rationale":"Repeated finite jobs do not preserve the requested execution model.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"A shorter interval is a reasonable batch-size experiment.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":92,"images":["questions/197-1.png"],"hasEmbeddedCode":false,"relatedQuestion":21,"original":{"id":197,"prompt":"A Structured Streaming job deployed to production has been experiencing delays during peak hours of the day. At present, during normal\nexecution, each microbatch of data is processed in less than 3 seconds. During peak hours of the day, execution time for each microbatch\nbecomes very inconsistent, sometimes exceeding 30 seconds. The streaming write is currently configured with a trigger interval of 10 seconds.\nHolding all other variables constant and assuming records need to be processed in less than 10 seconds, which adjustment will meet the\nrequirement?","options":[{"id":"A","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently allows idle executors to begin processing the next batch\nwhile longer running tasks from previous batches finish."},{"id":"B","text":"Decrease the trigger interval to 5 seconds; triggering batches more frequently may prevent records from backing up and large batches from\ncausing spill."},{"id":"C","text":"The trigger interval cannot be modified without modifying the checkpoint directory; to maintain the current stream state, increase the\nnumber of shuffle partitions to maximize parallelism."},{"id":"D","text":"Use the trigger once option and configure a Databricks job to execute the query every 10 seconds; this ensures all backlogged records are\nprocessed with each batch."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Smaller batches may reduce backlog and spill, making B the best proposed change. Microbatches do not overlap as A claims. No trigger setting alone guarantees sub-ten-second latency during a sustained capacity bottleneck.","topic":"triggers","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/triggers","sourceTitle":"Configure Structured Streaming trigger intervals | Databricks on AWS","sourcePage":92,"images":["questions/197-1.png"],"hasEmbeddedCode":false,"relatedQuestion":21},"reviewRevision":2,"reviewNote":"Removed an unsupported guarantee that a trigger change alone meets a strict latency deadline.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":198,"prompt":"Which statement describes the default execution mode for Databricks Auto Loader?","options":[{"id":"A","text":"Cloud vendor-specific queue storage and notification services are configured to track newly arriving files; new files are incrementally and\nidempotently loaded into the target Delta Lake table.","rationale":"Notification mode was explicitly excluded by the context.","isCorrect":false},{"id":"B","text":"New files are identified by listing the input directory; the target table is materialized by directly querying all valid files in the source directory.","rationale":"Auto Loader loads new files rather than querying all files as a view.","isCorrect":false},{"id":"C","text":"Webhooks trigger a Databricks job to run anytime new data arrives in a source directory; new data are automatically merged into target\ntables using rules inferred from the data.","rationale":"It does not infer CDC merge rules from webhooks.","isCorrect":false},{"id":"D","text":"New files are identified by listing the input directory; new files are incrementally and idempotently loaded into the target Delta Lake table.","rationale":"The scoped default lists files and incrementally loads them with tracked progress.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The scoped default lists files and incrementally loads them with tracked progress.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/release-notes/runtime/18.1","sourceTitle":"Runtime 18.1: change to Auto Loader file-event defaults","sourcePage":92,"images":["questions/198-1.png"],"hasEmbeddedCode":false,"relatedQuestion":108,"original":{"id":198,"prompt":"Which statement describes the default execution mode for Databricks Auto Loader?","options":[{"id":"A","text":"Cloud vendor-specific queue storage and notification services are configured to track newly arriving files; new files are incrementally and\nidempotently loaded into the target Delta Lake table."},{"id":"B","text":"New files are identified by listing the input directory; the target table is materialized by directly querying all valid files in the source directory."},{"id":"C","text":"Webhooks trigger a Databricks job to run anytime new data arrives in a source directory; new data are automatically merged into target\ntables using rules inferred from the data."},{"id":"D","text":"New files are identified by listing the input directory; new files are incrementally and idempotently loaded into the target Delta Lake table."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"Directory listing was the default file-discovery mode, with incremental processing tracked in checkpoints. Newer runtimes can default to managed file events when available, so the answer depends on runtime and external-location setup.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/","sourceTitle":"What is Auto Loader? | Databricks on AWS","sourcePage":92,"images":["questions/198-1.png"],"hasEmbeddedCode":false,"relatedQuestion":108},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use Databricks Runtime 17.3 LTS, without managed file events or notification mode configured.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":199,"prompt":"Which statement describes the correct use of pyspark.sql.functions.broadcast?","options":[{"id":"A","text":"It marks a column as having low enough cardinality to properly map distinct values to available partitions, allowing a broadcast join.","rationale":"broadcast marks a DataFrame, not a column cardinality.","isCorrect":false},{"id":"B","text":"It marks a column as small enough to store in memory on all executors, allowing a broadcast join.","rationale":"The hint applies to a DataFrame, not one column.","isCorrect":false},{"id":"C","text":"It caches a copy of the indicated table on all nodes in the cluster for use in all future queries during the cluster lifetime.","rationale":"It does not create a permanent all-query cache.","isCorrect":false},{"id":"D","text":"It marks a DataFrame as small enough to store in memory on all executors, allowing a broadcast join.","rationale":"The hint identifies a small DataFrame as a broadcast-join input.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The hint identifies a small DataFrame as a broadcast-join input.","topic":"broadcast","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.functions.broadcast.html","sourceTitle":"pyspark.sql.functions.broadcast — PySpark 4.2.0 documentation","sourcePage":93,"images":["questions/199-1.png"],"hasEmbeddedCode":false,"relatedQuestion":74,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":200,"prompt":"Spill occurs as a result of executing various wide transformations. However, diagnosing spill requires one to proactively look for key indicators.\nWhere in the Spark UI are two of the primary indicators that a partition is spilling to disk?","options":[{"id":"A","text":"Stage’s detail screen and Query’s detail screen","rationale":"Stage task metrics and query operators expose spill information.","isCorrect":true},{"id":"B","text":"Stage’s detail screen and Executor’s log files","rationale":"Log files are not the pair of native UI metric views requested.","isCorrect":false},{"id":"C","text":"Driver’s and Executor’s log files","rationale":"Logs are not the requested Spark UI detail views.","isCorrect":false},{"id":"D","text":"Executor’s detail screen and Executor’s log files","rationale":"Executor views do not replace stage and query operator metrics.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Stage task metrics and query operators expose spill information.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":93,"images":["questions/200-1.png"],"hasEmbeddedCode":false,"relatedQuestion":94,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":201,"prompt":"An upstream source writes Parquet data as hourly batches to directories named with the current date. A nightly batch job runs the following code\nto ingest all data from the previous day as indicated by the date variable:\nAssume that the fields customer_id and order_id serve as a composite key to uniquely identify each order.\nIf the upstream system is known to occasionally produce duplicate entries for a single order hours apart, which statement is correct?","options":[{"id":"A","text":"Each write to the orders table will only contain unique records, and only those records without duplicates in the target table will be written.","rationale":"Batch deduplication does not check the existing target.","isCorrect":false},{"id":"B","text":"Each write to the orders table will only contain unique records, but newly written records may have duplicates already present in the target\ntable.","rationale":"The batch is deduplicated; append does not deduplicate history.","isCorrect":true},{"id":"C","text":"Each write to the orders table will only contain unique records; if existing records with the same key are present in the target table, these\nrecords will be overwritten.","rationale":"Append does not overwrite matching business keys.","isCorrect":false},{"id":"D","text":"Each write to the orders table will run deduplication over the union of new and existing records, ensuring no duplicate records are present.","rationale":"Existing target rows are not part of this deduplication.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"The batch is deduplicated; append does not deduplicate history.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":93,"images":["questions/201-1.png"],"hasEmbeddedCode":true,"relatedQuestion":8,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":202,"prompt":"A junior data engineer on your team has implemented the following code block.\nThe view new_events contains a batch of records with the same schema as the events Delta table. The event_id field serves as a unique key for\nthis table.\nWhen this query is executed, what will happen with new records that have the same event_id as an existing record?","options":[{"id":"A","text":"They are merged.","rationale":"No matched-row merge action is defined.","isCorrect":false},{"id":"B","text":"They are ignored.","rationale":"Matching source keys have no applicable action and are ignored.","isCorrect":true},{"id":"C","text":"They are updated.","rationale":"There is no WHEN MATCHED UPDATE clause.","isCorrect":false},{"id":"D","text":"They are inserted.","rationale":"The insert clause applies only to unmatched keys.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Matching source keys have no applicable action and are ignored.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":94,"images":["questions/202-1.png"],"hasEmbeddedCode":true,"relatedQuestion":27,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":203,"prompt":"A new data engineer notices that a critical field was omitted from an application that writes its Kafka source to Delta Lake. This happened even\nthough the critical field was in the Kafka source. That field was further missing from data written to dependent, long-term storage. The retention\nthreshold on the Kafka service is seven days. The pipeline has been in production for three months.\nWhich describes how Delta Lake can help to avoid data loss of this nature in the future?","options":[{"id":"A","text":"The Delta log and Structured Streaming checkpoints record the full history of the Kafka producer.","rationale":"Checkpoints and transaction metadata do not archive full Kafka payloads.","isCorrect":false},{"id":"B","text":"Delta Lake schema evolution can retroactively calculate the correct value for newly added fields, as long as the data was in the original\nsource.","rationale":"Schema evolution cannot reconstruct values that were never retained.","isCorrect":false},{"id":"C","text":"Delta Lake automatically checks that all fields present in the source data are included in the ingestion layer.","rationale":"Completeness requires explicit ingestion design, not an automatic guarantee.","isCorrect":false},{"id":"D","text":"Ingesting all raw data and metadata from Kafka to a bronze Delta table creates a permanent, replayable history of the data state.","rationale":"Retaining complete raw payloads allows later replay.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Retaining complete raw payloads allows later replay.","topic":"medallion","sourceUrl":"https://docs.databricks.com/aws/en/lakehouse/medallion","sourceTitle":"What is the medallion lakehouse architecture? | Databricks on AWS","sourcePage":94,"images":["questions/203-1.png"],"hasEmbeddedCode":false,"relatedQuestion":29,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":204,"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source table has been de-duplicated and validated, which statement\ndescribes what will occur when this code is executed?","options":[{"id":"A","text":"The silver_customer_sales table will be overwritten by aggregated values calculated from all records in the\ngold_customer_lifetime_sales_summary table as a batch job.","rationale":"The named source and target are reversed.","isCorrect":false},{"id":"B","text":"A batch job will update the gold_customer_lifetime_sales_summary table, replacing only those rows that have different values than the\ncurrent version of the table, using customer_id as the primary key.","rationale":"Overwrite is not a primary-key upsert.","isCorrect":false},{"id":"C","text":"The gold_customer_lifetime_sales_summary table will be overwritten by aggregated values calculated from all records in the\nsilver_customer_sales table as a batch job.","rationale":"The batch aggregates replace the target summary.","isCorrect":true},{"id":"D","text":"An incremental job will detect if new rows have been written to the silver_customer_sales table; if new rows are detected, all aggregates will\nbe recalculated and used to overwrite the gold_customer_lifetime_sales_summary table.","rationale":"No incremental source change detection is implemented.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The batch aggregates replace the target summary.","topic":"write","sourceUrl":"https://docs.delta.io/latest/delta-batch.html","sourceTitle":"Table batch reads and writes","sourcePage":95,"images":["questions/204-1.png"],"hasEmbeddedCode":false,"relatedQuestion":78,"practiceEligible":true,"code":"from pyspark.sql import functions as F\n(spark.table(\"silver_customer_sales\")\n .groupBy(\"customer_id\")\n .agg(F.min(\"sale_date\").alias(\"first_transaction_date\"),\n      F.max(\"sale_date\").alias(\"last_transaction_date\"),\n      F.mean(\"sale_total\").alias(\"average_sales\"),\n      F.countDistinct(\"order_id\").alias(\"total_orders\"),\n      F.sum(\"sale_total\").alias(\"lifetime_value\"))\n .write.format(\"delta\").mode(\"overwrite\")\n .saveAsTable(\"gold_customer_lifetime_sales_summary\"))","reviewNote":"Second audit: Corrected the batch writer API to saveAsTable.","reviewRevision":3,"auditModified":true,"original":{"prompt":"The data engineering team maintains the following code:\nAssuming that this code produces logically correct results and the data in the source table has been de-duplicated and validated, which statement\ndescribes what will occur when this code is executed?","options":[{"id":"A","text":"The silver_customer_sales table will be overwritten by aggregated values calculated from all records in the\ngold_customer_lifetime_sales_summary table as a batch job."},{"id":"B","text":"A batch job will update the gold_customer_lifetime_sales_summary table, replacing only those rows that have different values than the\ncurrent version of the table, using customer_id as the primary key."},{"id":"C","text":"The gold_customer_lifetime_sales_summary table will be overwritten by aggregated values calculated from all records in the\nsilver_customer_sales table as a batch job."},{"id":"D","text":"An incremental job will detect if new rows have been written to the silver_customer_sales table; if new rows are detected, all aggregates will\nbe recalculated and used to overwrite the gold_customer_lifetime_sales_summary table."}],"correctAnswers":["C"],"explanation":"The code uses spark.table and batch write.mode('overwrite'). It recomputes all customer aggregates and replaces the gold table; it is not incremental or a reverse write into silver.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":205,"prompt":"The data engineering team is migrating an enterprise system with thousands of tables and views into the Lakehouse. They plan to implement the\ntarget architecture using a series of bronze, silver, and gold tables. Bronze tables will almost exclusively be used by production data engineering\nworkloads, while silver tables will be used to support both data engineering and machine learning workloads. Gold tables will largely serve\nbusiness intelligence and reporting purposes. While personal identifying information (PII) exists in all tiers of data, pseudonymization and\nanonymization rules are in place for all data at the silver and gold levels.\nThe organization is interested in reducing security concerns while maximizing the ability to collaborate across diverse teams.\nWhich statement exemplifies best practices for implementing this system?","options":[{"id":"A","text":"Isolating tables in separate databases based on data quality tiers allows for easy permissions management through database ACLs and\nallows physical separation of default storage locations for managed tables.","rationale":"Tier-specific schemas simplify grants and managed storage separation.","isCorrect":true},{"id":"B","text":"Because databases on Databricks are merely a logical construct, choices around database organization do not impact security or\ndiscoverability in the Lakehouse.","rationale":"Schema organization does affect governance and discovery.","isCorrect":false},{"id":"C","text":"Storing all production tables in a single database provides a unified view of all data assets available throughout the Lakehouse, simplifying\ndiscoverability by granting all users view privileges on this database.","rationale":"Broad access in one schema weakens the required isolation.","isCorrect":false},{"id":"D","text":"Working in the default Databricks database provides the greatest security when working with managed tables, as these will be created in\nthe DBFS root.","rationale":"The default database is not inherently most secure.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Tier-specific schemas simplify grants and managed storage separation.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":96,"images":["questions/205-1.png"],"hasEmbeddedCode":false,"relatedQuestion":33,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":206,"prompt":"The data architect has mandated that all tables in the Lakehouse should be configured as external (also known as \"unmanaged\") Delta Lake\ntables.\nWhich approach will ensure that this requirement is met?","options":[{"id":"A","text":"When a database is being created, make sure that the LOCATION keyword is used.","rationale":"A schema location does not establish external table ownership semantics.","isCorrect":false},{"id":"B","text":"When the workspace is being configured, make sure that external cloud object storage has been mounted.","rationale":"Mounting a path does not make every table external.","isCorrect":false},{"id":"C","text":"Create each registered Delta table with CREATE TABLE ... USING DELTA LOCATION '<approved-external-path>' (or an equivalent saveAsTable with an explicit path).","rationale":"The explicit table path registers external Delta storage.","isCorrect":true},{"id":"D","text":"When tables are created, make sure that the UNMANAGED keyword is used in the CREATE TABLE statement.","rationale":"The EXTERNAL keyword alone lacks a required location.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The explicit table path registers external Delta storage.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":96,"images":["questions/206-1.png"],"hasEmbeddedCode":false,"relatedQuestion":79,"original":{"id":206,"prompt":"The data architect has mandated that all tables in the Lakehouse should be configured as external (also known as \"unmanaged\") Delta Lake\ntables.\nWhich approach will ensure that this requirement is met?","options":[{"id":"A","text":"When a database is being created, make sure that the LOCATION keyword is used."},{"id":"B","text":"When the workspace is being configured, make sure that external cloud object storage has been mounted."},{"id":"C","text":"When data is saved to a table, make sure that a full file path is specified alongside the USING DELTA clause."},{"id":"D","text":"When tables are created, make sure that the UNMANAGED keyword is used in the CREATE TABLE statement."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"A path-backed Delta write used to register an external table is the intended answer. A full path alone writes files, so table registration must also be explicit. Database LOCATION or mounting storage does not make every table external.","topic":"external","sourceUrl":"https://docs.databricks.com/aws/en/tables/external","sourceTitle":"Work with external tables | Databricks on AWS","sourcePage":96,"images":["questions/206-1.png"],"hasEmbeddedCode":false,"relatedQuestion":79},"reviewRevision":2,"reviewNote":"Made the table-level external location explicit; a file write by itself does not register a table.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":207,"prompt":"To reduce storage and compute costs, the data engineering team has been tasked with curating a series of aggregate tables leveraged by\nbusiness intelligence dashboards, customer-facing applications, production machine learning models, and ad hoc analytical queries.\nThe data engineering team has been made aware of new requirements from a customer-facing application, which is the only downstream\nworkload they manage entirely. As a result, an aggregate table used by numerous teams across the organization will need to have a number of\nfields renamed, and additional fields will also be added.\nWhich of the solutions addresses the situation while minimally interrupting other teams in the organization without increasing the number of\ntables that need to be managed?","options":[{"id":"A","text":"Send all users notice that the schema for the table will be changing; include in the communication the logic necessary to revert the new\ntable schema to match historic queries.","rationale":"Notification alone breaks existing consumers at cutover.","isCorrect":false},{"id":"B","text":"Configure a new table with all the requisite fields and new names and use this as the source for the customer-facing application; create a\nview that maintains the original data schema and table name by aliasing select fields from the new table.","rationale":"A compatibility view preserves old names with one physical table.","isCorrect":true},{"id":"C","text":"Create a new table with the required schema and new fields and use Delta Lake's deep clone functionality to sync up changes committed to\none table to the corresponding table.","rationale":"Deep clones are independent snapshots, not automatic bidirectional sync.","isCorrect":false},{"id":"D","text":"Replace the current table definition with a logical view defined with the query logic currently writing the aggregate table; create a new table\nto power the customer-facing application.","rationale":"Recomputing original aggregation through a view increases ongoing compute.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"A compatibility view preserves old names with one physical table.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":97,"images":["questions/207-1.png"],"hasEmbeddedCode":false,"relatedQuestion":35,"original":{"id":207,"prompt":"To reduce storage and compute costs, the data engineering team has been tasked with curating a series of aggregate tables leveraged by\nbusiness intelligence dashboards, customer-facing applications, production machine learning models, and ad hoc analytical queries.\nThe data engineering team has been made aware of new requirements from a customer-facing application, which is the only downstream\nworkload they manage entirely. As a result, an aggregate table used by numerous teams across the organization will need to have a number of\nfields renamed, and additional fields will also be added.\nWhich of the solutions addresses the situation while minimally interrupting other teams in the organization without increasing the number of\ntables that need to be managed?","options":[{"id":"A","text":"Send all users notice that the schema for the table will be changing; include in the communication the logic necessary to revert the new\ntable schema to match historic queries."},{"id":"B","text":"Configure a new table with all the requisite fields and new names and use this as the source for the customer-facing application; create a\nview that maintains the original data schema and table name by aliasing select fields from the new table."},{"id":"C","text":"Create a new table with the required schema and new fields and use Delta Lake's deep clone functionality to sync up changes committed to\none table to the corresponding table."},{"id":"D","text":"Replace the current table definition with a logical view defined with the query logic currently writing the aggregate table; create a new table\nto power the customer-facing application."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Replace the physical table with the new schema and preserve the old contract using a view under the old name. This avoids maintaining two physical tables; deployment must migrate/rename the original table to free its name.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":97,"images":["questions/207-1.png"],"hasEmbeddedCode":false,"relatedQuestion":35},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"The migration retires the old physical table and frees its name for a compatibility view. Count physical tables after cutover.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":208,"prompt":"A Delta Lake table representing metadata about content posts from users has the following schema:\nuser_id LONG, post_text STRING, post_id STRING, longitude FLOAT, latitude FLOAT, post_time TIMESTAMP, date DATE\nBased on the above schema, which column is a good candidate for partitioning the Delta Table?","options":[{"id":"A","text":"post_time","rationale":"A precise timestamp usually creates excessive partition cardinality.","isCorrect":false},{"id":"B","text":"date","rationale":"Date matches the assumed daily volume and filter pattern.","isCorrect":true},{"id":"C","text":"post_id","rationale":"Per-post identifiers create excessive small partitions.","isCorrect":false},{"id":"D","text":"user_id","rationale":"Per-user keys do not match the stated date-filter workload.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"Date matches the assumed daily volume and filter pattern.","topic":"partitioning","sourceUrl":"https://docs.databricks.com/aws/en/tables/partitions","sourceTitle":"When to partition tables on Databricks | Databricks on AWS","sourcePage":97,"images":["questions/208-1.png"],"hasEmbeddedCode":false,"relatedQuestion":109,"original":{"id":208,"prompt":"A Delta Lake table representing metadata about content posts from users has the following schema:\nuser_id LONG, post_text STRING, post_id STRING, longitude FLOAT, latitude FLOAT, post_time TIMESTAMP, date DATE\nBased on the above schema, which column is a good candidate for partitioning the Delta Table?","options":[{"id":"A","text":"post_time"},{"id":"B","text":"date"},{"id":"C","text":"post_id"},{"id":"D","text":"user_id"}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Date is the most suitable traditional partition key among these choices; IDs and precise timestamps risk high cardinality. Partition only when table/partition sizes justify it; liquid clustering is preferred for many current workloads.","topic":"partitioning","sourceUrl":"https://docs.databricks.com/aws/en/tables/partitions","sourceTitle":"When to partition tables on Databricks | Databricks on AWS","sourcePage":97,"images":["questions/208-1.png"],"hasEmbeddedCode":false,"relatedQuestion":109},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Traditional directory partitioning is required and the table is large enough to justify it. Assume substantial daily data, common date filters and manageable date cardinality.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":209,"prompt":"The downstream consumers of a Delta Lake table have been complaining about data quality issues impacting performance in their applications.\nSpecifically, they have complained that invalid latitude and longitude values in the activity_details table have been breaking their ability to use\nother geolocation processes.\nA junior engineer has written the following code to add CHECK constraints to the Delta Lake table:\nA senior engineer has confirmed the above logic is correct and the valid ranges for latitude and longitude are provided, but the code fails when\nexecuted.\nWhich statement explains the cause of this failure?","options":[{"id":"A","text":"The current table schema does not contain the field valid_coordinates; schema evolution will need to be enabled before altering the table to\nadd a constraint.","rationale":"valid_coordinates names a constraint, not a required data column.","isCorrect":false},{"id":"B","text":"The activity_details table already exists; CHECK constraints can only be added during initial table creation.","rationale":"CHECK constraints can be added to existing tables.","isCorrect":false},{"id":"C","text":"The activity_details table already contains records that violate the constraints; all existing data must pass CHECK constraints in order to\nadd them to an existing table.","rationale":"Existing rows must satisfy the new constraint.","isCorrect":true},{"id":"D","text":"The activity_details table already contains records; CHECK constraints can only be added prior to inserting values into a table.","rationale":"Existing valid data does not prevent adding constraints.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Existing rows must satisfy the new constraint.","topic":"constraints","sourceUrl":"https://docs.databricks.com/aws/en/tables/constraints","sourceTitle":"Constraints on Databricks | Databricks on AWS","sourcePage":98,"images":["questions/209-1.png"],"hasEmbeddedCode":true,"relatedQuestion":38,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":210,"prompt":"What is true for Delta Lake?","options":[{"id":"A","text":"Views in the Lakehouse maintain a valid cache of the most recent versions of source tables at all times.","rationale":"Ordinary views do not maintain an automatic data cache.","isCorrect":false},{"id":"B","text":"Primary and foreign key constraints can be leveraged to ensure duplicate values are never entered into a dimension table.","rationale":"Primary and foreign keys are informational, not enforced uniqueness.","isCorrect":false},{"id":"C","text":"Delta Lake automatically collects statistics on the first 32 columns of each table which are leveraged in data skipping based on query\nfilters.","rationale":"The stated traditional configuration covers the first 32 columns.","isCorrect":true},{"id":"D","text":"Z-order can only be applied to numeric values stored in Delta Lake tables.","rationale":"Z-ordering is not limited to numeric columns.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"The stated traditional configuration covers the first 32 columns.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":98,"images":["questions/210-1.png"],"hasEmbeddedCode":false,"relatedQuestion":39,"original":{"id":210,"prompt":"What is true for Delta Lake?","options":[{"id":"A","text":"Views in the Lakehouse maintain a valid cache of the most recent versions of source tables at all times."},{"id":"B","text":"Primary and foreign key constraints can be leveraged to ensure duplicate values are never entered into a dimension table."},{"id":"C","text":"Delta Lake automatically collects statistics on the first 32 columns of each table which are leveraged in data skipping based on query\nfilters."},{"id":"D","text":"Z-order can only be applied to numeric values stored in Delta Lake tables."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"legacy","explanation":"C describes the traditional default statistics coverage. It is not universal today: predictive optimization on Unity Catalog managed tables can choose columns beyond the first 32. Keys are informational, views are not automatic caches, and ZORDER is not numeric-only.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":98,"images":["questions/210-1.png"],"hasEmbeddedCode":false,"relatedQuestion":39},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use a Delta table with the traditional default data-skipping statistics configuration; predictive optimization and custom statistics-column settings are disabled.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":211,"prompt":"The view updates represents an incremental batch of all newly ingested data to be inserted or updated in the customers table.\nThe following logic is used to process these records.\nWhich statement describes this implementation?","options":[{"id":"A","text":"The customers table is implemented as a Type 2 table; old values are overwritten and new customers are appended.","rationale":"Type 2 does not overwrite away the old versions.","isCorrect":false},{"id":"B","text":"The customers table is implemented as a Type 2 table; old values are maintained but marked as no longer current and new values are\ninserted.","rationale":"Old versions remain with current=false and new versions are inserted.","isCorrect":true},{"id":"C","text":"The customers table is implemented as a Type 0 table; all writes are append only with no changes to existing values.","rationale":"Existing rows are updated, so this is not Type 0.","isCorrect":false},{"id":"D","text":"The customers table is implemented as a Type 1 table; old values are overwritten by new values and no history is maintained.","rationale":"History is preserved rather than overwritten in place.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Old versions remain with current=false and new versions are inserted.","topic":"scd","sourceUrl":"https://docs.delta.io/delta-update/","sourceTitle":"Table deletes, updates, and merges | Delta Lake","sourcePage":99,"images":["questions/211-1.png"],"hasEmbeddedCode":false,"relatedQuestion":40,"practiceEligible":true,"code":"MERGE INTO customers AS c\nUSING (\n  SELECT u.customer_id AS merge_key, u.* FROM updates AS u\n  UNION ALL\n  SELECT NULL AS merge_key, u.*\n  FROM updates AS u JOIN customers AS old\n    ON u.customer_id = old.customer_id\n  WHERE old.current = true AND NOT (u.address <=> old.address)\n) AS s\nON c.customer_id = s.merge_key\nWHEN MATCHED AND c.current = true AND NOT (c.address <=> s.address)\n  THEN UPDATE SET current = false, end_date = s.effective_date\nWHEN NOT MATCHED THEN INSERT\n  (customer_id, address, current, effective_date, end_date)\n  VALUES (s.customer_id, s.address, true, s.effective_date, NULL)","studyContext":"updates has at most one change per customer_id in this batch; customers has one current row per existing customer.","reviewNote":"Second audit: Normalized inconsistent merge-key aliases and used null-safe address comparison.","reviewRevision":3,"auditModified":true,"original":{"prompt":"The view updates represents an incremental batch of all newly ingested data to be inserted or updated in the customers table.\nThe following logic is used to process these records.\nWhich statement describes this implementation?","options":[{"id":"A","text":"The customers table is implemented as a Type 2 table; old values are overwritten and new customers are appended."},{"id":"B","text":"The customers table is implemented as a Type 2 table; old values are maintained but marked as no longer current and new values are\ninserted."},{"id":"C","text":"The customers table is implemented as a Type 0 table; all writes are append only with no changes to existing values."},{"id":"D","text":"The customers table is implemented as a Type 1 table; old values are overwritten by new values and no history is maintained."}],"correctAnswers":["B"],"explanation":"The MERGE closes the old current row and inserts a new version with effective dates. That is Type 2 history, rather than overwriting in place or storing an old value in an extra column.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":212,"prompt":"A team of data engineers are adding tables to a DLT pipeline that contain repetitive expectations for many of the same data quality checks. One\nmember of the team suggests reusing these data quality rules across all tables defined for this pipeline.\nWhat approach would allow them to do this?","options":[{"id":"A","text":"Add data quality constraints to tables in this pipeline using an external job with access to pipeline configuration files.","rationale":"External table constraints are not reusable expectation definitions within the pipeline.","isCorrect":false},{"id":"B","text":"Use global Python variables to make expectations visible across DLT notebooks included in the same pipeline.","rationale":"Python globals are not automatically shared across separate pipeline source notebooks.","isCorrect":false},{"id":"C","text":"Maintain data quality rules in a separate Databricks notebook that each DLT notebook or file can import as a library.","rationale":"A Databricks notebook is not an importable Python library module; a proper Python module would be another supported pattern.","isCorrect":false},{"id":"D","text":"Maintain data quality rules in a Delta table outside of this pipeline's target schema, providing the schema name as a pipeline parameter.","rationale":"The pipeline can read reusable rules from a separately maintained Delta configuration table.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The pipeline can read reusable rules from a separately maintained Delta configuration table.","topic":"expectations","sourceUrl":"https://docs.databricks.com/aws/en/ldp/expectation-patterns","sourceTitle":"Expectation recommendations and advanced patterns | Databricks on AWS","sourcePage":99,"images":["questions/212-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":213,"prompt":"The DevOps team has configured a production workload as a collection of notebooks scheduled to run daily using the Jobs UI. A new data\nengineering hire is onboarding to the team and has requested access to one of these notebooks to review the production logic.\nWhat are the maximum notebook permissions that can be granted to the user without allowing accidental changes to production code or data?","options":[{"id":"A","text":"Can manage","rationale":"CAN MANAGE permits more than read-only inspection.","isCorrect":false},{"id":"B","text":"Can edit","rationale":"CAN EDIT permits production-code changes.","isCorrect":false},{"id":"C","text":"Can run","rationale":"CAN RUN can execute code that modifies data.","isCorrect":false},{"id":"D","text":"Can read","rationale":"CAN READ permits inspection without edit or execution rights.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"CAN READ permits inspection without edit or execution rights.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":100,"images":["questions/213-1.png"],"hasEmbeddedCode":false,"relatedQuestion":41,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":214,"prompt":"A table named user_ltv is being used to create a view that will be used by data analysts on various teams. Users in the workspace are configured\ninto groups, which are used for setting up data access using ACLs.\nThe user_ltv table has the following schema:\nemail STRING, age INT, ltv INT\nThe following view definition is executed:\nAn analyst who is not a member of the marketing group executes the following query:\nSELECT * FROM email_ltv -\nWhich statement describes the results returned by this query?","options":[{"id":"A","text":"Three columns will be returned, but one column will be named \"REDACTED\" and contain only null values.","rationale":"The alias remains email and values are strings, not nulls.","isCorrect":false},{"id":"B","text":"Only the email and ltv columns will be returned; the email column will contain all null values.","rationale":"The CASE returns REDACTED, not null.","isCorrect":false},{"id":"C","text":"The email and ltv columns will be returned with the values in user_ltv.","rationale":"Nonmarketing users do not receive raw emails.","isCorrect":false},{"id":"D","text":"Only the email and ltv columns will be returned; the email column will contain the string \"REDACTED\" in each row.","rationale":"The view selects email and ltv and masks email with REDACTED.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The view selects email and ltv and masks email with REDACTED.","topic":"dynamicviews","sourceUrl":"https://docs.databricks.com/aws/en/views/dynamic","sourceTitle":"Create a dynamic view | Databricks on AWS","sourcePage":100,"images":["questions/214-1.png"],"hasEmbeddedCode":true,"relatedQuestion":42,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":215,"prompt":"The data governance team has instituted a requirement that all tables containing Personal Identifiable Information (PII) must be clearly\nannotated. This includes adding column comments, table comments, and setting the custom table property \"contains_pii\" = true.\nThe following SQL DDL statement is executed to create a new table:\nWhich command allows manual confirmation that these three requirements have been met?","options":[{"id":"A","text":"DESCRIBE EXTENDED dev.pii_test","rationale":"Extended describe includes columns, comments and table properties.","isCorrect":true},{"id":"B","text":"DESCRIBE DETAIL dev.pii_test","rationale":"Detail omits the required per-column comments.","isCorrect":false},{"id":"C","text":"SHOW TBLPROPERTIES dev.pii_test","rationale":"Table properties alone omit column and table comments.","isCorrect":false},{"id":"D","text":"DESCRIBE HISTORY dev.pii_test","rationale":"History lists operations, not the full current column definition.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Extended describe includes columns, comments and table properties.","topic":"describe","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-aux-describe-table","sourceTitle":"DESCRIBE TABLE | Databricks on AWS","sourcePage":101,"images":["questions/215-1.png"],"hasEmbeddedCode":true,"relatedQuestion":43,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":216,"prompt":"The data governance team is reviewing code used for deleting records for compliance with GDPR. They note the following logic is used to delete\nrecords from the Delta Lake table named users.\nAssuming that user_id is a unique identifying key and that delete_requests contains all users that have requested deletion, which statement\ndescribes whether successfully executing the above logic guarantees that the records to be deleted are no longer accessible and why?","options":[{"id":"A","text":"Yes; Delta Lake ACID guarantees provide assurance that the DELETE command succeeded fully and permanently purged these records.","rationale":"ACID changes the current snapshot; it does not purge history.","isCorrect":false},{"id":"B","text":"No; files containing deleted records may still be accessible with time travel until a VACUUM command is used to remove invalidated data\nfiles.","rationale":"Retained historical files remain accessible until eligible physical cleanup.","isCorrect":true},{"id":"C","text":"Yes; the Delta cache immediately updates to reflect the latest data files recorded to disk.","rationale":"Cache refresh does not prove physical removal of old files.","isCorrect":false},{"id":"D","text":"No; the Delta Lake DELETE command only provides ACID guarantees when combined with the MERGE INTO command.","rationale":"DELETE is independently transactional without MERGE.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Retained historical files remain accessible until eligible physical cleanup.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":101,"images":["questions/216-1.png"],"hasEmbeddedCode":true,"relatedQuestion":44,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":217,"prompt":"The data architect has decided that once data has been ingested from external sources into the\nDatabricks Lakehouse, table access controls will be leveraged to manage permissions for all production tables and views.\nThe following logic was executed to grant privileges for interactive queries on a production database to the core engineering group.\nGRANT USAGE ON DATABASE prod TO eng;\nGRANT SELECT ON DATABASE prod TO eng;\nAssuming these are the only privileges that have been granted to the eng group and that these users are not workspace administrators, which\nstatement describes their privileges?","options":[{"id":"A","text":"Group members are able to create, query, and modify all tables and views in the prod database, but cannot define custom functions.","rationale":"No CREATE or MODIFY privileges were granted.","isCorrect":false},{"id":"B","text":"Group members are able to list all tables in the prod database but are not able to see the results of any queries on those tables.","rationale":"SELECT permits reading table data.","isCorrect":false},{"id":"C","text":"Group members are able to query and modify all tables and views in the prod database, but cannot create new tables or views.","rationale":"No modification privilege was granted.","isCorrect":false},{"id":"D","text":"Group members are able to query all tables and views in the prod database, but cannot create or edit anything in the database.","rationale":"The grants allow querying without creating or modifying objects.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"The grants allow querying without creating or modifying objects.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":102,"images":["questions/217-1.png"],"hasEmbeddedCode":false,"relatedQuestion":84,"original":{"id":217,"prompt":"The data architect has decided that once data has been ingested from external sources into the\nDatabricks Lakehouse, table access controls will be leveraged to manage permissions for all production tables and views.\nThe following logic was executed to grant privileges for interactive queries on a production database to the core engineering group.\nGRANT USAGE ON DATABASE prod TO eng;\nGRANT SELECT ON DATABASE prod TO eng;\nAssuming these are the only privileges that have been granted to the eng group and that these users are not workspace administrators, which\nstatement describes their privileges?","options":[{"id":"A","text":"Group members are able to create, query, and modify all tables and views in the prod database, but cannot define custom functions."},{"id":"B","text":"Group members are able to list all tables in the prod database but are not able to see the results of any queries on those tables."},{"id":"C","text":"Group members are able to query and modify all tables and views in the prod database, but cannot create new tables or views."},{"id":"D","text":"Group members are able to query all tables and views in the prod database, but cannot create or edit anything in the database."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"Under the stated Hive-metastore ACL model, USAGE plus SELECT permits reading database tables/views without CREATE or MODIFY. It does not grant permission administration.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":102,"images":["questions/217-1.png"],"hasEmbeddedCode":false,"relatedQuestion":84},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use legacy Hive-metastore table access controls with only the grants stated in the question.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":218,"prompt":"A user wants to use DLT expectations to validate that a derived table report contains all records from the source, included in the table\nvalidation_copy.\nThe user attempts and fails to accomplish this by adding an expectation to the report table definition.\nWhich approach would allow using DLT expectations to validate all expected records are present in this table?","options":[{"id":"A","text":"Define a temporary table that performs a left outer join on validation_copy and report, and define an expectation that no report key values\nare null","rationale":"The left join retains all expected keys and exposes missing matches as NULL for the expectation.","isCorrect":true},{"id":"B","text":"Define a SQL UDF that performs a left outer join on two tables, and check if this returns null values for report key values in a DLT\nexpectation for the report table","rationale":"An expectation on existing report rows cannot detect source rows absent from that report through this UDF pattern.","isCorrect":false},{"id":"C","text":"Define a view that performs a left outer join on validation_copy and report, and reference this view in DLT expectations for the report table","rationale":"Referencing a separate view from a report-row expectation is not the required row-level validation design.","isCorrect":false},{"id":"D","text":"Define a function that performs a left outer join on validation_copy and report, and check against the result in a DLT expectation for the\nreport table","rationale":"A function comparison on existing report rows does not expose absent expected rows to the expectation.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"The left join retains all expected keys and exposes missing matches as NULL for the expectation.","topic":"expectations","sourceUrl":"https://docs.databricks.com/aws/en/ldp/expectation-patterns","sourceTitle":"Expectation recommendations and advanced patterns | Databricks on AWS","sourcePage":102,"images":["questions/218-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A user wants to use DLT expectations to validate that a derived table report contains all records from the source, included in the table\nvalidation_copy.\nThe user attempts and fails to accomplish this by adding an expectation to the report table definition.\nWhich approach would allow using DLT expectations to validate all expected records are present in this table?","options":[{"id":"A","text":"Define a temporary table that performs a left outer join on validation_copy and report, and define an expectation that no report key values\nare null"},{"id":"B","text":"Define a SQL UDF that performs a left outer join on two tables, and check if this returns null values for report key values in a DLT\nexpectation for the report table"},{"id":"C","text":"Define a view that performs a left outer join on validation_copy and report, and reference this view in DLT expectations for the report table"},{"id":"D","text":"Define a function that performs a left outer join on validation_copy and report, and check against the result in a DLT expectation for the\nreport table"}],"correctAnswers":["A"],"explanation":"Build a validation dataset by left-joining expected source keys to report keys, then apply a row-level expectation that the report key exists. Expectations cannot directly use a cross-table subquery to enforce global completeness.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"studyContext":"Both tables use non-NULL record keys. The requirement is that every expected key exists; duplicate multiplicity is a separate check.","reviewNote":"Second audit: Clarified that the validation tests key membership.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":219,"prompt":"A user new to Databricks is trying to troubleshoot long execution times for some pipeline logic they are working on. Presently, the user is\nexecuting code cell-by-cell, using display() calls to confirm code is producing the logically correct results as new transformations are added to an\noperation. To get a measure of average time to execute, the user is running each cell multiple times interactively.\nWhich of the following adjustments will get a more accurate measure of how code is likely to perform in production?","options":[{"id":"A","text":"The Jobs UI should be leveraged to occasionally run the notebook as a job and track execution time during incremental code development\nbecause Photon can only be enabled on clusters launched for scheduled jobs.","rationale":"Photon is not limited to scheduled-job compute.","isCorrect":false},{"id":"B","text":"The only way to meaningfully troubleshoot code execution times in development notebooks Is to use production-sized data and production-\nsized clusters with Run All execution.","rationale":"Production-scale runs are useful but not the only diagnostic technique.","isCorrect":false},{"id":"C","text":"Production code development should only be done using an IDE; executing code against a local build of open source Spark and Delta Lake\nwill provide the most accurate benchmarks for how code will perform in production.","rationale":"A local Spark environment need not reproduce Databricks performance.","isCorrect":false},{"id":"D","text":"Benchmark the production write without intermediate display actions, and measure cold and warm-cache runs separately so repeated execution does not hide costs.","rationale":"Use production-like actions and distinguish cold from warm-cache runs.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Use production-like actions and distinguish cold from warm-cache runs.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":103,"images":["questions/219-1.png"],"hasEmbeddedCode":false,"relatedQuestion":49,"practiceEligible":true,"reviewNote":"Second audit: Replaced an overly absolute caching claim with a concrete repeatable benchmarking procedure.","reviewRevision":3,"auditModified":true,"original":{"prompt":"A user new to Databricks is trying to troubleshoot long execution times for some pipeline logic they are working on. Presently, the user is\nexecuting code cell-by-cell, using display() calls to confirm code is producing the logically correct results as new transformations are added to an\noperation. To get a measure of average time to execute, the user is running each cell multiple times interactively.\nWhich of the following adjustments will get a more accurate measure of how code is likely to perform in production?","options":[{"id":"A","text":"The Jobs UI should be leveraged to occasionally run the notebook as a job and track execution time during incremental code development\nbecause Photon can only be enabled on clusters launched for scheduled jobs."},{"id":"B","text":"The only way to meaningfully troubleshoot code execution times in development notebooks is to use production-sized data and production-\nsized clusters with Run All execution."},{"id":"C","text":"Production code development should only be done using an IDE; executing code against a local build of open source Spark and Delta Lake\nwill provide the most accurate benchmarks for how code will perform in production."},{"id":"D","text":"Calling display() forces a job to trigger, while many transformations will only add to the logical query plan; because of caching, repeated\nexecution of the same logic does not provide meaningful results."}],"correctAnswers":["D"],"explanation":"display triggers execution and interactive reruns may reuse cached data. Those measurements can differ from a production run; PySpark, notebooks and all-purpose Photon compute are not intrinsically invalid for development.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":220,"prompt":"Where in the Spark UI can one diagnose a performance problem induced by not leveraging predicate push-down?","options":[{"id":"A","text":"In the Executor’s log file, by grepping for \"predicate push-down\"","rationale":"Searching logs for a phrase is not direct plan inspection.","isCorrect":false},{"id":"B","text":"In the Stage’s Detail screen, in the Completed Stages table, by noting the size of data read from the Input column","rationale":"Input size can suggest inefficiency but does not show pushdown decisions.","isCorrect":false},{"id":"C","text":"In the Query Detail screen, by interpreting the Physical Plan","rationale":"The physical plan exposes scan filters and pushed predicates.","isCorrect":true},{"id":"D","text":"In the Delta Lake transaction log. by noting the column statistics","rationale":"Table statistics do not show the executed query plan.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"The physical plan exposes scan filters and pushed predicates.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":103,"images":["questions/220-1.png"],"hasEmbeddedCode":false,"relatedQuestion":51,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":221,"prompt":"A data engineer needs to capture pipeline settings from an existing setting in the workspace, and use them to create and version a JSON file to\ncreate a new pipeline.\nWhich command should the data engineer enter in a web terminal configured with the Databricks CLI?","options":[{"id":"A","text":"Use list pipelines to get the specs for all pipelines; get the pipeline spec from the returned results; parse and use this to create a pipeline","rationale":"The list response is a summary, not the complete pipeline specification needed here.","isCorrect":false},{"id":"B","text":"Stop the existing pipeline; use the returned settings in a reset command","rationale":"Stopping a pipeline does not return a reusable specification or clone it through reset.","isCorrect":false},{"id":"C","text":"Run databricks pipelines get PIPELINE_ID --output json; extract the spec object, remove source identity fields, set the new name and target locations, version that JSON, then run databricks pipelines create --json @pipeline.json.","rationale":"Get the pipeline, extract its specification, adjust identity and destinations, then create from that JSON.","isCorrect":true},{"id":"D","text":"Use the clone command to create a copy of an existing pipeline; use the get JSON command to get the pipeline definition; save this to git","rationale":"The specified clone/get JSON sequence is not the documented pipeline CLI workflow.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Get the pipeline, extract its specification, adjust identity and destinations, then create from that JSON.","topic":"pipelinecli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/pipelines-commands","sourceTitle":"pipelines command group | Databricks on AWS","sourcePage":103,"images":["questions/221-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer needs to capture pipeline settings from an existing setting in the workspace, and use them to create and version a JSON file to\ncreate a new pipeline.\nWhich command should the data engineer enter in a web terminal configured with the Databricks CLI?","options":[{"id":"A","text":"Use list pipelines to get the specs for all pipelines; get the pipeline spec from the returned results; parse and use this to create a pipeline"},{"id":"B","text":"Stop the existing pipeline; use the returned settings in a reset command"},{"id":"C","text":"Use the get command to capture the settings for the existing pipeline; remove the pipeline_id and rename the pipeline; use this in a create\ncommand"},{"id":"D","text":"Use the clone command to create a copy of an existing pipeline; use the get JSON command to get the pipeline definition; save this to git"}],"correctAnswers":["C"],"explanation":"Get the existing pipeline, extract its specification and remove generated identity fields, then create the renamed pipeline from that specification. Listing is not a full export and stopping/resetting does not clone a definition.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Clarified extracting the actual pipeline spec rather than submitting the whole response.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":222,"prompt":"Which Python variable contains a list of directories to be searched when trying to locate required modules?","options":[{"id":"A","text":"importlib.resource_path","rationale":"This is not Python's module search-path variable.","isCorrect":false},{"id":"B","text":"sys.path","rationale":"sys.path contains module search directories.","isCorrect":true},{"id":"C","text":"os.path","rationale":"os.path provides path operations, not the import search list.","isCorrect":false},{"id":"D","text":"pypi.path","rationale":"This is not the standard module search variable.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"sys.path contains module search directories.","topic":"python","sourceUrl":"https://docs.python.org/3/tutorial/modules.html","sourceTitle":"6. Modules — Python 3.14.8 documentation","sourcePage":104,"images":["questions/222-1.png"],"hasEmbeddedCode":false,"relatedQuestion":54,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":223,"prompt":"You are testing a collection of mathematical functions, one of which calculates the area under a curve as described by another function.\nassert(myIntegrate(lambda x: x*x, 0, 3) [0] == 9)\nWhich kind of test would the above line exemplify?","options":[{"id":"A","text":"Unit","rationale":"The assertion checks one mathematical function in isolation.","isCorrect":true},{"id":"B","text":"Manual","rationale":"It is a programmatic assertion, not necessarily manual testing.","isCorrect":false},{"id":"C","text":"Functional","rationale":"The isolated-function scope is more specifically unit testing.","isCorrect":false},{"id":"D","text":"Integration","rationale":"Mathematical integration is not subsystem integration testing.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"The assertion checks one mathematical function in isolation.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":104,"images":["questions/223-1.png"],"hasEmbeddedCode":false,"relatedQuestion":88,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":224,"prompt":"What is a key benefit of an end-to-end test?","options":[{"id":"A","text":"It makes it easier to automate your test suite","rationale":"End-to-end tests can be harder, not inherently easier, to automate.","isCorrect":false},{"id":"B","text":"It pinpoints errors in the building blocks of your application","rationale":"Unit tests generally localize component failures more directly.","isCorrect":false},{"id":"C","text":"It provides testing coverage for all code paths and branches","rationale":"End-to-end coverage does not guarantee every branch is exercised.","isCorrect":false},{"id":"D","text":"It closely simulates real world usage of your application","rationale":"The complete workflow approximates user-visible application behavior.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"The complete workflow approximates user-visible application behavior.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":104,"images":["questions/224-1.png"],"hasEmbeddedCode":false,"relatedQuestion":103,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":225,"prompt":"Which REST API call can be used to review the notebooks configured to run as tasks in a multi-task job?","options":[{"id":"A","text":"/jobs/runs/list","rationale":"Lists executions rather than directly fetching the saved job definition.","isCorrect":false},{"id":"B","text":"/jobs/list","rationale":"Enumerates jobs rather than retrieving one by the specified job_id.","isCorrect":false},{"id":"C","text":"/jobs/runs/get","rationale":"Returns a run snapshot, not the dedicated saved-job definition.","isCorrect":false},{"id":"D","text":"/jobs/get","rationale":"Fetches the known job's definition and notebook task settings.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Fetches the known job's definition and notebook task settings.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/job","sourceTitle":"Jobs API: get a single job","sourcePage":104,"images":["questions/225-1.png"],"hasEmbeddedCode":false,"relatedQuestion":57,"original":{"id":225,"prompt":"Which REST API call can be used to review the notebooks configured to run as tasks in a multi-task job?","options":[{"id":"A","text":"/jobs/runs/list"},{"id":"B","text":"/jobs/list"},{"id":"C","text":"/jobs/runs/get"},{"id":"D","text":"/jobs/get"}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"best_fit","explanation":"jobs/get retrieves a particular job definition and its task notebook paths. Run endpoints describe executions. Some current jobs/list responses can also include task settings, so D is the most direct answer, not the only possible endpoint in all API versions.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":104,"images":["questions/225-1.png"],"hasEmbeddedCode":false,"relatedQuestion":57},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"The job_id is known. Choose the dedicated endpoint for retrieving one saved job definition, rather than enumerating jobs or inspecting an execution.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":226,"prompt":"A Data Engineer wants to run unit tests using common Python testing frameworks on Python functions defined across several Databricks\nnotebooks currently used in production.\nHow can the data engineer run unit tests against functions that work with data in production?","options":[{"id":"A","text":"Define and import unit test functions from a separate Databricks notebook","rationale":"Where tests are defined does not isolate their production reads and writes.","isCorrect":false},{"id":"B","text":"Define and unit test functions using Files in Repos","rationale":"Files in Git help organization, but do not themselves isolate test data.","isCorrect":false},{"id":"C","text":"Run unit tests against non-production data that closely mirrors production","rationale":"Representative non-production fixtures let tests exercise writes safely and repeatably.","isCorrect":true},{"id":"D","text":"Define unit tests and functions within the same notebook","rationale":"Putting tests in the same notebook does not prevent production data changes.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Representative non-production fixtures let tests exercise writes safely and repeatably.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":105,"images":["questions/226-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":226,"prompt":"A Data Engineer wants to run unit tests using common Python testing frameworks on Python functions defined across several Databricks\nnotebooks currently used in production.\nHow can the data engineer run unit tests against functions that work with data in production?","options":[{"id":"A","text":"Define and import unit test functions from a separate Databricks notebook"},{"id":"B","text":"Define and unit test functions using Files in Repos"},{"id":"C","text":"Run unit tests against non-production data that closely mirrors production"},{"id":"D","text":"Define unit tests and functions within the same notebook"}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"Use isolated non-production data that closely mirrors production, especially for functions that write or delete. Importable files and notebook-based tests can both organize the code, so B helps modularity but does not establish safe test data. The wording mixes these concerns; C best addresses production isolation.","topic":"testing","sourceUrl":"https://docs.databricks.com/aws/en/notebooks/testing","sourceTitle":"Unit testing for Databricks notebooks","sourcePage":105,"images":["questions/226-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Choose the testing-data strategy that safely isolates production data, including functions that write or delete; code organization is a separate decision.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":227,"prompt":"A data engineer wants to refactor the following DLT code, which includes multiple table definitions with very similar code.\nIn an attempt to programmatically create these tables using a parameterized table definition, the data engineer writes the following code.\nThe pipeline runs an update with this refactored code, but generates a different DAG showing incorrect configuration values for these tables.\nHow can the data engineer fix this?","options":[{"id":"A","text":"Wrap the for loop inside another table definition, using generalized names and properties to replace with those from the inner table\ndefinition.","rationale":"Nesting the loop in another table definition does not bind each iteration's values correctly.","isCorrect":false},{"id":"B","text":"Convert the list of configuration values to a dictionary of table settings, using table names as keys.","rationale":"Changing the container to a dictionary does not fix late-bound closures.","isCorrect":false},{"id":"C","text":"Move the table definition into a separate function, and make calls to this function using different input parameters inside the for loop.","rationale":"A factory function binds each table's parameters in its own function scope.","isCorrect":true},{"id":"D","text":"Load the configuration values for these tables from a separate file, located at a path provided by a pipeline parameter.","rationale":"An external configuration file does not fix closure capture in the table definitions.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"A factory function binds each table's parameters in its own function scope.","topic":"ldpcode","sourceUrl":"https://docs.databricks.com/aws/en/ldp/developer/python-dev","sourceTitle":"Develop pipeline code with Python | Databricks on AWS","sourcePage":105,"images":["questions/227-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":228,"prompt":"A data engineer has created a 'transactions' Delta table on Databricks that should be used by the analytics team. The analytics team wants to use\nthe table with another tool which requires Apache Iceberg format.\nWhat should the data engineer do?","options":[{"id":"A","text":"Require the analytics team to use a tool which supports Delta table.","rationale":"Changing the consuming tool does not meet the specified interoperability requirement.","isCorrect":false},{"id":"B","text":"Create an Iceberg copy of the 'transactions' Delta table which can be used by the analytics team.","rationale":"A second data copy violates the single-copy requirement and introduces synchronization work.","isCorrect":false},{"id":"C","text":"Convert the 'transactions' Delta to Iceberg and enable uniform so that the table can be read as a Delta table.","rationale":"UniForm exposes Delta data to Iceberg readers; this is not a reverse conversion workflow.","isCorrect":false},{"id":"D","text":"Enable uniform on the transactions table to 'iceberg' so that the table can be read as an Iceberg table.","rationale":"UniForm generates Iceberg-compatible metadata over the Delta table's data files for supported readers.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"UniForm generates Iceberg-compatible metadata over the Delta table's data files for supported readers.","topic":"uniform","sourceUrl":"https://docs.databricks.com/aws/en/delta/iceberg-reads","sourceTitle":"Read Delta Lake tables with Iceberg clients | Databricks on AWS","sourcePage":106,"images":["questions/228-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer has created a 'transactions' Delta table on Databricks that should be used by the analytics team. The analytics team wants to use\nthe table with another tool which requires Apache Iceberg format.\nWhat should the data engineer do?","options":[{"id":"A","text":"Require the analytics team to use a tool which supports Delta table."},{"id":"B","text":"Create an Iceberg copy of the 'transactions' Delta table which can be used by the analytics team."},{"id":"C","text":"Convert the 'transactions' Delta to Iceberg and enable uniform so that the table can be read as a Delta table."},{"id":"D","text":"Enable uniform on the transactions table to 'iceberg' so that the table can be read as an Iceberg table."}],"correctAnswers":["D"],"explanation":"Enable UniForm/Iceberg reads on the Delta table to generate compatible Iceberg metadata over its data. This does not require duplicating the table or converting the source away from Delta.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Keep one authoritative Delta data copy and make it available to a supported Iceberg reader; creating a second synchronized copy is not allowed. The table meets UniForm requirements.","reviewNote":"Second audit: A second Iceberg copy would otherwise also satisfy broad tool compatibility.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":229,"prompt":"A junior data engineer is working to implement logic for a Lakehouse table named silver_device_recordings. The source data contains 100 unique\nfields in a highly nested JSON structure.\nThe silver_device_recordings table will be used downstream for highly selective joins on a number of fields, and will also be leveraged by the\nmachine learning team to filter on a handful of relevant fields. In total, 15 fields have been identified that will often be used for filter and join logic.\nThe data engineer is trying to determine the best approach for dealing with these nested fields before declaring the table schema.\nWhich of the following accurately presents information about Delta Lake and Databricks that may impact their decision-making process?","options":[{"id":"A","text":"Because Delta Lake uses Parquet for data storage, Dremel encoding information for nesting can be directly referenced by the Delta\ntransaction log.","rationale":"Parquet nesting encoding is not a substitute for Delta file-level skipping statistics.","isCorrect":false},{"id":"B","text":"Schema inference and evolution on Databricks ensure that inferred types will always accurately match the data types used by downstream\nsystems.","rationale":"Schema inference cannot guarantee every downstream system's intended data types.","isCorrect":false},{"id":"C","text":"The Tungsten encoding used by Databricks is optimized for storing string data; newly-added native support for querying JSON strings\nmeans that string types are always most efficient.","rationale":"Strings are not universally the most efficient representation for typed analytical fields.","isCorrect":false},{"id":"D","text":"By default, Delta Lake collects statistics on the first 32 columns in a table; these statistics are leveraged for data skipping when executing\nselective queries.","rationale":"Under the specified traditional default, statistics cover the first 32 columns; nested leaf fields count individually.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Under the specified traditional default, statistics cover the first 32 columns; nested leaf fields count individually.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":106,"images":["questions/229-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":229,"prompt":"A junior data engineer is working to implement logic for a Lakehouse table named silver_device_recordings. The source data contains 100 unique\nfields in a highly nested JSON structure.\nThe silver_device_recordings table will be used downstream for highly selective joins on a number of fields, and will also be leveraged by the\nmachine learning team to filter on a handful of relevant fields. In total, 15 fields have been identified that will often be used for filter and join logic.\nThe data engineer is trying to determine the best approach for dealing with these nested fields before declaring the table schema.\nWhich of the following accurately presents information about Delta Lake and Databricks that may impact their decision-making process?","options":[{"id":"A","text":"Because Delta Lake uses Parquet for data storage, Dremel encoding information for nesting can be directly referenced by the Delta\ntransaction log."},{"id":"B","text":"Schema inference and evolution on Databricks ensure that inferred types will always accurately match the data types used by downstream\nsystems."},{"id":"C","text":"The Tungsten encoding used by Databricks is optimized for storing string data; newly-added native support for querying JSON strings\nmeans that string types are always most efficient."},{"id":"D","text":"By default, Delta Lake collects statistics on the first 32 columns in a table; these statistics are leveraged for data skipping when executing\nselective queries."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"legacy","explanation":"Traditional first-32-column statistics coverage motivates placing frequently filtered fields within coverage or configuring statistics columns. Predictive optimization changes this default for UC managed tables. Inference does not guarantee downstream types and strings are not universally faster.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":106,"images":["questions/229-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use a Delta table with the traditional default data-skipping statistics configuration; predictive optimization and custom statistics-column settings are disabled.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":230,"prompt":"A platform engineer is creating catalogs and schemas for the development team to use.\nThe engineer has created an initial catalog, Catalog_A, and initial schema, Schema_A. The engineer has also granted USE CATALOG, USE\nSCHEMA, and CREATE TABLE to the development team so that the engineer can begin populating the schema with new tables.\nDespite being owner of the catalog and schema, the engineer noticed that they do not have access to the underlying tables in Schema_A.\nWhat explains the engineer's lack of access to the underlying tables?","options":[{"id":"A","text":"The owner of the schema does not automatically have permission to tables within the schema, but can grant them to themselves at any\npoint.","rationale":"Parent ownership permits managing/granting child privileges, but does not automatically grant SELECT on every child table.","isCorrect":true},{"id":"B","text":"Users granted with USE CATALOG can modify the owner's permissions to downstream tables.","rationale":"USE CATALOG allows namespace usage, not arbitrary permission changes.","isCorrect":false},{"id":"C","text":"Permissions explicitly given by the table creator are the only way the Platform Engineer could access the underlying tables in their schema.","rationale":"The parent owner can grant required child privileges without relying exclusively on the table creator.","isCorrect":false},{"id":"D","text":"The platform engineer needs to execute a REFRESH statement as the table permissions did not automatically update for owners.","rationale":"REFRESH does not grant privileges.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Parent ownership permits managing/granting child privileges, but does not automatically grant SELECT on every child table.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":107,"images":["questions/230-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":231,"prompt":"A data engineer has created a new cluster using shared access mode with default configurations. The data engineer needs to allow the\ndevelopment team access to view the driver logs if needed.\nWhat are the minimal cluster permissions that allow the development team to accomplish this?","options":[{"id":"A","text":"CAN VIEW","rationale":"CAN VIEW is not the cluster ACL that grants these restricted driver logs.","isCorrect":false},{"id":"B","text":"CAN RESTART","rationale":"Restart permission alone does not include default restricted driver-log access.","isCorrect":false},{"id":"C","text":"CAN ATTACH TO","rationale":"Attach permission alone does not include default restricted driver-log access.","isCorrect":false},{"id":"D","text":"CAN MANAGE","rationale":"Under the stated default log ACL, CAN MANAGE is the minimum listed cluster permission.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Under the stated default log ACL, CAN MANAGE is the minimum listed cluster permission.","topic":"compute","sourceUrl":"https://docs.databricks.com/aws/en/compute/clusters-manage","sourceTitle":"Manage classic compute | Databricks on AWS","sourcePage":107,"images":["questions/231-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer has created a new cluster using shared access mode with default configurations. The data engineer needs to allow the\ndevelopment team access to view the driver logs if needed.\nWhat are the minimal cluster permissions that allow the development team to accomplish this?","options":[{"id":"A","text":"CAN VIEW"},{"id":"B","text":"CAN RESTART"},{"id":"C","text":"CAN ATTACH TO"},{"id":"D","text":"CAN MANAGE"}],"correctAnswers":["D"],"explanation":"With the default driver-log access restriction on this compute, CAN MANAGE is required. Lower permissions require an explicit configuration change to allow log viewing.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Use standard (formerly shared) classic compute with default restricted driver-log ACLs; spark.databricks.acl.needAdminPermissionToViewLogs is true.","reviewNote":"Second audit: The minimum permission depends on the driver-log ACL setting.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":232,"prompt":"A data engineer wants to create a cluster using the Databricks CLI for a big ETL pipeline. The cluster should have five workers and one driver of\ntype i3.xlarge and should use the '14.3.x-scala2.12' runtime.\nWhich command should the data engineer use?","options":[{"id":"A","text":"databricks compute add 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --cluster-name Data Engineer_cluster","rationale":"The CLI command group is clusters, not compute add.","isCorrect":false},{"id":"B","text":"databricks clusters create 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --driver-node-type-id i3.xlarge --cluster-name 'Data Engineer_cluster'","rationale":"clusters create accepts the runtime and worker, driver and naming options shown.","isCorrect":true},{"id":"C","text":"databricks compute create 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --cluster-name Data Engineer_cluster","rationale":"compute create is not this Databricks CLI cluster command.","isCorrect":false},{"id":"D","text":"databricks clusters add 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --cluster-name Data Engineer_cluster","rationale":"clusters add is not the cluster creation command.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"clusters create accepts the runtime and worker, driver and naming options shown.","topic":"clustercli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/clusters-commands","sourceTitle":"clusters command group | Databricks on AWS","sourcePage":107,"images":["questions/232-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":232,"prompt":"A data engineer wants to create a cluster using the Databricks CLI for a big ETL pipeline. The cluster should have five workers and one driver of\ntype i3.xlarge and should use the '14.3.x-scala2.12' runtime.\nWhich command should the data engineer use?","options":[{"id":"A","text":"databricks compute add 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --cluster-name Data Engineer_cluster"},{"id":"B","text":"databricks clusters create 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --cluster-name Data Engineer_cluster"},{"id":"C","text":"databricks compute create 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --cluster-name Data Engineer_cluster"},{"id":"D","text":"databricks clusters add 14.3.x-scala2.12 --num-workers 5 --node-type-id i3.xlarge --cluster-name Data Engineer_cluster"}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"clusters create is the correct CLI command group and verb with the shown runtime and worker options. The multiword cluster name must be quoted, for example --cluster-name 'Data Engineer_cluster'; the printed command is not exact runnable shell syntax.","topic":"clustercli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/clusters-commands","sourceTitle":"clusters command group | Databricks on AWS","sourcePage":107,"images":["questions/232-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Quoted the multiword cluster name and made the driver type explicit.","studyContext":"Assume the specified runtime and AWS node type are available in this workspace and allowed by policy.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":233,"prompt":"An existing liquid-clustered transactions table uses product_id, user_id and event_date. Assume each batch write below meets the required clustering-on-write threshold. Structured Streaming eager clustering is disabled. Which operation will not cluster data as part of its write in this configuration?","options":[{"id":"A","text":"CREATE TABLE AS SELECT and REPLACE TABLE AS SELECT, with clustering specified.","rationale":"Eligible batch CTAS/RTAS writes support clustering on write.","isCorrect":false},{"id":"B","text":"df.writeStream.format(\"delta\").outputMode(\"append\").option(\"checkpointLocation\", checkpoint).toTable(\"transactions\")","rationale":"With eager streaming clustering disabled, this streaming write does not perform clustering on write.","isCorrect":true},{"id":"C","text":"df.write.format(\"delta\").mode(\"append\").saveAsTable(\"transactions\")","rationale":"A sufficiently large batch append supports clustering on write.","isCorrect":false},{"id":"D","text":"INSERT INTO transactions SELECT ...","rationale":"An eligible INSERT INTO supports clustering on write.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"With eager streaming clustering disabled, this streaming write does not perform clustering on write.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":108,"images":["questions/233-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":233,"prompt":"A 'transactions' table has been liquid clustered on the columns 'product_id’, ’user_id' and 'event_date'.\nWhich operation lacks support for cluster on write?","options":[{"id":"A","text":"CTAS and RTAS statements"},{"id":"B","text":"spark.writeStream.format(’delta').mode(’append’)"},{"id":"C","text":"spark.write.format('delta’).mode('append')"},{"id":"D","text":"INSERT INTO operations"}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"legacy","explanation":"Older liquid-clustering support excluded streaming writes from clustering on write, making B the historical answer. Current runtimes support additional streaming behavior. The printed writeStream.mode('append') is also not valid streaming output-mode syntax.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":108,"images":["questions/233-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Used valid DataFrame writer syntax and made streaming eager clustering configuration explicit.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":234,"prompt":"The data governance team has instituted a requirement that the \"user\" table containing Personal Identifiable Information (PII) must have the\nappropriate masking on the SSN column. This means that anyone outside of the HRAdminGroup should see masked social security numbers as\n***-**-****.\nThe team created a masking function:\nWhat does the data governance team need to do next to achieve this goal?","options":[{"id":"A","text":"CREATE TABLE users\n(name STRING);\nALTER TABLE users CREATE COLUMN ssn CREATE MASK ssn_mask;","rationale":"CREATE COLUMN ... CREATE MASK is not the supported ALTER TABLE syntax.","isCorrect":false},{"id":"B","text":"CREATE TABLE users\n(name STRING, int STRING);\nALTER TABLE users ALTER COLUMN ssn CREATE MASK if is_member('HRAdminGroup');","rationale":"This is not a valid column mask clause and the table lacks the named ssn column.","isCorrect":false},{"id":"C","text":"CREATE TABLE users\n(name STRING, ssn INT MASKED ssn_mask);","rationale":"MASKED is not the supported function-binding syntax in this declaration.","isCorrect":false},{"id":"D","text":"CREATE TABLE users\n(name STRING, ssn STRING);\nALTER TABLE users ALTER COLUMN ssn SET MASK ssn_mask;","rationale":"SET MASK attaches the SQL masking function to the existing STRING column.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"SET MASK attaches the SQL masking function to the existing STRING column.","topic":"masks","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Row filters and column masks | Databricks on AWS","sourcePage":108,"images":["questions/234-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"The data governance team has instituted a requirement that the \"user\" table containing Personal Identifiable Information (PII) must have the\nappropriate masking on the SSN column. This means that anyone outside of the HRAdminGroup should see masked social security numbers as\n***-**-****.\nThe team created a masking function:\nWhat does the data governance team need to do next to achieve this goal?","options":[{"id":"A","text":"CREATE TABLE users -\n(name STRING);\nALTER TABLE users CREATE COLUMN ssn CREATE MASK ssn_mask;"},{"id":"B","text":"CREATE TABLE users -\n(name STRING, int STRING);\nALTER TABLE users ALTER COLUMN ssn CREATE MASK if is_member('HRAdminGroup');"},{"id":"C","text":"CREATE TABLE users -\n(name STRING, ssn INT MASKED ssn_mask);"},{"id":"D","text":"CREATE TABLE users -\n(name STRING, ssn STRING);\nALTER TABLE users ALTER COLUMN ssn SET MASK ssn_mask;"}],"correctAnswers":["D"],"explanation":"Create the string column and attach the masking function with ALTER TABLE ... ALTER COLUMN ssn SET MASK ssn_mask. The other choices use nonexistent clauses or omit the required column.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"CREATE FUNCTION ssn_mask(ssn STRING)\nRETURN CASE WHEN is_account_group_member('HRAdminGroup')\n  THEN ssn ELSE '***-**-****' END;","reviewNote":"Second audit: Corrected the mask function and removed malformed punctuation from the table declarations.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":235,"prompt":"A data engineer needs to create an application that will collect information about the latest job run including the repair history.\nHow should the data engineer format the request?","options":[{"id":"A","text":"Call/api/2.1/jobs/runs/list with the run_id and include_history parameters","rationale":"The list endpoint is not the run-id detail request with repair history.","isCorrect":false},{"id":"B","text":"Call/api/2.1/jobs/runs/get with the run_id and include_history parameters","rationale":"The get endpoint accepts the known run_id and include_history to return repair attempts.","isCorrect":true},{"id":"C","text":"Call/api/2.1/jobs/runs/get with the job_id and include_history parameters","rationale":"The get-run endpoint identifies a run by run_id, not job_id.","isCorrect":false},{"id":"D","text":"Call/api/2.1/jobs/runs/list with the job_id and include_history parameters","rationale":"Listing a job's runs is not the detailed get-run history request.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"The get endpoint accepts the known run_id and include_history to return repair attempts.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":108,"images":["questions/235-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer needs to create an application that will collect information about the latest job run including the repair history.\nHow should the data engineer format the request?","options":[{"id":"A","text":"Call/api/2.1/jobs/runs/list with the run_id and include_history parameters"},{"id":"B","text":"Call/api/2.1/jobs/runs/get with the run_id and include_history parameters"},{"id":"C","text":"Call/api/2.1/jobs/runs/get with the job_id and include_history parameters"},{"id":"D","text":"Call/api/2.1/jobs/runs/list with the job_id and include_history parameters"}],"correctAnswers":["B"],"explanation":"jobs/runs/get takes a run_id and include_history=true to include repair history. First discover the latest run if needed; job_id belongs to job/run-list queries rather than selecting one run with get.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The application has already used the run listing to determine the latest run_id; now it needs that run and its repair history.","reviewNote":"Second audit: Get-run requires a known run ID.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":236,"prompt":"A data engineer is working in an interactive notebook with many transformations before outputting the result from display(df.collect() ). The\nnotebook includes wide transformations and a cross join.\nThe data engineer is getting the following error: \"The spark driver has stopped unexpectedly and is restarting. Your notebook will be automatically\nreattached.\"\nWhich action should the data engineer take?","options":[{"id":"A","text":"Run the notebook on a single node cluster to keep driver from falling.","rationale":"Moving all processing onto one node does not resolve collecting excessive data to the driver.","isCorrect":false},{"id":"B","text":"Rewrite their code to avoid putting memory pressure on the driver node.","rationale":"Avoid collecting the full result; keep processing distributed and limit data brought to the driver.","isCorrect":true},{"id":"C","text":"Check into the Spark UI to see how many jobs are assigned to each stage as they are employing fewer executors.","rationale":"Tasks belong to stages and stages to jobs; this does not address driver memory pressure.","isCorrect":false},{"id":"D","text":"Look at the compute metrics UI to see if the executors have higher than 90% memory utilization.","rationale":"Executor utilization alone does not diagnose the excessive driver collect.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Avoid collecting the full result; keep processing distributed and limit data brought to the driver.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":109,"images":["questions/236-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":237,"prompt":"An analytics team wants run an experiment in the short term on the customer transaction Delta table (with 20 billions records) created by the data\nengineering team in Databricks SQL.\nWhich strategy should the data engineering team use to ensure minimal downtime and no impact on the ongoing ETL processes?","options":[{"id":"A","text":"Deep clone the table for the analytics team.","rationale":"A deep clone copies data and is more expensive than the short-lived copy required.","isCorrect":false},{"id":"B","text":"Create a new table for the analytics team using a CTAS statement.","rationale":"CTAS rewrites the full result and is costly for 20 billion rows.","isCorrect":false},{"id":"C","text":"Shallow clone the table for the analytics team.","rationale":"A shallow clone supplies a separate table definition while reusing source files; retention and separate compute must be arranged.","isCorrect":true},{"id":"D","text":"Give access to the table for the analytics team.","rationale":"Direct access does not provide the required independently writable experiment table.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"A shallow clone supplies a separate table definition while reusing source files; retention and separate compute must be arranged.","topic":"clone","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/clone","sourceTitle":"Clone a table on Databricks | Databricks on AWS","sourcePage":109,"images":["questions/237-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"An analytics team wants run an experiment in the short term on the customer transaction Delta table (with 20 billions records) created by the data\nengineering team in Databricks SQL.\nWhich strategy should the data engineering team use to ensure minimal downtime and no impact on the ongoing ETL processes?","options":[{"id":"A","text":"Deep clone the table for the analytics team."},{"id":"B","text":"Create a new table for the analytics team using a CTAS statement."},{"id":"C","text":"Shallow clone the table for the analytics team."},{"id":"D","text":"Give access to the table for the analytics team."}],"correctAnswers":["C"],"explanation":"A shallow clone creates independent metadata quickly without copying billions of rows. It suits a short-lived sandbox; confirm source retention behavior for the catalog/runtime. Deep clone and CTAS perform expensive data copies.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The experiment needs its own writable table with no full data copy. Use separate compute and a supported shallow-clone configuration; keep referenced source files available for the experiment lifetime.","reviewNote":"Second audit: Clarified why a separate shallow clone is needed instead of direct SELECT access.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":238,"prompt":"A data team is working to optimize an existing large, fast-growing table 'orders' with high cardinality columns, which experiences significant data\nskew and requires frequent concurrent writes. The team notice that the columns 'user_id', 'event_timestamp' and 'product_id' are heavily used in\nanalytical queries and filters, although those keys may be subject to change in the future due to different business requirements.\nWhich partitioning strategy should the team choose to optimize the table for immediate data skipping, incremental management over time, and\nflexibility?","options":[{"id":"A","text":"Partition the table with: ALTER TABLE orders PARTITION BY user_id, product_id, event_timestamp","rationale":"High-cardinality Hive partitions create excessive fragmentation and are not easily changed.","isCorrect":false},{"id":"B","text":"Use z-order after partitiing the table: OPTIMIZE orders ZORDER BY (user_id, product_id) WHERE event_timestamp = current date () - 1 DAY","rationale":"Combining static partitions and Z-order does not offer the same incremental flexibility.","isCorrect":false},{"id":"C","text":"ALTER TABLE orders CLUSTER BY (user_id, product_id, event_timestamp); then run OPTIMIZE orders to cluster existing files.","rationale":"Liquid clustering supports changing keys; OPTIMIZE applies clustering to existing files.","isCorrect":true},{"id":"D","text":"Z-order the table with OPTIMIZE orders ZORDER BY (user_id, product_id, event_timestamp)","rationale":"Z-order can help skipping but requires manual rewrites and is less adaptable to this requirement.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Liquid clustering supports changing keys; OPTIMIZE applies clustering to existing files.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":109,"images":["questions/238-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":238,"prompt":"A data team is working to optimize an existing large, fast-growing table 'orders' with high cardinality columns, which experiences significant data\nskew and requires frequent concurrent writes. The team notice that the columns 'user_id', 'event_timestamp' and 'product_id' are heavily used in\nanalytical queries and filters, although those keys may be subject to change in the future due to different business requirements.\nWhich partitioning strategy should the team choose to optimize the table for immediate data skipping, incremental management over time, and\nflexibility?","options":[{"id":"A","text":"Partition the table with: ALTER TABLE orders PARTITION BY user_id, product_id, event_timestamp"},{"id":"B","text":"Use z-order after partitiing the table: OPTIMIZE orders ZORDER BY (user_id, product_id) WHERE event_timestamp = current date () - 1 DAY"},{"id":"C","text":"Cluster the table with: ALTER TABLE orders CLUSTER BY user_id, product_id, event_timestamp"},{"id":"D","text":"Z-order the table with OPTIMIZE orders ZORDER BY (user_id, product_id, event_timestamp)"}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"Liquid clustering is the intended strategy for high-cardinality evolving keys. Exact syntax is ALTER TABLE orders CLUSTER BY (user_id, product_id, event_timestamp), followed by OPTIMIZE for existing data. The printed option omits parentheses.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":109,"images":["questions/238-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Fixed CLUSTER BY syntax and included optimization of existing data.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":239,"prompt":"A faulty IoT sensor in a factory reports a temperature of -500, causing the LDP pipeline to fail the expectation, which only allows values between\n-100 and 200 degrees Celsius. The data engineer would like to further analyze the faulty data to better understand the reason behind this.\nHow should the data engineer resolve the faulty data while ensuring data quality standards are maintained?","options":[{"id":"A","text":"Remove all expectations form the pipeline to prevent any future failures, regardless of data quality.","rationale":"Removing quality rules abandons the data quality requirement.","isCorrect":false},{"id":"B","text":"Ignore the error and simply re-run the pipeline, as Databricks will automatically skip the problematic record on the next run.","rationale":"Retrying does not automatically repair or skip a record that fails the same expectation.","isCorrect":false},{"id":"C","text":"Fix the pipeline code and implement a quarantine logic to isolate the faulty data before re-running the pipeline.","rationale":"Separate invalid records into quarantine so valid data proceeds under the original quality rules.","isCorrect":true},{"id":"D","text":"Change the expectation action from fail to warn so that invalid records are included in the output and the pipeline does not fail.","rationale":"Widening acceptable temperatures to admit the faulty value defeats the stated quality rule.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Separate invalid records into quarantine so valid data proceeds under the original quality rules.","topic":"expectations","sourceUrl":"https://docs.databricks.com/aws/en/ldp/expectation-patterns","sourceTitle":"Expectation recommendations and advanced patterns | Databricks on AWS","sourcePage":110,"images":["questions/239-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":240,"prompt":"An eligible unpartitioned managed Delta table under 1 TB has skew and changing filter columns. Which layout supports changing declared clustering keys without immediately rewriting the entire table, then incrementally applying layout maintenance?","options":[{"id":"A","text":"Use Hive-style partitioning, as it provides efficient data skipping and is easy to change partition columns at any time.","rationale":"Changing Hive partition columns is not a cheap metadata-only operation.","isCorrect":false},{"id":"B","text":"Combine partitioning and Z-ordering to maximize flexibility and minimize maintenance as query patterns change.","rationale":"Partitioning plus Z-order adds maintenance and does not give the requested key-change behavior.","isCorrect":false},{"id":"C","text":"Use liquid clustering. ALTER TABLE ... CLUSTER BY changes the declared keys without immediately rewriting existing files; subsequent OPTIMIZE operations rewrite data to apply clustering.","rationale":"Changing declared liquid clustering keys is a metadata change; OPTIMIZE later rewrites data to apply the layout.","isCorrect":true},{"id":"D","text":"Apply Z-ordering, since it allows flexible reorganization of data layout without rewriting existing and adapts easily to new filter columns.","rationale":"Physically Z-ordering existing data requires rewriting files.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Changing declared liquid clustering keys is a metadata change; OPTIMIZE later rewrites data to apply the layout.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":110,"images":["questions/240-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is optimizing a managed table that suffers from data skew and frequently changing query filter columns. The engineer needs to\navoid costly data rewrites when query patterns evolve. The table size is under 1TB.\nHow should data engineer meet this requirement?","options":[{"id":"A","text":"Use Hive-style partitioning, as it provides efficient data skipping and is easy to change partition columns at any time."},{"id":"B","text":"Combine partitioning and Z-ordering to maximize flexibility and minimize maintenance as query patterns change."},{"id":"C","text":"Enable liquid clustering, as it efficiently handles data skew, allows clustering keys to be changed without rewriting existing data, and adapts\nto evolving query patterns."},{"id":"D","text":"Apply Z-ordering, since it allows flexible reorganization of data layout without rewriting existing and adapts easily to new filter columns."}],"correctAnswers":["C"],"explanation":"Liquid clustering permits changing keys without immediately rewriting all existing data and suits skew/evolving filters. A later OPTIMIZE applies clustering; changing keys does not instantly reorganize every old file.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Changing keys is metadata-only; physically applying the new layout still rewrites files.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":241,"prompt":"A security team wants to enforce data protection for a customer table containing customer PII data. To comply with local policies, sales team\nmembers should only see customers from their region, while non-admin users should have email addresses masked.\nWhich implementation approach should be used when using Unity Catalog row filters and column masks?","options":[{"id":"A","text":"Create SQL UDFs for row filtering based on user region and column masking based on group membership, then apply them using ALTER\nTABLE SET ROW FILTER and ALTER COLUMN SET MASK commands.","rationale":"SQL UDF-backed row filters and column masks enforce both policies on the base table.","isCorrect":true},{"id":"B","text":"Use table ACLs to restrict access using tags with GRANT SELECT ON table_name WITH TAG command, and rely on application-level filtering\nfor sensitive data based on user region.","rationale":"The proposed WITH TAG grant syntax is not the stated row-filter and column-mask mechanism.","isCorrect":false},{"id":"C","text":"Create a view with dynamic WHERE clauses for region filtering and use string replacement functions for email masking using ALTER\nCOLUMN SET MASK command.","rationale":"A separate view and an unbound replacement expression do not implement both requested base-table policies.","isCorrect":false},{"id":"D","text":"Implement row filters with SQL UDFs based on user region only since column masks cannot be combined with row filters on the same table,\nthen apply them be recreating the table with DROP TABLE and CREATE TABLE SET ROW FILTER commands.","rationale":"Row filters and column masks can coexist; recreating the table is unnecessary.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"SQL UDF-backed row filters and column masks enforce both policies on the base table.","topic":"masks","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Row filters and column masks | Databricks on AWS","sourcePage":110,"images":["questions/241-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":242,"prompt":"A data engineer is evaluating tools to build a production-grade data pipeline. The team must process change data from cloud object storage, filter\nout or isolate invalid records, and ensure the timely delivery of clean data to downstream consumers. The team is small, under tight deadlines,\nand wants to minimize operational overhead while keeping pipelines auditable and maintainable.\nWhich approach should the data engineer implement?","options":[{"id":"A","text":"Ingest data directly into Delta tables via Spark jobs, apply data quality filters using UDFs, and use LDP for creating Materialized Views.","rationale":"This can be built, but splits ingestion and quality logic across more manually maintained components.","isCorrect":false},{"id":"B","text":"Use a hybrid approach: Ingest with Auto Loader into Bronze tables, then process using SQL queries in Databricks Workflows to generate\ncleaned Silver and Gold tables on a schedule.","rationale":"Scheduled custom SQL is viable but adds orchestration and quality-management work.","isCorrect":false},{"id":"C","text":"Implement ingestion using Auto Loader with Structured Streaming, and manage invalid data handling and table updates using\ncheckpointing and merge logic.","rationale":"This is viable but makes the team manage checkpoints, changes and quarantine logic itself.","isCorrect":false},{"id":"D","text":"Use LDP to build declarative pipelines with Streaming Tables and Materialized Views, leveraging built-in support for data expectations and\nincremental processing.","rationale":"Declarative tables, expectations and managed orchestration best fit the minimum-overhead requirement.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Declarative tables, expectations and managed orchestration best fit the minimum-overhead requirement.","topic":"ldp","sourceUrl":"https://docs.databricks.com/aws/en/ldp/","sourceTitle":"Spark Declarative Pipelines | Databricks on AWS","sourcePage":111,"images":["questions/242-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":243,"prompt":"A data engineer is using Structured Streaming to read in transaction data from a bronze Delta table. It was discovered that the data has quality\nissues where sometimes the transaction value is negative, and when that occurs, the rows need to be routed to a separate quarantine table. They\nhave low latency requirements for the good data since it is used by downstream systems, but the bad data will only be analyzed periodically and\nhas no production dependencies. The quarantine job needs to be implemented so that it cannot affect the production processes that depend on\nthe good data, and the cost of the job needs to be minimized.\nHow should the quarantine process be implemented in order to satisfy these requirements?","options":[{"id":"A","text":"The streaming job for the good data needs to be modified to filter out records with a transaction value less than 0 before writing. The\nstreaming job for the quarantine data needs to filter out records with a transaction value greater than or equal to 0 before writing. Both should\nrun as separate streams on the same cluster to minimize cost.","rationale":"Shared compute allows quarantine resource contention to affect production latency.","isCorrect":false},{"id":"B","text":"The existing streaming job for the good data should be updated to incorporate the quarantining of the bad data. A new boolean column\ncalled “quarantine” should be added to the dataframe, and its value should be set to true if the transaction value is less than 0 and false if the\ntransaction value is greater than or equal to 0. Processing and storing all the data together will save costs.","rationale":"One combined stream and table does not isolate the quarantine workload.","isCorrect":false},{"id":"C","text":"The existing streaming job for the good data should be updated to incorporate the quarantining of the bad data. Inside a foreachBatch\nfunction, the dataframe should be filtered so that records with a transaction value greater than or equal to 0 are written to the good data table\nand records with a transaction value less than 0 are written to a quarantine table. Try/Catch can be added around the writes in the\nforeachBatch function so that the stream can’t fail.","rationale":"Two sequential writes share the production failure and latency path; catching exceptions can hide lost quarantine writes.","isCorrect":false},{"id":"D","text":"The streaming job for the good data needs to be modified to filter out records with a transaction value less than 0 before writing, and\nshould not share compute with other processes. The streaming job for the quarantine data needs to filter out records with a transaction value\ngreater than or equal to 0 before writing, and should be implemented on a separate small cluster and only run once a day to minimize cost.","rationale":"Separate compute and a daily incremental quarantine run isolate the low-priority workload and reduce its running time.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Separate compute and a daily incremental quarantine run isolate the low-priority workload and reduce its running time.","topic":"streamprod","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/production","sourceTitle":"Production considerations for Structured Streaming | Databricks on AWS","sourcePage":111,"images":["questions/243-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":244,"prompt":"When monitoring a complex workload, being able to see the query plan is critical to understanding what the workload is doing.\nWhere can the visualization of the query plan be found?","options":[{"id":"A","text":"In the Spart UI, under the Jobs tab","rationale":"The Jobs tab focuses on job execution rather than the SQL query-plan graph.","isCorrect":false},{"id":"B","text":"In the Query Profiler, under Query Source","rationale":"Query Source displays source text rather than the requested Spark plan visualization.","isCorrect":false},{"id":"C","text":"In the Spark UI, under the SQL/DataFrame tab","rationale":"The SQL/DataFrame tab contains query execution details and plan visualization.","isCorrect":true},{"id":"D","text":"In the Query Profiler, under the Stages tab","rationale":"This is not the Spark SQL query-plan location described.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"The SQL/DataFrame tab contains query execution details and plan visualization.","topic":"sparkui","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/","sourceTitle":"Diagnose cost and performance issues using the Spark UI | Databricks on AWS","sourcePage":112,"images":["questions/244-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":245,"prompt":"A data engineer is troubleshooting a slow-running Delta Lake query on Databricks SQL involves complex joins and large datasets. They need to\nidentify whether the root cause is related to poor data skipping, inefficient join strategies, or excessive data shuffling.\nWhich approach should identify the specific bottlenecks using native Databricks tools?","options":[{"id":"A","text":"Analyze the Top Operators panel in the Query Profile to identify high-cost operations like BroadcastNestedLoopJoin","rationale":"Operator runtime metrics expose costly joins, scans and shuffles for targeted investigation.","isCorrect":true},{"id":"B","text":"Check the query’s execution time in the Jobs UI and correlate it with cluster resource utilization metrics.","rationale":"Overall job timing and utilization lack the needed operator-level evidence.","isCorrect":false},{"id":"C","text":"Enable the EXPLAIN command to review the parsed logical plan and manually estimate shuffle sizes.","rationale":"A parsed logical plan does not provide the measured execution bottlenecks.","isCorrect":false},{"id":"D","text":"Use the LIMIT clause to run a subset of the query and compare execution times with the full dataset.","rationale":"LIMIT can change execution and is not a reliable bottleneck diagnosis for the full query.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Operator runtime metrics expose costly joins, scans and shuffles for targeted investigation.","topic":"profile","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/queries/query-profile","sourceTitle":"Query profile | Databricks on AWS","sourcePage":112,"images":["questions/245-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":246,"prompt":"A data engineer is designing a secure data sharing strategy for their organization. The company needs to share sensitive customer analytics data\nwith two different partners. Partner A uses Databricks with Unity Catalog enabled, while Partner B uses Apache Spark on AWS without Databricks.\nHow should the company implement secure data sharing for these scenarios?","options":[{"id":"A","text":"Use Databricks-to-Databricks sharing with Unity Catalog identity for Partner A, without manually distributed provider bearer tokens. Use open sharing with supported bearer-token or OIDC-federated authentication for Partner B.","rationale":"Native UC sharing fits Partner A; open sharing with supported authentication fits the external Spark recipient.","isCorrect":true},{"id":"B","text":"Both partners should use the same Delta Sharing approach since security requirements are identical. You should create bearer tokens for\nboth partners and use the open sharing protocol (D2O) for maximum compatibility.","rationale":"Open sharing can work, but unnecessarily replaces native UC recipient identity for Partner A.","isCorrect":false},{"id":"C","text":"Open sharing protocol (D2O) should be used for both partners because it provides better security than D2D sharing. The bearer token\napproach is always more secure than Unity Catalog’s native authentication.","rationale":"Bearer tokens are not inherently more secure than native UC authentication.","isCorrect":false},{"id":"D","text":"Databricks-to-Databricks sharing (D2D) can only be used within the same cloud provider, so you must use open sharing (D2O) for any cross-\ncloud scenarios. Unit Catalog governance is not available when sharing with external platforms.","rationale":"Databricks-to-Databricks sharing supports cross-cloud recipients.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"Native UC sharing fits Partner A; open sharing with supported authentication fits the external Spark recipient.","topic":"sharing","sourceUrl":"https://docs.databricks.com/aws/en/opensharing","sourceTitle":"What is OpenSharing? | Databricks on AWS","sourcePage":112,"images":["questions/246-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is designing a secure data sharing strategy for their organization. The company needs to share sensitive customer analytics data\nwith two different partners. Partner A uses Databricks with Unity Catalog enabled, while Partner B uses Apache Spark on AWS without Databricks.\nHow should the company implement secure data sharing for these scenarios?","options":[{"id":"A","text":"For Partner A, implement Databricks-to-Databricks sharing (D2D) with Unit Catalog integration and no-token exchange system. For Partner\nB, use open sharing protocol (D2O) with either bearer tokens or OIDC federation for authentication, ensuring both approaches maintain robust\nsecurity and governance."},{"id":"B","text":"Both partners should use the same Delta Sharing approach since security requirements are identical. You should create bearer tokens for\nboth partners and use the open sharing protocol (D2O) for maximum compatibility."},{"id":"C","text":"Open sharing protocol (D2O) should be used for both partners because it provides better security than D2D sharing. The bearer token\napproach is always more secure than Unity Catalog’s native authentication."},{"id":"D","text":"Databricks-to-Databricks sharing (D2D) can only be used within the same cloud provider, so you must use open sharing (D2O) for any cross-\ncloud scenarios. Unit Catalog governance is not available when sharing with external platforms."}],"correctAnswers":["A"],"explanation":"Use native Databricks-to-Databricks sharing for a UC recipient and open sharing authentication for a non-Databricks recipient. D2D works across clouds and avoids recipient token-file exchange.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Native sharing does not require recipients to manage provider bearer tokens; it is not literally token-free.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":247,"prompt":"Assume imports, df, test_input and expected are defined correctly. Which snippet explicitly calls DataFrame.transform with a reusable function and also asserts the transformed test output?","options":[{"id":"A","text":"class Pipeline:\n    def transform(self, df):\n        return df.withColumn(\"value_upper\", upper(col(\"value\")))\nassertDataFrameEqual(Pipeline().transform(test_input), expected)","rationale":"This tests a class method but does not invoke DataFrame.transform.","isCorrect":false},{"id":"B","text":"def transform_data(df):\n    return df.withColumn(\"value_upper\", upper(col(\"value\")))\nassertDataFrameEqual(transform_data(test_input), expected)","rationale":"This tests a function directly rather than through DataFrame.transform.","isCorrect":false},{"id":"C","text":"def upper_transform(df):\n    return df.withColumn(\"value_upper\", upper(col(\"value\")))\nactual = test_input.transform(upper_transform)\nassertDataFrameEqual(actual, expected)","rationale":"It passes the reusable function to DataFrame.transform and asserts the result.","isCorrect":true},{"id":"D","text":"def upper_value(df):\n    return df.withColumn(\"value_upper\", upper(col(\"value\")))\ndef filter_positive(df):\n    return df.filter(df[\"id\"] > 0)\npipeline_df = df.transform(upper_value).transform(filter_positive)","rationale":"It uses transform composition but contains no output assertion.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"It passes the reusable function to DataFrame.transform and asserts the result.","topic":"transform","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.transform.html","sourceTitle":"pyspark.sql.DataFrame.transform — PySpark 4.2.0 documentation","sourcePage":113,"images":["questions/247-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":247,"prompt":"Which approach demonstrates a modular and testable way to use DataFrame transform for ETL code in PySpark?","options":[{"id":"A","text":"[Code choice shown in the original PDF image]"},{"id":"B","text":"[Code choice shown in the original PDF image]"},{"id":"C","text":"[Code choice shown in the original PDF image]"},{"id":"D","text":"[Code choice shown in the original PDF image]"}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"C explicitly applies DataFrame.transform to a reusable function and verifies its output. D also demonstrates valid modular transform composition if its line wrapping is corrected, so it is not intrinsically untestable. C most directly demonstrates both the API and a test.","topic":"transform","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.transform.html","sourceTitle":"pyspark.sql.DataFrame.transform — PySpark 4.2.0 documentation","sourcePage":113,"images":["questions/247-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Narrowed the question to the explicit transform API plus an output assertion; all code choices were transcribed.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":248,"prompt":"A company stores account transactions in a Delta Lake table. The company needs to apply frequent account-level correlations (e.g., UPDATE\nstatements) but wants to avoid rewriting entire Parquet files for each change to reduce file churn and improve write performance.\nWhich Delta Lake feature should they enable?","options":[{"id":"A","text":"Enable automatic file compaction on writes","rationale":"Compaction combines small files and does not avoid row-change rewrites in the requested way.","isCorrect":false},{"id":"B","text":"Enable change data feed on the Delta table","rationale":"CDF records changes for consumers; it is not the file-rewrite optimization.","isCorrect":false},{"id":"C","text":"Partition the Delta table by account_id","rationale":"High-cardinality partitioning does not provide deletion-vector behavior.","isCorrect":false},{"id":"D","text":"Enable deletion vectors on the Delta table","rationale":"Deletion vectors let supported row-level operations mark old rows without immediately rewriting their Parquet files.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Deletion vectors let supported row-level operations mark old rows without immediately rewriting their Parquet files.","topic":"dv","sourceUrl":"https://docs.databricks.com/aws/en/tables/features/deletion-vectors","sourceTitle":"Deletion vectors in Databricks","sourcePage":113,"images":["questions/248-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A company stores account transactions in a Delta Lake table. The company needs to apply frequent account-level correlations (e.g., UPDATE\nstatements) but wants to avoid rewriting entire Parquet files for each change to reduce file churn and improve write performance.\nWhich Delta Lake feature should they enable?","options":[{"id":"A","text":"Enable automatic file compaction on writes"},{"id":"B","text":"Enable change data feed on the Delta table"},{"id":"C","text":"Partition the Delta table by account_id"},{"id":"D","text":"Enable deletion vectors on the Delta table"}],"correctAnswers":["D"],"explanation":"Deletion vectors record changed/deleted row positions without rewriting every affected Parquet file immediately. Compaction and CDF serve different purposes; high-cardinality partitioning does not provide this mechanism.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Use an eligible Delta table and Databricks Runtime 14.3 LTS or later supporting deletion vectors for UPDATE.","reviewNote":"Second audit: Deletion-vector support depends on runtime and operation.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":249,"prompt":"A bundle declares resources.apps.databricks_app_deployed and resources.volumes.volume_deployed. The app service principal already has USE CATALOG and USE SCHEMA on the parent objects. Which grant on volume_deployed gives that app identity both read and write access?","options":[{"id":"A","text":"grants:\n  - principal: ${resources.apps.databricks_app_deployed.service_principal_client_id}\n    privileges: [READ_VOLUME, WRITE_VOLUME]","rationale":"It grants both privileges to the deployed app's service principal client ID.","isCorrect":true},{"id":"B","text":"Grant READ_VOLUME only to ${resources.apps.databricks_app_deployed.service_principal_client_id}.","rationale":"READ_VOLUME alone cannot write volume files.","isCorrect":false},{"id":"C","text":"Grant READ_VOLUME and WRITE_VOLUME using ${resources.app.databricks_app_deployed.id} as the principal.","rationale":"The resource reference is wrong and the app object ID is not the required service principal identity.","isCorrect":false},{"id":"D","text":"Grant READ_VOLUME and WRITE_VOLUME to the user who deploys the bundle, without granting the app identity access.","rationale":"Granting the deploying human does not grant the app service principal access.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"It grants both privileges to the deployed app's service principal client ID.","topic":"appresources","sourceUrl":"https://github.com/databricks/cli/blob/main/acceptance/bundle/refschema/out.fields.txt","sourceTitle":"Databricks CLI bundle schema: app service principal and volume grants","sourcePage":114,"images":["questions/249-1.png","questions/249-2.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":249,"prompt":"In a Databricks Asset Bundle project, in the file resources/app.yml, the data engineer would like to deploy a Databricks Apps\ndatabricks_app_deployed and Volume volume_deployed and grant the Service Principal behind Databricks Apps permissions to READ and WRITE\nto the Volume.\nHow should the data engineer achieve the deployment?","options":[{"id":"A","text":"[Code choice shown in the original PDF image]"},{"id":"B","text":"[Code choice shown in the original PDF image]"},{"id":"C","text":"[Code choice shown in the original PDF image]"},{"id":"D","text":"[Code choice shown in the original PDF image]"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["A"],"status":"review","explanation":"A is the likely intended outline, but every shown substitution uses resources.app and an app id rather than the app service principal. Use resources.apps.<key>.service_principal_client_id for a principal grant, with READ_VOLUME/WRITE_VOLUME and required parent USE privileges. None is fully correct as printed.","topic":"appresources","sourceUrl":"https://github.com/databricks/cli/blob/main/acceptance/bundle/refschema/out.fields.txt","sourceTitle":"Databricks CLI bundle resource schema","sourcePage":114,"images":["questions/249-1.png","questions/249-2.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected the bundle resource substitution and principal identity. Replaced the image-only choices with readable equivalent configurations.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":250,"prompt":"A data engineering teams needs to implement a tagging system for their tables as part of an automated ETL process, and needs to apply tags\nprogrammatically to tables in Unity Catalog.\nWhich SQL command adds tags to a table programmatically?","options":[{"id":"A","text":"ALTER TABLE table_name SET TAGS ('key1' = 'value1', 'key2' = 'value2');","rationale":"ALTER TABLE ... SET TAGS assigns the specified table tags.","isCorrect":true},{"id":"B","text":"APPLY TAGS ON table_name VALUES ('key1' = 'value1', 'key2' = 'value2')","rationale":"APPLY TAGS ON ... VALUES is not this SQL syntax.","isCorrect":false},{"id":"C","text":"COMMENT ON TABLE table_name TAGS ('key1' = 'value1', 'key2' = 'value2')","rationale":"COMMENT ON TABLE does not accept this TAGS clause.","isCorrect":false},{"id":"D","text":"SET TAGS FOR table_name AS ('key1' = 'value1', 'key2' = 'value2')","rationale":"SET TAGS FOR ... AS is not this SQL syntax.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"ALTER TABLE ... SET TAGS assigns the specified table tags.","topic":"tags","sourceUrl":"https://docs.databricks.com/aws/en/database-objects/tags","sourceTitle":"Apply tags to Unity Catalog securable objects | Databricks on AWS","sourcePage":115,"images":["questions/250-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineering teams needs to implement a tagging system for their tables as part of an automated ETL process, and needs to apply tags\nprogrammatically to tables in Unity Catalog.\nWhich SQL command adds tags to a table programmatically?","options":[{"id":"A","text":"ALTER TABLE table_name SET TAGS (‘key1’ = ‘value1’, ‘key2’ = ‘value2’);"},{"id":"B","text":"APPLY TAGS ON table_name VALUES (‘key1’ = ‘value1’, ‘key2’ = ‘value2’)"},{"id":"C","text":"COMMENT ON TABLE table_name TAGS (‘key1’ = ‘value1’, ‘key2’ = ‘value2’)"},{"id":"D","text":"SET TAGS FOR table_name AS (‘key1’ = ‘value1’, ‘key2’ = ‘value2’)"}],"correctAnswers":["A"],"explanation":"ALTER TABLE ... SET TAGS ('key' = 'value') is valid tagging syntax. The other statements are not valid alternatives for setting Unity Catalog tags.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Normalized typographic quotes to valid SQL literals.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":251,"prompt":"Using system.billing.usage across available workspaces, which query returns daily DBU consumption by SKU? Include signed correction records; do not mix DBUs with other usage units.","options":[{"id":"A","text":"SELECT usage_date, sku_name, SUM(dbus) AS daily_dbus FROM system.billing.usage WHERE usage_unit = 'DBU' GROUP BY usage_date, sku_name","rationale":"The billing usage table does not expose a dbus column for this SUM.","isCorrect":false},{"id":"B","text":"SELECT usage_date, sku_name, COUNT(usage_quantity) AS daily_dbus FROM system.billing.usage WHERE usage_unit = 'DBU' GROUP BY usage_date, sku_name","rationale":"COUNT counts records rather than summing consumption quantities.","isCorrect":false},{"id":"C","text":"SELECT usage_date, sku_name, SUM(usage_quantity) AS daily_dbus FROM system.billing.usage WHERE usage_unit = 'DBU' GROUP BY usage_date, sku_name ORDER BY usage_date, sku_name","rationale":"Filtering to DBU units and summing signed quantities by usage_date and SKU gives daily DBU totals, including corrections.","isCorrect":true},{"id":"D","text":"SELECT usage_date, sku_name, SUM(usage_quantity) AS daily_dbus FROM system.billing.usage WHERE usage_unit = 'DBU' GROUP BY usage_date ORDER BY usage_date","rationale":"Selecting SKU without grouping or aggregating it is invalid and would not give per-SKU totals.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Filtering to DBU units and summing signed quantities by usage_date and SKU gives daily DBU totals, including corrections.","topic":"billing","sourceUrl":"https://docs.databricks.com/aws/en/admin/system-tables/billing","sourceTitle":"Billable usage system table reference","sourcePage":116,"images":["questions/251-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A platform engineer needs to report the resource consumption, categorized by SKU tier, across all workspaces. The engineer decides to use the\nsystem.billing.usage system table to create a query.\nWhich SQL query will accurately return the daily usage by product?","options":[{"id":"A","text":"[Code choice shown in the original PDF image]"},{"id":"B","text":"[Code choice shown in the original PDF image]"},{"id":"C","text":"[Code choice shown in the original PDF image]"},{"id":"D","text":"[Code choice shown in the original PDF image]"}],"correctAnswers":["C"],"explanation":"Sum usage_quantity and group by both date and sku_name. A references a nonexistent dbus column; B counts rows; D omits sku_name from GROUP BY. Filter/group by usage_unit when combining different billing units.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"","reviewNote":"Second audit: Usage quantities have units; explicitly report DBUs, group by usage date and SKU, and include signed corrections.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":252,"prompt":"A data engineer is running a groupBy aggregation on a massive user activity log grouped by user_id. A few users have millions of records, causing\ntask skew and long runtimes.\nWhich technique will fix the skew in this aggregation?","options":[{"id":"A","text":"Increase the Spark driver memory and retry.","rationale":"More driver memory does not distribute an oversized executor aggregation key.","isCorrect":false},{"id":"B","text":"Filter out the skewed users before the aggregation","rationale":"Discarding heavy users changes the required result.","isCorrect":false},{"id":"C","text":"Use salting by adding a random prefix to skewed keys before aggregation, then aggregate again after removing the prefix.","rationale":"For a decomposable aggregate, salted partial groups and a final combine can distribute heavy keys without losing data.","isCorrect":true},{"id":"D","text":"Use reduceByKey instead of groupBy to avoid shuffles.","rationale":"reduceByKey still shuffles; replacing the API does not inherently eliminate skew or all exchanges.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"For a decomposable aggregate, salted partial groups and a final combine can distribute heavy keys without losing data.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":117,"images":["questions/252-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is running a groupBy aggregation on a massive user activity log grouped by user_id. A few users have millions of records, causing\ntask skew and long runtimes.\nWhich technique will fix the skew in this aggregation?","options":[{"id":"A","text":"Increase the Spark driver memory and retry."},{"id":"B","text":"Filter out the skewed users before the aggregation"},{"id":"C","text":"Use salting by adding a random prefix to skewed keys before aggregation, then aggregate again after removing the prefix."},{"id":"D","text":"Use reduceByKey instead of groupBy to avoid shuffles."}],"correctAnswers":["C"],"explanation":"Salt hot keys, aggregate partials, then combine them by the original key using an appropriate mergeable aggregation. Driver memory does not fix skewed executor tasks; dropping users loses data and reduceByKey still shuffles.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The aggregate is SUM of event values (a decomposable aggregate). Measured oversized heavy-key groups remain the bottleneck after normal partial aggregation; preserve every user.","reviewNote":"Second audit: Salting requires an aggregate that can be correctly combined from partial results.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":253,"prompt":"A job runs four independent tasks (X, Y, Z, W) in parallel to process regional sales data. The Data Engineering team recently updated its cluster\npolicy to ban cost-prohibitive instance types. Task Y now fails due to the newly enforced cluster policy restricting the use of a specific instance\ntype. A data engineer needs to resolve the failure quickly without disrupting the other tasks.\nHow should the data engineer resolve the failure of tasks?","options":[{"id":"A","text":"Delete the failed run, disable the cluster policy, and re-execute all tasks.","rationale":"Deleting the run and disabling policy discards recovery information and violates the policy.","isCorrect":false},{"id":"B","text":"Manually create a new cluster for Task Y, update the job configuration, and trigger a full re-run.","rationale":"A complete rerun repeats independent tasks that already succeeded.","isCorrect":false},{"id":"C","text":"Update Task Y to use policy-compliant compute, then use Repair run to rerun Y while retaining the successful results of the independent tasks.","rationale":"Policy-compliant compute plus Repair reruns the failed work while retaining independent successes.","isCorrect":true},{"id":"D","text":"Edit the global cluster policy to allow the restricted instance type, then re-run the entire job.","rationale":"Weakening the global policy is unnecessary and affects unrelated workloads.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Policy-compliant compute plus Repair reruns the failed work while retaining independent successes.","topic":"repair","sourceUrl":"https://docs.databricks.com/aws/en/jobs/repair-job-failures","sourceTitle":"Troubleshoot and repair job failures | Databricks on AWS","sourcePage":117,"images":["questions/253-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":253,"prompt":"A job runs four independent tasks (X, Y, Z, W) in parallel to process regional sales data. The Data Engineering team recently updated its cluster\npolicy to ban cost-prohibitive instance types. Task Y now fails due to the newly enforced cluster policy restricting the use of a specific instance\ntype. A data engineer needs to resolve the failure quickly without disrupting the other tasks.\nHow should the data engineer resolve the failure of tasks?","options":[{"id":"A","text":"Delete the failed run, disable the cluster policy, and re-execute all tasks."},{"id":"B","text":"Manually create a new cluster for Task Y, update the job configuration, and trigger a full re-run."},{"id":"C","text":"Use “Repair run”, override the cluster configuration for Task Y to use a permitted instance type, and let Databricks re-run only Task Y."},{"id":"D","text":"Edit the global cluster policy to allow the restricted instance type, then re-run the entire job."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"Repair only the failed task using a compliant compute configuration; update the job/task's compute settings before repair as needed. Do not weaken global policy or repeat successful independent tasks.","topic":"repair","sourceUrl":"https://docs.databricks.com/aws/en/jobs/repair-job-failures","sourceTitle":"Troubleshoot and repair job failures | Databricks on AWS","sourcePage":117,"images":["questions/253-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Clarified that job compute settings are updated before repairing the failed task.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":254,"prompt":"A data engineer is analyzing a large, partitioned retail dataset in Databricks, where each row represents a sale made by a salesperson. The\ndataset contains millions of records with the following schema:\nsales_df: [salesperson_id: string, region: string, sale_amount: double, sale_date: date]\nThe data engineer needs to generate a DataFrame that ranks salespeople within each region based on their total cumulative sales, with the\nhighest seller ranked as 1. If multiple salespeople have the same total sales, they should share the same rank.\nThe data engineer wants to implement this logic using a PySpark window function and the dense_rank () function.\nWhich code snippet will perform this ranking?","options":[{"id":"A","text":"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\nw = Window.partitionBy(\"region\").orderBy(F.desc(\"sale_amount\"))\nranked_df = sales_df.withColumn(\"rank\", F.dense_rank().over(w))","rationale":"It ranks individual sales rather than each salesperson's total.","isCorrect":false},{"id":"B","text":"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\nagg_df = sales_df.groupBy(\"salesperson_id\", \"region\").agg(F.sum(\"sale_amount\").alias(\"total_sales\"))\nw = Window.partitionBy(\"region\").orderBy(F.desc(\"total_sales\"))\nranked_df = agg_df.withColumn(\"rank\", F.rank().over(w))","rationale":"rank can leave gaps after ties, while the question explicitly requires dense_rank.","isCorrect":false},{"id":"C","text":"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\nagg_df = sales_df.groupBy(\"salesperson_id\", \"region\").agg(F.sum(\"sale_amount\").alias(\"total_sales\"))\nw = Window.orderBy(F.desc(\"total_sales\"))\nranked_df = agg_df.withColumn(\"rank\", F.dense_rank().over(w))","rationale":"Without partitioning the window by region, it ranks across all regions.","isCorrect":false},{"id":"D","text":"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\nagg_df = sales_df.groupBy(\"salesperson_id\", \"region\").agg(F.sum(\"sale_amount\").alias(\"total_sales\"))\nw = Window.partitionBy(\"region\").orderBy(F.desc(\"total_sales\"))\nranked_df = agg_df.withColumn(\"rank\", F.dense_rank().over(w))","rationale":"Aggregate per salesperson and region, then dense-rank totals descending within each region.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Aggregate per salesperson and region, then dense-rank totals descending within each region.","topic":"window","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/window.html","sourceTitle":"Window — PySpark 4.2.0 documentation","sourcePage":118,"images":["questions/254-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is analyzing a large, partitioned retail dataset in Databricks, where each row represents a sale made by a salesperson. The\ndataset contains millions of records with the following schema:\nsales_df: [salesperson_id: string, region: string, sale_amount: double, sale_date: date]\nThe data engineer needs to generate a DataFrame that ranks salespeople within each region based on their total cumulative sales, with the\nhighest seller ranked as 1. If multiple salespeople have the same total sales, they should share the same rank.\nThe data engineer wants to implement this logic using a PySpark window function and the dense_rank () function.\nWhich code snippet will perform this ranking?","options":[{"id":"A","text":"[Code choice shown in the original PDF image]"},{"id":"B","text":"[Code choice shown in the original PDF image]"},{"id":"C","text":"[Code choice shown in the original PDF image]"},{"id":"D","text":"[Code choice shown in the original PDF image]"}],"correctAnswers":["D"],"explanation":"Aggregate total sales per salesperson and region first, then dense_rank over each region ordered by descending total. A ranks individual sales; B uses rank rather than dense_rank; C omits the regional window partition.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"","reviewNote":"Second audit: Corrected misspelled PySpark methods in the intended answer and transcribed all four choices.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":255,"prompt":"What describes a primary technical challenge in ensuring consistent PII masking across all nodes in large-scale, distributed Databricks batch and\nstreaming pipelines?","options":[{"id":"A","text":"PII masking is only required for direct identifiers.","rationale":"Indirect identifiers and combinations can also be sensitive under the defined policy.","isCorrect":false},{"id":"B","text":"Dynamic data masking is applied only at rest, so it does not affect query performance.","rationale":"Dynamic masks run at query time and can affect query performance.","isCorrect":false},{"id":"C","text":"Masking functions must be standardized and managed through Unity Catalog, with enforcement applied across all relevant datasets to\navoid any data inconsistency.","rationale":"Consistent governed functions and dataset coverage prevent divergent masking implementations.","isCorrect":true},{"id":"D","text":"Native masking in Databricks automatically synchronizes with all downstream external Databricks systems.","rationale":"External downstream copies do not automatically inherit every Databricks masking policy.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Consistent governed functions and dataset coverage prevent divergent masking implementations.","topic":"masks","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Row filters and column masks | Databricks on AWS","sourcePage":119,"images":["questions/255-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"What describes a primary technical challenge in ensuring consistent PII masking across all nodes in large-scale, distributed Databricks batch and\nstreaming pipelines?","options":[{"id":"A","text":"PII masking is only required for direct identifiers."},{"id":"B","text":"Dynamic data masking is applied only at rest, so it does not affect query performance."},{"id":"C","text":"Masking functions must be standardized and managed through Unity Catalog, with enforcement applied across all relevant datasets to\navoid any data inconsistency."},{"id":"D","text":"Native masking in Databricks automatically synchronizes with all downstream external Databricks systems."}],"correctAnswers":["C"],"explanation":"Govern and consistently apply shared masking policies/functions across the relevant datasets. Masks are not limited to direct identifiers or guaranteed to propagate to all external downstream copies.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The organization has chosen Unity Catalog as its central governance layer for shared masking functions and policies.","reviewNote":"Second audit: Unity Catalog is the governance design in this question, not the only possible way to transform PII.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":256,"prompt":"A data engineer is working on a Databricks notebook that requires several third-party Python libraries. Some of these are available on PyPI, while\nothers are custom-developed and stored as local.wheel (.whl) and source (.tar.gz) files in an S3 bucket. The goal is to ensure all dependencies are\ninstalled and correctly available across multiple jobs running on any automated cluster in a Unity Catalog-enabled workspace. The engineer needs\nto install the required dependencies in a way that ensures a consistent environment setup across interactive notebooks and jobs and complies\nwith workspace security policies (no internet access).\nWhich approach should the engineer use to install and manage these dependencies while also ensuring reproducibility and compliance?","options":[{"id":"A","text":"Use an init script on the cluster to install all dependencies using pip, referencing the local file system.","rationale":"Local init-script installation alone does not specify pinned, staged dependencies and compatible deployment across these jobs.","isCorrect":false},{"id":"B","text":"Install all dependencies manually in the driver node of an interactive cluster, then export the environment and reimport on job clusters using\n%conda.","rationale":"Driver-only manual installation and obsolete %conda do not provide reproducible supported job environments.","isCorrect":false},{"id":"C","text":"Build compatible wheels for the project and all transitive dependencies, pin versions and stage them in approved Workspace Files/Volumes or an internal repository. Declare libraries in the bundle and install from these offline artifacts (for pip, --no-index with a staged wheelhouse/requirements file).","rationale":"Pinned compatible offline artifacts, including transitive dependencies, provide a reproducible installation without public internet access.","isCorrect":true},{"id":"D","text":"Use %pip install in every notebook and job to install packages directly from PyPl and custom S3 paths.","rationale":"Direct PyPI access violates the no-internet constraint.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Pinned compatible offline artifacts, including transitive dependencies, provide a reproducible installation without public internet access.","topic":"libraries","sourceUrl":"https://docs.databricks.com/aws/en/libraries/notebooks-python-libraries","sourceTitle":"Notebook-scoped Python libraries | Databricks on AWS","sourcePage":119,"images":["questions/256-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":256,"prompt":"A data engineer is working on a Databricks notebook that requires several third-party Python libraries. Some of these are available on PyPI, while\nothers are custom-developed and stored as local.wheel (.whl) and source (.tar.gz) files in an S3 bucket. The goal is to ensure all dependencies are\ninstalled and correctly available across multiple jobs running on any automated cluster in a Unity Catalog-enabled workspace. The engineer needs\nto install the required dependencies in a way that ensures a consistent environment setup across interactive notebooks and jobs and complies\nwith workspace security policies (no internet access).\nWhich approach should the engineer use to install and manage these dependencies while also ensuring reproducibility and compliance?","options":[{"id":"A","text":"Use an init script on the cluster to install all dependencies using pip, referencing the local file system."},{"id":"B","text":"Install all dependencies manually in the driver node of an interactive cluster, then export the environment and reimport on job clusters using\n%conda."},{"id":"C","text":"Create a Python wheel file for the entire project, upload it to the Databricks Workspace Files or Volumes, and install it using a Cluster\nLibrary or pip install in a requirements.txt declared within a Databricks Asset Bundle."},{"id":"D","text":"Use %pip install in every notebook and job to install packages directly from PyPl and custom S3 paths."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"Package and pin dependencies, store artifacts in approved workspace files/volumes and declare them in deployment configuration. To satisfy no internet access, also stage every transitive dependency or use an internal package repository; a project wheel alone is insufficient.","topic":"libraries","sourceUrl":"https://docs.databricks.com/aws/en/libraries/notebooks-python-libraries","sourceTitle":"Notebook-scoped Python libraries | Databricks on AWS","sourcePage":119,"images":["questions/256-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Added all transitive dependencies and offline installation; a project wheel alone is insufficient.","studyContext":"Select compute/access modes supporting the chosen library source, and ensure deployment identities have access to the staged artifacts.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":257,"prompt":"Auto Loader reads newline-delimited JSON using the code below. There is no rescuedDataColumn configured. Input contains {\"a\": \"not-an-integer\", \"b\": 2}; the JSON is syntactically valid and single-line. Why can the record fail the parser schema and be directed to badRecordsPath?","options":[{"id":"A","text":"The source data is valid JSON, but doesn’t conform to their defined schema in some way","rationale":"The string value cannot be parsed as the declared INT without rescue handling.","isCorrect":true},{"id":"B","text":"The badRecordsPath location is accumulating many small files","rationale":"Small files in the error directory do not cause this input type mismatch.","isCorrect":false},{"id":"C","text":"The engineer forgot to set the option “cloudFiles.quarantineMode”, “rescue”.","rationale":"cloudFiles.quarantineMode is not the described supported option.","isCorrect":false},{"id":"D","text":"At some point, the upstream data provider switched everything to multi-line JSON.","rationale":"The supplied input is explicitly single-line JSON.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"The string value cannot be parsed as the declared INT without rescue handling.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceTitle":"Auto Loader schema mismatches and bad records","sourcePage":119,"images":["questions/257-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":257,"prompt":"A data engineer is using Auto Loader to read in JSON data as it arrives. They have configured Auto Loader to quarantine invalid JSON records.\nThey are noticing that over time, some records are being quarantined even though they are well-formed JSON.\nThe snippet of code is:\nWhat is the cause of the missing data?","options":[{"id":"A","text":"The source data is valid JSON, but doesn’t conform to their defined schema in some way"},{"id":"B","text":"The badRecordsPath location is accumulating many small files"},{"id":"C","text":"The engineer forgot to set the option “cloudFiles.quarantineMode”, “rescue”."},{"id":"D","text":"At some point, the upstream data provider switched everything to multi-line JSON."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"The explicit integer schema can reject otherwise valid JSON with incompatible values. Parser and rescued-data settings determine whether mismatches go to badRecordsPath or rescued data. Multiline input is another possible issue but is not established by the question.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/","sourceTitle":"What is Auto Loader? | Databricks on AWS","sourcePage":119,"images":["questions/257-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Made parser settings and observed input explicit so schema mismatch is distinguishable from malformed JSON.","studyContext":"","code":"df = (spark.readStream.format(\"cloudFiles\")\n .option(\"cloudFiles.format\", \"json\")\n .option(\"badRecordsPath\", \"/tmp/bad-records\")\n .schema(\"a INT, b INT\")\n .load(\"/Volumes/catalog/schema/raw_data/\"))","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":258,"prompt":"A data engineer wants to enforce the principle of least privilege when configuring ACLs for Databricks jobs in a collaborative workspace.\nWhich approach should the data engineer use?","options":[{"id":"A","text":"Assign only the minimum required job permission, such as CAN_VIEW for viewing or CAN_MANAGE_RUN for triggering and managing runs.","rationale":"Choose the narrow permission matching the person's actual viewing or run-management duty.","isCorrect":true},{"id":"B","text":"Use only folder-level permissions and avoid setting permissions on individual jobs.","rationale":"Folder permissions do not replace job resource ACL management.","isCorrect":false},{"id":"C","text":"Grant CAN RUN permission to everyone and CAN MANAGE to a single admin group.","rationale":"CAN RUN is not the specified job permission level, and universal run access is not least privilege.","isCorrect":false},{"id":"D","text":"Grant all users CAN MANAGE permission on all jobs to avoid access issues.","rationale":"Universal CAN MANAGE grants excessive configuration and permission control.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"Choose the narrow permission matching the person's actual viewing or run-management duty.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":120,"images":["questions/258-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":258,"prompt":"A data engineer wants to enforce the principle of least privilege when configuring ACLs for Databricks jobs in a collaborative workspace.\nWhich approach should the data engineer use?","options":[{"id":"A","text":"Assign users only the minimum permission level (e.g., CAN RUN or CAN VIEW) required for their role on each job."},{"id":"B","text":"Use only folder-level permissions and avoid setting permissions on individual jobs."},{"id":"C","text":"Grant CAN RUN permission to everyone and CAN MANAGE to a single admin group."},{"id":"D","text":"Grant all users CAN MANAGE permission on all jobs to avoid access issues."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Assign only the required permission per role. The conceptual answer is A, but the actual Jobs execution permission is CAN MANAGE RUN, not CAN RUN; CAN VIEW is valid.","topic":"permissions","sourceUrl":"https://docs.databricks.com/aws/en/security/auth/access-control/","sourceTitle":"Access control lists | Databricks on AWS","sourcePage":120,"images":["questions/258-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Used the actual Jobs ACL permission name.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":259,"prompt":"A data engineering workspace was automatically enabled for Unity Catalog, creating a workspace catalog. New team members report they can\ncreate tables in the default schema but cannot access table in other schemas within the same workspace catalog.\nWhy are the new team members unable to access tables in other schemas?","options":[{"id":"A","text":"Workspace catalog permissions are not subject to inheritance rules.","rationale":"Inheritance still applies to the workspace catalog.","isCorrect":false},{"id":"B","text":"Workspace users receive USE CATALOG and specific privileges on default schema only.","rationale":"The default grants cover catalog use and the default schema, not arbitrary access to all other schemas' tables.","isCorrect":true},{"id":"C","text":"Tables in other schemas require additional BROWSE privileges that new users don’t receive automatically","rationale":"BROWSE is metadata discovery and does not substitute for SELECT and usage privileges.","isCorrect":false},{"id":"D","text":"New users only receive CREATE TABLE privileges on the default schema.","rationale":"Default access includes more than CREATE TABLE, while grants are scoped to the default schema.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"The default grants cover catalog use and the default schema, not arbitrary access to all other schemas' tables.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":120,"images":["questions/259-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":260,"prompt":"A data engineer is implementing a job to download multiple PDF files from a third-party provided REST API endpoint by specifying different report\ntypes. The REST API is time-consuming and encounters intermittent errors, so the engineer wants to track each download activity to know when it\nfails and to retry partially, while providing scalable throughput. The engineer needs to download ten report types, and the list can be changed over\ntime.\nHow should the data engineer achieve this?","options":[{"id":"A","text":"Use a foreach task with a list of report types as its inputs.","rationale":"A For each task iterates a configurable input list with per-iteration visibility and controlled concurrency/retries.","isCorrect":true},{"id":"B","text":"Define ten Notebook tasks to clearly track which report download failed.","rationale":"Ten hardcoded tasks require manual maintenance when report types change.","isCorrect":false},{"id":"C","text":"Use a Delta Lake table to track each report download status as 10 rows, and use it as a source table to execute the download function as a\nPandas UDF.","rationale":"A Pandas UDF for side-effecting HTTP downloads complicates retries and duplicate effects without native iteration monitoring.","isCorrect":false},{"id":"D","text":"Define a list variable within a Notebook to loop through the report types to download them, and print the download results. Execute it as a\nNotebook tasks.","rationale":"A notebook loop and printed output do not provide the requested task-level iteration recovery.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A For each task iterates a configurable input list with per-iteration visibility and controlled concurrency/retries.","topic":"foreach","sourceUrl":"https://docs.databricks.com/aws/en/jobs/tasks/for-each","sourceTitle":"Use a For each task to run another task in a loop | Databricks on AWS","sourcePage":120,"images":["questions/260-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":261,"prompt":"To gate an external script on today’s latest run succeeding, first list completed candidates for a known job. Which command retrieves those candidates? The script must then select the latest matching run and require state.result_state == SUCCESS before proceeding.","options":[{"id":"A","text":"databricks jobs list-runs --job-id JOB_ID --start-time-to TODAY_MIDNIGHT_EPOCH_MS --completed-only","rationale":"The upper bound selects runs starting before today's midnight.","isCorrect":false},{"id":"B","text":"databricks jobs list-runs --job-id JOB_ID --start-time-from TODAY_MIDNIGHT_EPOCH_MS --active-only","rationale":"Active runs have not completed and cannot establish final success.","isCorrect":false},{"id":"C","text":"databricks jobs list-runs --job-id JOB_ID --start-time-to TODAY_MIDNIGHT_EPOCH_MS --active-only","rationale":"This selects older active runs, not today's completed runs.","isCorrect":false},{"id":"D","text":"databricks jobs list-runs --job-id JOB_ID --start-time-from TODAY_MIDNIGHT_EPOCH_MS --completed-only","rationale":"This lists today's completed candidates; inspect the latest run's result_state for SUCCESS before invoking the external script.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"This lists today's completed candidates; inspect the latest run's result_state for SUCCESS before invoking the external script.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":121,"images":["questions/261-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer and a platform engineer are working together to automate their system tasks. A script needs to be executed outside of Databricks\nonly if a particular daily Databricks job finishes successfully for the day. Databricks CLI command was used to check the last execution of the job.\nWhat are the required command options for that task?","options":[{"id":"A","text":"databricks jobs list-runs --job-id JOB_ID --start-time-to TODAY_MIDNIGHT_EPOCH_MS --completed-only"},{"id":"B","text":"databricks jobs list-runs --job-id JOB_ID --start-time-from TODAY_MIDNIGHT_EPOCH_MS --active-only"},{"id":"C","text":"databricks jobs list-runs --job-id JOB_ID --start-time-to TODAY_MIDNIGHT_EPOCH_MS --active-only"},{"id":"D","text":"databricks jobs list-runs --job-id JOB_ID --start-time-from TODAY_MIDNIGHT_EPOCH_MS --completed-only"}],"correctAnswers":["D"],"explanation":"Use start-time-from midnight with completed-only to locate completed runs from today, then inspect result_state for SUCCESS before triggering the external script. Completed does not itself mean successful; time filtering uses run start time.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"TODAY_MIDNIGHT_EPOCH_MS is correctly computed for the business timezone. Pagination is handled; a completed run is not necessarily successful.","reviewNote":"Second audit: Completed includes failed runs; a separate SUCCESS check is essential.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":262,"prompt":"A data engineering team needs to create a SQL Alert that monitors data quality across multiple columns in their customer table. They want to\ntrigger an alert when both the percentage of customers with missing email addresses exceeds 15% AND the percentage of customers with invalid\nphone number formats exceeds 10%.\nWhich SQL query pattern is appropriate for implementing this multi-column alert condition?","options":[{"id":"A","text":"SELECT COUNT (*) FROM customers WHERE email IS NULL OR phone_format_invalid = true","rationale":"A row count with OR is neither two percentages nor an AND threshold decision.","isCorrect":false},{"id":"B","text":"SELECT email, phone FROM customers WHERE email IS NULL AND phone NOT RLIKE ‘ˆ[0-9-+()\\\\s]+$’","rationale":"Returning individual invalid rows does not evaluate the two population percentages.","isCorrect":false},{"id":"C","text":"SELECT email_null_pct, phone_invalid_pct FROM (SELECT (COUNT(CASE WHEN email IS NULL THEN 1 END) *\n100.0/COUNT (*)) as email_null_pct, (COUNT(CASE WHEN phone NOT RLIKE ‘ˆ[0-9-+()\\\\s]+$’ THEN 1 END)*\n100.0/COUNT (*)) as phone_invalid_pct FROM customers)","rationale":"Two percentage columns alone do not produce the configured combined Boolean alert result.","isCorrect":false},{"id":"D","text":"WITH metrics AS (\n SELECT\n  100.0 * COUNT(CASE WHEN email IS NULL THEN 1 END) / NULLIF(COUNT(*), 0) AS email_null_pct,\n  100.0 * COUNT(CASE WHEN phone_format_invalid = true THEN 1 END) / NULLIF(COUNT(*), 0) AS phone_invalid_pct\n FROM customers\n)\nSELECT CASE WHEN email_null_pct > 15 AND phone_invalid_pct > 10\n THEN 1 ELSE 0 END AS should_alert\nFROM metrics","rationale":"It computes both percentages, applies the AND thresholds and produces a non-alerting result for empty input.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"It computes both percentages, applies the AND thresholds and produces a non-alerting result for empty input.","topic":"alerts","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/alerts/query-patterns","sourceTitle":"SQL alerts: combine multiple column conditions","sourcePage":121,"images":["questions/262-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":262,"prompt":"A data engineering team needs to create a SQL Alert that monitors data quality across multiple columns in their customer table. They want to\ntrigger an alert when both the percentage of customers with missing email addresses exceeds 15% AND the percentage of customers with invalid\nphone number formats exceeds 10%.\nWhich SQL query pattern is appropriate for implementing this multi-column alert condition?","options":[{"id":"A","text":"SELECT COUNT (*) FROM customers WHERE email IS NULL OR phone_format_invalid = true"},{"id":"B","text":"SELECT email, phone FROM customers WHERE email IS NULL AND phone NOT RLIKE ‘ˆ[0-9-+()\\\\s]+$’"},{"id":"C","text":"SELECT email_null_pct, phone_invalid_pct FROM (SELECT (COUNT(CASE WHEN email IS NULL THEN 1 END) *\n100.0/COUNT (*)) as email_null_pct, (COUNT(CASE WHEN phone NOT RLIKE ‘ˆ[0-9-+()\\\\s]+$’ THEN 1 END)*\n100.0/COUNT (*)) as phone_invalid_pct FROM customers)"},{"id":"D","text":"SELECT CASE WHEN email_null_pct >15 AND phone_invalid_pct> 10 THEN 1 ELSE 0 END FROM (SELECT (COUNT (CASE WHEN email IS\nNULL THEN 1 END) * 100.0 / COUNT (*)) as phone_invalid_pct FROM customers) metrics"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"No printed query expresses the complete valid condition. C computes both percentages but does not combine thresholds; D refers to an undefined email_null_pct and mislabels its only aggregate. Repair D to compute both metrics and return their AND condition, handling an empty table.","topic":"alerts","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/alerts/","sourceTitle":"Databricks SQL alerts | Databricks on AWS","sourcePage":121,"images":["questions/262-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Added both aggregate metrics, a combined condition and empty-input handling.","studyContext":"phone_format_invalid is a precomputed Boolean flag from the agreed phone validation rule. Configure the alert to trigger when the single output should_alert equals 1. Empty input should not trigger.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":263,"prompt":"A data engineer is brining an existing production Databricks job under asset bundle management and wants to ensure that:\n• The job’s current configuration is captured as YAML, and referenced notebooks and any other required artifacts are included in their bundle project.\n• Future changes to the bundle’s YAML will update the existing job in-place (not create a new job)\nHow should the data engineer successfully move the production job under asset bundle management?","options":[{"id":"A","text":"Run Databricks bundle generate job --existing-job-id to generate the YAML and download referenced files. Then, run Databricks bundle\ndeploy to deploy the bundle, which will always update the existing job automatically.","rationale":"Deploy does not automatically associate a generated resource with an existing job.","isCorrect":false},{"id":"B","text":"Export the job definition as JSON, convert it to YAML, and place it in your bundle. Then, run Databricks bundle deploy to update the existing\njob.","rationale":"Equivalent YAML content does not bind the resource to the production job ID.","isCorrect":false},{"id":"C","text":"Manually create the YAML configuration for the job in your bundle project, ensuring all settings match the existing job. Then, run Databricks\nbundle deploy the bundle, which will update the existing job in your workspace.","rationale":"Matching settings alone do not prevent creation of a separate job.","isCorrect":false},{"id":"D","text":"Run databricks bundle generate job --existing-job-id JOB_ID to capture the configuration and referenced notebooks; stage any other required artifacts. Run databricks bundle deployment bind RESOURCE_KEY JOB_ID, then validate and deploy the bundle.","rationale":"Generate captures the definition; deployment bind associates its resource key with the existing job before deployment.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Generate captures the definition; deployment bind associates its resource key with the existing job before deployment.","topic":"bundles","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/bundles/migrate-resources","sourceTitle":"Migrate existing resources to a bundle","sourcePage":121,"images":["questions/263-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is brining an existing production Databricks job under asset bundle management and wants to ensure that:\n• The job’s current configuration is captured as YAML, and all referenced files are included in their bundle project.\n• Future changes to the bundle’s YAML will update the existing job in-place (not create a new job)\nHow should the data engineer successfully move the production job under asset bundle management?","options":[{"id":"A","text":"Run Databricks bundle generate job --existing-job-id to generate the YAML and download referenced files. Then, run Databricks bundle\ndeploy to deploy the bundle, which will always update the existing job automatically."},{"id":"B","text":"Export the job definition as JSON, convert it to YAML, and place it in your bundle. Then, run Databricks bundle deploy to update the existing\njob."},{"id":"C","text":"Manually create the YAML configuration for the job in your bundle project, ensuring all settings match the existing job. Then, run Databricks\nbundle deploy the bundle, which will update the existing job in your workspace."},{"id":"D","text":"Run databricks bundle generate job --existing-job-id to generate the YAML and download referenced files. Then, run Databricks bundle\ndeployment, bind to link the bundle’s job resource to the existing job in Databricks."}],"correctAnswers":["D"],"explanation":"Generate bundle YAML/assets from the existing job, then bind that resource to the existing job ID before deployment. Deploying an unbound resource can create another job instead of updating the original.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Corrected deployment bind syntax and distinguished downloaded notebooks from other required artifacts.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":264,"prompt":"A data architect is implementing Delta Sharing as part of their data governance strategy to enable secure data collaboration with external partners\nand internal business units. The architect must establish a permission framework that allows designated data stewards to create shares for their\nrespective domains while maintaining security boundaries and audit compliance.\nWhich specific permissions and roles must be assigned to enable users to create, configure, and manage Delta Shares while maintaining proper\nsecurity governance and access controls?","options":[{"id":"A","text":"Only workspace admins can create and manage shares","rationale":"Workspace administration is not the exclusive route to metastore share creation.","isCorrect":false},{"id":"B","text":"Users need the MANAGE SHARES permission on the workspace","rationale":"MANAGE SHARES is not the stated workspace privilege.","isCorrect":false},{"id":"C","text":"Users need to be metastore admins or have CREATE SHARE privilege for the metastore","rationale":"CREATE SHARE on the metastore, or metastore administration, permits share creation; adding assets has additional prerequisites.","isCorrect":true},{"id":"D","text":"Any user with USE_CATALOG privilege can create shares","rationale":"USE CATALOG does not grant metastore share creation.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"CREATE SHARE on the metastore, or metastore administration, permits share creation; adding assets has additional prerequisites.","topic":"sharing","sourceUrl":"https://docs.databricks.com/aws/en/opensharing","sourceTitle":"What is OpenSharing? | Databricks on AWS","sourcePage":122,"images":["questions/264-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data architect is implementing Delta Sharing as part of their data governance strategy to enable secure data collaboration with external partners\nand internal business units. The architect must establish a permission framework that allows designated data stewards to create shares for their\nrespective domains while maintaining security boundaries and audit compliance.\nWhich specific permissions and roles must be assigned to enable users to create, configure, and manage Delta Shares while maintaining proper\nsecurity governance and access controls?","options":[{"id":"A","text":"Only workspace admins can create and manage shares"},{"id":"B","text":"Users need the MANAGE SHARES permission on the workspace"},{"id":"C","text":"Users need to be metastore admins or have CREATE SHARE privilege for the metastore"},{"id":"D","text":"Any user with USE_CATALOG privilege can create shares"}],"correctAnswers":["C"],"explanation":"A metastore admin or principal granted CREATE SHARE on the metastore can create a share. Managing its contents also requires ownership/MANAGE and the necessary source-object privileges; USE CATALOG alone is insufficient.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Ask for the metastore-level privilege enabling creation of a share the user will own. Required privileges on the underlying assets and recipients are already in place.","reviewNote":"Second audit: CREATE SHARE alone does not authorize adding arbitrary assets.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":265,"prompt":"A data engineer manages a production Lakeflow Spark Declarative Pipeline that processes customer transaction data. The pipeline includes\nseveral data quality expectations, such as: transaction_amount > 0 and customer_id IS NOT NULL.\nThese expectations are defined using the EXPECT clause in SQL. The engineer aims to monitor the pipeline’s data quality by analyzing the number\nof records that passed or failed each expectation during the latest pipeline update. The Lakeflow Spark Declarative Pipelines event logs are stored\nin a Delta table named event_log_table.\nFor the most recent pipeline update, determine a programmatically approach to extract information like the name of each expectation, associated\ndataset, count of records that passed the expectation, and count of records that failed the expectation.\nWhich method retrieves the desired data quality metrics from the Lakeflow Spark Declarative Pipelines event log?","options":[{"id":"A","text":"Filter event_log_table for event_type = 'flow_progress' and the latest desired origin.update_id; parse details.flow_progress.data_quality.expectations for each dataset’s expectation names and passed/failed counts.","rationale":"flow_progress contains expectation metrics, scoped by update and dataset.","isCorrect":true},{"id":"B","text":"Use the Lakeflow Spark Declarative Pipelines UI to navigate to the specific pipeline, select the dataset, and view the Data Quality tab to\nmanually retrieve the expectation metrics.","rationale":"The UI can show metrics, but this is not the requested programmatic extraction.","isCorrect":false},{"id":"C","text":"Query the event_log_table for events with event_type = ‘data_quality’ and directly select the passed_records and failed_records fields.","rationale":"data_quality is not the event_type carrying these expectation metrics.","isCorrect":false},{"id":"D","text":"Access the event_log_table, filter for events where event_type = ‘expectatation_result’, and extract the expectation metrics from the details\nfield.","rationale":"expectatation_result is not the documented event_type.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"flow_progress contains expectation metrics, scoped by update and dataset.","topic":"eventlog","sourceUrl":"https://docs.databricks.com/aws/en/ldp/monitor-event-logs","sourceTitle":"Pipeline event log | Databricks on AWS","sourcePage":122,"images":["questions/265-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":265,"prompt":"A data engineer manages a production Lakeflow Spark Declarative Pipeline that processes customer transaction data. The pipeline includes\nseveral data quality expectations, such as: transaction_amount > 0 and customer_id IS NOT NULL.\nThese expectations are defined using the EXPECT clause in SQL. The engineer aims to monitor the pipeline’s data quality by analyzing the number\nof records that passed or failed each expectation during the latest pipeline update. The Lakeflow Spark Declarative Pipelines event logs are stored\nin a Delta table named event_log_table.\nFor the most recent pipeline update, determine a programmatically approach to extract information like the name of each expectation, associated\ndataset, count of records that passed the expectation, and count of records that failed the expectation.\nWhich method retrieves the desired data quality metrics from the Lakeflow Spark Declarative Pipelines event log?","options":[{"id":"A","text":"Access the event_log_table, filter for events where event_type = ‘flow progress’, and parse the\ndetails.flow_progress.data_quality.expectations field to extract the required metrics."},{"id":"B","text":"Use the Lakeflow Spark Declarative Pipelines UI to navigate to the specific pipeline, select the dataset, and view the Data Quality tab to\nmanually retrieve the expectation metrics."},{"id":"C","text":"Query the event_log_table for events with event_type = ‘data_quality’ and directly select the passed_records and failed_records fields."},{"id":"D","text":"Access the event_log_table, filter for events where event_type = ‘expectatation_result’, and extract the expectation metrics from the details\nfield."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Query flow_progress events and parse details.flow_progress.data_quality.expectations, restricted to the desired update ID. The option prints 'flow progress' with a space; the actual event_type is 'flow_progress'. The other event names are incorrect.","topic":"eventlog","sourceUrl":"https://docs.databricks.com/aws/en/ldp/monitor-event-logs","sourceTitle":"Pipeline event log | Databricks on AWS","sourcePage":122,"images":["questions/265-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected flow_progress and explicitly filtered the selected update.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":266,"prompt":"Predictive Optimization is an automated Databricks service enabled by default for Unity Catalog Managed tables. It helps maintain Delta tables by\ncontinuously optimizing them to ensure optimal performance and costs.\nWhich two operations does Predictive Optimization run to maintain the Delta tables? (Choose two.)","options":[{"id":"A","text":"PARTITION BY","rationale":"Predictive optimization does not run a PARTITION BY maintenance command.","isCorrect":false},{"id":"B","text":"COMPACT","rationale":"COMPACT is not the named SQL maintenance operation; compaction is performed through OPTIMIZE.","isCorrect":false},{"id":"C","text":"ANALYZE","rationale":"ANALYZE collects statistics as part of predictive optimization.","isCorrect":true},{"id":"D","text":"OPTIMIZE","rationale":"OPTIMIZE maintains the physical file layout; predictive optimization can also run VACUUM, which is not listed.","isCorrect":true},{"id":"E","text":"BUCKETING","rationale":"Bucketing is not a predictive optimization maintenance operation.","isCorrect":false}],"selectionCount":2,"correctAnswers":["C","D"],"suggestedAnswers":[],"status":"confirmed","explanation":"ANALYZE collects statistics as part of predictive optimization. OPTIMIZE maintains the physical file layout; predictive optimization can also run VACUUM, which is not listed.","topic":"predictive","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/predictive-optimization","sourceTitle":"Predictive optimization for Unity Catalog managed tables | Databricks on AWS","sourcePage":122,"images":["questions/266-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":267,"prompt":"A data engineer is building a customer data pipeline in Lakeflow Spark Declarative Pipelines. The source is a cloud-based event stream with\nlimited retention containing inserts, updates, and deletes for customer records. These changes are being applied using the AUTO CDC INTO\nsyntax to maintain an SCD Type 1 table as the target table, customer_dim.\nHow should the data engineer build a downstream job that streams from the customer_dim table to only act on updates and delete events,\nprocessing data incrementally?","options":[{"id":"A","text":"Use ignoreChanges flag while streaming from customer_dim to avoid breaking the pipeline during updates and deletes.","rationale":"ignoreChanges can re-emit rows and does not expose deletions as CDC events.","isCorrect":false},{"id":"B","text":"Read change data feed from customer_dim table and apply filters to incrementally act on the change events.","rationale":"CDF provides change types that the downstream stream can filter and process.","isCorrect":true},{"id":"C","text":"Streaming from customer_dim table would only be possible in the case of SCD 2 retention.","rationale":"Supported CDF streaming is not restricted to SCD Type 2 targets.","isCorrect":false},{"id":"D","text":"When stored as SCD 1, the target of AUTO CDC INTO includes updates and deletes. Streaming from customer_dim can fail due to these\noperations. Instead, build another stream from the original source.","rationale":"Returning to the limited-retention original source does not satisfy consuming changes from customer_dim.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"CDF provides change types that the downstream stream can filter and process.","topic":"cdf","sourceUrl":"https://docs.databricks.com/aws/en/tables/features/change-data-feed","sourceTitle":"Use change data feed on Databricks | Databricks on AWS","sourcePage":123,"images":["questions/267-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is building a customer data pipeline in Lakeflow Spark Declarative Pipelines. The source is a cloud-based event stream with\nlimited retention containing inserts, updates, and deletes for customer records. These changes are being applied using the AUTO CDC INTO\nsyntax to maintain an SCD Type 1 table as the target table, customer_dim.\nHow should the data engineer build a downstream job that streams from the customer_dim table to only act on updates and delete events,\nprocessing data incrementally?","options":[{"id":"A","text":"Use ignoreChanges flag while streaming from customer_dim to avoid breaking the pipeline during updates and deletes."},{"id":"B","text":"Read change data feed from customer_dim table and apply filters to incrementally act on the change events."},{"id":"C","text":"Streaming from customer_dim table would only be possible in the case of SCD 2 retention."},{"id":"D","text":"When stored as SCD 1, the target of AUTO CDC INTO includes updates and deletes. Streaming from customer_dim can fail due to these\noperations. Instead, build another stream from the original source."}],"correctAnswers":["B"],"explanation":"Consume CDF and filter the appropriate change types, normally update_postimage and delete for these requirements. ignoreChanges can re-emit rows and does not reliably propagate deletes; SCD Type 2 is not required.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"customer_dim has CDF enabled, required changes are retained, and the pipeline/runtime supports reading CDF from the AUTO CDC target.","reviewNote":"Second audit: CDF must be enabled and retained before downstream consumption.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":268,"prompt":"A data engineer is designing a system leveraging Lakeflow Declarative Pipeline technology to process real-time truck telemetry data ingested from\nJSON files in S3 using Auto Loader. The data includes truck_id, timestamp, location, speed, and fuel_level. The system must support two use\ncases:\n1. Near-real-time monitoring of the latest location, speed, and fuel_level per truck_id for the operations team.\n2. Daily aggregated reports of total distance traveled and average fuel efficiency per truck_id for the management team.\nWhich approach should the data engineer use for streaming tables and materialized views in the Lakeflow Declarative Pipeline to meet these\nrequirements?","options":[{"id":"A","text":"Define a streaming table to ingest and store the raw telemetry data, and create a streaming table to compute the daily aggregated distance\nand fuel efficiency per truck_id reporting. Create a materialized view to compute the latest location, speed, and fuel_level per truck_id for real-\ntime monitoring.","rationale":"The latest-state output is a materialized view, contrary to the specified streaming CDC contract.","isCorrect":false},{"id":"B","text":"Define a streaming table to ingest and store the raw telemetry data, and create a materialized view to compute the latest location, speed,\nand fuel_level per truck_id for real-time monitoring. Create another materialized view to compute the daily aggregated distance and fuel\nefficiency per truck_id for reporting.","rationale":"This also uses a materialized view for the required streaming latest-state output.","isCorrect":false},{"id":"C","text":"Ingest raw telemetry into a streaming table; maintain latest state per truck_id in another streaming table with keyed, timestamp-sequenced AUTO CDC (SCD Type 1); compute daily aggregates from raw telemetry in a materialized view.","rationale":"The raw history supports daily reports while keyed sequenced AUTO CDC maintains the latest truck state.","isCorrect":true},{"id":"D","text":"Define a materialized view to ingest and store the raw telemetry data, and create a streaming table to compute the latest location, speed,\nand fuel_level per truck_id for real-time monitoring. Create another materialized view to compute the daily aggregated distance and fuel\nefficiency per truck_id for reporting.","rationale":"A raw materialized view is not the required incremental file-ingestion streaming table, and latest-state semantics are unspecified.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"The raw history supports daily reports while keyed sequenced AUTO CDC maintains the latest truck state.","topic":"ldp","sourceUrl":"https://docs.databricks.com/aws/en/ldp/","sourceTitle":"Spark Declarative Pipelines | Databricks on AWS","sourcePage":123,"images":["questions/268-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":268,"prompt":"A data engineer is designing a system leveraging Lakeflow Declarative Pipeline technology to process real-time truck telemetry data ingested from\nJSON files in S3 using Auto Loader. The data includes truck_id, timestamp, location, speed, and fuel_level. The system must support two use\ncases:\n1. Near-real-time monitoring of the latest location, speed, and fuel_level per truck_id for the operations team.\n2. Daily aggregated reports of total distance traveled and average fuel efficiency per truck_id for the management team.\nWhich approach should the data engineer use for streaming tables and materialized views in the Lakeflow Declarative Pipeline to meet these\nrequirements?","options":[{"id":"A","text":"Define a streaming table to ingest and store the raw telemetry data, and create a streaming table to compute the daily aggregated distance\nand fuel efficiency per truck_id reporting. Create a materialized view to compute the latest location, speed, and fuel_level per truck_id for real-\ntime monitoring."},{"id":"B","text":"Define a streaming table to ingest and store the raw telemetry data, and create a materialized view to compute the latest location, speed,\nand fuel_level per truck_id for real-time monitoring. Create another materialized view to compute the daily aggregated distance and fuel\nefficiency per truck_id for reporting."},{"id":"C","text":"Define a streaming table to ingest and store the raw telemetry data, and create a streaming table to incrementally compute the latest\nlocation, speed, and fuel_level per truck_id for real-time monitoring. Create a materialized view to compute the daily aggregated distance and\nfuel efficiency per truck_id for reporting."},{"id":"D","text":"Define a materialized view to ingest and store the raw telemetry data, and create a streaming table to compute the latest location, speed,\nand fuel_level per truck_id for real-time monitoring. Create another materialized view to compute the daily aggregated distance and fuel\nefficiency per truck_id for reporting."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"Use an ingestion streaming table, a latest-state streaming target maintained with AUTO CDC, and a materialized view for daily reports. A plain append-only streaming table alone does not compute latest state; suitable materialized-view refreshes can also serve alternative designs.","topic":"ldp","sourceUrl":"https://docs.databricks.com/aws/en/ldp/","sourceTitle":"Spark Declarative Pipelines | Databricks on AWS","sourcePage":123,"images":["questions/268-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Specified AUTO CDC for the latest-state streaming table and the required streaming update contract.","studyContext":"Latest state must be maintained through a streaming CDC flow, not a scheduled snapshot refresh; a deterministic source sequence breaks equal timestamps.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":269,"prompt":"A platform team lead is responsible for automating the individual teams attribution towards SQL Warehouse usage. The requirement is to identify\nthe SQL warehouse usage at the individual user’s level and generate a daily report to be shared with an executive team that includes leaders from\nall business units.\nHow should the platform lead generate an automated report that can be shared daily?","options":[{"id":"A","text":"Use the system tables to capture the audit and billing usage data and share the queries with the executive team. This enables the\nexecutives to execute the query and see the latest results any time.","rationale":"Sharing queries alone does not automate the daily report delivery.","isCorrect":false},{"id":"B","text":"Use the system tables to capture the audit and billing usage data and create a dashboard with daily refresh schedules and shared with the\nexecutive team.","rationale":"A scheduled dashboard over the documented allocation model produces a repeatable daily report.","isCorrect":true},{"id":"C","text":"Restrict users from running any SQL query unless they provide all the query details so that the attribution can be calculated and shared with\nthe executive team.","rationale":"Manual pre-declarations are not an automated reporting solution.","isCorrect":false},{"id":"D","text":"Let the users run the SQL query and then directly report the usage to the executives. The ownership of the SQL warehouse usage will be\nwith the individual teams.","rationale":"Self-reported consumption does not supply a consistent automated allocation.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"A scheduled dashboard over the documented allocation model produces a repeatable daily report.","topic":"billing","sourceUrl":"https://docs.databricks.com/aws/en/admin/system-tables/billing","sourceTitle":"Billable usage system table reference | Databricks on AWS","sourcePage":124,"images":["questions/269-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":269,"prompt":"A platform team lead is responsible for automating the individual teams attribution towards SQL Warehouse usage. The requirement is to identify\nthe SQL warehouse usage at the individual user’s level and generate a daily report to be shared with an executive team that includes leaders from\nall business units.\nHow should the platform lead generate an automated report that can be shared daily?","options":[{"id":"A","text":"Use the system tables to capture the audit and billing usage data and share the queries with the executive team. This enables the\nexecutives to execute the query and see the latest results any time."},{"id":"B","text":"Use the system tables to capture the audit and billing usage data and create a dashboard with daily refresh schedules and shared with the\nexecutive team."},{"id":"C","text":"Restrict users from running any SQL query unless they provide all the query details so that the attribution can be calculated and shared with\nthe executive team."},{"id":"D","text":"Let the users run the SQL query and then directly report the usage to the executives. The ownership of the SQL warehouse usage will be\nwith the individual teams."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"A scheduled dashboard over system data is the automated reporting choice. User attribution needs query/audit identity plus an explicit allocation model; shared warehouse billing is not an exact per-user cost ledger by itself.","topic":"billing","sourceUrl":"https://docs.databricks.com/aws/en/admin/system-tables/billing","sourceTitle":"Billable usage system table reference | Databricks on AWS","sourcePage":124,"images":["questions/269-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"Use a documented allocation model combining audit/query identity with warehouse billing. The task is daily automated reporting, not exact per-user metering of shared compute.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":270,"prompt":"A data engineering team is collaborating on a Databricks project where each team member needs to develop and test code independently before\nmerging changes into the main branch.\nThey want to avoid accidental overwrites or branch switching issues while ensuring that all work is version- controlled and can be integrated into\ntheir CI/CD pipeline.\nHow should the data engineer achieve collaboration?","options":[{"id":"A","text":"Each team member creates their own Databricks Git folder, mapped to the same remote Git repository, and works in their own development\nbranch within their personal folder.","rationale":"Personal checkouts and branches isolate working state while sharing remote version control.","isCorrect":true},{"id":"B","text":"All team members work in the same Databricks Git folder and perform Git operations (pull, push, commit, branch switching) directly in that\nshared folder.","rationale":"A shared checkout also shares branch and working-tree state, causing the stated conflicts.","isCorrect":false},{"id":"C","text":"Team members edit notebooks directly in the workspace’s shared folder and periodically copy changes into a Git folder for version control.","rationale":"Manual copying leaves active development outside reliable version control.","isCorrect":false},{"id":"D","text":"Team members use the Databricks CLI to clone the Git repository and perform Git operations from a cluster’s web terminal.","rationale":"Cluster-terminal Git is not the requested integrated personal workspace Git-folder workflow.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Personal checkouts and branches isolate working state while sharing remote version control.","topic":"git","sourceUrl":"https://docs.databricks.com/aws/en/repos/git-operations-with-repos","sourceTitle":"Create and manage Git folders | Databricks on AWS","sourcePage":124,"images":["questions/270-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":271,"prompt":"A data engineer is using the AUTO CDC API in Lakeflow Spark Declarative Pipeline to propagate deletions from a source table (orders_source) to a\ntarget table (orders_target). The source has Change Data Feed (CDF) enabled, but some delete events arrive out of order due to upstream delays.\nHow does the AUTO CDC API internally ensure deletions are applied correctly despite out-of-order events?","options":[{"id":"A","text":"It ignores deletions if they arrive after updates for the same key.","rationale":"Late deletes are not categorically ignored; sequence ordering determines their applicability.","isCorrect":false},{"id":"B","text":"It manually sorts incoming events by timestamp before applying changes.","rationale":"The service handles sequencing rather than requiring this manual pre-sort.","isCorrect":false},{"id":"C","text":"It runs VACUUM on the target table to purge conflicting records.","rationale":"VACUUM removes obsolete files and does not resolve event ordering.","isCorrect":false},{"id":"D","text":"AUTO CDC uses sequence_by ordering and retains deletion tombstones for a configurable retention period (normally two days by default). This prevents older events within that horizon from resurrecting deleted rows.","rationale":"Sequencing plus retention-bounded delete tombstones prevents older changes from resurrecting rows within the configured lateness horizon.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Sequencing plus retention-bounded delete tombstones prevents older changes from resurrecting rows within the configured lateness horizon.","topic":"autocdc","sourceUrl":"https://docs.databricks.com/aws/en/ldp/developer/ldp-python-ref-apply-changes","sourceTitle":"AUTO CDC API reference and tombstone retention","sourcePage":124,"images":["questions/271-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is using the AUTO CDC API in Lakeflow Spark Declarative Pipeline to propagate deletions from a source table (orders_source) to a\ntarget table (orders_target). The source has Change Data Feed (CDF) enabled, but some delete events arrive out of order due to upstream delays.\nHow does the AUTO CDC API internally ensure deletions are applied correctly despite out-of-order events?","options":[{"id":"A","text":"It ignores deletions if they arrive after updates for the same key."},{"id":"B","text":"It manually sorts incoming events by timestamp before applying changes."},{"id":"C","text":"It runs VACUUM on the target table to purge conflicting records."},{"id":"D","text":"It uses sequence_by to order events and retains tombstones for deleted rows until older sequences are processed."}],"correctAnswers":["D"],"explanation":"AUTO CDC uses sequence values and retained tombstones to handle out-of-order changes. Tombstone retention must exceed the expected delay; this is not an unlimited guarantee or a VACUUM conflict-resolution mechanism.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Set tombstone retention longer than the maximum out-of-order delay; arriving events are within that configured horizon.","reviewNote":"Second audit: Delete tombstones have configurable finite retention, not an unlimited wait for every older event.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":272,"prompt":"A team needs draft descriptions for undocumented Unity Catalog table columns. Which built-in feature generates suggestions from metadata such as column names and schema, for a human to review before saving?","options":[{"id":"A","text":"Write custom PySpark code using df.describe () and df.schema to programmatically generate basic statistical descriptions for each\ncolumn.","rationale":"Statistics and schema inspection are not built-in AI comment suggestions.","isCorrect":false},{"id":"B","text":"Use AI-generated comments in Catalog Explorer, then review and edit each suggestion before saving it.","rationale":"Catalog Explorer generates draft comments that can be reviewed and edited.","isCorrect":true},{"id":"C","text":"Use the DESCRIBE TABLE command to extract existing schema information and manually write descriptions based on column names and\ndata types.","rationale":"DESCRIBE reads existing metadata; it does not generate the requested suggestions.","isCorrect":false},{"id":"D","text":"Use Delta Lake’s DESCRIBE HISTORY command to analyze table evolution and infer column purposes from historical changes.","rationale":"Transaction history does not explain column business meanings automatically.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Catalog Explorer generates draft comments that can be reviewed and edited.","topic":"aicomments","sourceUrl":"https://docs.databricks.com/aws/en/comments/ai-comments","sourceTitle":"Add AI-generated comments to Unity Catalog objects | Databricks on AWS","sourcePage":125,"images":["questions/272-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":272,"prompt":"A data governance team at a large enterprise is improving data discoverability across its organization. The team has hundreds of tables in their\nDatabricks Lakehouse with thousands of columns that lack proper documentation. Many of these tables were created by different teams over\nseveral years, with missing context about column meanings and business logic. The data governance team needs to quickly generate\ncomprehensive column descriptions for all existing tables to meet compliance requirements and improve data literacy across the organization.\nThey want to leverage modern capabilities to automatically generate meaningful descriptions rather than manually documenting each column,\nwhich would take months to complete. The team is looking for a solution that can understand data patterns, column names, and sample values to\ncreate intelligent descriptions.\nWhich approach should the team use in Databricks to automatically generate column comments and descriptions for existing tables?","options":[{"id":"A","text":"Write custom PySpark code using df.describe () and df.schema to programmatically generate basic statistical descriptions for each\ncolumn."},{"id":"B","text":"Navigate to the table in Databricks Catalog Explorer, select the table schema view, and use the “AI Generate” option which leverages\nartificial intelligence to automatically create meaningful column descriptions based on column names, data types, sample values, and data\npatterns."},{"id":"C","text":"Use the DESCRIBE TABLE command to extract existing schema information and manually write descriptions based on column names and\ndata types."},{"id":"D","text":"Use Delta Lake’s DESCRIBE HISTORY command to analyze table evolution and infer column purposes from historical changes."}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"best_fit","explanation":"Catalog Explorer AI-generated comments are the intended feature. Review suggestions for correctness; do not assume it inspects sample values or satisfies compliance automatically. Statistical summaries/history do not generate equivalent semantic documentation.","topic":"aicomments","sourceUrl":"https://docs.databricks.com/aws/en/comments/ai-comments","sourceTitle":"Add AI-generated comments to Unity Catalog objects | Databricks on AWS","sourcePage":125,"images":["questions/272-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Removed unsubstantiated sample-value analysis and automatic compliance guarantees.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":273,"prompt":"A company processes semi-structured JSON files from an external source using Auto Loader in a classic Databricks job. Occasionally, records\narrive with null critical fields, invalid types, or unexpected nested schema variations. The engineer must ensure that malformed or non-conforming\nrecords are not dropped silently and are captured in a separate quarantine table. The pipeline should continue processing good records into the\nBronze layer without failing the job, and the approach must support both batch and streaming ingestion.\nThe data engineer needs to build a robust ingestion pattern that automatically routes bad records to a quarantine Delta table, while still ingesting\ngood records into the Bronze layer for further processing.\nWhich approach fulfills the quarantine mechanism in this ingestion architecture?","options":[{"id":"A","text":"Create a notebook job with inferSchema= True, write a streaming query with .foreachBatch() and catch exceptions using try/except to\nredirect failed batches to quarantine.","rationale":"Catching batch failures neither identifies every bad row nor safely preserves good rows by itself.","isCorrect":false},{"id":"B","text":"Use Auto Loader with failFast mode to set to false, and enable schema evolution; invalid records will be silently ignored during ingestion.","rationale":"Schema evolution and the proposed setting do not implement a quarantine sink.","isCorrect":false},{"id":"C","text":"Use Lakeflow Spark Declarative Pipelines with a SQL pipeline; configure it to drop rows with nulls using where critical_fields is not null, and\nrely on audit logs for malformed data.","rationale":"Dropping rows loses their payloads; audit logs are not a replacement for storing rejected data.","isCorrect":false},{"id":"D","text":"Use permissive parsing with rescued and corrupt-record capture, then explicit null/type/schema checks to split valid and invalid rows. Write good rows to Bronze and bad rows plus error reasons to quarantine. Reuse this validation function for batch input and foreachBatch; make both streaming sink writes idempotent with a persistent checkpoint.","rationale":"Explicit parsing capture and validation preserve rejected rows and reasons; idempotent dual writes handle streaming retries.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Explicit parsing capture and validation preserve rejected rows and reasons; idempotent dual writes handle streaming retries.","topic":"expectations","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema","sourceTitle":"Auto Loader schema and rescued-data behavior","sourcePage":125,"images":["questions/273-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":273,"prompt":"A company processes semi-structured JSON files from an external source using Auto Loader in a classic Databricks job. Occasionally, records\narrive with null critical fields, invalid types, or unexpected nested schema variations. The engineer must ensure that malformed or non-conforming\nrecords are not dropped silently and are captured in a separate quarantine table. The pipeline should continue processing good records into the\nBronze layer without failing the job, and the approach must support both batch and streaming ingestion.\nThe data engineer needs to build a robust ingestion pattern that automatically routes bad records to a quarantine Delta table, while still ingesting\ngood records into the Bronze layer for further processing.\nWhich approach fulfills the quarantine mechanism in this ingestion architecture?","options":[{"id":"A","text":"Create a notebook job with inferSchema= True, write a streaming query with .foreachBatch() and catch exceptions using try/except to\nredirect failed batches to quarantine."},{"id":"B","text":"Use Auto Loader with failFast mode to set to false, and enable schema evolution; invalid records will be silently ignored during ingestion."},{"id":"C","text":"Use Lakeflow Spark Declarative Pipelines with a SQL pipeline; configure it to drop rows with nulls using where critical_fields is not null, and\nrely on audit logs for malformed data."},{"id":"D","text":"Use Auto Loader with LDP and implement an EXPECT () constraint with a record audit logic to route bad records."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["D"],"status":"review","explanation":"D expresses the intended expectations-plus-quarantine pattern but changes the stated classic-job architecture. For a classic job, use permissive/rescued-data parsing and explicit row validation to split good and bad rows, with reliable writes. An EXPECT alone does not automatically create a quarantine table.","topic":"expectations","sourceUrl":"https://docs.databricks.com/aws/en/ldp/expectation-patterns","sourceTitle":"Expectation recommendations and advanced patterns | Databricks on AWS","sourcePage":125,"images":["questions/273-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Replaced the incompatible LDP-only answer with a complete classic-job quarantine pattern.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":274,"prompt":"df contains customer_id, transaction_timestamp, transaction_id and amount_spent. Multiple transactions can share a timestamp; transaction_id uniquely and stably breaks ties within each customer. Which snippet computes a running total per customer ordered by timestamp then transaction_id, stopping at the current individual row?","options":[{"id":"A","text":"from pyspark.sql.window import Window\nfrom pyspark.sql import functions as F\nw = Window.partitionBy(\"customer_id\").rowsBetween(Window.unboundedPreceding, Window.currentRow)\ndf.withColumn(\"cumulative_spent\", F.sum(\"amount_spent\").over(w))","rationale":"Without an ordering clause, the row frame has no deterministic temporal order.","isCorrect":false},{"id":"B","text":"from pyspark.sql.window import Window\nfrom pyspark.sql import functions as F\nw = Window.orderBy(\"transaction_timestamp\", \"transaction_id\").rowsBetween(Window.unboundedPreceding, Window.currentRow)\ndf.withColumn(\"cumulative_spent\", F.sum(\"amount_spent\").over(w))","rationale":"Without customer partitioning, it mixes different customers into the cumulative total.","isCorrect":false},{"id":"C","text":"from pyspark.sql.window import Window\nfrom pyspark.sql import functions as F\nw = Window.partitionBy(\"customer_id\").orderBy(\"transaction_timestamp\", \"transaction_id\").rowsBetween(Window.unboundedPreceding, Window.currentRow)\ndf.withColumn(\"cumulative_spent\", F.sum(\"amount_spent\").over(w))","rationale":"Customer partitioning, timestamp plus a stable tie-breaker, and a ROWS frame give a deterministic row-by-row running total.","isCorrect":true},{"id":"D","text":"from pyspark.sql.window import Window\nfrom pyspark.sql import functions as F\nw = Window.partitionBy(\"customer_id\").orderBy(\"transaction_timestamp\")\ndf.withColumn(\"cumulative_spent\", F.sum(\"amount_spent\").over(w))","rationale":"The default ordered RANGE frame includes all timestamp peers, rather than stopping at the current individual row.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"Customer partitioning, timestamp plus a stable tie-breaker, and a ROWS frame give a deterministic row-by-row running total.","topic":"window","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/window.html","sourceTitle":"Window — PySpark 4.2.0 documentation","sourcePage":126,"images":["questions/274-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is analyzing transactional data in a PySpark DataFrame df containing customer_id, transaction_timestamp (precise to\nmilliseconds), and amount_spent. The objective is to compute a cumulative sum of amount_spent per customer, strictly ordered by\ntransaction_timestamp. The cumulative sum must include all transactions from the earliest timestamp up to and including the current row,\nrespecting temporal ordering within each customer partition.\nWhich PySpark code snippet most accurately constructs the appropriate window specification and applies the aggregation to yield the correct\ncumulative expenditure per customer?","options":[{"id":"A","text":"[Code choice shown in the original PDF image]"},{"id":"B","text":"[Code choice shown in the original PDF image]"},{"id":"C","text":"[Code choice shown in the original PDF image]"},{"id":"D","text":"[Code choice shown in the original PDF image]"}],"correctAnswers":["C"],"explanation":"Partition by customer, order by timestamp and use ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW. A lacks ordering, B mixes customers, D defaults to a RANGE frame. Add a deterministic tie-breaker when timestamps are equal.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"","reviewNote":"Second audit: Timestamp peers make RANGE and ROWS different; added a stable tie-breaker for deterministic row order.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":275,"prompt":"A data team is implementing an append-only Delta Lake pipeline that needs to handle both and streaming data. They want to ensure that schema\nchanges in the source data can be automatically incorporated without breaking the pipeline.\nWhich configuration should the team use when writing data to the Delta table?","options":[{"id":"A","text":"ignoreChanges = false","rationale":"ignoreChanges is a streaming source option, not writer schema evolution.","isCorrect":false},{"id":"B","text":"validateSchema= false","rationale":"validateSchema=false is not the supported Delta writer setting for this evolution.","isCorrect":false},{"id":"C","text":"overwriteSchema=true","rationale":"overwriteSchema replaces a schema in overwrite workflows, not incremental append evolution.","isCorrect":false},{"id":"D","text":"mergeSchema=true","rationale":"mergeSchema enables supported additive schema evolution during the append write.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"mergeSchema enables supported additive schema evolution during the append write.","topic":"schema","sourceUrl":"https://docs.databricks.com/aws/en/tables/update-schema","sourceTitle":"Update table schemas with schema evolution | Databricks on AWS","sourcePage":126,"images":["questions/275-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data team is implementing an append-only Delta Lake pipeline that needs to handle both and streaming data. They want to ensure that schema\nchanges in the source data can be automatically incorporated without breaking the pipeline.\nWhich configuration should the team use when writing data to the Delta table?","options":[{"id":"A","text":"ignoreChanges = false"},{"id":"B","text":"validateSchema= false"},{"id":"C","text":"overwriteSchema=true"},{"id":"D","text":"mergeSchema=true"}],"correctAnswers":["D"],"explanation":"mergeSchema on the write allows supported additive schema evolution. overwriteSchema replaces a schema during overwrite, and neither ignoreChanges nor a made-up validateSchema switch implements this requirement.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Changes are supported additions of nullable columns already present in the input DataFrame. Ask for the Delta append-writer option; source schema discovery and stream restart handling are configured separately.","reviewNote":"Second audit: mergeSchema supports compatible additive evolution, not every possible schema change or restart-free source evolution.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":276,"prompt":"A team is evaluating Delta Lake together with the Databricks pipeline platform. Which recommendation is incorrect?","options":[{"id":"A","text":"Databricks can ingest JSON/CSV and other sources into Delta tables, whose data files use Parquet.","rationale":"This correctly distinguishes input formats from Delta's Parquet data files.","isCorrect":false},{"id":"B","text":"Delta Lake optimizes metadata handling, efficiently managing billions of files and facilitating scalability to petabyte-scale datasets.","rationale":"Scalable transaction-log metadata handling is a Delta capability, though specific scale still depends on the workload.","isCorrect":false},{"id":"C","text":"Delta Lake’s capability to process data in both batch and streaming modes seamlessly, providing flexibility in data ingestion and\nprocessing.","rationale":"Delta supports both batch and streaming access.","isCorrect":false},{"id":"D","text":"Assume Databricks lacks native pipeline monitoring and troubleshooting, so third-party monitoring tools are always required.","rationale":"Databricks has native pipeline monitoring and troubleshooting; third-party tooling is not always required.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Databricks has native pipeline monitoring and troubleshooting; third-party tooling is not always required.","topic":"ldp","sourceUrl":"https://docs.databricks.com/aws/en/ldp/","sourceTitle":"Spark Declarative Pipelines | Databricks on AWS","sourcePage":127,"images":["questions/276-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":276,"prompt":"A senior data engineer is planning large-scale data workflows. The current task is to identify the considerations that form a foundation for\ncreating scalable data models that are essential for effective management of large datsets. The data engineering team has identified the core\ncapabilities as part of a scalable data model to build a modern data platform and provided their reasoning for considering Delta Lake for review.\nThe senior data engineer is responsible for identifying the recommendations that are not valid.\nWhich key features can be ignored while evaluating Delta Lake?","options":[{"id":"A","text":"Delta Lake works with various data formats (e.g., Parquet, JSON, CSV) and integrates well with Spark and Databricks tools:"},{"id":"B","text":"Delta Lake optimizes metadata handling, efficiently managing billions of files and facilitating scalability to petabyte-scale datasets."},{"id":"C","text":"Delta Lake’s capability to process data in both batch and streaming modes seamlessly, providing flexibility in data ingestion and\nprocessing."},{"id":"D","text":"Delta Lake provides limited support for monitoring and troubleshooting data pipelines, so relevant partner tools have to be identified and\nset up for enhanced operational efficiency."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"best_fit","explanation":"D is the intended false statement: Databricks has substantial native observability. The question loosely conflates Delta with its platform; Delta table data is Parquet, although pipelines can ingest JSON/CSV. Monitoring is not a reason to disregard operational design.","topic":"ldp","sourceUrl":"https://docs.databricks.com/aws/en/ldp/","sourceTitle":"Spark Declarative Pipelines | Databricks on AWS","sourcePage":127,"images":["questions/276-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Separated Delta storage format from source ingestion formats and clarified the false recommendation.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":277,"prompt":"Which Delta table property blocks logical UPDATE and DELETE operations while the property remains enabled? Authorized administrators can change the property; physical file maintenance is outside this question.","options":[{"id":"A","text":"delta.appendOnly = true","rationale":"With delta.appendOnly=true in force, logical updates and deletes are disallowed.","isCorrect":true},{"id":"B","text":"Delta VACUUM","rationale":"VACUUM physically removes obsolete files; it does not prohibit logical row changes.","isCorrect":false},{"id":"C","text":"Delta OPTIMIZE","rationale":"OPTIMIZE reorganizes files while preserving table data, rather than preventing updates and deletes.","isCorrect":false},{"id":"D","text":"Delta Time Travel","rationale":"Time travel reads retained historical versions; it does not make a table immutable.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"With delta.appendOnly=true in force, logical updates and deletes are disallowed.","topic":"properties","sourceUrl":"https://docs.databricks.com/aws/en/tables/table-properties","sourceTitle":"Table properties reference | Databricks on AWS","sourcePage":127,"images":["questions/277-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineering team is implementing an append-only data pipeline using Delta Lake, and wants to ensure that data is never modified or\ndeleted once written.\nWhich Delta Lake feature should the data engineer enable to prevent modifications to existing data?","options":[{"id":"A","text":"Delta APPEND_ONLY"},{"id":"B","text":"Delta VACUUM"},{"id":"C","text":"Delta OPTIMIZE"},{"id":"D","text":"Delta Time Travel"}],"correctAnswers":["A"],"explanation":"Set the Delta table property delta.appendOnly = true. This prevents logical updates/deletes; VACUUM, OPTIMIZE and time travel do not impose an append-only policy. Privileged users can still change the property.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: The property prevents logical updates/deletes while enabled, but is not permanent physical immutability.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":278,"prompt":"A data engineering team is setting up a Git project to automate integration tests using Databricks Asset Bundles and the Git provider’s CI/CD\nfunctionalities. When a pull containing changes to their pipleline is sent, they need to run a Job to test their data pipeline.\nWhat is the correct databricks bundle command sequence to be executed from the Git provider’s CI/CD automation for this task?","options":[{"id":"A","text":"init, deploy, run, validate","rationale":"Validation belongs before deployment; init is not needed for the existing project.","isCorrect":false},{"id":"B","text":"validate, deploy, run","rationale":"Validate the existing bundle, deploy it, then run its test job.","isCorrect":true},{"id":"C","text":"init, validate, deploy, run","rationale":"init creates a bundle project and is unnecessary for every CI run of an existing bundle.","isCorrect":false},{"id":"D","text":"deploy, run, validate","rationale":"Validation after running the deployed job cannot prevent invalid configuration from reaching deployment.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"Validate the existing bundle, deploy it, then run its test job.","topic":"bundles","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes","sourceTitle":"Declarative Automation Bundles deployment modes | Databricks on AWS","sourcePage":127,"images":["questions/278-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineering team is setting up a Git project to automate integration tests using Databricks Asset Bundles and the Git provider’s CI/CD\nfunctionalities. When a pull containing changes to their pipleline is sent, they need to run a Job to test their data pipeline.\nWhat is the correct databricks bundle command sequence to be executed from the Git provider’s CI/CD automation for this task?","options":[{"id":"A","text":"init, deploy, run, validate"},{"id":"B","text":"validate, deploy, run"},{"id":"C","text":"init, validate, deploy, run"},{"id":"D","text":"deploy, run, validate"}],"correctAnswers":["B"],"explanation":"For an existing bundle, validate configuration, deploy resources, then run the test job. init creates a project and is not required on every pull-request CI run.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The repository already contains an initialized and versioned bundle. This is the normal validation/deploy/test sequence on each pull request.","reviewNote":"Second audit: Both init sequences could apply to a new project; this scenario uses an existing bundle.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":279,"prompt":"A batch query runs df.groupBy(\"region\").agg(sum(\"revenue\")). An engineer proposes inserting df.repartition(\"region\") immediately before the aggregation, without reusing the repartitioned data. Which assessment is correct?","options":[{"id":"A","text":"Calling coalesce(1) after aggregation removes all shuffle that already occurred.","rationale":"A later coalesce does not undo exchanges already executed.","isCorrect":false},{"id":"B","text":"Caching df automatically partitions its rows by region and removes the aggregation exchange.","rationale":"Caching does not automatically create the required key distribution.","isCorrect":false},{"id":"C","text":"A broadcast join hint eliminates the shuffle in this query even though there is no join.","rationale":"A broadcast join hint cannot remove an aggregation shuffle in a query with no join.","isCorrect":false},{"id":"D","text":"repartition(\"region\") itself performs a shuffle. It may replace an exchange but does not inherently reduce total shuffle; inspect the physical plan, partial aggregation and measured workload before adding it.","rationale":"An explicit repartition introduces an exchange; evaluate the plan rather than assuming it reduces shuffle.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"An explicit repartition introduces an exchange; evaluate the plan rather than assuming it reduces shuffle.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Apache Spark SQL performance tuning","sourcePage":128,"images":["questions/279-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":279,"prompt":"A data engineer is attempting to execute the following PySpark code:\ndf=spark.read.table(“sales”)\nresult=df.groupBy(“region”).agg(sum(“revenue”))\nHowever, upon inspecting the execution plan and profiling the Spark job, they observe excessive data shuffling during the aggregation phase.\nWhich technique should be applied to reduce shuffling during the groupBy aggregation operation?","options":[{"id":"A","text":"Use.coalesce(1) after the aggregation"},{"id":"B","text":"Caching the DataFrame df"},{"id":"C","text":"Use broadcast join"},{"id":"D","text":"Repartition by region before aggregation"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["D"],"status":"review","explanation":"D is the likely intended answer, but repartition('region') itself shuffles the data. A plain groupBy already performs required key exchange and often partial aggregation; adding repartition does not guarantee less shuffle. No option reliably achieves the claimed optimization without workload evidence.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":128,"images":["questions/279-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Removed the false claim that adding repartition inherently reduces total shuffle.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":280,"prompt":"While reviewing a query’s execution in the Deatricks Query Profile, a data engineer observes that the “Top operators” panel shows a sort operator\nwith high “Time spent” and “Memory peak” metrics, and the Spark UI reports frequent data spilling.\nHow should the data engineering address this issue?","options":[{"id":"A","text":"Repartition the DataFrame to a single partition before sorting.","rationale":"One partition increases the per-task working set and worsens this memory-pressure scenario.","isCorrect":false},{"id":"B","text":"Convert the sort operation to a filter operation.","rationale":"Replacing a required sort with a filter changes the computation.","isCorrect":false},{"id":"C","text":"Switch to a broadcast join to reduce memory usage.","rationale":"A broadcast join does not address this sort and is not part of the stated query.","isCorrect":false},{"id":"D","text":"Increase the number of shuffle partitions to better distribute data.","rationale":"More suitably sized shuffle partitions reduce each sort task's working set in the stated balanced-data scenario.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"More suitably sized shuffle partitions reduce each sort task's working set in the stated balanced-data scenario.","topic":"sparkperf","sourceUrl":"https://spark.apache.org/docs/latest/sql-performance-tuning.html","sourceTitle":"Performance Tuning - Spark 4.2.0 Documentation","sourcePage":128,"images":["questions/280-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"While reviewing a query’s execution in the Deatricks Query Profile, a data engineer observes that the “Top operators” panel shows a sort operator\nwith high “Time spent” and “Memory peak” metrics, and the Spark UI reports frequent data spilling.\nHow should the data engineering address this issue?","options":[{"id":"A","text":"Repartition the DataFrame to a single partition before sorting."},{"id":"B","text":"Convert the sort operation to a filter operation."},{"id":"C","text":"Switch to a broadcast join to reduce memory usage."},{"id":"D","text":"Increase the number of shuffle partitions to better distribute data."}],"correctAnswers":["D"],"explanation":"More shuffle partitions can reduce per-task sort data and memory pressure. One partition concentrates the problem; replacing sort with filter changes semantics and broadcast join does not address a standalone sort.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The sort operates on uniformly oversized shuffle partitions; it is not a skewed single key or a forced single-partition sort. Configure the effective partition count so adaptive coalescing does not undo the change.","reviewNote":"Second audit: More shuffle partitions addresses oversized balanced partitions, not all causes of spill.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":281,"prompt":"A data engineer manages a Unity Catalog table customer_data in schema finance that includes sensitive fields like ssn and credit_score. Intern\nGroup should only see masked values, while Analyst Group should only access rows for their assigned region. The data engineer needs to restrict\naccess based on user role and region without duplicating data.\nHow should the data engineer enforce this security policy?","options":[{"id":"A","text":"Use Unity Catalog’s row filters based on the region and column masks based on user roles.","rationale":"Base-table row filters and masks implement the two policies without copying data.","isCorrect":true},{"id":"B","text":"Create views using current_user() and is_account_group_member() functions, and apply masking logic inside the SQL SELECT clause for\neach sensitive column.","rationale":"A dynamic view can be useful but does not attach enforcement to direct base-table reads as requested.","isCorrect":false},{"id":"C","text":"Create dynamic views for each user role and manage access with ACLs.","rationale":"View-only interfaces do not meet the explicit base-table enforcement requirement.","isCorrect":false},{"id":"D","text":"Use Unity Catalog’s row filters based on the user roles and column masks based on the region.","rationale":"The proposed roles of the region filter and sensitive-column mask are reversed.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"Base-table row filters and masks implement the two policies without copying data.","topic":"masks","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Row filters and column masks | Databricks on AWS","sourcePage":128,"images":["questions/281-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":281,"prompt":"A data engineer manages a Unity Catalog table customer_data in schema finance that includes sensitive fields like ssn and credit_score. Intern\nGroup should only see masked values, while Analyst Group should only access rows for their assigned region. The data engineer needs to restrict\naccess based on user role and region without duplicating data.\nHow should the data engineer enforce this security policy?","options":[{"id":"A","text":"Use Unity Catalog’s row filters based on the region and column masks based on user roles."},{"id":"B","text":"Create views using current_user() and is_account_group_member() functions, and apply masking logic inside the SQL SELECT clause for\neach sensitive column."},{"id":"C","text":"Create dynamic views for each user role and manage access with ACLs."},{"id":"D","text":"Use Unity Catalog’s row filters based on the user roles and column masks based on the region."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Table row filters for region and column masks for role directly enforce the requested policy. Dynamic views can also implement equivalent rules if base-table access is restricted, so B/C are not universally invalid alternatives; A best matches table-native enforcement.","topic":"masks","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Row filters and column masks | Databricks on AWS","sourcePage":128,"images":["questions/281-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"The security policy must be attached directly to the base table and apply when users query that table. A separate view-only interface is not the requested design.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":282,"prompt":"Which Auto Loader option sets a soft 1 GB target for input bytes per microbatch, allowing the target to be exceeded to process whole files?","options":[{"id":"A","text":".option(\"cloudFiles.maxBytesPerTrigger\", \"1g\")","rationale":"maxBytesPerTrigger is the supported soft byte target; a batch can exceed it to process a whole large file.","isCorrect":true},{"id":"B","text":"Configure cloudFiles.maxSizePerTrigger with 1 GB to place a limit.","rationale":"cloudFiles.maxSizePerTrigger is not the supported option.","isCorrect":false},{"id":"C","text":"Configure cloudFiles.maxFilesPerTrigger and estimate the average file size to approximate a size-based throttle of 1 GB.","rationale":"File count times an average cannot reliably target actual input bytes.","isCorrect":false},{"id":"D","text":"Configure cloudFiles.maxPartitionBytes with 1GB to limit data in each partition.","rationale":"cloudFiles.maxPartitionBytes is not the Auto Loader microbatch byte-limit option.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"maxBytesPerTrigger is the supported soft byte target; a batch can exceed it to process a whole large file.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/batch-size","sourceTitle":"Configure Structured Streaming batch size","sourcePage":129,"images":["questions/282-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer us ingesting JSON files from cloud object storage using Databricks Auto Loader. The source folder may occasionally receive large\nfiles of data, which risks overwhelming the stream. To ensure predictable micro-batch sizes, the team wants to throttle ingestion based on the\nvolume of data scanned at 1 GB, regardless of the number of files.\nWhich Auto Loader configuration should the data engineer used to achieve this?","options":[{"id":"A","text":"Configure cloudFiles.maxBytesPerTrigger with 1 GB to place a limit."},{"id":"B","text":"Configure cloudFiles.maxSizePerTrigger with 1 GB to place a limit."},{"id":"C","text":"Configure cloudFiles.maxFilesPerTrigger and estimate the average file size to approximate a size-based throttle of 1 GB."},{"id":"D","text":"Configure cloudFiles.maxPartitionBytes with 1GB to limit data in each partition."}],"correctAnswers":["A"],"explanation":"cloudFiles.maxBytesPerTrigger provides a byte-based soft limit, for example '1g'. It cannot split an oversized file to enforce an absolute one-GB cap; maxFilesPerTrigger controls count instead.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: maxBytesPerTrigger is a soft target, not a hard cap on individual files.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":283,"prompt":"A data company uses Databricks Unity Catalog and has multiple enterprise data sources, including PostgreSQL, Snowflake, and SQL Server. The\ncentral data platform team wants to configure Lakehouse Federation so analysts can query external tables directly in Databricks using Databricks\nSQL, without duplicating data.\nWhich steps are necessary to configure Lakehouse Federation in a secure and governed manner?","options":[{"id":"A","text":"Mirror the external datasets into Delta Lake using Auto Loader, and govern them using Data Lineage and System Tables.","rationale":"Mirroring copies the data and is not federation.","isCorrect":false},{"id":"B","text":"Configure connections and foreign catalog in Unity Catalog, then grant access to foreign catalogs, schemas, and tables using Unity Catalog\npermissions.","rationale":"Connections define external access and foreign catalogs expose the source under Unity Catalog permissions.","isCorrect":true},{"id":"C","text":"Use Partner Connect to create linked datasets, and apply table ACLs at the source system to govern access through Databricks.","rationale":"Partner Connect is not a substitute for configuring federation connections and foreign catalogs.","isCorrect":false},{"id":"D","text":"Create external locations and storage credentials to connect to each database, then register foreign tables in Unity Catalog.","rationale":"Storage credentials and external locations govern object storage, not these database connections.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Connections define external access and foreign catalogs expose the source under Unity Catalog permissions.","topic":"federation","sourceUrl":"https://docs.databricks.com/aws/en/query-federation/","sourceTitle":"Connect to external databases and catalogs | Databricks on AWS","sourcePage":129,"images":["questions/283-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":284,"prompt":"Why are Pandas UDFs often preferred over traditional PySpark UDFs in performance-critical applications involving large datasets?","options":[{"id":"A","text":"They minimize memory usage by streaming each row individually through a lightweight Python wrapper, avoiding batch processing\noverhead.","rationale":"Pandas UDFs use batches rather than this individual-row model.","isCorrect":false},{"id":"B","text":"They leverage Apache Arrow to enable vectorized operations between the JVM and Python runtimes, reducing serialization costs and\nimproving computational efficiency.","rationale":"Arrow-based columnar transfer and vectorized operations can reduce Python processing overhead.","isCorrect":true},{"id":"C","text":"They allow row-level execution of functions in Python with native Spark optimization, removing the need for columnar execution.","rationale":"Arbitrary Python row logic is not automatically optimized as native Spark expressions.","isCorrect":false},{"id":"D","text":"They eliminate the JVM-Python boundary by bypassing serialization entirely, thereby avoiding data conversion overhead.","rationale":"The JVM/Python boundary and data conversion still exist.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Arrow-based columnar transfer and vectorized operations can reduce Python processing overhead.","topic":"pandas","sourceUrl":"https://docs.databricks.com/aws/en/udf/pandas","sourceTitle":"pandas user-defined functions | Databricks on AWS","sourcePage":129,"images":["questions/284-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":285,"prompt":"A data engineer is setting up a pipeline to ingest data from a message bus system that occasionally delivers duplicate messages. The duplicate\nmessages can be a week apart. The target is a Databricks Delta Lake table where each record should appear exactly once.\nWhich Databricks ingestion pattern should be implemented to handle potential duplicates where events can arrive outside of the configured\nwatermark?","options":[{"id":"A","text":"Use Delta Lake’s change data feed to filter duplicate records","rationale":"CDF exposes row changes but does not enforce unique message keys.","isCorrect":false},{"id":"B","text":"Use Delta Lake time travel to identify and remove duplicates","rationale":"Time travel does not enforce uniqueness while writing incoming records.","isCorrect":false},{"id":"C","text":"Use watermark-bounded Structured Streaming dropDuplicatesWithinWatermark on the message key.","rationale":"Watermark-bounded deduplication forgets sufficiently old keys; retaining every key would violate the bounded-state requirement.","isCorrect":false},{"id":"D","text":"Deduplicate incoming keys within foreachBatch, then execute an idempotent insert-only MERGE INTO the retained Delta target by unique message key, using a persistent stream checkpoint.","rationale":"Deduplicate each incoming batch and use an idempotent insert-only MERGE against retained target keys, including duplicates older than the watermark.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Deduplicate each incoming batch and use an idempotent insert-only MERGE against retained target keys, including duplicates older than the watermark.","topic":"merge","sourceUrl":"https://docs.databricks.com/aws/en/delta/merge","sourceTitle":"Upsert into a Delta Lake table using merge | Databricks on AWS","sourcePage":130,"images":["questions/285-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is setting up a pipeline to ingest data from a message bus system that occasionally delivers duplicate messages. The duplicate\nmessages can be a week apart. The target is a Databricks Delta Lake table where each record should appear exactly once.\nWhich Databricks ingestion pattern should be implemented to handle potential duplicates where events can arrive outside of the configured\nwatermark?","options":[{"id":"A","text":"Use Delta Lake’s change data feed to filter duplicate records"},{"id":"B","text":"Use Delta Lake time travel to identify and remove duplicates"},{"id":"C","text":"Configure Structured Streaming with dropDuplicates transformation"},{"id":"D","text":"Implement a write operation using MERGE INTO with a unique key"}],"correctAnswers":["D"],"explanation":"Merge deduplicated incoming records against persistent target keys for deduplication beyond an event-time window. CDF and time travel are not uniqueness enforcement; avoid an indefinitely growing streaming key state when the target can enforce the match logic.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Keep streaming state bounded. Target business keys remain available beyond one week. Each microbatch can contain duplicate keys, and writes can be retried.","reviewNote":"Second audit: Unbounded key deduplication could also work; specified bounded stream state and an idempotent persistent-key strategy.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":286,"prompt":"A data engineer needs to design an efficient pipeline that automatically processes new CSV files as they arrive in S3 storage.\nWhich Databricks feature should the data engineer use to meet these requirements?","options":[{"id":"A","text":"Streaming from cloud storage using standard Spark readStream with format (“csv”) and format (“json”)","rationale":"A generic file stream requires more manual discovery/schema management, and the chained formats do not mean both readers.","isCorrect":false},{"id":"B","text":"COPY INTO SQL command with parameters to track processed files","rationale":"COPY INTO is useful for repeatable batch loading but does not provide this managed continuous Auto Loader design.","isCorrect":false},{"id":"C","text":"Traditional batch processing with scheduled Databricks Jobs","rationale":"Scheduled batch code adds manual discovery, bookkeeping and schema-handling work.","isCorrect":false},{"id":"D","text":"Auto Loader with schema inference and evolution enabled","rationale":"Auto Loader provides scalable incremental file discovery and schema management with a checkpoint and configured restart handling.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Auto Loader provides scalable incremental file discovery and schema management with a checkpoint and configured restart handling.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/","sourceTitle":"What is Auto Loader? | Databricks on AWS","sourcePage":130,"images":["questions/286-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer needs to design an efficient pipeline that automatically processes new CSV files as they arrive in S3 storage.\nWhich Databricks feature should the data engineer use to meet these requirements?","options":[{"id":"A","text":"Streaming from cloud storage using standard Spark readStream with format (“csv”) and format (“json”)"},{"id":"B","text":"COPY INTO SQL command with parameters to track processed files"},{"id":"C","text":"Traditional batch processing with scheduled Databricks Jobs"},{"id":"D","text":"Auto Loader with schema inference and evolution enabled"}],"correctAnswers":["D"],"explanation":"Auto Loader incrementally discovers files and supports schema inference/evolution with checkpointed progress. COPY INTO is useful for batch ingestion but does not by itself continuously watch and run on file arrival.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Choose a scalable ongoing ingestion design with checkpointed discovery and additive schema inference/evolution, minimizing custom file bookkeeping. Configure recovery after source schema additions and a compatible Delta sink.","reviewNote":"Second audit: Ordinary file streams and COPY INTO are alternatives; clarified the high-volume managed-discovery criterion.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":287,"prompt":"A data engineer is implementing liquid clustering on a Delta Lale table and needs to understand how it affects data management operations. The\ntable will be updated frequently with new data. The table is an external table and not managed by Unity Catalog.\nHow does liquid clustering in Delta Lake handle new data that is inserted after the initial table creation?","options":[{"id":"A","text":"New data is rejected if it doesn’t match the clustering pattern.","rationale":"New records are not rejected merely because they are not clustered yet.","isCorrect":false},{"id":"B","text":"New data is automatically clustered during write operations.","rationale":"The stated append does not meet the threshold for clustering on write.","isCorrect":false},{"id":"C","text":"New data is written to a staging area and clustered during scheduled maintenance.","rationale":"The rows are committed to the table, not held in a separate staging area.","isCorrect":false},{"id":"D","text":"New data remains unclustered until the next OPTIMIZE operation.","rationale":"For this below-threshold append, OPTIMIZE subsequently clusters the new data.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"For this below-threshold append, OPTIMIZE subsequently clusters the new data.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":130,"images":["questions/287-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":287,"prompt":"A data engineer is implementing liquid clustering on a Delta Lale table and needs to understand how it affects data management operations. The\ntable will be updated frequently with new data. The table is an external table and not managed by Unity Catalog.\nHow does liquid clustering in Delta Lake handle new data that is inserted after the initial table creation?","options":[{"id":"A","text":"New data is rejected if it doesn’t match the clustering pattern."},{"id":"B","text":"New data is automatically clustered during write operations."},{"id":"C","text":"New data is written to a staging area and clustered during scheduled maintenance."},{"id":"D","text":"New data remains unclustered until the next OPTIMIZE operation."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"Behavior depends on write operation, runtime and batch size. Eligible writes can cluster on write, while smaller/unsupported writes require a later OPTIMIZE. B and D are both overbroad; being external alone does not determine the result.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":130,"images":["questions/287-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Specified a small append below the clustering-on-write threshold, making the result deterministic.","studyContext":"Use a supported external liquid-clustered Delta table. This append is below the applicable clustering-on-write size threshold, and no maintenance has run since it committed.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":288,"prompt":"A data engineer is optimizing a MERGE operation on an 800GB UC-managed table that experiences frequent updates and deletions.\nWhich two actions should the engineer prioritize to improve MERGE performance? (Choose two.)","options":[{"id":"A","text":"Apply liquid clustering using the merge join keys.","rationale":"Liquid clustering on relevant merge keys improves skipping and supports the required evolving layout.","isCorrect":true},{"id":"B","text":"Enable deletion vectors on the table if not already enabled.","rationale":"Deletion vectors reduce immediate rewrites for supported row changes.","isCorrect":true},{"id":"C","text":"Partition the table by date.","rationale":"Date partitions do not match the stated key lookup and unpartitioned design.","isCorrect":false},{"id":"D","text":"Use ZORDER on high-cardinality columns.","rationale":"Z-order cannot be combined with the chosen liquid clustering layout.","isCorrect":false},{"id":"E","text":"Overwrite the table instead of Merge.","rationale":"Overwriting the entire table is not an incremental MERGE optimization.","isCorrect":false}],"selectionCount":2,"correctAnswers":["A","B"],"suggestedAnswers":[],"status":"scoped","explanation":"Liquid clustering on relevant merge keys improves skipping and supports the required evolving layout. Deletion vectors reduce immediate rewrites for supported row changes.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":131,"images":["questions/288-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is optimizing a MERGE operation on an 800GB UC-managed table that experiences frequent updates and deletions.\nWhich two actions should the engineer prioritize to improve MERGE performance? (Choose two.)","options":[{"id":"A","text":"Apply liquid clustering using the merge join keys."},{"id":"B","text":"Enable deletion vectors on the table if not already enabled."},{"id":"C","text":"Partition the table by date."},{"id":"D","text":"Use ZORDER on high-cardinality columns."},{"id":"E","text":"Overwrite the table instead of Merge."}],"correctAnswers":["A","B"],"explanation":"Cluster on relevant merge keys to reduce candidate files and enable deletion vectors to reduce rewrite cost. Unrelated date partitions or ZORDER are not the best combination here; a full overwrite changes the operation's scope.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Keep the table unpartitioned and adopt a layout whose keys can evolve. MERGE predicates use high-cardinality business keys, not date. Select two mutually compatible features on a supported runtime.","reviewNote":"Second audit: Clarified the compatible modern layout pair instead of treating Z-order as universally ineffective.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":289,"prompt":"A data engineer is building a streaming data pipeline to ingest JSON files from cloud storage into a Delta Lake table. The pipeline must process\nfiles incrementally, handle schema evolution automatically, ensure exactly-once processing, and minimize manual infrastructure management.\nHow should the data engineer fulfill these requirements?","options":[{"id":"A","text":"Use Lakeflow Spark Declarative Pipelines with a static DataFrame read, merge schema with spark.conf.set\n(“spark.databricks.delta.schema.autoMerge.enabled”, “true”)","rationale":"A static read is not an incremental file stream.","isCorrect":false},{"id":"B","text":"Use Auto Loader in batch mode with a daily job to overwrite the Delta table.","rationale":"Daily overwrite does not meet incremental streaming or minimal-management requirements.","isCorrect":false},{"id":"C","text":"Create a managed Lakeflow streaming table from Auto Loader (readStream/cloudFiles), with schema inference and cloudFiles.schemaEvolutionMode=\"addNewColumns\"; configure supported additive schema propagation and recovery after schema changes. Let the pipeline manage checkpoints and orchestration.","rationale":"A managed declarative streaming table with Auto Loader provides checkpointing and the specified additive evolution/recovery configuration.","isCorrect":true},{"id":"D","text":"Use traditional Spark Structured Streaming with Auto Loader, manually configuring checkpoints location and enabling schema inference\nwith “mergeSchema”= “true”","rationale":"A manually managed stream adds operations work, and mergeSchema is a sink evolution option rather than source schema inference.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"A managed declarative streaming table with Auto Loader provides checkpointing and the specified additive evolution/recovery configuration.","topic":"autoloader","sourceUrl":"https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/","sourceTitle":"What is Auto Loader? | Databricks on AWS","sourcePage":131,"images":["questions/289-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is building a streaming data pipeline to ingest JSON files from cloud storage into a Delta Lake table. The pipeline must process\nfiles incrementally, handle schema evolution automatically, ensure exactly-once processing, and minimize manual infrastructure management.\nHow should the data engineer fulfill these requirements?","options":[{"id":"A","text":"Use Lakeflow Spark Declarative Pipelines with a static DataFrame read, merge schema with spark.conf.set\n(“spark.databricks.delta.schema.autoMerge.enabled”, “true”)"},{"id":"B","text":"Use Auto Loader in batch mode with a daily job to overwrite the Delta table."},{"id":"C","text":"Use Lakeflow Spart Declarative Pipelines with Auto Loader and enabling schema inference with “cloudFiles.schemaEvolutionMode”=\n“addNewColumns”"},{"id":"D","text":"Use traditional Spark Structured Streaming with Auto Loader, manually configuring checkpoints location and enabling schema inference\nwith “mergeSchema”= “true”"}],"correctAnswers":["C"],"explanation":"Managed declarative pipelines with Auto Loader provide incremental ingestion, managed checkpoints and schema evolution. addNewColumns controls evolution; mergeSchema is a write-side setting rather than source inference.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: Specified the source, sink and schema-change recovery behavior instead of treating one option as the whole pipeline.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":290,"prompt":"The following selective DATE filter is pushed into the Delta scan, but almost all files are read. Which listed metadata problem could explain poor file skipping?","options":[{"id":"A","text":"The Delta table lacks optimization that enables dynamic file pruning.","rationale":"Dynamic join pruning is not necessary for this simple scan predicate's static file skipping.","isCorrect":false},{"id":"B","text":"The filter condition involves a data type that is excluded from data skipping support.","rationale":"DATE columns support file-level data-skipping statistics.","isCorrect":false},{"id":"C","text":"The filter is executed only after the full data scan, which prevents data skipping from taking place.","rationale":"The context explicitly states that the predicate is pushed into the scan.","isCorrect":false},{"id":"D","text":"The Delta log lacks usable file-level min/max statistics for event_date, so the engine cannot exclude files using that predicate.","rationale":"Without usable per-file bounds for event_date, files cannot be eliminated through those bounds.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Without usable per-file bounds for event_date, files cannot be eliminated through those bounds.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":131,"images":["questions/290-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":290,"prompt":"Given the following PySpark code snippet in a Databricks notebook:\nfiltered_df=spark.read.format(“delta”).load(“/mnt/daya/large_table”) \\\n.filter (“event_date> ‘2024-01-01’”)\nfiltered_df.count ()\nThe data engineer notices from the Query Profile that the scan operator for filtered_df is reading almost all files, despite a filter being applied.\nWhat is the probable reason for poor data skipping?","options":[{"id":"A","text":"The Delta table lacks optimization that enables dynamic file pruning."},{"id":"B","text":"The filter condition involves a data type that is excluded from data skipping support."},{"id":"C","text":"The filter is executed only after the full data scan, which prevents data skipping from taking place."},{"id":"D","text":"The event_date column is outside the table’s partitioning and Z-ordering scheme."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":[],"status":"review","explanation":"No option establishes the cause. Weak/missing event_date statistics or a nonselective filter can cause broad scans even without partitioning/ZORDER. D is a possible layout issue, not a prerequisite for skipping; A confuses join-driven dynamic pruning with a literal filter.","topic":"skipping","sourceUrl":"https://docs.databricks.com/aws/en/tables/data-skipping","sourceTitle":"Data skipping | Databricks on AWS","sourcePage":131,"images":["questions/290-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":3,"reviewNote":"Replaced the incorrect partition/ZORDER prerequisite with missing file-level statistics. Second audit: Normalized the executable Python and SQL string quoting.","studyContext":"event_date is a DATE column and the predicate is pushed into the scan. The filter is selective; the question asks for a plausible metadata cause, not a guaranteed diagnosis.","reviewedAt":"2026-10-04","practiceEligible":true,"code":"filtered_df = (spark.read.format(\"delta\").load(\"/mnt/data/large_table\")\n    .filter(\"event_date > DATE '2024-01-01'\"))\nfiltered_df.count()","auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":291,"prompt":"When a new Databricks project starts, the central IP team provisions the required infrastructure using Terraform and a Service Principal. This\nincludes creating a Databricks workspace, a Unity Catalog linked to an External Location, and a Databricks group containing all project team\nmembers. Project teams must store all assets – e.g., tables and volumes, as Managed assets in Unity Catalog. This model hides infrastructure\ncomplexity while giving teams autonomy within their catalog. They can create and manage schemas, tables, volumes, and related objects but\ncannot rename, delete, or change catalog permissions, those remain under IT’s control.\nWhich rights should the project group be granted to enable this model?","options":[{"id":"A","text":"The group needs to have USE CATALOG and USE SCHEMA on the catalog.","rationale":"Usage privileges alone do not grant object creation and data operations.","isCorrect":false},{"id":"B","text":"The group needs to have ALL PRIVILEGES and the MANAGE on the catalog.","rationale":"MANAGE on the catalog permits permission administration that the team must not receive.","isCorrect":false},{"id":"C","text":"The group needs to have ALL PRIVILEGES on the catalog.","rationale":"ALL PRIVILEGES supplies applicable data and creation privileges but excludes catalog MANAGE and ownership; external-location grants are separately withheld.","isCorrect":true},{"id":"D","text":"The group should be made OWNER of the catalog.","rationale":"Catalog ownership permits catalog administration beyond the team's remit.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"ALL PRIVILEGES supplies applicable data and creation privileges but excludes catalog MANAGE and ownership; external-location grants are separately withheld.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":132,"images":["questions/291-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"When a new Databricks project starts, the central IP team provisions the required infrastructure using Terraform and a Service Principal. This\nincludes creating a Databricks workspace, a Unity Catalog linked to an External Location, and a Databricks group containing all project team\nmembers. Project teams must store all assets – e.g., tables and volumes, as Managed assets in Unity Catalog. This model hides infrastructure\ncomplexity while giving teams autonomy within their catalog. They can create and manage schemas, tables, volumes, and related objects but\ncannot rename, delete, or change catalog permissions, those remain under IT’s control.\nWhich rights should the project group be granted to enable this model?","options":[{"id":"A","text":"The group needs to have USE CATALOG and USE SCHEMA on the catalog."},{"id":"B","text":"The group needs to have ALL PRIVILEGES and the MANAGE on the catalog."},{"id":"C","text":"The group needs to have ALL PRIVILEGES on the catalog."},{"id":"D","text":"The group should be made OWNER of the catalog."}],"correctAnswers":["C"],"explanation":"ALL PRIVILEGES supplies applicable catalog/descendant data and creation privileges but excludes MANAGE and ownership. Those exclusions preserve IT's control over catalog grants and lifecycle; USE-only grants are insufficient.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The team has no CREATE EXTERNAL TABLE or CREATE EXTERNAL VOLUME privilege on any external location. IT retains catalog ownership and MANAGE; applicable managed storage is already configured.","reviewNote":"Second audit: External storage rights are separate from catalog privileges.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":292,"prompt":"A data engineer needs to productionize a new Spark application written by teammate. This application has numerous external dependencies,\nincluding libraries, and requires custom environment variables and Spark configuration parameters to be set.\nWhich two methods will help the data engineer accomplish the task? (Choose two.)","options":[{"id":"A","text":"Install libraries on DBFS","rationale":"Merely placing library files on deprecated DBFS storage neither installs nor governs them.","isCorrect":false},{"id":"B","text":"Add libraries to compute policies","rationale":"Compute policies can define supported libraries for consistent installation.","isCorrect":true},{"id":"C","text":"Use secrets in init scripts to store configuration data","rationale":"Storing secrets in init scripts is not a suitable governed configuration or dependency strategy.","isCorrect":false},{"id":"D","text":"Use compute policies to set system properties, environment variables, and Spark configuration parameters.","rationale":"Compute policies can constrain Spark settings and environment variables for repeatable compute.","isCorrect":true},{"id":"E","text":"Create init scripts on DBFS.","rationale":"DBFS-hosted init scripts are not the supported governed deployment approach.","isCorrect":false}],"selectionCount":2,"correctAnswers":["B","D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Compute policies can define supported libraries for consistent installation. Compute policies can constrain Spark settings and environment variables for repeatable compute.","topic":"policies","sourceUrl":"https://docs.databricks.com/aws/en/admin/clusters/policies","sourceTitle":"Create and manage compute policies","sourcePage":132,"images":["questions/292-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":293,"prompt":"A healthcare analytics team is implementing a dimensional model in Delta Lake for patient care analysis. They have a date dimension table and\nare evaluating design options to ensure it supports a wide range of time-based analyses.\nWhich design approach for the date dimension will support efficient time-based querying and aggregation?","options":[{"id":"A","text":"Store the date as string in ISO format (YYYY-MM-DD) for readability.","rationale":"A string date alone lacks the reusable analytical attributes.","isCorrect":false},{"id":"B","text":"Pre-calculate attributes like fiscal_period, quarter, month_name, day_of_week, and holiday.","rationale":"Precomputed calendar and business attributes simplify repeated joins and aggregations.","isCorrect":true},{"id":"C","text":"Store only the date value and calculate all time attributes in queries.","rationale":"Repeatedly computing all attributes adds work and risks inconsistent business-calendar definitions.","isCorrect":false},{"id":"D","text":"Create separate dimension tables for different calendar systems (fiscal, academic, etc.)","rationale":"Separate calendar tables can be useful, but do not replace the requested reusable attributes and add joins.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Precomputed calendar and business attributes simplify repeated joins and aggregations.","topic":"dimensional","sourceUrl":"https://www.databricks.com/glossary/star-schema","sourceTitle":"Star schema","sourcePage":132,"images":["questions/293-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":294,"prompt":"Which snippet persists a 15-day default deleted-file retention interval on my_table? Assume VACUUM uses that default and authorized administrators do not lower or override the setting.","options":[{"id":"A","text":"spark.sql(\"ALTER TABLE my_table SET TBLPROPERTIES ('delta.deletedFileRetentionDuration' = 'interval 15 days')\")","rationale":"The table property sets the default deleted-file retention interval to 15 days.","isCorrect":true},{"id":"B","text":"from delta.tables import DeltaTable\ndeltaTable = DeltaTable.forPath(spark, \"/mnt/data/my_table\")\ndeltaTable.deletedFileRetentionDuration = \"interval 15 days\"","rationale":"Assigning an attribute on a Python DeltaTable object does not alter the persisted table property.","isCorrect":false},{"id":"C","text":"spark.sql(\"VACUUM my_table RETAIN HOURS\")","rationale":"The VACUUM statement is incomplete and would not set a persistent retention property.","isCorrect":false},{"id":"D","text":"spark.conf.set(\"spark.databricks.delta.deletedFileRetemtionDuration\", \"15 days\")","rationale":"The misspelled Spark configuration is not the table retention property.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"The table property sets the default deleted-file retention interval to 15 days.","topic":"vacuum","sourceUrl":"https://docs.databricks.com/aws/en/tables/operations/vacuum","sourceTitle":"Remove unused data files with vacuum | Databricks on AWS","sourcePage":133,"images":["questions/294-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is tasked with ensuring that a Delta table in Databricks continuously retains deleted files for 15 days (instead of the default 7\ndays), in order to permanently comply with the organization’s data retention policy.\nWhich code snippet correctly sets this retention period for deleted files?","options":[{"id":"A","text":"spark.sql(“ALTER TABLE my_table SET TBLPROPERTIES (‘delta.deletedFileRetentionDuration’ = ‘interval 15 days’)”)"},{"id":"B","text":"[Code choice shown in the original PDF image]"},{"id":"C","text":"spark.sql(“VACUUM my_table RETAIN HOURS”)"},{"id":"D","text":"spark.conf.set(“spark.databricks.delta.deletedFileRetemtionDuration”, “15 days”)"}],"correctAnswers":["A"],"explanation":"delta.deletedFileRetentionDuration is a persistent table property with an interval value. A one-off VACUUM clause is not the table policy; assigning an arbitrary Python attribute or misspelled Spark setting does not change it.","hasEmbeddedCode":true,"code":null,"status":"confirmed"},"code":"","reviewNote":"Second audit: A retention setting is not an immutable compliance guarantee; corrected code quotation.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":295,"prompt":"A Data Engineer is building a fraud detection pipeline that calls out to Open AI, via a Python library, and needs to include an access token when\nusing the API.\nWhich Databricks CLI command should the Data Engineer use to create the secret?","options":[{"id":"A","text":"databricks secrets put-secret KEY SCOPE; dbutils.secrets.get (KEY, SCOPE)","rationale":"The secret scope and key arguments are reversed.","isCorrect":false},{"id":"B","text":"databricks tokens put-token SCOPE KEY; dbutils.tokens.get (SCOPE, KEY)","rationale":"The proposed tokens commands are not the secret storage/retrieval interfaces.","isCorrect":false},{"id":"C","text":"databricks secrets put-secret SCOPE KEY; dbutils.secrets.get (SCOPE, KEY)","rationale":"Create the secret with CLI scope then key, and retrieve it separately in the notebook with dbutils.secrets.get(scope, key).","isCorrect":true},{"id":"D","text":"databricks tokens put-token KEY SCOPE; dbutils.secrets.get (KEY, SCOPE)","rationale":"This is neither the correct secret command nor the correct retrieval argument order.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Create the secret with CLI scope then key, and retrieve it separately in the notebook with dbutils.secrets.get(scope, key).","topic":"secretcli","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/cli/reference/secrets-commands","sourceTitle":"secrets command group | Databricks on AWS","sourcePage":133,"images":["questions/295-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A Data Engineer is building a fraud detection pipeline that calls out to Open AI, via a Python library, and needs to include an access token when\nusing the API.\nWhich Databricks CLI command should the Data Engineer use to create the secret?","options":[{"id":"A","text":"databricks secrets put-secret KEY SCOPE; dbutils.secrets.get (KEY, SCOPE)"},{"id":"B","text":"databricks tokens put-token SCOPE KEY; dbutils.tokens.get (SCOPE, KEY)"},{"id":"C","text":"databricks secrets put-secret SCOPE KEY; dbutils.secrets.get (SCOPE, KEY)"},{"id":"D","text":"databricks tokens put-token KEY SCOPE; dbutils.secrets.get (KEY, SCOPE)"}],"correctAnswers":["C"],"explanation":"The CLI syntax is secrets put-secret SCOPE KEY, and retrieval uses dbutils.secrets.get(scope, key). The tokens command group manages authentication tokens rather than secret-scope values.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"In each choice, the CLI command runs in the terminal and the dbutils expression runs separately in the notebook. The scope exists and both identities have the required permissions.","reviewNote":"Second audit: Distinguished the terminal CLI operation from notebook retrieval.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":296,"prompt":"A company has a task management system that tracks the most recent status of tasks. The system takes task events as input and processes\nevents in near real-time using Lakeflow Spark Declarative Pipelines. A new task event is ingested into the system when a task is created or the\nstatus is changed. Lakeflow Spark Declarative Pipelines provides a streaming table (table name: tasks_status) for the BI users to query. The table\nrepresents the latest status of all tasks and includes 5 columns: task_id(unique for each task), task_name, task_owner, task_status,\ntask_event_time. The table enables 3 properties: deletion vectors, row tracking, and change data feed.\nA data engineer is asked to create a new Lakeflow Spark Declarative Pipelines to enrich the “task_status” table in near real-time by adding one\nadditional column representing task_owner’s department, which can be looked up from a static dimension table (table name: employee).\nHow should this enrichment be implemented?","options":[{"id":"A","text":"Stream tasks_status CDF with readChangeFeed, discard update_preimage rows, enrich against the fixed employee dimension, then apply keyed and _commit_version-sequenced AUTO CDC (formerly apply_changes) into a streaming SCD Type 1 target, using _change_type = delete for apply_as_deletes.","rationale":"Read CDF, join the dimension, discard preimages and apply keyed sequenced updates/deletes to maintain the current enriched state.","isCorrect":true},{"id":"B","text":"Create a new Lakeflow Spark Declarative pipeline: use the readStream()function to read tasks_status table, enrich with the employee table;\nstore the result in a new streaming table.","rationale":"A plain append-oriented Delta stream cannot faithfully propagate source row updates and deletes.","isCorrect":false},{"id":"C","text":"Create a new Lakeflow Spark Declarative Pipeline: use the readStream() function with the option skipChangeCommits to read the\ntasks_status table; enrich with the employee table; store the result in a new streaming table.","rationale":"skipChangeCommits skips affected commits and therefore misses required changes.","isCorrect":false},{"id":"D","text":"Create a new Lakeflow Spark Declarative Pipeline: use the read () function to read tasks_status table; enrich with employee table; store the\nresult in a materialized view.","rationale":"A materialized view refresh does not meet the explicit streaming CDC output contract.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"Read CDF, join the dimension, discard preimages and apply keyed sequenced updates/deletes to maintain the current enriched state.","topic":"autocdc","sourceUrl":"https://docs.databricks.com/aws/en/ldp/developer/ldp-python-ref-apply-changes","sourceTitle":"create_auto_cdc_flow","sourcePage":133,"images":["questions/296-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":296,"prompt":"A company has a task management system that tracks the most recent status of tasks. The system takes task events as input and processes\nevents in near real-time using Lakeflow Spark Declarative Pipelines. A new task event is ingested into the system when a task is created or the\nstatus is changed. Lakeflow Spark Declarative Pipelines provides a streaming table (table name: tasks_status) for the BI users to query. The table\nrepresents the latest status of all tasks and includes 5 columns: task_id(unique for each task), task_name, task_owner, task_status,\ntask_event_time. The table enables 3 properties: deletion vectors, row tracking, and change data feed.\nA data engineer is asked to create a new Lakeflow Spark Declarative Pipelines to enrich the “task_status” table in near real-time by adding one\nadditional column representing task_owner’s department, which can be looked up from a static dimension table (table name: employee).\nHow should this enrichment be implemented?","options":[{"id":"A","text":"Create a new Lakeflow Spark Declarative Pipelines: use readStream() function with option readChangeFeed to read tasks_status table CDF;\nenrich with the employee table; create a new streaming table as the result table and use apply_changes() function to process the changes\nfrom the enriched CDF."},{"id":"B","text":"Create a new Lakeflow Spark Declarative pipeline: use the readStream()function to read tasks_status table, enrich with the employee table;\nstore the result in a new streaming table."},{"id":"C","text":"Create a new Lakeflow Spark Declarative Pipeline: use the readStream() function with the option skipChangeCommits to read the\ntasks_status table; enrich with the employee table; store the result in a new streaming table."},{"id":"D","text":"Create a new Lakeflow Spark Declarative Pipeline: use the read () function to read tasks_status table; enrich with employee table; store the\nresult in a materialized view."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Read the changing source's CDF, enrich it and apply keyed, sequenced changes to the target. A plain stream or skipChangeCommits loses update/delete semantics. A refreshed materialized view can also maintain a joined snapshot, so D is viable if its refresh latency meets the requirement.","topic":"autocdc","sourceUrl":"https://docs.databricks.com/aws/en/ldp/developer/ldp-python-ref-apply-changes","sourceTitle":"create_auto_cdc_flow","sourcePage":133,"images":["questions/296-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":3,"reviewNote":"The answer is scored within the explicit context shown with this question. Second audit: CDF propagation requires delete handling and must discard update preimages.","studyContext":"The output must be a streaming table that propagates source inserts, updates and deletes continuously; the employee dimension is fixed during the exercise. A scheduled materialized-view refresh does not meet this contract. Use task_id as the key. There is at most one final change per task per Delta commit, so _commit_version orders events; retain CDF long enough for recovery.","reviewedAt":"2026-10-04","practiceEligible":true,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":297,"prompt":"A DataFrame df has a user_email column. For a pseudonymization exercise, replace that column with a deterministic SHA-256 digest so repeated emails still match, without keeping an additional plaintext email column. This is not a guarantee of irreversible anonymization. After importing pyspark.sql.functions as F, which expression meets this coding requirement?","options":[{"id":"A","text":"df.withColumn(\"user_emai\", F.expr(\"uuid()\"))","rationale":"It changes a misspelled column and UUIDs are not a deterministic email digest.","isCorrect":false},{"id":"B","text":"df.withColumn(\"user_email\", F.sha2(\"user_email\", 256))","rationale":"sha2 with 256 produces a deterministic SHA-256 digest in the original column.","isCorrect":true},{"id":"C","text":"df.withColumn(\"hashed_email\", F.sha2(\"user_email\", 256))","rationale":"This leaves the original plaintext email column in the DataFrame.","isCorrect":false},{"id":"D","text":"df.withColumn(\"user_email\", F.regexp_replace(\"user_email\", \"@.*\", \"@anonymized.com\"))","rationale":"Domain replacement is not a SHA-256 digest and still exposes the local part.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"sha2 with 256 produces a deterministic SHA-256 digest in the original column.","topic":"hash","sourceUrl":"https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.functions.sha2.html","sourceTitle":"PySpark sha2 signature","sourcePage":134,"images":["questions/297-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":297,"prompt":"A data engineer is reviewing the PySpark code to copy a part of the production dataset to the sandbox environment, and needs to be sure that no\nPII(Personally Identifiable Information) data is being copied. After checking the sales table, the data engineer notices that it has user emails as\nthe only PII data included as well as being the only column to identify the user.\nfrom pyspark.sql import functions as F\nWhich anonymised code should be used to achieve the required outcome?","options":[{"id":"A","text":"df.withColumn (“user_emai”, F.expr(“uuid()”))"},{"id":"B","text":"df.withColumn (“user_email”, F.sha2 (“user_email”))"},{"id":"C","text":"df.withColumn (“hashed_email”, sha2 (“user_email”))"},{"id":"D","text":"df.withColumn (“user_email”, F.regexp_replace (“user_eamail”, “@*”, “@anonymized.com”))"}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["B"],"status":"review","explanation":"None is correct as printed. B intends to replace the email with a hash but PySpark sha2 requires numBits: F.sha2('user_email', 256). A uses a misspelled output column, C retains the raw email and D is malformed. Unsalted email hashes are pseudonyms, not guaranteed anonymization.","topic":"hash","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/functions/sha2","sourceTitle":"sha2 function | Databricks on AWS","sourcePage":134,"images":["questions/297-1.png"],"hasEmbeddedCode":true,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected the sha2 signature and changed the claim from guaranteed anonymization to deterministic pseudonymization.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":298,"prompt":"A data engineer wants to ingest a large collection of image files (JPEG and PNG) from cloud object storage into Unity Catalog-managed table for\nfurther analysis and visualization.\nWhich two configurations and practices are recommended to incrementally ingest these images into the table? (Choose two.)","options":[{"id":"A","text":"Use Auto loader and set cloudFiles.format to \"TEXT\"","rationale":"TEXT is not the binary file ingestion format.","isCorrect":false},{"id":"B","text":"Use Auto Loader with cloudFiles.format set to \"binaryFile\".","rationale":"binaryFile ingests each image's bytes and file metadata incrementally through Auto Loader.","isCorrect":true},{"id":"C","text":"Use Auto loader and set cloudFiles.format to \"IMAGE\"","rationale":"IMAGE is not the supported Auto Loader format for this binary ingestion pattern.","isCorrect":false},{"id":"D","text":"Use pathGlobFilter to select supported image filename extensions, for example \"*.{jpg,jpeg,png}\".","rationale":"A supported glob filters filenames to the desired extensions; this is filename filtering, not content validation.","isCorrect":true},{"id":"E","text":"Move files to a volume and read with SQL editor","rationale":"Moving files to a volume and opening the SQL editor is not incremental binary ingestion into a table.","isCorrect":false}],"selectionCount":2,"correctAnswers":["B","D"],"suggestedAnswers":[],"status":"corrected","explanation":"binaryFile ingests each image's bytes and file metadata incrementally through Auto Loader. A supported glob filters filenames to the desired extensions; this is filename filtering, not content validation.","topic":"binary","sourceUrl":"https://docs.databricks.com/aws/en/spark/api-options","sourceTitle":"Spark API options reference | Databricks on AWS","sourcePage":134,"images":["questions/298-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":298,"prompt":"A data engineer wants to ingest a large collection of image files (JPEG and PNG) from cloud object storage into Unity Catalog-managed table for\nfurther analysis and visualization.\nWhich two configurations and practices are recommended to incrementally ingest these images into the table? (Choose two.)","options":[{"id":"A","text":"Use Auto loader and set cloudFiles.format to \"TEXT\""},{"id":"B","text":"Use Auto loader and set cloudFiles.format to \"BINARYFILE\""},{"id":"C","text":"Use Auto loader and set cloudFiles.format to \"IMAGE\""},{"id":"D","text":"Use the pathGlobFilter option to select only image files (e.g.. \"*.jpg, *.png\")"},{"id":"E","text":"Move files to a volume and read with SQL editor"}],"selectionCount":2,"correctAnswers":["B","D"],"suggestedAnswers":[],"status":"best_fit","explanation":"Use Auto Loader binaryFile plus an image path filter. Use a valid glob such as '*.{jpg,jpeg,png}', not the literal comma-separated example. IMAGE is not the supported Auto Loader format here; text decoding does not preserve image bytes.","topic":"binary","sourceUrl":"https://docs.databricks.com/aws/en/spark/api-options","sourceTitle":"Spark API options reference | Databricks on AWS","sourcePage":134,"images":["questions/298-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Replaced the invalid comma-separated filename pattern with a valid glob.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":299,"prompt":"A data engineer is configuring Delta Sharing for a Databricks-to-Databricks scenario to optimize read performance. The recipient needs to perform\ntime travel queries and streaming reads on shared sales data.\nWhich configuration will provide the optimal performance while enabling these capabilities?","options":[{"id":"A","text":"Use the open sharing protocol instead of Databricks-to Databricks sharing for better performance.","rationale":"Switching to open sharing does not provide the claimed performance advantage.","isCorrect":false},{"id":"B","text":"Share tables WITHOUT HISTORY and enable partitioning for better query performance.","rationale":"WITHOUT HISTORY cannot provide the requested historical/streaming access.","isCorrect":false},{"id":"C","text":"Share the Delta table WITH HISTORY without a share partition filter; enable change data feed before the required changes are generated, and use a supported recipient runtime/connector.","rationale":"WITH HISTORY and the supported reader/CDF configuration supply the required capabilities without a restrictive share partition filter.","isCorrect":true},{"id":"D","text":"Share the entire schema WITHOUT HISTORY and rely on recipient-side caching for performance.","rationale":"Caching cannot restore history that was not shared.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"corrected","explanation":"WITH HISTORY and the supported reader/CDF configuration supply the required capabilities without a restrictive share partition filter.","topic":"sharing","sourceUrl":"https://docs.databricks.com/aws/en/opensharing","sourceTitle":"What is OpenSharing? | Databricks on AWS","sourcePage":134,"images":["questions/299-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":299,"prompt":"A data engineer is configuring Delta Sharing for a Databricks-to-Databricks scenario to optimize read performance. The recipient needs to perform\ntime travel queries and streaming reads on shared sales data.\nWhich configuration will provide the optimal performance while enabling these capabilities?","options":[{"id":"A","text":"Use the open sharing protocol instead of Databricks-to Databricks sharing for better performance."},{"id":"B","text":"Share tables WITHOUT HISTORY and enable partitioning for better query performance."},{"id":"C","text":"Share tables WITH HISTORY, ensure tables don't have partitioning enabled. and enable CDF before sharing."},{"id":"D","text":"Share the entire schema WITHOUT HISTORY and rely on recipient-side caching for performance."}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"best_fit","explanation":"WITH HISTORY enables historical/streaming access, and CDF is needed to read row changes. Unpartitioned tables can improve some sharing optimizations, but are not a universal requirement; the question overstates that part.","topic":"sharing","sourceUrl":"https://docs.databricks.com/aws/en/opensharing","sourceTitle":"What is OpenSharing? | Databricks on AWS","sourcePage":134,"images":["questions/299-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Removed the unsupported requirement that the table be unpartitioned; distinguished partition filters from partitioned storage.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":300,"prompt":"A data organization has adopted Delta Sharing to securely distribute curated datasets from a Unity Catalog-enabled workspace. The data\nengineering team is sharing large Delta tables with an internal partner via Databricks-to-Databricks and aggregated reports with an external client\nvia Open Sharing. While testing new sharing workflows, the data engineering team encounters challenges related to access control, data update\nvisibility, and shareable object types.\nWhat is a limitation of the Delta Sharing protocol or implementation when used with Databricks-to-Databricks or Open Sharing?","options":[{"id":"A","text":"Delta Sharing does not support Unity Catalog enabled tables; only legacy Hive Metastore tables are shareable.","rationale":"Unity Catalog tables are supported and central to governed Delta Sharing.","isCorrect":false},{"id":"B","text":"With Databricks-to-Databricks sharing. Unity Catalog recipients must re-ingest data manually using COPY INTO or REST APIs.","rationale":"Databricks recipients can query shared tables without manually re-ingesting them.","isCorrect":false},{"id":"C","text":"Delta Sharing (both Databricks-to-Databricks and Open sharing) allows recipients to modify the source data if they have SELECT privileges.","rationale":"SELECT on shared data does not authorize modifying the provider's source table.","isCorrect":false},{"id":"D","text":"Databricks-to-Open sharing does not support notebook, Unity Catalog volume or model sharing available in Databricks-to-Databricks sharing. Supported table data can change; it is not restricted to frozen snapshots.","rationale":"Open sharing has a narrower set of shareable objects; shared table data is not limited to a permanently frozen snapshot.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"Open sharing has a narrower set of shareable objects; shared table data is not limited to a permanently frozen snapshot.","topic":"sharing","sourceUrl":"https://docs.databricks.com/aws/en/opensharing/","sourceTitle":"Sharing protocol capabilities and recipient access","sourcePage":135,"images":["questions/300-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":300,"prompt":"A data organization has adopted Delta Sharing to securely distribute curated datasets from a Unity Catalog-enabled workspace. The data\nengineering team is sharing large Delta tables with an internal partner via Databricks-to-Databricks and aggregated reports with an external client\nvia Open Sharing. While testing new sharing workflows, the data engineering team encounters challenges related to access control, data update\nvisibility, and shareable object types.\nWhat is a limitation of the Delta Sharing protocol or implementation when used with Databricks-to-Databricks or Open Sharing?","options":[{"id":"A","text":"Delta Sharing does not support Unity Catalog enabled tables; only legacy Hive Metastore tables are shareable."},{"id":"B","text":"With Databricks-to-Databricks sharing. Unity Catalog recipients must re-ingest data manually using COPY INTO or REST APIs."},{"id":"C","text":"Delta Sharing (both Databricks-to-Databricks and Open sharing) allows recipients to modify the source data if they have SELECT privileges."},{"id":"D","text":"With Open sharing, recipients cannot access Volumes, Models, or notebooks — only static Delta tables are supported."}],"selectionCount":1,"correctAnswers":[],"suggestedAnswers":["D"],"status":"review","explanation":"D is the closest intended capability distinction, but 'only static Delta tables' is too restrictive: open sharing can expose updated Delta data and supported history/CDF/streaming functionality. Other choices are false. Rewrite the limitations before scoring.","topic":"sharing","sourceUrl":"https://docs.databricks.com/aws/en/opensharing","sourceTitle":"What is OpenSharing? | Databricks on AWS","sourcePage":135,"images":["questions/300-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Removed the inaccurate static-only claim while retaining the documented protocol distinction.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":301,"prompt":"A data engineer is creating a daily reporting Job. There are two reporting notebooks one for weekdays and the other for weekends. An \"If/else\ncondition\" task is configured as \"{{job.start_time.is_weekday}} == true\" to route the job to either weekday or weekend notebook tasks. The same\njob would be used in multiple time zones.\nWhich action should a senior data engineer take upon reviewing the job to merge or reject the pull request?","options":[{"id":"A","text":"Reject. As they should use {{job.trigger_time.is_weekday}} instead.","rationale":"Changing the reference to this trigger_time name is not the timezone fix.","isCorrect":false},{"id":"B","text":"Reject. As the {{job.start_time.is_weekday}} is not a valid value reference.","rationale":"job.start_time.is_weekday is a supported dynamic value reference.","isCorrect":false},{"id":"C","text":"Reject. As the {{job.start_time.is_weekday}} is for the UTC timezone.","rationale":"Its weekday is derived in UTC, so local business weekday routing needs explicit timezone handling.","isCorrect":true},{"id":"D","text":"Merge. As the job configuration looks good.","rationale":"UTC weekday routing does not satisfy differing local timezone calendars without adjustment.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Its weekday is derived in UTC, so local business weekday routing needs explicit timezone handling.","topic":"dynamicvalues","sourceUrl":"https://docs.databricks.com/aws/en/jobs/dynamic-value-references","sourceTitle":"Dynamic value references | Databricks on AWS","sourcePage":135,"images":["questions/301-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is creating a daily reporting Job. There are two reporting notebooks one for weekdays and the other for weekends. An \"If/else\ncondition\" task is configured as \"{{job.start_time.is_weekday}} == true\" to route the job to either weekday or weekend notebook tasks. The same\njob would be used in multiple time zones.\nWhich action should a senior data engineer take upon reviewing the job to merge or reject the pull request?","options":[{"id":"A","text":"Reject. As they should use {{job.trigger_time.is_weekday}} instead."},{"id":"B","text":"Reject. As the {{job.start_time.is_weekday}} is not a valid value reference."},{"id":"C","text":"Reject. As the {{job.start_time.is_weekday}} is for the UTC timezone."},{"id":"D","text":"Merge. As the job configuration looks good."}],"correctAnswers":["C"],"explanation":"job.start_time.is_weekday is valid but evaluated using UTC. It does not automatically follow each business timezone; derive the local business date explicitly when routing across regions.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Weekday/weekend routing must follow each deployment’s local business timezone, including runs near UTC date boundaries.","reviewNote":"Second audit: Made the local-calendar requirement explicit.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":302,"prompt":"How are the operational aspects of Lakeflow Spark Declarative Pipelines from Spark Structured Streaming different?","options":[{"id":"A","text":"Lakeflow Spark Declarative Pipelines automatically handle schema evolution, while Structured Streaming always requires manual schema\nmanagement.","rationale":"Schema evolution is configurable in both; Structured Streaming does not always require manual changes.","isCorrect":false},{"id":"B","text":"Structured Streaming can process continuous data streams, while Lakeflow Spark Declarative Pipelines cannot.","rationale":"Declarative pipelines can process streaming data.","isCorrect":false},{"id":"C","text":"Lakeflow Spark Declarative Pipelines manage the orchestration of multi-stage pipelines automatically, while Structured Streaming requires\nexternal orchestration for complex dependencies.","rationale":"Declarative pipelines manage the dependency graph and orchestration that a standalone multi-query streaming application must arrange.","isCorrect":true},{"id":"D","text":"Lakeflow Spark Declarative Pipelines can write to Delta Lake format while structured streaming cannot.","rationale":"Structured Streaming can write Delta tables.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"Declarative pipelines manage the dependency graph and orchestration that a standalone multi-query streaming application must arrange.","topic":"ldp","sourceUrl":"https://docs.databricks.com/aws/en/ldp/","sourceTitle":"Spark Declarative Pipelines | Databricks on AWS","sourcePage":135,"images":["questions/302-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":303,"prompt":"A workspace admin has created a new catalog called ‘finance_data’ and wants to delegate permission management to a finance team lead\nwithout giving them full admin rights.\nWhich privilege should be granted to the finance team lead?","options":[{"id":"A","text":"GRANT_OPTION privilege on the finance_data catalog.","rationale":"GRANT_OPTION is not the requested Unity Catalog privilege.","isCorrect":false},{"id":"B","text":"Make the finance team lead a metastore admin.","rationale":"Metastore administration grants far more authority than catalog permission management.","isCorrect":false},{"id":"C","text":"MANAGE privilege on the finance_data catalog.","rationale":"MANAGE allows permission management on the catalog without metastore administrator rights.","isCorrect":true},{"id":"D","text":"ALL PRIVILEGES on the finance_data catalog.","rationale":"ALL PRIVILEGES excludes MANAGE and does not provide this delegation by itself.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"MANAGE allows permission management on the catalog without metastore administrator rights.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":136,"images":["questions/303-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":304,"prompt":"A data engineer is configuring a Lakeflow Spark Declarative Pipelines to process CDC data from a source. The source events sometimes arrive out\nof order, and multiple updates may occur with the same update_timestamp but with different update_sequence_id.\nWhat should the data engineer do to ensure events are sequenced correctly?","options":[{"id":"A","text":"Use SEQUENCE BY STRUCT(update_timestamp, update_sequence_id) in AUTO CDC.","rationale":"A STRUCT orders by timestamp and then the sequence ID, resolving timestamp ties.","isCorrect":true},{"id":"B","text":"Set track history column list to [event timestamp, event id] in AUTO CDC APIs.","rationale":"Tracked history columns control SCD history recording, not CDC event order.","isCorrect":false},{"id":"C","text":"Use dropduplicate() to remove out-of-order and duplicate records in LDP.","rationale":"Dropping duplicates does not establish which conflicting event is latest.","isCorrect":false},{"id":"D","text":"Use a window function to sort update_sequence_id within the same partition, i.e., update_timestamp in the LDP pipeline.","rationale":"A window sort alone is not AUTO CDC's persistent sequence ordering across incoming batches.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"corrected","explanation":"A STRUCT orders by timestamp and then the sequence ID, resolving timestamp ties.","topic":"autocdc","sourceUrl":"https://docs.databricks.com/aws/en/ldp/developer/ldp-python-ref-apply-changes","sourceTitle":"create_auto_cdc_flow","sourcePage":136,"images":["questions/304-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":304,"prompt":"A data engineer is configuring a Lakeflow Spark Declarative Pipelines to process CDC data from a source. The source events sometimes arrive out\nof order, and multiple updates may occur with the same update_timestamp but with different update_sequence_id.\nWhat should the data engineer do to ensure events are sequenced correctly?","options":[{"id":"A","text":"Use SEQUENCE BY STRUCT(event_timestamp, update_sequence_id) in AUTO CDC APIs."},{"id":"B","text":"Set track history column list to [event timestamp, event id] in AUTO CDC APIs."},{"id":"C","text":"Use dropduplicate() to remove out-of-order and duplicate records in LDP."},{"id":"D","text":"Use a window function to sort update_sequence_id within the same partition, i.e., update_timestamp in the LDP pipeline."}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"best_fit","explanation":"Use a composite sequence such as STRUCT(update_timestamp, update_sequence_id) to break timestamp ties. The option uses event_timestamp instead of the field named in the stem; use the actual source column. History tracking or dropping records does not order CDC events.","topic":"autocdc","sourceUrl":"https://docs.databricks.com/aws/en/ldp/developer/ldp-python-ref-apply-changes","sourceTitle":"create_auto_cdc_flow","sourcePage":136,"images":["questions/304-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Aligned the sequence expression with the timestamp column named in the question.","studyContext":"","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":305,"prompt":"A streaming video analytics team ingests billions of events daily into a Unity Catalog-managed Delta table video_events. Analysts run ad-hoc\npoint-lookup queries on columns like user_id, campaign_id, and region. The team manually runs OPTIMIZE video_events Z-ORDER user_id,\ncampaign_id, region, but still sees poor performance on recent data, and dislikes the operational overhead. The team wants a hands-off way to\nkeep hot columns co-located as query patterns evolve.\nWhich Delta capability should the team leverage on video_events?","options":[{"id":"A","text":"Enable auto-compaction (optimizeWrite & autoCompact).","rationale":"Compaction reduces file count but does not adapt clustering keys to query patterns.","isCorrect":false},{"id":"B","text":"Schedule OPTIMIZE/ZORDER to run after each job to improve recent file performance.","rationale":"Manually scheduled Z-order retains the maintenance overhead the team wants to remove.","isCorrect":false},{"id":"C","text":"Utilize Liquid Clustering CLUSTER BY AUTO and Predictive Optimization.","rationale":"Automatic liquid clustering with predictive optimization selects and maintains useful clustering keys on eligible managed tables.","isCorrect":true},{"id":"D","text":"Enable Delta caching.","rationale":"Caching does not reorganize file layout or adapt clustering keys.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Automatic liquid clustering with predictive optimization selects and maintains useful clustering keys on eligible managed tables.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":136,"images":["questions/305-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A streaming video analytics team ingests billions of events daily into a Unity Catalog-managed Delta table video_events. Analysts run ad-hoc\npoint-lookup queries on columns like user_id, campaign_id, and region. The team manually runs OPTIMIZE video_events Z-ORDER user_id,\ncampaign_id, region, but still sees poor performance on recent data, and dislikes the operational overhead. The team wants a hands-off way to\nkeep hot columns co-located as query patterns evolve.\nWhich Delta capability should the team leverage on video_events?","options":[{"id":"A","text":"Enable auto-compaction (optimizeWrite & autoCompact)."},{"id":"B","text":"Schedule OPTIMIZE/ZORDER to run after each job to improve recent file performance."},{"id":"C","text":"Utilize Liquid Clustering CLUSTER BY AUTO and Predictive Optimization."},{"id":"D","text":"Enable Delta caching."}],"correctAnswers":["C"],"explanation":"CLUSTER BY AUTO with predictive optimization selects and maintains useful clustering keys for a supported UC managed table. Compaction controls file size; disk cache or periodic manual ZORDER does not automatically adapt the layout keys.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Use an eligible Unity Catalog managed Delta table, supported runtime, and predictive optimization enabled; migrate any incompatible partitioned/Z-order layout first.","reviewNote":"Second audit: Automatic clustering and predictive optimization require eligible managed tables.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":306,"prompt":"A data engineer is designing a data pipeline in Databricks that needs to process records from a Kafka stream where late-arriving data common.\nWhich approach should the data engineer use?","options":[{"id":"A","text":"Use a watermark to specify the allowed lateness to accommodate records that arrive after their expected window, ensuring correct\naggregation and state management.","rationale":"An event-time watermark supports bounded state and handling of late data within the configured guarantee.","isCorrect":true},{"id":"B","text":"Use an Auto CDC pipeline with batch tables to simplify late data handling.","rationale":"Batch CDC sequencing is not this windowed stream aggregation design.","isCorrect":false},{"id":"C","text":"Implement a custom solution using Databricks Jobs to periodically reprocess all historical data","rationale":"Repeated full-history reprocessing adds high latency and cost.","isCorrect":false},{"id":"D","text":"Use batch processing and overwrite the entire output table each time to ensure late data is incorporated correctly.","rationale":"Full-table overwrites are not the requested efficient streaming solution.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"scoped","explanation":"An event-time watermark supports bounded state and handling of late data within the configured guarantee.","topic":"watermarks","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/watermarks","sourceTitle":"Apply watermarks to control data processing thresholds | Databricks on AWS","sourcePage":137,"images":["questions/306-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is designing a data pipeline in Databricks that needs to process records from a Kafka stream where late-arriving data common.\nWhich approach should the data engineer use?","options":[{"id":"A","text":"Use a watermark to specify the allowed lateness to accommodate records that arrive after their expected window, ensuring correct\naggregation and state management."},{"id":"B","text":"Use an Auto CDC pipeline with batch tables to simplify late data handling."},{"id":"C","text":"Implement a custom solution using Databricks Jobs to periodically reprocess all historical data"},{"id":"D","text":"Use batch processing and overwrite the entire output table each time to ensure late data is incorporated correctly."}],"correctAnswers":["A"],"explanation":"Event-time watermarks define a lateness threshold and allow state cleanup for stateful streaming. They do not wait indefinitely for every late record; set the threshold to the business requirement.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"This is an event-time windowed aggregation with a configured acceptable lateness bound. Data beyond that bound may be dropped and needs a separate recovery policy.","reviewNote":"Second audit: Watermarks do not guarantee handling arbitrarily late events.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":307,"prompt":"A data engineering team is configuring access controls in Databricks Unity Catalog. They grant the SELECT privilege on the sales catalog to the\nanalyst_group, expecting that members of this group will automatically have SELECT access to all current and future schemas, tables, and views\nwithin the sales catalog.\nWhat describes the privilege inheritance behavior in Unity Catalog?","options":[{"id":"A","text":"Privileges in Unity Catalog do not cascade; SELECT most be explicitly granted on each schema and table, even if granted at the catalog\nlevel.","rationale":"Unity Catalog supports privilege inheritance to current and future child objects.","isCorrect":false},{"id":"B","text":"Granting SELECT on a catalog automatically applies SELECT to all current and future schemas, tables, and views within that catalog.","rationale":"SELECT is inherited by current and future tables/views; exercising it also needs the parent usage privileges.","isCorrect":true},{"id":"C","text":"Granting SELECT at the catalog level applies to existing schemas and tables but not to those created in the future.","rationale":"Inheritance also applies to future child objects.","isCorrect":false},{"id":"D","text":"Privileges granted at the schema level override any catalog-level privileges and prevent access unless explicitly revoked.","rationale":"Child grants do not override inherited grants in the manner claimed.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"SELECT is inherited by current and future tables/views; exercising it also needs the parent usage privileges.","topic":"governance","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control/privileges-reference","sourceTitle":"Unity Catalog privileges reference | Databricks on AWS","sourcePage":137,"images":["questions/307-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineering team is configuring access controls in Databricks Unity Catalog. They grant the SELECT privilege on the sales catalog to the\nanalyst_group, expecting that members of this group will automatically have SELECT access to all current and future schemas, tables, and views\nwithin the sales catalog.\nWhat describes the privilege inheritance behavior in Unity Catalog?","options":[{"id":"A","text":"Privileges in Unity Catalog do not cascade; SELECT most be explicitly granted on each schema and table, even if granted at the catalog\nlevel."},{"id":"B","text":"Granting SELECT on a catalog automatically applies SELECT to all current and future schemas, tables, and views within that catalog."},{"id":"C","text":"Granting SELECT at the catalog level applies to existing schemas and tables but not to those created in the future."},{"id":"D","text":"Privileges granted at the schema level override any catalog-level privileges and prevent access unless explicitly revoked."}],"correctAnswers":["B"],"explanation":"Catalog-level SELECT inherits to applicable current and future child objects. Users still need USE CATALOG and USE SCHEMA to access them; a narrower grant is not a deny that overrides inherited access.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The group already has USE CATALOG and USE SCHEMA on the applicable hierarchy. SELECT is inherited for tables/views; schemas carry inherited grants rather than being queried as tables.","reviewNote":"Second audit: Inherited SELECT does not by itself grant the required usage privileges.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":308,"prompt":"An organization processes customer data from web and mobile applications. Data includes names, emails phone numbers, and location history.\nData arrives both as Batch files from an SFTP drop (daily) and Streaming JSON events from Kafka (real-time).\nTo comply with internal data privacy policies, the following requirements must be met:\n• Personally identifiable information (PII) like email, phone_number, and ip_address must be masked or anonymized before storage\n• Both batch and streaming pipelines must apply consistent PII handling\n• Masking logic must be auditable and reproducible\n• The masked data must still be usable for downstream analytics\nHow should the data engineer design a compliant data pipeline on Databricks that supports both batch and streaming modes, applies data\nmasking to PII, and maintains traceability of transformations for audits?","options":[{"id":"A","text":"Ingest both batch and streaming data using Lakeflow Spark Declarative Pipelines, and apply masking via Unity Catalog column masks at\nread time to avoid modifying the data during ingestion.","rationale":"Read-time masking leaves unmasked values stored, violating masking before storage.","isCorrect":false},{"id":"B","text":"Load batch data with notebooks and ingest streaming data with SQL Warehouses; use Unity Catalog column masks on Silver tables to\nredact fields after storage.","rationale":"Post-storage column masks fail the ingestion-time protection requirement.","isCorrect":false},{"id":"C","text":"Use Lakeflow Spark Declarative Pipelines for batch and streaming ingestion define a PII masking function, and apply it during Bronze\ningestion before writing to Delta Lake.","rationale":"A versioned shared masking transform before the first Delta write applies the policy in both modes; retain code/lineage for audit.","isCorrect":true},{"id":"D","text":"Allow PII to be stored unmasked in Bronze for lineage tracking, then apply masking logic in Gold tables used for reporting.","rationale":"Storing raw PII in Bronze explicitly violates the stated policy.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"A versioned shared masking transform before the first Delta write applies the policy in both modes; retain code/lineage for audit.","topic":"masks","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/","sourceTitle":"Row filters and column masks | Databricks on AWS","sourcePage":137,"images":["questions/308-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":309,"prompt":"Which method can be used to determine the total wall-clock time it took to execute a query?","options":[{"id":"A","text":"In the Spark UI, take the job duration of the longest-running job associated with that query.","rationale":"The longest job alone can omit other sequential jobs and query overhead.","isCorrect":false},{"id":"B","text":"In the Spark UI, take the sum of all task durations that ran across all stages (or all jobs associated with that query.","rationale":"Parallel task durations add to more than elapsed wall-clock time.","isCorrect":false},{"id":"C","text":"Open the Query Profiler associated with that query and use the Total wall-clock duration metric.","rationale":"The profile's wall-clock duration measures the query's elapsed execution interval.","isCorrect":true},{"id":"D","text":"Open the Query Profiler associated with that query and use the Aggregated task time metric.","rationale":"Aggregated task time sums work across tasks and is not elapsed query duration.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"confirmed","explanation":"The profile's wall-clock duration measures the query's elapsed execution interval.","topic":"profile","sourceUrl":"https://docs.databricks.com/aws/en/sql/user/queries/query-profile","sourceTitle":"Query profile | Databricks on AWS","sourcePage":138,"images":["questions/309-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":310,"prompt":"A data architect is designing a Databricks solution to efficiently process data for different business requirements.\nIn which scenario should a data engineer use a materialized view compared to a streaming table?","options":[{"id":"A","text":"Precomputing complex aggregations and joins from multiple large tables to accelerate BI dashboard performance.","rationale":"Materialized views precompute and refresh query results for complex BI joins and aggregations.","isCorrect":true},{"id":"B","text":"Processing high-volume, continuous clickstream data from a website to monitor user behavior in real-time.","rationale":"Continuous event ingestion is a natural streaming-table workload.","isCorrect":false},{"id":"C","text":"Ingesting data from Apache Kafka topics with sub second processing requirements for immediate alerting,","rationale":"Sub-second event alerting is not the stated materialized-view use case.","isCorrect":false},{"id":"D","text":"Implementing a CDC (Change Data Capture) pipeline that needs to detect and respond to database changes within seconds.","rationale":"Incremental keyed CDC belongs in a streaming CDC design.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"Materialized views precompute and refresh query results for complex BI joins and aggregations.","topic":"views","sourceUrl":"https://docs.databricks.com/aws/en/views/","sourceTitle":"What is a view? | Databricks on AWS","sourcePage":138,"images":["questions/310-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":311,"prompt":"A query is taking too long to run. After investigating the Spark UI, the data engineer discovered a significant amount of disk spill. The type of\ncompute instance the data engineer used only provides a core-to-memory ratio of 1:2.\nWhat are the two steps the data engineer should take to minimize spillage? (Choose two.)","options":[{"id":"A","text":"Increase spark.sql.files.maxPartitionBytes.","rationale":"Larger file-read partitions increase the stated per-task working set.","isCorrect":false},{"id":"B","text":"Choose a compute instance with more disk space.","rationale":"More disk accommodates spill but does not reduce the need to spill.","isCorrect":false},{"id":"C","text":"Choose a compute instance with a higher memory-to-core ratio (more memory available per concurrent task).","rationale":"More memory per core increases memory available to concurrently running tasks.","isCorrect":true},{"id":"D","text":"Reduce spark.sql.files.maxPartitionBytes.","rationale":"Smaller splittable file-read partitions reduce the stated per-task working set.","isCorrect":true},{"id":"E","text":"Choose a compute instance with more network bandwidth.","rationale":"More network bandwidth does not supply the missing per-task memory.","isCorrect":false}],"selectionCount":2,"correctAnswers":["C","D"],"suggestedAnswers":[],"status":"corrected","explanation":"More memory per core increases memory available to concurrently running tasks. Smaller splittable file-read partitions reduce the stated per-task working set.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":138,"images":["questions/311-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":311,"prompt":"A query is taking too long to run. After investigating the Spark UI, the data engineer discovered a significant amount of disk spill. The type of\ncompute instance the data engineer used only provides a core-to-memory ratio of 1:2.\nWhat are the two steps the data engineer should take to minimize spillage? (Choose two.)","options":[{"id":"A","text":"Increase spark.sql.files.maxPartitionBytes."},{"id":"B","text":"Choose a compute instance with more disk space."},{"id":"C","text":"Choose a compute instance with a higher core-to-memory ratio"},{"id":"D","text":"Reduce spark.sql.files.maxPartitionBytes."},{"id":"E","text":"Choose a compute instance with more network bandwidth."}],"selectionCount":2,"correctAnswers":[],"suggestedAnswers":["C","D"],"status":"review","explanation":"D reduces input partition size. C is intended to mean more memory per core, but a mathematically higher core-to-memory ratio means the opposite. Correct the wording to 'higher memory-to-core ratio' before scoring this choose-two item.","topic":"sizing","sourceUrl":"https://docs.databricks.com/aws/en/compute/cluster-config-best-practices","sourceTitle":"Classic compute configuration best practices | Databricks on AWS","sourcePage":138,"images":["questions/311-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"Corrected the inverted ratio: more memory per core, not more cores per unit of memory.","studyContext":"The spill is caused by per-task memory pressure in file-scan-driven processing; the input is splittable and the file-read partition size controls the working set.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":312,"prompt":"A data engineering team has a time-consuming data ingestion job. It has three data sources, and each data ingestion notebook takes about one\nhour to load new data. The job had been working fine, loading data every midnight. However, one day they received an alert message stating the\njob had failed. By investigating the cause, they figured out that the failed notebook code was updated, and a new required configuration was\nintroduced to parameterize a hardcoded value without notice. Now, the team has to fix the issue as quickly as possible to load the latest data from\nthe failing data source.\nWhich action should the team take in this scenario?","options":[{"id":"A","text":"Update the task by adding the missing task parameter, and manually run the job.","rationale":"A complete job rerun repeats successful work unnecessarily.","isCorrect":false},{"id":"B","text":"Share the analysis with the failing notebook owner so that they can fix it quickly.","rationale":"Asking the owner alone does not immediately repair the run or persist the missing parameter.","isCorrect":false},{"id":"C","text":"Repair the run with the new parameter.","rationale":"A repair-only override can fix this run but leave future scheduled runs misconfigured.","isCorrect":false},{"id":"D","text":"Repair the run with the new parameter, and update the task by adding the missing task parameter.","rationale":"Repair with the parameter restores failed work; updating the saved task fixes future runs.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"Repair with the parameter restores failed work; updating the saved task fixes future runs.","topic":"repair","sourceUrl":"https://docs.databricks.com/aws/en/jobs/repair-job-failures","sourceTitle":"Troubleshoot and repair job failures | Databricks on AWS","sourcePage":139,"images":["questions/312-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":313,"prompt":"Which SQL expression produces a deterministic, fixed-length hexadecimal SHA-256 digest of the email column? This is a fingerprint/pseudonymization exercise; uniqueness and irreversible anonymization are not guaranteed.","options":[{"id":"A","text":"hash(email)","rationale":"The 32-bit integer hash is not the required fixed-length hexadecimal SHA-256 string.","isCorrect":false},{"id":"B","text":"mask(email, '?')","rationale":"Character masking is not a deterministic cryptographic fingerprint and can collapse many distinct emails.","isCorrect":false},{"id":"C","text":"sha1('email')","rationale":"It hashes the literal string 'email', producing the same digest for every row.","isCorrect":false},{"id":"D","text":"sha2(email,0)","rationale":"sha2(email, 0) uses SHA-256 and returns a fixed-length hexadecimal digest; it does not promise collision-free anonymization.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"corrected","explanation":"sha2(email, 0) uses SHA-256 and returns a fixed-length hexadecimal digest; it does not promise collision-free anonymization.","topic":"hash","sourceUrl":"https://docs.databricks.com/aws/en/sql/language-manual/functions/sha2","sourceTitle":"sha2 function | Databricks on AWS","sourcePage":139,"images":["questions/313-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is masking the provided data column containing the email address. The goal is to have an output of the same length for all rows,\nwhile keeping different outputs for different values.\nWhich SQL function should be used to achieve this?","options":[{"id":"A","text":"hash(email)"},{"id":"B","text":"mask(email, ‘?’)"},{"id":"C","text":"sha1(‘email’)"},{"id":"D","text":"sha2(email,0)"}],"correctAnswers":["D"],"explanation":"sha2(email, 0) is the SQL form for SHA-256 and returns a fixed-length hexadecimal string. hash returns an integer, mask preserves varying input lengths, and sha1('email') hashes a constant. Hashes are not mathematically collision-free.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: A digest is not collision-free anonymization; clarified the required SHA-256 representation.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":314,"prompt":"A company wants to implement Lakehouse Federation across multiple data sources, but is worried about data consistency and ensuring all teams\naccess the same authoritative version of their data.\nWhich statement is applicable for Lakehouse Federations to maintain data consistency?","options":[{"id":"A","text":"Federation creates local copies that must be manually refreshed.","rationale":"Federated reads do not inherently create manually refreshed local copies.","isCorrect":false},{"id":"B","text":"Federation implements change data capture from all sources.","rationale":"Federation is not universal CDC ingestion from every source.","isCorrect":false},{"id":"C","text":"A separate data synchronization service must be deployed.","rationale":"A separate synchronization service is not required for federated reads.","isCorrect":false},{"id":"D","text":"Federation provides read-only access that reflects the current state of source systems.","rationale":"Queries read the external source under its connector/isolation semantics; there is no universal cross-source snapshot guarantee.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Queries read the external source under its connector/isolation semantics; there is no universal cross-source snapshot guarantee.","topic":"federation","sourceUrl":"https://docs.databricks.com/aws/en/query-federation/","sourceTitle":"Connect to external databases and catalogs | Databricks on AWS","sourcePage":139,"images":["questions/314-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A company wants to implement Lakehouse Federation across multiple data sources, but is worried about data consistency and ensuring all teams\naccess the same authoritative version of their data.\nWhich statement is applicable for Lakehouse Federations to maintain data consistency?","options":[{"id":"A","text":"Federation creates local copies that must be manually refreshed."},{"id":"B","text":"Federation implements change data capture from all sources."},{"id":"C","text":"A separate data synchronization service must be deployed."},{"id":"D","text":"Federation provides read-only access that reflects the current state of source systems."}],"correctAnswers":["D"],"explanation":"Query federation reads governed external data from the source rather than maintaining a manually refreshed local copy. Visibility follows source transaction semantics; this does not promise global cross-system snapshot consistency.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The question concerns reading source data without managing a replicated local copy. Consistency follows each connector and source isolation behavior; no atomic cross-source snapshot is promised.","reviewNote":"Second audit: Federation is not a global transactional snapshot across independent sources.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":315,"prompt":"A data engineer needs to implement column masking for a sensitive column in a Unity Catalog-managed table. The masking logic must\ndynamically check if users belong to specific groups defined in a separate table (group_access) that maps groups to allowed departments.\nWhich approach should the engineer use to efficiently enforce this requirement?","options":[{"id":"A","text":"Create a view without selecting the sensitive column","rationale":"Removing the column entirely does not provide conditional masking.","isCorrect":false},{"id":"B","text":"Apply a column mask that references the group_access mapping table in its UDF","rationale":"A supported mask UDF can consult a mapping table and group identity to choose masked or clear values.","isCorrect":true},{"id":"C","text":"Create a UDF that hardcodes allowed groups and apply it as a column mask.","rationale":"Hardcoded groups do not follow the required maintained mapping table.","isCorrect":false},{"id":"D","text":"Use a row filter to restrict access based on the user's group.","rationale":"A row filter governs which rows are returned, not the sensitive column's value.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"A supported mask UDF can consult a mapping table and group identity to choose masked or clear values.","topic":"masks","sourceUrl":"https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/manually-apply","sourceTitle":"Manually apply row filters and column masks","sourcePage":140,"images":["questions/315-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":316,"prompt":"Two data engineers are working on the same Databricks notebook in separate branches. Both have edited the same section of code. When one\ntries to merge the other’s branch into their own using the Databricks Git folders UI, a merge conflict occurs on that notebook file. The UI highlights\nthe conflict and presents options for resolution.\nHow should the data engineers resolve this merge conflict using Databricks Git folders?","options":[{"id":"A","text":"Use the Git CLI in the cluster's web terminal to force-push the conflicted merge (git push --force), overriding the remote branch with local\nversion and discarding changes.","rationale":"Force-pushing does not resolve the local content conflict safely and can overwrite colleagues' work.","isCorrect":false},{"id":"B","text":"Use the Git folders UI to manually edit the notebook file, selecting the desired lines from both versions and removing the conflict markers,\nthen mark the conflict as resolved.","rationale":"Review both sides, edit a valid combined result, remove markers and complete resolution in the Git-folder UI.","isCorrect":true},{"id":"C","text":"Abort the merge, discard all local changes, and try the merge operation again without reviewing the confiding code.","rationale":"Discarding changes loses work and does not thoughtfully reconcile the conflicting edits.","isCorrect":false},{"id":"D","text":"Delete the conflicted notebook file via the Databricks workspace UI, commit the deletion, and recreate the notebook from scratch in a new\ncommit to bypass the conflict entirely.","rationale":"Deleting and recreating the notebook is unnecessary and risks losing valid changes.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"confirmed","explanation":"Review both sides, edit a valid combined result, remove markers and complete resolution in the Git-folder UI.","topic":"git","sourceUrl":"https://docs.databricks.com/aws/en/repos/git-operations-with-repos","sourceTitle":"Create and manage Git folders | Databricks on AWS","sourcePage":140,"images":["questions/316-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":317,"prompt":"A data engineer wants to automate job monitoring and recovery in Databricks using the Jobs API. They need to list all jobs, identify a failed job,\nand rerun it.\nWhich sequence of API actions should the data engineer perform?","options":[{"id":"A","text":"Use the jobs list endpoint to list jobs, check job run statuses with jobs runs list, and rerun a failed job using jobs run-now.","rationale":"List job definitions and runs, identify failure, then run-now starts a new run of the existing job.","isCorrect":true},{"id":"B","text":"Use the jobs get endpoint to retrieve job details, then use jobs update to rerun failed jobs.","rationale":"update changes job settings; it does not rerun the job.","isCorrect":false},{"id":"C","text":"Use the jobs list endpoint to list jobs, then use the jobs create endpoint to create a new job, and run the new job using jobs run-now.","rationale":"Creating a duplicate job is unnecessary to rerun an existing failed job.","isCorrect":false},{"id":"D","text":"Use the jobs cancel endpoint to remove failed jobs, then recreate them with jobs create endpoint and run the new ones.","rationale":"Canceling does not delete job definitions, and recreating them is unnecessary.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"List job definitions and runs, identify failure, then run-now starts a new run of the existing job.","topic":"jobsapi","sourceUrl":"https://docs.databricks.com/api/jobs/v2/get-run","sourceTitle":"Get a single job run | Databricks API Reference","sourcePage":140,"images":["questions/317-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":318,"prompt":"A data engineering team is setting up deployment automation. To deploy workspace assets remotely using the Databricks CLI command, they\nmust configure it with proper authentication.\nWhich authentication approach will provide the highest level of security?","options":[{"id":"A","text":"Use a service principal and its Personal Access Token","rationale":"A service-principal PAT is a stored long-lived credential requiring secret management.","isCorrect":false},{"id":"B","text":"Use a service principal with OAuth token federation","rationale":"Supported workload identity federation exchanges the CI identity for short-lived credentials without storing a Databricks secret.","isCorrect":true},{"id":"C","text":"Use a service principal ID and its OAuth client secret","rationale":"Client-secret OAuth still requires storing and rotating a client secret.","isCorrect":false},{"id":"D","text":"Use a shared user account and its OAuth client secret","rationale":"A shared human account weakens identity separation and accountability.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"scoped","explanation":"Supported workload identity federation exchanges the CI identity for short-lived credentials without storing a Databricks secret.","topic":"oauth","sourceUrl":"https://docs.databricks.com/aws/en/dev-tools/auth/oauth-federation","sourceTitle":"Authenticate access to Databricks using OAuth token federation | Databricks on AWS","sourcePage":141,"images":["questions/318-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineering team is setting up deployment automation. To deploy workspace assets remotely using the Databricks CLI command, they\nmust configure it with proper authentication.\nWhich authentication approach will provide the highest level of security?","options":[{"id":"A","text":"Use a service principal and its Personal Access Token"},{"id":"B","text":"Use a service principal with OAuth token federation"},{"id":"C","text":"Use a service principal ID and its OAuth client secret"},{"id":"D","text":"Use a shared user account and its OAuth client secret"}],"correctAnswers":["B"],"explanation":"OAuth workload identity federation uses short-lived tokens without storing a long-lived client secret or PAT. A dedicated service principal also avoids shared human-account credentials.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The CI/CD runner provides a supported OIDC workload identity and the service principal has an appropriately restricted federation policy.","reviewNote":"Second audit: Workload federation requires a supported external identity provider.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":319,"prompt":"A data engineer treated a daily batch ingestion pipeline using a cluster with the latest DBR version to store banking transaction data, and persisted\nit in a MANAGED DELTA table called prod.gold.all_banking_transactions_daily. The data engineer is constantly receiving complaints, from\nbusiness units that constantly read this table in an ad hoc way using a SOL Serverless Warehouse, regarding the poor performance of their\nqueries. Analyzing the queries, the data engineer slated that these areas use high cardinality columns as filters, to perform their analysis. The data\nengineer is studying possibilities to implement a data layout optimization technique for that table, which is incremental, easy to maintain, and can\neasily evolve over time.\nWhich command should the data engineer implement?","options":[{"id":"A","text":"Alter the table to use Hive Style Partitions + Z-ORDER and implement a periodic OPTIMIZE command.","rationale":"High-cardinality Hive partitions with Z-order are less flexible and require more layout maintenance.","isCorrect":false},{"id":"B","text":"Alter the table to use Hive Style Partitions and implement a periodic OPTIMIZE command.","rationale":"Hive partitioning alone is poorly suited to changing high-cardinality filter keys.","isCorrect":false},{"id":"C","text":"Alter the table to use Z-ORDER arid implement a periodic OPTIMIZE command.","rationale":"Z-order can help skipping but offers less incremental layout flexibility.","isCorrect":false},{"id":"D","text":"Alter the table to use Liquid Clustering and implement a periodic OPTIMIZE command","rationale":"Liquid clustering provides flexible keys and incremental optimization with OPTIMIZE on the supported table.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Liquid clustering provides flexible keys and incremental optimization with OPTIMIZE on the supported table.","topic":"liquid","sourceUrl":"https://docs.databricks.com/aws/en/tables/clustering","sourceTitle":"Use liquid clustering for tables | Databricks on AWS","sourcePage":141,"images":["questions/319-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer treated a daily batch ingestion pipeline using a cluster with the latest DBR version to store banking transaction data, and persisted\nit in a MANAGED DELTA table called prod.gold.all_banking_transactions_daily. The data engineer is constantly receiving complaints, from\nbusiness units that constantly read this table in an ad hoc way using a SOL Serverless Warehouse, regarding the poor performance of their\nqueries. Analyzing the queries, the data engineer slated that these areas use high cardinality columns as filters, to perform their analysis. The data\nengineer is studying possibilities to implement a data layout optimization technique for that table, which is incremental, easy to maintain, and can\neasily evolve over time.\nWhich command should the data engineer implement?","options":[{"id":"A","text":"Alter the table to use Hive Style Partitions + Z-ORDER and implement a periodic OPTIMIZE command."},{"id":"B","text":"Alter the table to use Hive Style Partitions and implement a periodic OPTIMIZE command."},{"id":"C","text":"Alter the table to use Z-ORDER arid implement a periodic OPTIMIZE command."},{"id":"D","text":"Alter the table to use Liquid Clustering and implement a periodic OPTIMIZE command"}],"correctAnswers":["D"],"explanation":"Liquid clustering supports evolving high-cardinality keys and incremental OPTIMIZE maintenance. Hive partitions are inflexible for this case; ZORDER is not the most adaptable layout choice offered.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The existing managed Delta table is unpartitioned and eligible for liquid clustering on the supported runtime.","reviewNote":"Second audit: Specified a layout on which the proposed ALTER is supported.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":320,"prompt":"A data engineer is designing an append-only pipeline that needs to handle both batch and streaming data in Delta Lake. The team wants to ensure\nthat the streaming component can efficiently track which data has already been processed.\nWhich configuration should be set to enable this?","options":[{"id":"A","text":"checkpointLocation","rationale":"A persistent unique checkpoint tracks progress and recovery information for the stream.","isCorrect":true},{"id":"B","text":"overwriteSchema","rationale":"overwriteSchema controls schema replacement during writes.","isCorrect":false},{"id":"C","text":"mergeSchema","rationale":"mergeSchema controls compatible schema evolution, not stream progress.","isCorrect":false},{"id":"D","text":"partitionBy","rationale":"partitionBy controls physical partition layout, not processed offsets.","isCorrect":false}],"selectionCount":1,"correctAnswers":["A"],"suggestedAnswers":[],"status":"confirmed","explanation":"A persistent unique checkpoint tracks progress and recovery information for the stream.","topic":"checkpoints","sourceUrl":"https://docs.databricks.com/aws/en/structured-streaming/checkpoints","sourceTitle":"Structured Streaming checkpoints | Databricks on AWS","sourcePage":141,"images":["questions/320-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":321,"prompt":"A data engineer is implementing Unity Catalog governance for a multi-team environment. Data scientists need interactive clusters for basic data\nexploration tasks, while automated ETL jobs require dedicated processing.\nHow should the data engineer configure cluster isolation policies to enforce least privilege and ensure Unity Catalog compliance?","options":[{"id":"A","text":"Configure all dusters with NO_ISOLATION_SHARED access modes since Unity Catalog works with any cluster configuration","rationale":"No-isolation shared compute does not support the required Unity Catalog security model.","isCorrect":false},{"id":"B","text":"Allow all users to create any duster type and rely on manual configuration to enable Unity Catalog access modes.","rationale":"Unrestricted user configuration does not enforce access modes or least privilege.","isCorrect":false},{"id":"C","text":"Create compute policies with STANDARD access mode for interactive 'workloads and dedicated access mode for automated jobs.","rationale":"Policies can enforce standard multi-user exploration and dedicated single-principal job compute for the stated design.","isCorrect":true},{"id":"D","text":"Use only DEDICATED access mode for both interactive workloads and automated jobs to maximize security isolation.","rationale":"Dedicated-only interactive compute does not meet the specified shared multi-user exploration requirement.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Policies can enforce standard multi-user exploration and dedicated single-principal job compute for the stated design.","topic":"policies","sourceUrl":"https://docs.databricks.com/aws/en/admin/clusters/policy-definition","sourceTitle":"Compute policy reference | Databricks on AWS","sourcePage":142,"images":["questions/321-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is implementing Unity Catalog governance for a multi-team environment. Data scientists need interactive clusters for basic data\nexploration tasks, while automated ETL jobs require dedicated processing.\nHow should the data engineer configure cluster isolation policies to enforce least privilege and ensure Unity Catalog compliance?","options":[{"id":"A","text":"Configure all dusters with NO_ISOLATION_SHARED access modes since Unity Catalog works with any cluster configuration"},{"id":"B","text":"Allow all users to create any duster type and rely on manual configuration to enable Unity Catalog access modes."},{"id":"C","text":"Create compute policies with STANDARD access mode for interactive 'workloads and dedicated access mode for automated jobs."},{"id":"D","text":"Use only DEDICATED access mode for both interactive workloads and automated jobs to maximize security isolation."}],"correctAnswers":["C"],"explanation":"Policies can enforce standard access for shared interactive workloads and dedicated access where job isolation requires it. No-isolation shared mode is not UC-compliant; unrestricted creation undermines enforcement.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"The design requires shared multi-user interactive exploration on standard access mode and automated jobs isolated to a single assigned service principal on dedicated compute.","reviewNote":"Second audit: Dedicated-only compute can also be secure; specified the access-mode design being enforced.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":322,"prompt":"A data engineer, while designing a Pandas UDF to process financial time series data with complex calculations that require maintaining state\nacross rows within each stock symbol group must ensure the function is efficient and scalable.\nWhich approach will solve the problem with minimum overhead while preserving data integrity?","options":[{"id":"A","text":"Use a SCALAR_ITER Pandas UDF with iterator-based processing, implementing state management through persistent storage (Delta tables)\nthat gets updated after each batch to maintain continuity across iterator chunks.","rationale":"External state and scalar iterator batches add overhead and do not guarantee whole-symbol grouping.","isCorrect":false},{"id":"B","text":"Use a GROUPED_AGG UPF that processes each stock symbol group independently, maintaining state through intermediate aggregation\nresults that get passed between successive UDF calls via broadcast variables.","rationale":"Broadcast variables are read-only distribution tools, not mutable state passed reliably between group calls.","isCorrect":false},{"id":"C","text":"Use a SCALAR Pandas UDF that processes the entire dataset at once, implementing custom partitioning logic within the UDF to group by\nstock symbol and maintain state using global variables shared across all executor processes.","rationale":"Scalar batches are not the entire dataset and executor Python globals are not shared distributed state.","isCorrect":false},{"id":"D","text":"Use ApplyInPandas method on spark dataframe that receives all rows for each stock symbol as a pandas DataFrame, allowing processing\nwithin each group while maintaining state variables local to each group’s processing function.","rationale":"Grouped applyInPandas gives the function each symbol's rows; sorting inside the group supports the stated local stateful computation.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"scoped","explanation":"Grouped applyInPandas gives the function each symbol's rows; sorting inside the group supports the stated local stateful computation.","topic":"pandas","sourceUrl":"https://docs.databricks.com/aws/en/udf/pandas","sourceTitle":"pandas user-defined functions | Databricks on AWS","sourcePage":142,"images":["questions/322-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"original":{"id":322,"prompt":"A data engineer, while designing a Pandas UDF to process financial time series data with complex calculations that require maintaining state\nacross rows within each stock symbol group must ensure the function is efficient and scalable.\nWhich approach will solve the problem with minimum overhead while preserving data integrity?","options":[{"id":"A","text":"Use a SCALAR_ITER Pandas UDF with iterator-based processing, implementing state management through persistent storage (Delta tables)\nthat gets updated after each batch to maintain continuity across iterator chunks."},{"id":"B","text":"Use a GROUPED_AGG UPF that processes each stock symbol group independently, maintaining state through intermediate aggregation\nresults that get passed between successive UDF calls via broadcast variables."},{"id":"C","text":"Use a SCALAR Pandas UDF that processes the entire dataset at once, implementing custom partitioning logic within the UDF to group by\nstock symbol and maintain state using global variables shared across all executor processes."},{"id":"D","text":"Use ApplyInPandas method on spark dataframe that receives all rows for each stock symbol as a pandas DataFrame, allowing processing\nwithin each group while maintaining state variables local to each group’s processing function."}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"best_fit","explanation":"groupBy(...).applyInPandas supplies each symbol's rows to one function with local state. Sort within each group for time-series order and account for group memory; this is not persistent cross-batch streaming state. Global/broadcast variables cannot coordinate mutable executor state.","topic":"pandas","sourceUrl":"https://docs.databricks.com/aws/en/udf/pandas","sourceTitle":"pandas user-defined functions | Databricks on AWS","sourcePage":142,"images":["questions/322-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null},"reviewRevision":2,"reviewNote":"The answer is scored within the explicit context shown with this question.","studyContext":"State is local to one batch invocation per stock-symbol group. Each group fits in executor memory; sort rows within each group by time. Cross-microbatch state is not required.","reviewedAt":"2026-10-04","practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":323,"prompt":"A data engineer is developing an LDP pipeline using a Databricks notebook that is directly connected to their pipeline. After adding new table\ndefinitions and transformation logic in their notebook, they want to check for any syntax errors in the pipeline code without actually processing\nany data or running the pipeline.\nHow should the data engineer perform this syntax check?","options":[{"id":"A","text":"Open the web terminal from the notebook and run a shell command to validate the pipeline code.","rationale":"A shell syntax check does not substitute for the integrated pipeline validation of definitions and dependencies.","isCorrect":false},{"id":"B","text":"Disconnect the notebook from the pipeline and reconnect it to a compute cluster to access code validation features","rationale":"Disconnecting is unnecessary and removes the intended pipeline context.","isCorrect":false},{"id":"C","text":"Use the \"Validate\" option in the notebook to check for syntax errors.","rationale":"In the specified connected-notebook interface, Validate checks pipeline code without processing table data.","isCorrect":true},{"id":"D","text":"Switch to a workspace file instead of a notebook to access the validation and diagnostics tools.","rationale":"Switching source-file type is not required for validation.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"In the specified connected-notebook interface, Validate checks pipeline code without processing table data.","topic":"ldpvalidate","sourceUrl":"https://docs.databricks.com/aws/en/ldp/notebook-devex","sourceTitle":"Develop and debug pipelines with a notebook","sourcePage":142,"images":["questions/323-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer is developing an LDP pipeline using a Databricks notebook that is directly connected to their pipeline. After adding new table\ndefinitions and transformation logic in their notebook, they want to check for any syntax errors in the pipeline code without actually processing\nany data or running the pipeline.\nHow should the data engineer perform this syntax check?","options":[{"id":"A","text":"Open the web terminal from the notebook and run a shell command to validate the pipeline code."},{"id":"B","text":"Disconnect the notebook from the pipeline and reconnect it to a compute cluster to access code validation features"},{"id":"C","text":"Use the \"Validate\" option in the notebook to check for syntax errors."},{"id":"D","text":"Switch to a workspace file instead of a notebook to access the validation and diagnostics tools."}],"correctAnswers":["C"],"explanation":"The attached pipeline notebook offers Validate to check definitions without processing data. Moving the code or using a shell is unnecessary for this workflow.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Use the connected-notebook pipeline development interface that exposes a Validate action. UI locations can differ in the newer Pipelines Editor.","reviewNote":"Second audit: The Validate action belongs to the specified notebook interface.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":324,"prompt":"A Delta version of a benchmark reads fewer files during a selective join than a legacy-format version. The plans also happen to use different join strategies. Which listed optimization could explain the reduced file reads? Do not infer a universal performance ranking of join algorithms.","options":[{"id":"A","text":"The queries against the ORC tables leveraged the dynamic data skipping optimization but not the dynamic file pruning optimization.","rationale":"The premise does not establish this claimed ORC-specific optimization behavior.","isCorrect":false},{"id":"B","text":"The queries against the Delta Lake tables were able to leverage the dynamic file pruning optimization.","rationale":"Dynamic file pruning can use runtime join filters to skip Delta files; the plan must confirm that it was applied.","isCorrect":true},{"id":"C","text":"Delta Lake enables data skipping and file pruning using a vectorized Parquet reader.","rationale":"A vectorized reader improves reading efficiency but does not itself explain runtime join-based file pruning.","isCorrect":false},{"id":"D","text":"Shuffle Hash Joins are always more efficient than Sort Merge Joins.","rationale":"Hash joins are not always faster; data size, skew, memory and plan choices matter.","isCorrect":false}],"selectionCount":1,"correctAnswers":["B"],"suggestedAnswers":[],"status":"corrected","explanation":"Dynamic file pruning can use runtime join filters to skip Delta files; the plan must confirm that it was applied.","topic":"pruning","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/dynamic-file-pruning","sourceTitle":"Dynamic file pruning | Databricks on AWS","sourcePage":143,"images":["questions/324-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineering team is in the process of migrating off its legacy Hadcop platform. As part of the process, they are evaluating the different\nstorage formats to see which offers the best query performance. Their legacy platform utilizes ORC and RCFile formats. They converted a subset\nof their data to Delta Lake and ran a side-by-side benchmark, and found that their queries performed significantly better. Upon investigation, they\ndiscovered that the query plans were different, and the queries that read from the Delta Lake tables leveraged a Shuffle Hash\nJoin, whereas the legacy formats used Sort Merge Joins. The queries that read from the Delta Lake tables also read less data.\nWhich reason could be attributed to the difference in query performance?","options":[{"id":"A","text":"The queries against the ORC tables leveraged the dynamic data skipping optimization but not the dynamic file pruning optimization."},{"id":"B","text":"The queries against the Delta Lake tables were able to leverage the dynamic file pruning optimization."},{"id":"C","text":"Delta Lake enables data skipping and file pruning using a vectorized Parquet reader."},{"id":"D","text":"Shuffle Hash Joins are always more efficient than Sort Merge Joins."}],"correctAnswers":["B"],"explanation":"Dynamic file pruning can reduce Delta files scanned during joins. A shuffle hash join is not universally faster, and a vectorized reader alone is not the metadata pruning mechanism.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"reviewNote":"Second audit: File pruning can explain less input, but does not alone prove why a join strategy was selected.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":325,"prompt":"A data team is automating a daily multitask ETL pipeline in Databricks. The pipeline includes a notebook for ingesting raw data, a Python wheel\ntask for data transformation, and a SQL query to update aggregates. They want to trigger the pipeline programmatically and see previous runs in\nthe GUI. They need to ensure tasks are retried on failure and stakeholders are notified by email if any task fails.\nWhich two approaches will meet these requirements? (Choose two.)","options":[{"id":"A","text":"Trigger the job programmatically using the Databricks Jobs REST API (/jobs/run-now), the CLI (databricks jobs run-now), or one of the\nDatabricks SDKs.","rationale":"Jobs run-now through API, CLI or SDK triggers the configured saved multitask job.","isCorrect":true},{"id":"B","text":"Use Databricks Asset Bundles (DABs) to deploy the workflow, then trigger individual tasks directly by referencing each task’s notebook or\nscript path in the workspace.","rationale":"Invoking notebook/script paths individually bypasses the saved job's dependencies and task retry policy.","isCorrect":false},{"id":"C","text":"Create a multi-task job using the UI, DABs, or the Jobs REST API (/jobs/create) with notebook, Python wheel, and SQL tasks. Configure\ntask-level retries and email notifications in the job definition.","rationale":"A saved multitask job defines all three task types with task-level retries, notifications and GUI run history.","isCorrect":true},{"id":"D","text":"Use the REST API endpoint /jobs/runs/submit to trigger each task individually as separate job runs and implement retries using custom\nlogic in the orchestrator.","rationale":"Separate one-time submissions with custom orchestration do not implement the requested saved-job approach.","isCorrect":false},{"id":"E","text":"Create a single notebook that uses dbutils.notebook.run() to call each step in sequence. Define a job on this orchestrator notebook and\nconfigure retries and notifications at the notebook level.","rationale":"Notebook orchestration is not a direct replacement for native wheel and SQL tasks with independent task policies.","isCorrect":false}],"selectionCount":2,"correctAnswers":["A","C"],"suggestedAnswers":[],"status":"scoped","explanation":"Jobs run-now through API, CLI or SDK triggers the configured saved multitask job. A saved multitask job defines all three task types with task-level retries, notifications and GUI run history.","topic":"jobs","sourceUrl":"https://docs.databricks.com/aws/en/jobs/","sourceTitle":"Lakeflow Jobs | Databricks on AWS","sourcePage":143,"images":["questions/325-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data team is automating a daily multitask ETL pipeline in Databricks. The pipeline includes a notebook for ingesting raw data, a Python wheel\ntask for data transformation, and a SQL query to update aggregates. They want to trigger the pipeline programmatically and see previous runs in\nthe GUI. They need to ensure tasks are retried on failure and stakeholders are notified by email if any task fails.\nWhich two approaches will meet these requirements? (Choose two.)","options":[{"id":"A","text":"Trigger the job programmatically using the Databricks Jobs REST API (/jobs/run-now), the CLI (databricks jobs run-now), or one of the\nDatabricks SDKs."},{"id":"B","text":"Use Databricks Asset Bundles (DABs) to deploy the workflow, then trigger individual tasks directly by referencing each task’s notebook or\nscript path in the workspace."},{"id":"C","text":"Create a multi-task job using the UI, DABs, or the Jobs REST API (/jobs/create) with notebook, Python wheel, and SQL tasks. Configure\ntask-level retries and email notifications in the job definition."},{"id":"D","text":"Use the REST API endpoint /jobs/runs/submit to trigger each task individually as separate job runs and implement retries using custom\nlogic in the orchestrator."},{"id":"E","text":"Create a single notebook that uses dbutils.notebook.run() to call each step in sequence. Define a job on this orchestrator notebook and\nconfigure retries and notifications at the notebook level."}],"correctAnswers":["A","C"],"explanation":"Define one multi-task job with retries/notifications, then invoke it through run-now, CLI or SDK. Separate ad hoc task submissions or a nested notebook loop do not provide the same native task-level workflow management.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Use one saved multitask job with native notebook, wheel and SQL task definitions, task-level retries and failure notifications. Choose its setup and its programmatic trigger; do not replace it with custom per-step orchestration.","reviewNote":"Second audit: Specified native saved-job task policies so custom orchestration is not an equally valid interpretation.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D","E"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":326,"prompt":"A data engineer is designing a system to process batch patient encounter data stored in an S3 bucket, creating a Delta table (patient_encounters)\nwith columns encounter_id, patient_id, encounter_date, diagnosic_code, and treatment_cost. The table is queried frequently by patient_id and\nencounter_date, requiring fast performance. Fine grained access controls must be enforced. The engineer wants to minimize maintenance and\nboost performance.\nHow should the data engineer create the patient_encounters table?","options":[{"id":"A","text":"Create an external table in Unity Catalog, specifying an S3 location for the data files. Enable predictive optimization through table\nproperties, and configure Unity Catalog permissions for access controls.","rationale":"Predictive optimization is for eligible Unity Catalog managed tables, not this external table.","isCorrect":false},{"id":"B","text":"Create a managed table in Unity Catalog. Configure Unity Catalog permissions for access controls, schedule jobs to run OPTIMIZE and\nvacuum command daily to achieve best performance.","rationale":"Manual OPTIMIZE/VACUUM scheduling adds maintenance the team wants to avoid.","isCorrect":false},{"id":"C","text":"Create a managed table in Hive metastore. Configure Hive metastore permissions for access controls, and rely on predictive optimization\nto enhance query performance and simplify maintenance.","rationale":"Hive metastore tables do not receive Unity Catalog predictive optimization and governance.","isCorrect":false},{"id":"D","text":"Create a managed table in Unity Catalog. Configure Unity Catalog permissions for access controls, and rely on predictive optimization to\nenhance query performance and simplify maintenance.","rationale":"An eligible UC managed table combines governed access with predictive optimization maintenance.","isCorrect":true}],"selectionCount":1,"correctAnswers":["D"],"suggestedAnswers":[],"status":"confirmed","explanation":"An eligible UC managed table combines governed access with predictive optimization maintenance.","topic":"predictive","sourceUrl":"https://docs.databricks.com/aws/en/optimizations/predictive-optimization","sourceTitle":"Predictive optimization for Unity Catalog managed tables | Databricks on AWS","sourcePage":144,"images":["questions/326-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}},{"id":327,"prompt":"A data engineer has a delta table order with deletion vectors enabled for it. The engineer is attempting to execute the below code:\nDELETE FROM orders WHERE status = 'cancelled'\nWhat should be the behaviour of deletion vectors when the command is executed?","options":[{"id":"A","text":"Files are physically rewritten without the deleted row.","rationale":"In the specified deletion-vector operation, unchanged rows need not be copied into a rewritten Parquet file.","isCorrect":false},{"id":"B","text":"Rows are marked as deleted both in metadata and in files.","rationale":"A deletion vector does not alter the original Parquet row contents in place.","isCorrect":false},{"id":"C","text":"Rows are marked as deleted in metadata, not in files","rationale":"Deletion metadata marks the row as logically deleted while its bytes remain in the original file until physical cleanup.","isCorrect":true},{"id":"D","text":"Delta automatically removes all cancelled orders permanently.","rationale":"Logical deletion does not immediately guarantee permanent physical removal.","isCorrect":false}],"selectionCount":1,"correctAnswers":["C"],"suggestedAnswers":[],"status":"scoped","explanation":"Deletion metadata marks the row as logically deleted while its bytes remain in the original file until physical cleanup.","topic":"dv","sourceUrl":"https://docs.databricks.com/aws/en/tables/features/deletion-vectors","sourceTitle":"Deletion vectors in Databricks | Databricks on AWS","sourcePage":144,"images":["questions/327-1.png"],"hasEmbeddedCode":false,"relatedQuestion":null,"practiceEligible":true,"original":{"prompt":"A data engineer has a delta table order with deletion vectors enabled for it. The engineer is attempting to execute the below code:\nDELETE FROM orders WHERE status = 'cancelled'\nWhat should be the behaviour of deletion vectors when the command is executed?","options":[{"id":"A","text":"Files are physically rewritten without the deleted row."},{"id":"B","text":"Rows are marked as deleted both in metadata and in files."},{"id":"C","text":"Rows are marked as deleted in metadata, not in files"},{"id":"D","text":"Delta automatically removes all cancelled orders permanently."}],"correctAnswers":["C"],"explanation":"Deletion vectors mark row positions as deleted while leaving the original Parquet data files unchanged initially. A later purge/rewrite and eligible VACUUM physically remove the old data.","hasEmbeddedCode":false,"code":null,"status":"confirmed"},"studyContext":"Assume the runtime applies deletion vectors to this DELETE operation. Ask what happens to affected rows in their existing Parquet files immediately after the logical commit, before purge/VACUUM.","reviewNote":"Second audit: Distinguished logical deletion from later physical cleanup and allowed for operation-dependent optimization.","reviewRevision":3,"auditModified":true,"audit":{"revision":3,"date":"2026-10-04","reviewedOptions":["A","B","C","D"],"method":"Option-by-option technical review with official references; duplicate choices matched by content. Documentation review, not execution of every example on Databricks."}}];
